window.KAISHI_BUNPO_DATA = [{"id":"n5_b01_01","level":"N5","bab":1,"lokasi":"第1課","titleMain":"〜は〜です","titleSub":["〜じゃありません","〜ですか"],"meaning":"[A] adalah [B] · [A] bukan [B] · Apakah [A] itu [B]? — kalimat kata benda sopan","formula":"KB₁ + <b>は</b> + KB₂ + <b>です</b>（私は学生です）<br>Negatif: KB₂ + <b>じゃありません</b> ／ <b>ではありません</b> (formal)<br>Tanya: KB₂ + <b>ですか</b> → はい、〜です ／ いいえ、〜じゃありません","nuance":"<ol><li><b>は</b> (dibaca <b>wa</b>) menandai <b>topik</b>: \"kalau soal A, …\".</li><li><b>です</b> = penutup sopan; <b>か</b> di akhir = pertanyaan.</li><li><b>じゃ</b> = versi lisan dari <b>では</b>.</li></ol>⚠️ <b>さん</b> jangan dipakai untuk diri sendiri (×私はミラーさんです). Kata tanya orang: だれ / どなた (sopan).","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>はミラーです。","speech":"私はミラーです。","id":"Saya Miller. <i>(positif)</i>"},{"jp":"サントスさんは <ruby>学生<rt>がくせい</rt></ruby>じゃありません。","speech":"サントスさんは学生じゃありません。","id":"Pak Santos <b>bukan</b> pelajar. <i>(negatif)</i>"},{"jp":"ミラーさんは <ruby>会社員<rt>かいしゃいん</rt></ruby>ですか。","speech":"ミラーさんは会社員ですか。","id":"<b>Apakah</b> Pak Miller karyawan perusahaan? <i>(pertanyaan)</i>"},{"jp":"あの<ruby>方<rt>かた</rt></ruby>はどなたですか。","speech":"あの方はどなたですか。","id":"Beliau itu <b>siapa</b>? <i>(kata tanya)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>はインドネシア<ruby>人<rt>じん</rt></ruby>です。 <ruby>日本人<rt>にほんじん</rt></ruby>じゃありません。","speech":"私はインドネシア人です。日本人じゃありません。","id":"Saya orang Indonesia. <b>Bukan</b> orang Jepang. <i>(positif + negatif)</i>"}],"dialogs":[{"jp":"わっ<ruby>私<rt>わたし</rt></ruby><b>は</b> めぐみんのライバル<b>です</b>","speech":"わっ私はめぐみんのライバルです","id":"A-aku <b>adalah</b> rival Megumin! <i>(positif)</i>","source":"この素晴らしい世界に爆焔を！ · EP07 · 17:48"},{"jp":"<ruby>私<rt>わたし</rt></ruby><b>は</b>ニート<b>ではありません</b>","speech":"私はニートではありません","id":"Saya <b>bukan</b> NEET. <i>(negatif formal)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 02:45"},{"jp":"<ruby>勿論<rt>もちろん</rt></ruby><ruby>私<rt>わたし</rt></ruby><b>は</b> <ruby>詐欺師<rt>さぎし</rt></ruby>など<b>じゃありません</b>","speech":"勿論私は詐欺師などじゃありません","id":"Tentu saja saya <b>bukan</b> penipu atau semacamnya. <i>(negatif)</i>","source":"狼と香辛料 · EP07 · 11:57"},{"jp":"リゴロさん<ruby>今日<rt>きょう</rt></ruby><b>は</b> <ruby>会議<rt>かいぎ</rt></ruby><b>ですか</b>","speech":"リゴロさん今日は会議ですか","id":"Pak Rigolo hari ini <b>lagi rapat</b>? <i>(pertanyaan ですか)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP11 · 19:19"}]},{"id":"n5_b01_02","level":"N5","bab":1,"lokasi":"第1課","titleMain":"〜も","titleSub":["私もです"],"meaning":"Juga — hal yang sama berlaku untuk topik lain","formula":"KB + <b>も</b>（<b>は</b> diganti も）<br>グプタさん<b>も</b>会社員です<br>Jawaban singkat: 私<b>も</b>です","nuance":"<ol><li><b>も</b> menempati posisi <b>は</b>, bukan ditambahkan (×はも).</li><li>Dengan negatif = \"juga tidak\": 私<b>も</b>学生じゃありません.</li></ol>⚠️ Kalau jawabannya \"bukan\", kembali ke <b>は</b>. Kata tanya + も + negatif (何も・だれも) = \"sama sekali tidak\" (第5課).","examples":[{"jp":"ミラーさんは<ruby>会社員<rt>かいしゃいん</rt></ruby>です。グプタさんも <ruby>会社員<rt>かいしゃいん</rt></ruby>です。","speech":"ミラーさんは会社員です。グプタさんも会社員です。","id":"Pak Miller karyawan. Pak Gupta <b>juga</b> karyawan. <i>(juga)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>はインドネシア<ruby>人<rt>じん</rt></ruby>です。リナさんもインドネシア<ruby>人<rt>じん</rt></ruby>です。","speech":"私はインドネシア人です。リナさんもインドネシア人です。","id":"Saya orang Indonesia. Rina <b>juga</b> orang Indonesia. <i>(juga)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>学生<rt>がくせい</rt></ruby>です。 <ruby>私<rt>わたし</rt></ruby>もです。","speech":"私は学生です。私もです。","id":"Aku pelajar. ── Aku <b>juga</b>. <i>(jawaban singkat)</i>"},{"jp":"ワンさんも <ruby>先生<rt>せんせい</rt></ruby>ですか。","speech":"ワンさんも先生ですか。","id":"Apakah Pak Wang <b>juga</b> guru? <i>(pertanyaan)</i>"}],"dialogs":[{"jp":"わっ… <ruby>私<rt>わたし</rt></ruby><b>も</b>です!","speech":"わっ… 私もです!","id":"A-aku <b>juga</b>! <i>(jawaban singkat)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 18:10"},{"jp":"<ruby>私<rt>わたし</rt></ruby><b>も</b> <ruby>商人<rt>しょうにん</rt></ruby>ですから","speech":"私も商人ですから","id":"Soalnya saya <b>juga</b> pedagang. <i>(juga)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP09 · 11:43"},{"jp":"わ…<ruby>私<rt>わたし</rt></ruby><b>も</b> <ruby>由崎<rt>ゆざき</rt></ruby>です<ruby>奇遇<rt>きぐう</rt></ruby>ですね","speech":"わ…私も由崎です奇遇ですね","id":"Wah… aku <b>juga</b> Yuzaki! Kebetulan, ya. <i>(nama sama)</i>","source":"トニカクカワイイ · EP08 · 04:04"},{"jp":"<ruby>私<rt>わたし</rt></ruby><b>も</b>50<ruby>個<rt>こ</rt></ruby>です","speech":"私も50個です","id":"Aku <b>juga</b> 50 biji! <i>(juga)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 06:56"},{"jp":"えっ<ruby>私<rt>わたし</rt></ruby><b>も</b>ですか?","speech":"えっ私もですか?","id":"Eh, aku <b>juga</b>? <i>(pertanyaan)</i>","source":"ゆるキャン△ · EP10 · 19:39"}]},{"id":"n5_b01_03","level":"N5","bab":1,"lokasi":"第1課","titleMain":"ＮのＮ","titleSub":["私の本","日本の車"],"meaning":"[N₂] milik / dari / tentang [N₁] — menghubungkan dua kata benda","formula":"N₁ + <b>の</b> + N₂ （inti = N₂）<br>Milik: 私<b>の</b>本 · Afiliasi: IMC<b>の</b>社員<br>Isi: 日本語<b>の</b>本 · Asal: 日本<b>の</b>車","nuance":"<ol><li>Urutan <b>kebalikan</b> bahasa Indonesia: 私の本 = buku saya.</li><li>N₂ yang sudah jelas boleh dihilangkan: これは私<b>の</b>です (punyaku).</li></ol>⚠️ Kata sifat tidak pakai の: ×高いの本 → ○高い本.","examples":[{"jp":"ミラーさんはIMCの <ruby>社員<rt>しゃいん</rt></ruby>です。","speech":"ミラーさんはIMCの社員です。","id":"Pak Miller karyawan <b>IMC</b>. <i>(afiliasi)</i>"},{"jp":"これは<ruby>私<rt>わたし</rt></ruby>の <ruby>本<rt>ほん</rt></ruby>です。","speech":"これは私の本です。","id":"Ini buku <b>saya</b>. <i>(milik)</i>"},{"jp":"カリナさんは<ruby>富士大学<rt>ふじだいがく</rt></ruby>の <ruby>学生<rt>がくせい</rt></ruby>です。","speech":"カリナさんは富士大学の学生です。","id":"Karina mahasiswi <b>Universitas Fuji</b>. <i>(afiliasi)</i>"},{"jp":"あの<ruby>人<rt>ひと</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>の <ruby>友達<rt>ともだち</rt></ruby>です。","speech":"あの人は私の友達です。","id":"Orang itu teman <b>saya</b>. <i>(milik / hubungan)</i>"}],"dialogs":[{"jp":"あれ<ruby>私<rt>わたし</rt></ruby><b>の</b> <ruby>妹<rt>いもうと</rt></ruby>です","speech":"あれ私の妹です","id":"Itu adik <b>saya</b>. <i>(milik / hubungan)</i>","source":"ゆるキャン△ · EP12 · 05:09"},{"jp":"<ruby>私<rt>わたし</rt></ruby><b>の</b> <ruby>名前<rt>なまえ</rt></ruby>は<ruby>有栖川<rt>ありすがわ</rt></ruby><ruby>要<rt>かなめ</rt></ruby>","speech":"私の名前は有栖川要","id":"Nama<b>ku</b> Arisugawa Kaname. <i>(milik)</i>","source":"トニカクカワイイ · EP10 · 11:19"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby><b>の</b>ライブは　あたし<b>の</b> <ruby>友達<rt>ともだち</rt></ruby>が<ruby>結構<rt>けっこう</rt></ruby><ruby>来<rt>き</rt></ruby>てくれたから","speech":"昨日のライブはあたしの友達が結構来てくれたから","id":"Live <b>kemarin</b> itu lumayan banyak teman<b>ku</b> yang datang. <i>(waktu & milik)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 08:17"},{"jp":"<ruby>来年<rt>らいねん</rt></ruby><ruby>俺<rt>おれ</rt></ruby><b>の</b> <ruby>妹<rt>いもうと</rt></ruby>が<ruby>入学<rt>にゅうがく</rt></ruby>するんだ","speech":"来年俺の妹が入学するんだ","id":"Tahun depan adik <b>gue</b> masuk sekolah ini. <i>(milik / hubungan)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP05 · 20:43"}]},{"id":"n5_b02_01","level":"N5","bab":2,"lokasi":"第2課","titleMain":"これ・それ・あれ","titleSub":["どれ"],"meaning":"Ini · itu (dekat kamu) · itu (jauh di sana) — kata tunjuk benda yang berdiri sendiri","formula":"<b>これ</b> (dekat pembicara) ／ <b>それ</b> (dekat lawan bicara) ／ <b>あれ</b> (jauh dari keduanya)<br><b>これ</b> + は ＋ KB + です（これは辞書です）<br>Tanya: <b>どれ</b> = yang mana","nuance":"<ol><li>Berperan sebagai <b>kata benda</b> → langsung diikuti partikel (これは, それを).</li><li>Perspektif bergeser: それは何ですか → <b>これ</b>は〜です.</li><li>Pilihan: これは「ノ」ですか、「メ」ですか → jawab langsung, tanpa はい/いいえ.</li></ol>⚠️ Tidak boleh langsung + KB: ×これ本 → ○<b>この</b>本. 何 dibaca <b>なん</b> sebelum です.","examples":[{"jp":"これは<ruby>辞書<rt>じしょ</rt></ruby>です。","speech":"これは辞書です。","id":"<b>Ini</b> kamus. <i>(dekat pembicara)</i>"},{"jp":"それは<ruby>私<rt>わたし</rt></ruby>の<ruby>傘<rt>かさ</rt></ruby>です。","speech":"それは私の傘です。","id":"<b>Itu</b> payung saya. <i>(dekat lawan bicara)</i>"},{"jp":"あれは<ruby>銀行<rt>ぎんこう</rt></ruby>です。","speech":"あれは銀行です。","id":"<b>Itu (yang di sana)</b> bank. <i>(jauh)</i>"},{"jp":"それは<ruby>何<rt>なん</rt></ruby>ですか。","speech":"それは何ですか。","id":"<b>Itu</b> apa? <i>(tanya)</i>"},{"jp":"これは<ruby>私<rt>わたし</rt></ruby>のです。","speech":"これは私のです。","id":"<b>Ini</b> punya saya. <i>(Ｎの = punya)</i>"}],"dialogs":[{"jp":"うっ… <b>これ</b>は<ruby>硫黄<rt>いおう</rt></ruby>ですか?","speech":"うっ… これは硫黄ですか?","id":"Ugh… <b>ini</b> bau belerang? <i>(これ · dekat pembicara)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP15 · 10:13"},{"jp":"<b>それ</b>は<b>それ</b> <b>これ</b>は<b>これ</b>です","speech":"それはそれこれはこれです","id":"<b>Itu</b> ya itu, <b>ini</b> ya ini. <i>(それ vs これ)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP07 · 01:45"},{"jp":"<b>あれ</b>は<ruby>私<rt>わたし</rt></ruby>の<ruby>使<rt>つか</rt></ruby>い<ruby>魔<rt>ま</rt></ruby>です","speech":"あれは私の使い魔です","id":"<b>Itu</b> familiar saya. <i>(あれ · jauh)</i>","source":"この素晴らしい世界に爆焔を！ · EP09 · 16:32"},{"jp":"ああ <b>あれ</b>はレンタカーだよ","speech":"あああれはレンタカーだよ","id":"Oh, <b>itu</b> mobil sewaan kok. <i>(あれ · kasual だ)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP08 · 00:47"},{"jp":"<b>あれ</b>は<ruby>何猿<rt>なにざる</rt></ruby>だろう?","speech":"あれは何猿だろう?","id":"<b>Itu</b> monyet jenis apa, ya? <i>(あれ · bertanya-tanya)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 09:00"}]},{"id":"n5_b02_02","level":"N5","bab":2,"lokasi":"第2課","titleMain":"この・その・あの＋Ｎ","titleSub":["この本","あの人"],"meaning":"[N] ini · [N] itu · [N] itu (di sana) — kata tunjuk yang menempel pada kata benda","formula":"<b>この</b> ／ <b>その</b> ／ <b>あの</b> + KB（この本 ・ その傘 ・ あの人）<br>Tanya: <b>どの</b> + KB = N yang mana","nuance":"<ol><li>Jaraknya sama dengan これ・それ・あれ, tapi <b>wajib</b> diikuti KB.</li><li><b>あの人 / あの方</b> juga dipakai untuk orang yang sedang dibicarakan (\"dia itu\").</li></ol>⚠️ ×<b>この</b>は本です → ○<b>これ</b>は本です. あの… di awal kalimat bisa juga sekadar \"anu…\".","examples":[{"jp":"この<ruby>本<rt>ほん</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>のです。","speech":"この本は私のです。","id":"<b>Buku ini</b> punya saya. <i>(この)</i>"},{"jp":"その<ruby>傘<rt>かさ</rt></ruby>はだれのですか。","speech":"その傘はだれのですか。","id":"<b>Payung itu</b> punya siapa? <i>(その)</i>"},{"jp":"あの<ruby>人<rt>ひと</rt></ruby>はだれですか。","speech":"あの人はだれですか。","id":"<b>Orang itu</b> siapa? <i>(あの)</i>"},{"jp":"このかばんは<ruby>日本<rt>にほん</rt></ruby>のです。","speech":"このかばんは日本のです。","id":"<b>Tas ini</b> buatan Jepang. <i>(この)</i>"}],"dialogs":[{"jp":"<b>この<ruby>人<rt>ひと</rt></ruby></b> <ruby>店長<rt>てんちょう</rt></ruby>の<ruby>銀<rt>ぎん</rt></ruby>ちゃんね","speech":"この人店長の銀ちゃんね","id":"<b>Orang ini</b> manajernya, Gin-chan. <i>(この人 · memperkenalkan)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 13:40"},{"jp":"<b>この<ruby>人<rt>ひと</rt></ruby></b>は<ruby>由崎<rt>ゆざき</rt></ruby><ruby>司<rt>つかさ</rt></ruby>さん","speech":"この人は由崎司さん","id":"<b>Orang ini</b> Yuzaki Tsukasa-san. <i>(この人は)</i>","source":"トニカクカワイイ · EP10 · 12:03"},{"jp":"<b>その<ruby>話<rt>はなし</rt></ruby></b>は<ruby>忘<rt>わす</rt></ruby>れてください","speech":"その話は忘れてください","id":"Tolong lupakan <b>cerita itu</b>. <i>(その · yang tadi disebut)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP03 · 08:48"},{"jp":"ほほう <b>その<ruby>話<rt>はなし</rt></ruby></b>は<ruby>本当<rt>ほんとう</rt></ruby>でしたか","speech":"ほほうその話は本当でしたか","id":"Hoho, jadi <b>cerita itu</b> beneran? <i>(その)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP09 · 08:53"},{"jp":"<b>あの<ruby>人<rt>ひと</rt></ruby></b> <ruby>1人<rt>ひとり</rt></ruby>でキャンプしてるよ","speech":"あの人1人でキャンプしてるよ","id":"<b>Orang itu</b> kemah sendirian, lho. <i>(あの · jauh)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 05:50"}]},{"id":"n5_b02_03","level":"N5","bab":2,"lokasi":"第2課","titleMain":"そうです","titleSub":["そうですか","違います"],"meaning":"Betul / iya begitu · Oh, begitu ya · Bukan — menjawab & menanggapi","formula":"Membenarkan: はい、<b>そうです</b><br>Menyangkal: いいえ、<b>違います</b> ／ <b>そうじゃありません</b><br>Menerima info: <b>そうですか</b> ↘","nuance":"<ol><li><b>そうです</b> menjawab pertanyaan <b>kata benda</b> (〜ですか).</li><li><b>そうですか</b> intonasi turun = \"oh, begitu\" (bukan pertanyaan); naik = \"masa sih?\".</li><li>Dalam praktik, <b>違います</b> lebih umum daripada そうじゃありません.</li></ol>⚠️ Pertanyaan kata kerja (行きますか) dijawab dengan kata kerjanya: はい、行きます — bukan ×そうです.","examples":[{"jp":"それはテレホンカードですか。 はい、そうです。","speech":"それはテレホンカードですか。はい、そうです。","id":"Itu kartu telepon? ── Iya, <b>betul</b>. <i>(membenarkan)</i>"},{"jp":"それはノートですか。 いいえ、<ruby>違<rt>ちが</rt></ruby>います。","speech":"それはノートですか。いいえ、違います。","id":"Itu buku catatan? ── <b>Bukan</b>. <i>(menyangkal)</i>"},{"jp":"これはコーヒーです。 あ、そうですか。","speech":"これはコーヒーです。あ、そうですか。","id":"Ini kopi. ── Oh, <b>begitu ya</b>. <i>(menerima info)</i>"},{"jp":"ミラーさんはアメリカ<ruby>人<rt>じん</rt></ruby>ですか。 いいえ、そうじゃありません。","speech":"ミラーさんはアメリカ人ですか。いいえ、そうじゃありません。","id":"Pak Miller orang Amerika? ── <b>Bukan</b>. <i>(menyangkal)</i>"}],"dialogs":[{"jp":"あっ はい <b>そうです</b>","speech":"あっはいそうです","id":"Ah, iya, <b>betul</b>. <i>(membenarkan)</i>","source":"ゆるキャン△ · EP06 · 18:50"},{"jp":"あっ <b>そうですか</b>","speech":"あっそうですか","id":"Oh, <b>begitu ya</b>. <i>(menerima info)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP03 · 23:41"},{"jp":"そ… <b>そうですか</b>","speech":"そ… そうですか","id":"B-<b>begitu ya</b>… <i>(menerima info · canggung)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 19:18"},{"jp":"<b><ruby>違<rt>ちが</rt></ruby>います</b> クラスメートの<ruby>由比ヶ浜<rt>ゆいがはま</rt></ruby><ruby>結衣<rt>ゆい</rt></ruby>です","speech":"違いますクラスメートの由比ヶ浜結衣です","id":"<b>Bukan</b>, saya teman sekelasnya, Yuigahama Yui. <i>(menyangkal + koreksi)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP08 · 20:37"},{"jp":"いえ それは <b><ruby>違<rt>ちが</rt></ruby>います</b>","speech":"いえそれは違います","id":"Nggak, itu <b>salah</b>. <i>(menyangkal)</i>","source":"この素晴らしい世界に爆焔を！ · EP04 · 07:38"}]},{"id":"n5_b03_01","level":"N5","bab":3,"lokasi":"第3課","titleMain":"ここ・そこ・あそこ・どこ","titleSub":[],"meaning":"Sini · situ · sana · di mana — kata tunjuk tempat","formula":"<b>ここ</b> (dekat aku) ／ <b>そこ</b> (dekat kamu) ／ <b>あそこ</b> (jauh) ／ <b>どこ</b> (tanya)<br>Tempat + は + KB + です（<b>ここ</b>は食堂です）<br>KB + は + <b>どこ</b>ですか（トイレは<b>どこ</b>ですか）","nuance":"<ol><li>Sistem ko-so-a-do yang sama dengan これ・それ・あれ, tapi untuk <b>tempat</b>.</li><li>KB は <b>あそこ</b>です = \"N ada di sana\" (tanpa partikel tambahan).</li><li><b>どこの</b>＋Ｎ = N buatan/dari mana (どこのワイン).</li></ol>⚠️ ×どこにですか — cukup <b>どこですか</b>. Bentuk sopannya: こちら・そちら・あちら・どちら.","examples":[{"jp":"ここは<ruby>事務所<rt>じむしょ</rt></ruby>です。","speech":"ここは事務所です。","id":"<b>Sini</b> kantor. <i>(dekat pembicara)</i>"},{"jp":"そこは<ruby>会議室<rt>かいぎしつ</rt></ruby>です。","speech":"そこは会議室です。","id":"<b>Situ</b> ruang rapat. <i>(dekat lawan bicara)</i>"},{"jp":"<ruby>電話<rt>でんわ</rt></ruby>はあそこです。","speech":"電話はあそこです。","id":"Teleponnya <b>di sana</b>. <i>(KB は あそこです)</i>"},{"jp":"お<ruby>手洗<rt>てあら</rt></ruby>いはどこですか。","speech":"お手洗いはどこですか。","id":"Toiletnya <b>di mana</b>? <i>(tanya)</i>"},{"jp":"ミラーさんはどこですか。","speech":"ミラーさんはどこですか。","id":"Pak Miller <b>di mana</b>? <i>(tanya orang)</i>"}],"dialogs":[{"jp":"<b>ここ</b>は<b>どこ</b>? <ruby>今日<rt>きょう</rt></ruby>は<ruby>何日<rt>なんにち</rt></ruby>?","speech":"ここはどこ? 今日は何日?","id":"<b>Ini di mana</b>? Hari ini tanggal berapa? <i>(ここ · どこ)</i>","source":"ゆるキャン△ SEASON２ · EP10 · 09:36"},{"jp":"おまわりさん <b>あそこ</b>です!","speech":"おまわりさんあそこです!","id":"Pak polisi, <b>di sana</b>! <i>(あそこです)</i>","source":"この素晴らしい世界に爆焔を！ · EP07 · 05:48"},{"jp":"<b>あそこ</b>が おばあちゃんちだよ","speech":"あそこがおばあちゃんちだよ","id":"<b>Yang di sana</b> itu rumah nenek. <i>(あそこ)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 12:11"},{"jp":"<b>どこ</b>ですか?","speech":"どこですか?","id":"<b>Di mana</b>? <i>(どこですか)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP09 · 03:33"}]},{"id":"n5_b03_02","level":"N5","bab":3,"lokasi":"第3課","titleMain":"こちら・そちら・あちら・どちら","titleSub":["こっち","どっち"],"meaning":"Sebelah sini · situ · sana · mana — arah, dan versi sopan dari ここ・そこ・あそこ・どこ","formula":"Sopan / arah: <b>こちら・そちら・あちら・どちら</b><br>Kasual: <b>こっち・そっち・あっち・どっち</b><br>お国は<b>どちら</b>ですか · <b>こちら</b>は〜さんです (memperkenalkan)","nuance":"<ol><li>Arti dasar = <b>arah</b>; juga pengganti <b>sopan</b> ここ-series (toko, kantor, hotel).</li><li><b>こちら</b>は〜です = cara sopan memperkenalkan orang.</li><li><b>どちら様</b>ですか = \"dengan siapa, ya?\" (sangat sopan).</li></ol>⚠️ <b>どちら</b> juga = \"yang mana (dari dua)\" → 第12課.","examples":[{"jp":"エレベーターはあちらです。","speech":"エレベーターはあちらです。","id":"Liftnya <b>di sebelah sana</b>. <i>(arah)</i>"},{"jp":"<ruby>会議室<rt>かいぎしつ</rt></ruby>はどちらですか。 こちらです。","speech":"会議室はどちらですか。こちらです。","id":"Ruang rapatnya <b>sebelah mana</b>? ── <b>Sebelah sini</b>. <i>(sopan)</i>"},{"jp":"お<ruby>国<rt>くに</rt></ruby>はどちらですか。","speech":"お国はどちらですか。","id":"Asalnya dari negara <b>mana</b>? <i>(sopan)</i>"},{"jp":"こちらはミラーさんです。","speech":"こちらはミラーさんです。","id":"<b>Ini</b> Pak Miller. <i>(memperkenalkan)</i>"}],"dialogs":[{"jp":"<b>こちら</b>は<ruby>海老塚<rt>えびつか</rt></ruby><ruby>智<rt>とも</rt></ruby>ちゃん","speech":"こちらは海老塚智ちゃん","id":"<b>Ini</b> Ebizuka Tomo-chan. <i>(memperkenalkan)</i>","source":"ガールズバンドクライ · EP06 · 12:46"},{"jp":"おかえりなさいませ <b>こちら</b>へ どうぞ","speech":"おかえりなさいませこちらへどうぞ","id":"Selamat datang kembali~ Silakan <b>lewat sini</b>. <i>(arah · sopan)</i>","source":"ぼっち・ざ・ろっく！ · EP11 · 13:12"},{"jp":"ベースは <b>どちら</b>に?","speech":"ベースはどちらに?","id":"Bass-nya <b>di mana</b>? <i>(どちら · sopan)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 09:43"},{"jp":"<b>どちら</b> <ruby>様<rt>さま</rt></ruby>でしょうか","speech":"どちら様でしょうか","id":"<b>Dengan siapa</b>, ya? <i>(どちら様 · sangat sopan)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP09 · 06:57"}]},{"id":"n5_b04_01","level":"N5","bab":4,"lokasi":"第4課","titleMain":"〜ます","titleSub":["〜ません","〜ました","〜ませんでした"],"meaning":"Bentuk sopan kata kerja: melakukan · tidak · sudah/tadi · tidak (lampau)","formula":"Non-lampau: 起き<b>ます</b> ／ 起き<b>ません</b><br>Lampau: 起き<b>ました</b> ／ 起き<b>ませんでした</b><br>(batang tetap, ganti ujung ます saja)","nuance":"<ol><li><b>〜ます</b> = kebiasaan (毎日勉強します) <b>atau</b> rencana (明日行きます).</li><li><b>〜ました</b> = sudah terjadi; <b>〜ませんでした</b> = tidak terjadi (lampau).</li></ol>⚠️ 〜ます bukan \"sedang\" (→ 〜ています). Pertanyaan 〜ますか dijawab dengan KK-nya: はい、休みます (bukan ×そうです).","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>毎日<rt>まいにち</rt></ruby><ruby>勉強<rt>べんきょう</rt></ruby>します。","speech":"私は毎日勉強します。","id":"Saya belajar setiap hari. <i>(kebiasaan)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby><ruby>勉強<rt>べんきょう</rt></ruby>しました。","speech":"昨日勉強しました。","id":"Kemarin saya <b>(sudah) belajar</b>. <i>(lampau)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>働<rt>はたら</rt></ruby>きません。","speech":"今日は働きません。","id":"Hari ini saya <b>tidak</b> bekerja. <i>(negatif)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby><ruby>休<rt>やす</rt></ruby>みますか。","speech":"明日休みますか。","id":"Besok kamu <b>libur</b>? <i>(tanya · rencana)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby>の<ruby>晩<rt>ばん</rt></ruby>、 <ruby>勉強<rt>べんきょう</rt></ruby>しませんでした。","speech":"昨日の晩、勉強しませんでした。","id":"Kemarin malam saya <b>tidak belajar</b>. <i>(negatif lampau)</i>"}],"dialogs":[{"jp":"わ… <ruby>私<rt>わたし</rt></ruby><ruby>頑張<rt>がんば</rt></ruby>り<b>ます</b>!","speech":"わ… 私頑張ります!","id":"A-aku <b>akan</b> berjuang! <i>(ます · niat)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 20:21"},{"jp":"いいえ<ruby>帰<rt>かえ</rt></ruby>り<b>ません</b>よ","speech":"いいえ帰りませんよ","id":"Nggak, aku <b>nggak</b> pulang. <i>(ません)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 16:23"},{"jp":"お<ruby>客<rt>きゃく</rt></ruby>さん たくさん<ruby>来<rt>き</rt></ruby><b>ました</b>ね","speech":"お客さんたくさん来ましたね","id":"Pengunjungnya banyak yang <b>datang</b>, ya. <i>(ました · lampau)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP08 · 20:04"},{"jp":"<ruby>知<rt>し</rt></ruby>り<b>ませんでした</b>","speech":"知りませんでした","id":"Aku <b>nggak tahu</b> (sebelumnya). <i>(ませんでした)</i>","source":"ゆるキャン△ · EP09 · 06:20"}]},{"id":"n5_b04_02","level":"N5","bab":4,"lokasi":"第4課","titleMain":"時間＋に","titleSub":["６時に","日曜日に"],"meaning":"Pada (jam / tanggal / hari) … — titik waktu terjadinya aksi","formula":"Jam / tanggal / bulan + <b>に</b> + KK（６時<b>に</b>起きます）<br>Hari: 日曜日（<b>に</b>） — boleh pakai / tidak<br>Relatif (今日・明日・毎日・来週): <b>tanpa に</b>","nuance":"<ol><li>Waktu ber-<b>angka</b> → wajib に.</li><li>Waktu <b>relatif</b> → tanpa に (明日行きます).</li><li><b>何時に</b> pakai に, tapi <b>いつ</b> tanpa に.</li></ol>⚠️ ×明日に ×毎日に. Bacaan: 4時 <b>よじ</b>, 7時 <b>しちじ</b>, 9時 <b>くじ</b>.","examples":[{"jp":"６<ruby>時<rt>じ</rt></ruby>に <ruby>起<rt>お</rt></ruby>きます。","speech":"６時に起きます。","id":"Saya bangun <b>jam 6</b>. <i>(jam)</i>"},{"jp":"<ruby>毎朝<rt>まいあさ</rt></ruby> 7<ruby>時半<rt>じはん</rt></ruby>に <ruby>家<rt>いえ</rt></ruby>を<ruby>出<rt>で</rt></ruby>ます。","speech":"毎朝7時半に家を出ます。","id":"Tiap pagi saya keluar rumah <b>jam setengah 8</b>. <i>(relatif tanpa に + jam dengan に)</i>"},{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>に <ruby>京都<rt>きょうと</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きます。","speech":"日曜日に京都へ行きます。","id":"<b>Hari Minggu</b> saya pergi ke Kyoto. <i>(hari · に opsional)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>、 <ruby>何時<rt>なんじ</rt></ruby>に <ruby>起<rt>お</rt></ruby>きますか。","speech":"明日、何時に起きますか。","id":"Besok bangun <b>jam berapa</b>? <i>(何時に)</i>"}],"dialogs":[{"jp":"11<ruby>時<rt>じ</rt></ruby><b>に</b> <ruby>佐久米駅<rt>さくめえき</rt></ruby>で<ruby>待<rt>ま</rt></ruby>ち<ruby>合<rt>あ</rt></ruby>わせか","speech":"11時に佐久米駅で待ち合わせか","id":"Ketemuan di Stasiun Sakume <b>jam 11</b>, ya. <i>(jam + に)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 05:06"},{"jp":"<ruby>朝<rt>あさ</rt></ruby>5<ruby>時半<rt>じはん</rt></ruby><b>に</b> <ruby>起<rt>お</rt></ruby>きて<ruby>銭湯<rt>せんとう</rt></ruby>の<ruby>準備<rt>じゅんび</rt></ruby>","speech":"朝5時半に起きて銭湯の準備","id":"Bangun <b>jam setengah 6</b> pagi terus nyiapin pemandian. <i>(jam + に)</i>","source":"トニカクカワイイ · EP10 · 11:28"},{"jp":"これって<ruby>京都<rt>きょうと</rt></ruby>に<ruby>何時<rt>なんじ</rt></ruby><b>に</b> <ruby>着<rt>つ</rt></ruby>くの","speech":"これって京都に何時に着くの","id":"Ini nyampe Kyoto <b>jam berapa</b>? <i>(何時に)</i>","source":"トニカクカワイイ · EP06 · 18:32"},{"jp":"なんせ<ruby>夜<rt>よる</rt></ruby>7<ruby>時<rt>じ</rt></ruby><b>に</b>メールを<ruby>送<rt>おく</rt></ruby>れば","speech":"なんせ夜7時にメールを送れば","id":"Soalnya kalau aku kirim email <b>jam 7</b> malam… <i>(jam + に)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP04 · 07:11"}]},{"id":"n5_b04_03","level":"N5","bab":4,"lokasi":"第4課","titleMain":"〜から〜まで","titleSub":[],"meaning":"Dari … sampai … — titik awal &amp; akhir (waktu / tempat)","formula":"[Awal] <b>から</b> [Akhir] <b>まで</b> + KK（９時<b>から</b>５時<b>まで</b>働きます）<br>KB は 〜<b>から</b>〜<b>まで</b>です<br>Sendiri: 〜<b>から</b>です ／ 〜<b>まで</b>です","nuance":"<ol><li>Untuk <b>waktu</b> maupun <b>tempat</b> (大阪から東京まで).</li><li>Boleh dipakai terpisah: 5時からです (mulai jam 5).</li><li>Di bab ini juga: N1<b>と</b>N2 = N1 dan N2.</li></ol>⚠️ <b>から</b> setelah kalimat = \"karena\" (第9課). まで ≠ までに (sebelum batas, N4).","examples":[{"jp":"９<ruby>時<rt>じ</rt></ruby>から５<ruby>時<rt>じ</rt></ruby>まで <ruby>働<rt>はたら</rt></ruby>きます。","speech":"９時から５時まで働きます。","id":"Saya bekerja <b>dari</b> jam 9 <b>sampai</b> jam 5. <i>(waktu)</i>"},{"jp":"<ruby>銀行<rt>ぎんこう</rt></ruby>は<ruby>何時<rt>なんじ</rt></ruby>から <ruby>何時<rt>なんじ</rt></ruby>までですか。","speech":"銀行は何時から何時までですか。","id":"Bank buka <b>dari</b> jam berapa <b>sampai</b> jam berapa? <i>(〜です)</i>"},{"jp":"<ruby>大阪<rt>おおさか</rt></ruby>から <ruby>東京<rt>とうきょう</rt></ruby>まで３<ruby>時間<rt>じかん</rt></ruby>かかります。","speech":"大阪から東京まで３時間かかります。","id":"<b>Dari</b> Osaka <b>sampai</b> Tokyo makan waktu 3 jam. <i>(tempat)</i>"},{"jp":"<ruby>会議<rt>かいぎ</rt></ruby>は３<ruby>時<rt>じ</rt></ruby>からです。","speech":"会議は３時からです。","id":"Rapatnya <b>mulai</b> jam 3. <i>(から saja)</i>"}],"dialogs":[{"jp":"チケットの<ruby>販売<rt>はんばい</rt></ruby>は 5<ruby>時<rt>じ</rt></ruby><b>から</b>ですよ","speech":"チケットの販売は5時からですよ","id":"Penjualan tiketnya <b>mulai</b> jam 5, lho. <i>(〜からです)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 12:46"},{"jp":"<ruby>明日<rt>あした</rt></ruby><b>から</b> <ruby>練習<rt>れんしゅう</rt></ruby><ruby>頑張<rt>がんば</rt></ruby>るぞ!","speech":"明日から練習頑張るぞ!","id":"<b>Mulai</b> besok latihan yang semangat! <i>(から · titik mulai)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 19:20"},{"jp":"2<ruby>時<rt>じ</rt></ruby><b>まで</b> どうすっか?","speech":"2時までどうすっか?","id":"<b>Sampai</b> jam 2 enaknya ngapain? <i>(まで · batas)</i>","source":"ゆるキャン△ · EP11 · 01:47"},{"jp":"<ruby>今回<rt>こんかい</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>も<ruby>明日<rt>あした</rt></ruby><b>まで</b> ちゃんとキャンプするからね","speech":"今回は私も明日までちゃんとキャンプするからね","id":"Kali ini aku juga bakal kemah beneran <b>sampai</b> besok. <i>(まで)</i>","source":"ゆるキャン△ · EP03 · 05:56"}]},{"id":"n5_b05_01","level":"N5","bab":5,"lokasi":"第5課","titleMain":"〜へ 行きます・来ます・帰ります","titleSub":[],"meaning":"Pergi / datang / pulang ke … — kata kerja gerak + arah tujuan","formula":"Tempat + <b>へ</b> (dibaca e) ／ <b>に</b> + 行きます・来ます・帰ります<br>Asal: Tempat + <b>から</b> 来ました<br>Tanya: <b>どこへ</b> ・ <b>いつ</b> (tanpa に)","nuance":"<ol><li><b>行きます</b> = menjauh, <b>来ます</b> = mendekat ke posisi pembicara, <b>帰ります</b> = kembali ke tempat asal.</li><li><b>へ</b> menekankan arah; <b>に</b> menekankan titik tujuan — dalam praktik sering bisa tukar.</li></ol>⚠️ Ke rumah sendiri selalu <b>帰ります</b> (×うちへ行きます).","examples":[{"jp":"<ruby>京都<rt>きょうと</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きます。","speech":"京都へ行きます。","id":"Saya <b>pergi ke</b> Kyoto. <i>(行きます)</i>"},{"jp":"いつ<ruby>日本<rt>にほん</rt></ruby>へ<ruby>来<rt>き</rt></ruby>ましたか。","speech":"いつ日本へ来ましたか。","id":"Kapan kamu <b>datang ke</b> Jepang? <i>(来ます)</i>"},{"jp":"きのう、どこへ<ruby>行<rt>い</rt></ruby>きましたか。","speech":"きのう、どこへ行きましたか。","id":"Kemarin <b>pergi ke</b> mana? <i>(どこへ)</i>"},{"jp":"<ruby>来年<rt>らいねん</rt></ruby>、 <ruby>国<rt>くに</rt></ruby>へ<ruby>帰<rt>かえ</rt></ruby>ります。","speech":"来年、国へ帰ります。","id":"Tahun depan saya <b>pulang ke</b> negara asal. <i>(帰ります)</i>"}],"dialogs":[{"jp":"いい<ruby>私<rt>わたし</rt></ruby>は<ruby>祭<rt>まつ</rt></ruby>りの<ruby>方<rt>ほう</rt></ruby><b>へ<ruby>行<rt>い</rt></ruby>きます</b>が どうぞごゆっくり","speech":"いい私は祭りの方へ行きますがどうぞごゆっくり","id":"Nggak apa-apa. Saya <b>mau ke</b> arah festival, silakan santai saja. <i>(へ行きます)</i>","source":"狼と香辛料 · EP01 · 14:09"},{"jp":"<ruby>明日<rt>あした</rt></ruby>はダンジョン<b>に<ruby>行<rt>い</rt></ruby>きます</b>","speech":"明日はダンジョンに行きます","id":"Besok kita <b>pergi ke</b> dungeon. <i>(に行きます)</i>","source":"この素晴らしい世界に祝福を！2 · EP03 · 02:34"},{"jp":"<ruby>私<rt>わたし</rt></ruby><ruby>負<rt>ま</rt></ruby>けたくなくてここ<b>に<ruby>来<rt>き</rt></ruby>ました</b>","speech":"私負けたくなくてここに来ました","id":"Aku <b>datang ke</b> sini karena nggak mau kalah! <i>(に来ました)</i>","source":"ガールズバンドクライ · EP01 · 21:33"},{"jp":"はいはい<ruby>夏休<rt>なつやす</rt></ruby>みには<b><ruby>帰<rt>かえ</rt></ruby>ります</b>","speech":"はいはい夏休みには帰ります","id":"Iya, iya, liburan musim panas nanti aku <b>pulang</b>. <i>(帰ります)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP05 · 18:07"}]},{"id":"n5_b05_02","level":"N5","bab":5,"lokasi":"第5課","titleMain":"〜で","titleSub":["電車で 行きます","歩いて"],"meaning":"Naik … / dengan … — alat transportasi","formula":"Kendaraan + <b>で</b> + 行きます・来ます・帰ります<br>（電車<b>で</b> ・ タクシー<b>で</b> ・ 自転車<b>で</b>）<br>Jalan kaki: <b>歩いて</b> (tanpa で) · Tanya: <b>何で</b>","nuance":"<ol><li><b>で</b> = sarana/alat; di bab ini untuk kendaraan.</li><li>Jalan kaki = <b>歩いて</b>行きます.</li></ol>⚠️ ×歩きで ×足で. で juga untuk tempat aktivitas (第6課) & alat/bahasa (第7課).","examples":[{"jp":"タクシーでうちへ<ruby>帰<rt>かえ</rt></ruby>ります。","speech":"タクシーでうちへ帰ります。","id":"Saya pulang ke rumah <b>naik taksi</b>. <i>(kendaraan)</i>"},{"jp":"<ruby>何<rt>なん</rt></ruby>で <ruby>大阪<rt>おおさか</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きますか。","speech":"何で大阪へ行きますか。","id":"Ke Osaka <b>naik apa</b>? <i>(何で)</i>"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby>、 <ruby>電車<rt>でんしゃ</rt></ruby>で <ruby>会社<rt>かいしゃ</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きます。","speech":"毎日、電車で会社へ行きます。","id":"Tiap hari saya ke kantor <b>naik kereta</b>. <i>(kendaraan)</i>"},{"jp":"<ruby>駅<rt>えき</rt></ruby>から<ruby>歩<rt>ある</rt></ruby>いて <ruby>帰<rt>かえ</rt></ruby>りました。","speech":"駅から歩いて帰りました。","id":"Saya pulang <b>jalan kaki</b> dari stasiun. <i>(歩いて)</i>"}],"dialogs":[{"jp":"<ruby>電車<rt>でんしゃ</rt></ruby><b>で</b> <ruby>帰<rt>かえ</rt></ruby>ってこい","speech":"電車で帰ってこい","id":"Pulang <b>naik kereta</b> sana! <i>(電車で)</i>","source":"ガールズバンドクライ · EP08 · 18:42"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>泊<rt>と</rt></ruby>まって<ruby>明日<rt>あした</rt></ruby>の<ruby>夜<rt>よる</rt></ruby><ruby>夜行<rt>やこう</rt></ruby>バス<b>で</b> <ruby>帰<rt>かえ</rt></ruby>るよ","speech":"今日は泊まって明日の夜夜行バスで帰るよ","id":"Hari ini nginep, besok malam pulang <b>naik bus malam</b>. <i>(バスで)</i>","source":"トニカクカワイイ · EP08 · 07:31"},{"jp":"ねえ まさか ここまで<ruby>自転車<rt>じてんしゃ</rt></ruby><b>で</b> <ruby>来<rt>き</rt></ruby>たの?","speech":"ねえまさかここまで自転車で来たの?","id":"Eh, jangan-jangan kamu ke sini <b>naik sepeda</b>? <i>(自転車で)</i>","source":"ゆるキャン△ · EP03 · 05:42"},{"jp":"<ruby>湖<rt>みずうみ</rt></ruby>の<ruby>周<rt>まわ</rt></ruby>りを<b><ruby>歩<rt>ある</rt></ruby>いて</b> <ruby>行<rt>い</rt></ruby>ってください","speech":"湖の周りを歩いて行ってください","id":"Silakan <b>jalan kaki</b> memutari danau. <i>(歩いて · tanpa で)</i>","source":"ゆるキャン△ · EP06 · 18:57"}]},{"id":"n5_b05_03","level":"N5","bab":5,"lokasi":"第5課","titleMain":"〜と","titleSub":["友達と 行きます","一人で"],"meaning":"Bersama / dengan [orang]","formula":"Orang + <b>と</b> + KK（家族<b>と</b>来ました）<br>Orang + <b>と一緒に</b> + KK<br>Sendirian: <b>一人で</b> · Tanya: <b>だれと</b>","nuance":"<ol><li><b>と</b> = melakukan sesuatu bersama orang itu; <b>一緒に</b> menegaskan \"bareng\".</li><li>Sendirian pakai <b>で</b>: 一人<b>で</b>行きます.</li></ol>⚠️ ×一人と. と di antara dua KB = \"dan\" (パンと卵).","examples":[{"jp":"<ruby>家族<rt>かぞく</rt></ruby>と <ruby>日本<rt>にほん</rt></ruby>へ<ruby>来<rt>き</rt></ruby>ました。","speech":"家族と日本へ来ました。","id":"Saya datang ke Jepang <b>bersama keluarga</b>. <i>(と)</i>"},{"jp":"だれと <ruby>行<rt>い</rt></ruby>きますか。 <ruby>友達<rt>ともだち</rt></ruby>と <ruby>行<rt>い</rt></ruby>きます。","speech":"だれと行きますか。友達と行きます。","id":"Pergi <b>dengan siapa</b>? ── <b>Dengan teman</b>. <i>(だれと)</i>"},{"jp":"<ruby>一人<rt>ひとり</rt></ruby>で <ruby>東京<rt>とうきょう</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きました。","speech":"一人で東京へ行きました。","id":"Saya pergi ke Tokyo <b>sendirian</b>. <i>(一人で)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby>、 <ruby>彼女<rt>かのじょ</rt></ruby>と<ruby>一緒<rt>いっしょ</rt></ruby>に <ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>ます。","speech":"週末、彼女と一緒に映画を見ます。","id":"Akhir pekan aku nonton film <b>bareng pacar</b>. <i>(と一緒に)</i>"}],"dialogs":[{"jp":"み… みんな<b>と<ruby>一緒<rt>いっしょ</rt></ruby>に</b> <ruby>行<rt>い</rt></ruby>くって<ruby>言<rt>い</rt></ruby>おうかな","speech":"み… みんなと一緒に行くって言おうかな","id":"A-aku bilang aja deh kalau aku pergi <b>bareng</b> semuanya. <i>(と一緒に)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 04:54"},{"jp":"また<ruby>夏<rt>なつ</rt></ruby>が<ruby>来<rt>き</rt></ruby>たら　 <ruby>君<rt>きみ</rt></ruby><b>と<ruby>一緒<rt>いっしょ</rt></ruby>に</b> <ruby>花火<rt>はなび</rt></ruby>に<ruby>行<rt>い</rt></ruby>こう","speech":"また夏が来たら君と一緒に花火に行こう","id":"Nanti kalau musim panas datang lagi, ayo lihat kembang api <b>bareng kamu</b>. <i>(と一緒に)</i>","source":"トニカクカワイイ · EP12 · 21:31"},{"jp":"いや お<ruby>兄<rt>にい</rt></ruby>ちゃんは<ruby>行<rt>い</rt></ruby>かないでしょ　 <ruby>家族<rt>かぞく</rt></ruby>じゃなくて<ruby>友達<rt>ともだち</rt></ruby><b>と</b> <ruby>行<rt>い</rt></ruby>くし","speech":"いやお兄ちゃんは行かないでしょ家族じゃなくて友達と行くし","id":"Nggak lah, Kakak nggak ikut. Aku perginya <b>sama teman</b>, bukan sama keluarga. <i>(と)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP06 · 06:48"},{"jp":"また お<ruby>母<rt>かあ</rt></ruby>さん<b>と<ruby>一緒<rt>いっしょ</rt></ruby>に</b> ご<ruby>飯<rt>はん</rt></ruby><ruby>食<rt>た</rt></ruby>べよ ね?","speech":"またお母さんと一緒にご飯食べよね?","id":"Nanti makan <b>bareng Mama</b> lagi, ya? <i>(と一緒に)</i>","source":"ぼっち・ざ・ろっく！ · EP08 · 15:00"}]},{"id":"n5_b05_04","level":"N5","bab":5,"lokasi":"第5課","titleMain":"どこへも・何も・だれも〜ません","titleSub":[],"meaning":"Tidak ke mana-mana · tidak apa-apa · tidak ada siapa pun — penyangkalan total","formula":"Kata tanya (+ partikel) + <b>も</b> + 〜<b>ません</b><br><b>どこ（へ）も</b>行きません ・ <b>何も</b>食べません ・ <b>だれも</b>来ません<br>を／が hilang: ×何をも","nuance":"<ol><li>Partikel arah/teman tetap: どこ<b>へ</b>も, だれ<b>と</b>も.</li><li>Partikel <b>を・が</b> diganti も: 何<b>も</b>, だれ<b>も</b>.</li></ol>⚠️ Pasangkan dengan <b>negatif</b>. \"Semua orang\" di level ini = みんな.","examples":[{"jp":"どこへも <ruby>行<rt>い</rt></ruby>きません。","speech":"どこへも行きません。","id":"Saya <b>nggak pergi ke mana-mana</b>. <i>(どこへも)</i>"},{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>、どこも <ruby>行<rt>い</rt></ruby>きませんでした。","speech":"日曜日、どこも行きませんでした。","id":"Hari Minggu saya <b>nggak ke mana-mana</b>. <i>(どこも · へ dihilangkan)</i>"},{"jp":"けさ、<ruby>何<rt>なに</rt></ruby>も <ruby>食<rt>た</rt></ruby>べませんでした。","speech":"けさ、何も食べませんでした。","id":"Tadi pagi saya <b>nggak makan apa-apa</b>. <i>(何も)</i>"},{"jp":"パーティーにだれも <ruby>来<rt>き</rt></ruby>ませんでした。","speech":"パーティーにだれも来ませんでした。","id":"<b>Nggak ada seorang pun</b> yang datang ke pesta. <i>(だれも)</i>"}],"dialogs":[{"jp":"だから <b>どこにも</b> <ruby>行<rt>い</rt></ruby>か<b>ない</b>わ","speech":"だからどこにも行かないわ","id":"Makanya, aku <b>nggak ke mana-mana</b>. <i>(どこにも · kasual)</i>","source":"トニカクカワイイ · EP02 · 06:28"},{"jp":"な…　<b><ruby>何<rt>なに</rt></ruby>も</b> <ruby>思<rt>おも</rt></ruby>いつか<b>ない</b>…","speech":"な…　何も思いつかない…","id":"N-nggak kepikiran <b>apa-apa</b>… <i>(何も)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 05:54"},{"jp":"<ruby>曇<rt>くも</rt></ruby>ってて<b><ruby>何<rt>なに</rt></ruby>も</b> <ruby>見<rt>み</rt></ruby>え<b>ねえ</b>…","speech":"曇ってて何も見えねえ…","id":"Mendung, <b>nggak kelihatan apa-apa</b>… <i>(何も · ねえ = ない kasar)</i>","source":"ゆるキャン△ · EP05 · 07:17"},{"jp":"もう<ruby>広場<rt>ひろば</rt></ruby>は<b><ruby>誰<rt>だれ</rt></ruby>も</b> い<b>ない</b>ぞ","speech":"もう広場は誰もいないぞ","id":"Di alun-alun udah <b>nggak ada siapa-siapa</b>. <i>(だれも)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 19:36"}]},{"id":"n5_b06_01","level":"N5","bab":6,"lokasi":"第6課","titleMain":"〜を","titleSub":["ごはんを 食べます"],"meaning":"Penanda objek langsung — \"apa\" yang dimakan / dibaca / dibeli","formula":"Objek + <b>を</b> (dibaca o) + KK transitif<br>（ごはん<b>を</b>食べます ・ 写真<b>を</b>撮ります ・ テニス<b>を</b>します）<br>Tanya: <b>何を</b> (なにを)","nuance":"<ol><li>Untuk KK yang \"mengenai\" sesuatu: 食べる, 飲む, 読む, 買う, 見る, 聞く, 書く.</li><li><b>します</b> juga mengambil を: 宿題をします.</li><li>Bahasa santai sering membuang を: ご飯食べた？</li></ol>⚠️ Tujuan KK gerak pakai <b>へ／に</b>, bukan を. 何 = <b>なに</b> sebelum を.","examples":[{"jp":"ごはんを <ruby>食<rt>た</rt></ruby>べます。","speech":"ごはんを食べます。","id":"Saya makan <b>nasi</b>. <i>(objek)</i>"},{"jp":"<ruby>何<rt>なに</rt></ruby>を <ruby>買<rt>か</rt></ruby>いましたか。 <ruby>靴<rt>くつ</rt></ruby>を <ruby>買<rt>か</rt></ruby>いました。","speech":"何を買いましたか。靴を買いました。","id":"Beli <b>apa</b>? ── Beli <b>sepatu</b>. <i>(何を)</i>"},{"jp":"<ruby>毎朝<rt>まいあさ</rt></ruby>、 <ruby>新聞<rt>しんぶん</rt></ruby>を <ruby>読<rt>よ</rt></ruby>みます。","speech":"毎朝、新聞を読みます。","id":"Tiap pagi saya baca <b>koran</b>. <i>(objek)</i>"},{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>、 <ruby>何<rt>なに</rt></ruby>をしますか。","speech":"日曜日、何をしますか。","id":"Hari Minggu mau <b>ngapain</b>? <i>(何をする)</i>"}],"dialogs":[{"jp":"はい キンメバーガー<b>を</b> <ruby>食<rt>た</rt></ruby>べました","speech":"はいキンメバーガーを食べました","id":"Iya, kami makan <b>burger kinme</b>. <i>(を + 食べる)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 03:46"},{"jp":"ナサくんは<b><ruby>何<rt>なに</rt></ruby>を</b> <ruby>食<rt>た</rt></ruby>べる?","speech":"ナサくんは何を食べる?","id":"Nasa-kun mau makan <b>apa</b>? <i>(何を)</i>","source":"トニカクカワイイ · EP07 · 03:30"},{"jp":"<ruby>次<rt>つぎ</rt></ruby>のページ<b>を</b> <ruby>読<rt>よ</rt></ruby>んでください","speech":"次のページを読んでください","id":"Tolong baca <b>halaman berikutnya</b>. <i>(を + 読む)</i>","source":"ガールズバンドクライ · EP12 · 12:30"},{"jp":"まったく… <ruby>朝<rt>あさ</rt></ruby>から<b><ruby>何<rt>なに</rt></ruby>を</b>していた?","speech":"まったく… 朝から何をしていた?","id":"Astaga… dari pagi kamu <b>ngapain</b> aja? <i>(何をする)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP02 · 15:49"}]},{"id":"n5_b06_02","level":"N5","bab":6,"lokasi":"第6課","titleMain":"〜で","titleSub":["ロビーで 読みます"],"meaning":"Di [tempat] — tempat terjadinya aksi / kegiatan","formula":"Tempat + <b>で</b> + KK aksi（ロビー<b>で</b>新聞を読みます）<br>Tanya: <b>どこで</b><br>Keberadaan (あります／います) → <b>に</b>","nuance":"<ol><li><b>で</b> = panggung tempat sesuatu <b>dilakukan</b> (makan, belajar, menunggu).</li><li><b>に</b> = tempat sesuatu <b>berada</b>.</li></ol>⚠️ 部屋<b>で</b>勉強します (aksi) vs 部屋<b>に</b>います (ada).","examples":[{"jp":"ロビーで <ruby>新聞<rt>しんぶん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>みます。","speech":"ロビーで新聞を読みます。","id":"Saya baca koran <b>di</b> lobi. <i>(tempat aksi)</i>"},{"jp":"<ruby>駅<rt>えき</rt></ruby>で <ruby>友達<rt>ともだち</rt></ruby>を<ruby>待<rt>ま</rt></ruby>ちます。","speech":"駅で友達を待ちます。","id":"Saya nunggu teman <b>di</b> stasiun. <i>(tempat aksi)</i>"},{"jp":"どこでその<ruby>時計<rt>とけい</rt></ruby>を<ruby>買<rt>か</rt></ruby>いましたか。","speech":"どこでその時計を買いましたか。","id":"Jam itu belinya <b>di mana</b>? <i>(どこで)</i>"},{"jp":"<ruby>図書館<rt>としょかん</rt></ruby>で <ruby>日本語<rt>にほんご</rt></ruby>を<ruby>勉強<rt>べんきょう</rt></ruby>します。","speech":"図書館で日本語を勉強します。","id":"Saya belajar bahasa Jepang <b>di</b> perpustakaan. <i>(tempat aksi)</i>"}],"dialogs":[{"jp":"<ruby>放課後<rt>ほうかご</rt></ruby><ruby>生徒会室<rt>せいとかいしつ</rt></ruby><b>で</b> <ruby>待<rt>ま</rt></ruby>ってますねー","speech":"放課後生徒会室で待ってますねー","id":"Pulang sekolah nanti aku tunggu <b>di</b> ruang OSIS, ya~ <i>(で + 待つ)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP03 · 09:14"},{"jp":"いつも<ruby>見晴<rt>みは</rt></ruby>らし<ruby>公園<rt>こうえん</rt></ruby><b>で</b> <ruby>練習<rt>れんしゅう</rt></ruby>してましたもんね","speech":"いつも見晴らし公園で練習してましたもんね","id":"Kamu kan selalu latihan <b>di</b> Taman Miharashi. <i>(で + 練習する)</i>","source":"ガールズバンドクライ · EP13 · 17:45"},{"jp":"そうか<ruby>寒<rt>さむ</rt></ruby>いから<ruby>車<rt>くるま</rt></ruby>の<ruby>中<rt>なか</rt></ruby><b>で</b> <ruby>待<rt>ま</rt></ruby>ってたんだ","speech":"そうか寒いから車の中で待ってたんだ","id":"Oh, karena dingin, mereka nunggu <b>di dalam</b> mobil. <i>(で + 待つ)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 06:43"},{"jp":"それより あーし<ruby>屋上<rt>おくじょう</rt></ruby><b>で</b>ご<ruby>飯<rt>はん</rt></ruby><ruby>食<rt>た</rt></ruby>べたいんだけど","speech":"それよりあーし屋上でご飯食べたいんだけど","id":"Lagian, aku pengin makan <b>di</b> atap sekolah sih. <i>(で + 食べる)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP05 · 06:23"}]},{"id":"n5_b06_03","level":"N5","bab":6,"lokasi":"第6課","titleMain":"〜ませんか","titleSub":[],"meaning":"Gimana kalau kita …? / Mau … bareng nggak? — ajakan sopan","formula":"Ｖます → Ｖ<b>ませんか</b>（いっしょに飲み<b>ませんか</b>）<br>Setuju: ええ、いいですね ／ ええ、〜ましょう<br>Menolak: すみません、ちょっと…","nuance":"<ol><li>Bentuknya negatif-tanya, tapi maknanya <b>mengajak</b>.</li><li>Lebih halus dari ましょう karena memberi ruang untuk <b>menolak</b>.</li></ol>⚠️ Menolak cukup dengan <b>ちょっと…</b> (kalimat sengaja digantung).","examples":[{"jp":"いっしょにビールを<ruby>飲<rt>の</rt></ruby>みませんか。 ええ、いいですね。","speech":"いっしょにビールを飲みませんか。ええ、いいですね。","id":"Minum bir bareng, <b>yuk</b>? ── Iya, boleh tuh. <i>(setuju)</i>"},{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>、いっしょに<ruby>京都<rt>きょうと</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きませんか。 すみません、ちょっと…。","speech":"日曜日、いっしょに京都へ行きませんか。すみません、ちょっと…。","id":"Hari Minggu ke Kyoto bareng <b>yuk</b>? ── Maaf, agak… <i>(menolak halus)</i>"},{"jp":"ちょっと<ruby>休<rt>やす</rt></ruby>みませんか。","speech":"ちょっと休みませんか。","id":"<b>Gimana kalau</b> kita istirahat sebentar? <i>(usul)</i>"}],"dialogs":[{"jp":"ちょっと<ruby>散歩<rt>さんぽ</rt></ruby>に<ruby>行<rt>い</rt></ruby>き<b>ませんか</b>","speech":"ちょっと散歩に行きませんか","id":"<b>Gimana kalau</b> kita jalan-jalan sebentar? <i>(ajakan)</i>","source":"ガールズバンドクライ · EP09 · 19:04"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くん<ruby>少<rt>すこ</rt></ruby>しお<ruby>出<rt>で</rt></ruby>かけし<b>ませんか</b>?","speech":"周くん少しお出かけしませんか?","id":"Amane-kun, <b>mau</b> keluar sebentar <b>nggak</b>? <i>(ajakan halus)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP07 · 19:23"},{"jp":"じゃあ<ruby>最後<rt>さいご</rt></ruby>に お<ruby>参<rt>まい</rt></ruby>りだけして<ruby>帰<rt>かえ</rt></ruby>り<b>ませんか</b>?","speech":"じゃあ最後にお参りだけして帰りませんか?","id":"Kalau gitu, <b>gimana kalau</b> terakhir kita ke kuil dulu baru pulang? <i>(usul)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 18:25"},{"jp":"<ruby>先<rt>さき</rt></ruby>に お<ruby>参<rt>まい</rt></ruby>りしてき<b>ませんか</b>?","speech":"先にお参りしてきませんか?","id":"<b>Gimana kalau</b> kita berdoa di kuil dulu? <i>(usul)</i>","source":"ゆるキャン△ SEASON２ · EP02 · 14:26"},{"jp":"<ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>帰<rt>かえ</rt></ruby>り<b>ませんか</b>?　そして<ruby>帰<rt>かえ</rt></ruby>りに<ruby>買<rt>か</rt></ruby>い<ruby>食<rt>ぐ</rt></ruby>いでもしましょう","speech":"一緒に帰りませんか?　そして帰りに買い食いでもしましょう","id":"Pulang <b>bareng, yuk</b>? Terus di jalan kita jajan. <i>(ませんか → ましょう)</i>","source":"この素晴らしい世界に爆焔を！ · EP03 · 21:24"}]},{"id":"n5_b06_04","level":"N5","bab":6,"lokasi":"第6課","titleMain":"〜ましょう","titleSub":["〜ましょうか"],"meaning":"Ayo …! / Mari kita … · 〜ましょうか = yuk kita …? / mau saya …?","formula":"Ｖます → Ｖ<b>ましょう</b>（休み<b>ましょう</b>）<br>Lebih lembut / menawarkan: Ｖ<b>ましょうか</b><br>Bingung: どうし<b>ましょう</b>","nuance":"<ol><li><b>ましょう</b> = ajakan aktif, pembicara memimpin (さあ、行きましょう).</li><li><b>ましょうか</b> = ajakan lembut / menawarkan bantuan.</li><li>Jawaban atas ませんか: ええ、〜ましょう.</li></ol>⚠️ Ke atasan, ましょう bisa terdengar memerintah → pakai <b>ませんか</b>.","examples":[{"jp":"ちょっと<ruby>休<rt>やす</rt></ruby>みましょう。","speech":"ちょっと休みましょう。","id":"<b>Ayo</b> istirahat sebentar. <i>(ajakan)</i>"},{"jp":"ええ、 <ruby>見<rt>み</rt></ruby>ましょう。","speech":"ええ、見ましょう。","id":"Iya, <b>ayo nonton</b>! <i>(jawaban ませんか)</i>"},{"jp":"どこで<ruby>会<rt>あ</rt></ruby>いましょうか。 <ruby>駅<rt>えき</rt></ruby>で<ruby>会<rt>あ</rt></ruby>いましょう。","speech":"どこで会いましょうか。駅で会いましょう。","id":"<b>Kita ketemu</b> di mana? ── Ketemu di stasiun <b>aja</b>. <i>(ましょうか / ましょう)</i>"},{"jp":"さあ、 <ruby>始<rt>はじ</rt></ruby>めましょう。","speech":"さあ、始めましょう。","id":"Nah, <b>mari kita</b> mulai. <i>(ajakan)</i>"}],"dialogs":[{"jp":"よーし<ruby>後藤<rt>ごとう</rt></ruby>さん<ruby>頑張<rt>がんば</rt></ruby>り<b>ましょう</b>","speech":"よーし後藤さん頑張りましょう","id":"Oke! Gotoh-san, <b>ayo</b> berjuang! <i>(ajakan aktif)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 08:39"},{"jp":"<ruby>今<rt>いま</rt></ruby>は ゆっくり<ruby>休<rt>やす</rt></ruby>み<b>ましょう</b>","speech":"今はゆっくり休みましょう","id":"Sekarang <b>mari</b> kita istirahat dengan tenang. <i>(ajakan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP11 · 03:24"},{"jp":"<ruby>一緒<rt>いっしょ</rt></ruby>に ごはんを<ruby>食<rt>た</rt></ruby>べ<b>ましょう</b>ね<ruby>周<rt>あまね</rt></ruby>くん","speech":"一緒にごはんを食べましょうね周くん","id":"<b>Ayo</b> makan bareng ya, Amane-kun. <i>(ajakan lembut)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP12 · 16:06"},{"jp":"それじゃ<ruby>行<rt>い</rt></ruby>き<b>ましょうか</b>","speech":"それじゃ行きましょうか","id":"Kalau gitu, <b>yuk kita</b> berangkat? <i>(ましょうか)</i>","source":"ゆるキャン△ SEASON２ · EP10 · 00:34"},{"jp":"ど… どうし<b>ましょう</b>","speech":"ど… どうしましょう","id":"G-gimana <b>nih</b>…? <i>(どうしましょう · bingung)</i>","source":"ゆるキャン△ SEASON２ · EP10 · 15:00"}]},{"id":"n5_b07_01","level":"N5","bab":7,"lokasi":"第7課","titleMain":"〜で","titleSub":["はしで 食べます","日本語で"],"meaning":"Dengan / pakai [alat] · dalam bahasa …","formula":"Alat / media + <b>で</b> + KK（はし<b>で</b>食べます ・ メール<b>で</b>送ります）<br>Bahasa + <b>で</b>（日本語<b>で</b>書きます）<br>「Kata」は + Bahasa + <b>で何ですか</b>","nuance":"<ol><li><b>で</b> = sarana/cara melakukan sesuatu.</li><li>Kalimat wajib: 「Thank you」は日本語<b>で</b>何ですか.</li></ol>⚠️ で serba guna: kendaraan (第5課), tempat aksi (第6課), alat/bahasa (第7課). 何で bisa juga \"kenapa\" (kasual).","examples":[{"jp":"はしでごはんを<ruby>食<rt>た</rt></ruby>べます。","speech":"はしでごはんを食べます。","id":"Saya makan nasi <b>pakai sumpit</b>. <i>(alat)</i>"},{"jp":"<ruby>日本語<rt>にほんご</rt></ruby>でレポートを<ruby>書<rt>か</rt></ruby>きます。","speech":"日本語でレポートを書きます。","id":"Saya menulis laporan <b>dalam bahasa Jepang</b>. <i>(bahasa)</i>"},{"jp":"「ありがとう」は<ruby>英語<rt>えいご</rt></ruby>で <ruby>何<rt>なん</rt></ruby>ですか。","speech":"「ありがとう」は英語で何ですか。","id":"\"Arigatou\" <b>bahasa Inggrisnya</b> apa? <i>(〜で何ですか)</i>"},{"jp":"パソコンで <ruby>写真<rt>しゃしん</rt></ruby>を<ruby>送<rt>おく</rt></ruby>ります。","speech":"パソコンで写真を送ります。","id":"Saya kirim foto <b>lewat</b> komputer. <i>(media)</i>"}],"dialogs":[{"jp":"<ruby>箸<rt>はし</rt></ruby><b>で</b> <ruby>食<rt>た</rt></ruby>べるのがいいんだって","speech":"箸で食べるのがいいんだって","id":"Katanya paling enak dimakan <b>pakai sumpit</b>. <i>(alat)</i>","source":"ざつ旅-That's Journey- · EP10 · 15:01"},{"jp":"っていうより えっと… <ruby>日本語<rt>にほんご</rt></ruby><b>で</b> <ruby>何<rt>なん</rt></ruby>だっけ?","speech":"っていうよりえっと… 日本語で何だっけ?","id":"Atau lebih tepatnya… eh, <b>bahasa Jepangnya</b> apa ya? <i>(bahasa)</i>","source":"カードキャプターさくら · EP60 · 09:19"},{"jp":"<ruby>特殊<rt>とくしゅ</rt></ruby>で<ruby>何<rt>なに</rt></ruby>が<ruby>悪<rt>わる</rt></ruby>い<ruby>英語<rt>えいご</rt></ruby><b>で</b> <ruby>言<rt>い</rt></ruby>えばスペシャルだ","speech":"特殊で何が悪い英語で言えばスペシャルだ","id":"Apa salahnya jadi \"tokushu\"? <b>Dalam bahasa Inggris</b> itu \"special\"! <i>(bahasa)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP08 · 07:21"},{"jp":"メール<b>で</b> <ruby>連絡<rt>れんらく</rt></ruby>するなり すればいいのに","speech":"メールで連絡するなりすればいいのに","id":"Padahal bisa aja kabarin <b>lewat email</b> atau apa gitu. <i>(media)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP06 · 06:15"}]},{"id":"n5_b07_02","level":"N5","bab":7,"lokasi":"第7課","titleMain":"あげます","titleSub":["貸します","教えます"],"meaning":"Memberi (juga meminjamkan, mengajari) — aksi keluar dari pemberi","formula":"Pemberi <b>は</b> + Penerima <b>に</b> + Benda <b>を</b> + <b>あげます</b><br>Searah: <b>貸します</b> (meminjamkan) ・ <b>教えます</b> (mengajari) ・ 送ります","nuance":"<ol><li>Subjek = <b>pemberi</b>; penerima ditandai <b>に</b> (\"kepada\").</li><li>Sering dari \"aku\" ke orang lain, atau antar orang lain.</li></ol>⚠️ Kalau penerimanya <b>aku</b> → <b>くれます</b> (第24課), bukan あげます.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>木村<rt>きむら</rt></ruby>さんに<ruby>花<rt>はな</rt></ruby>をあげました。","speech":"私は木村さんに花をあげました。","id":"Saya <b>memberi</b> bunga kepada Bu Kimura. <i>(あげます)</i>"},{"jp":"カリナさんにCDを<ruby>貸<rt>か</rt></ruby>しました。","speech":"カリナさんにCDを貸しました。","id":"Saya <b>meminjamkan</b> CD ke Karina. <i>(貸します)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>はイーさんに<ruby>日本語<rt>にほんご</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えます。","speech":"私はイーさんに日本語を教えます。","id":"Saya <b>mengajari</b> Bu Lee bahasa Jepang. <i>(教えます)</i>"},{"jp":"<ruby>誕生日<rt>たんじょうび</rt></ruby>に<ruby>友達<rt>ともだち</rt></ruby>にプレゼントをあげます。","speech":"誕生日に友達にプレゼントをあげます。","id":"Saya <b>memberi</b> kado ke teman saat ulang tahunnya. <i>(あげます)</i>"}],"dialogs":[{"jp":"<ruby>千歳<rt>ちとせ</rt></ruby>さんにも<b>あげます</b>ね","speech":"千歳さんにもあげますね","id":"Chitose-san juga <b>aku kasih</b>, ya. <i>(に + あげます)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP06 · 04:02"},{"jp":"ぼっちちゃん　これ <b>あげる</b>","speech":"ぼっちちゃんこれあげる","id":"Bocchi-chan, ini <b>buat kamu</b>. <i>(あげる · kasual)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 10:42"},{"jp":"まひるんは チョコレート<ruby>誰<rt>だれ</rt></ruby>かに<b>あげる</b>の?","speech":"まひるんはチョコレート誰かにあげるの?","id":"Mahirun, cokelatnya mau <b>dikasih</b> ke seseorang? <i>(だれかにあげる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP06 · 03:48"},{"jp":"ホント? じゃあ<ruby>私<rt>わたし</rt></ruby>のも<b>あげる</b>","speech":"ホント? じゃあ私のもあげる","id":"Beneran? Kalau gitu punyaku juga <b>aku kasih</b>. <i>(tukar-menukar)</i>","source":"ゆるキャン△ · EP04 · 15:45"}]},{"id":"n5_b07_03","level":"N5","bab":7,"lokasi":"第7課","titleMain":"もらいます","titleSub":["借ります","習います"],"meaning":"Menerima / mendapat (juga meminjam, belajar dari) — aksi masuk ke penerima","formula":"Penerima <b>は</b> + Pemberi <b>に／から</b> + Benda <b>を</b> + <b>もらいます</b><br>Searah: <b>借ります</b> (meminjam) ・ <b>習います</b> (belajar dari)<br>Pemberi lembaga → wajib <b>から</b>","nuance":"<ol><li>Subjek = <b>penerima</b>; <b>に</b> di sini = \"<b>dari</b>\".</li><li>Kejadian sama dari sisi lain: 私は山田さんに本をもらいました = 山田さんは私に本をくれました.</li></ol>⚠️ <b>貸します</b> (meminjamkan) ≠ <b>借ります</b> (meminjam). 会社<b>から</b>もらいました (lembaga).","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>山田<rt>やまだ</rt></ruby>さんに<ruby>本<rt>ほん</rt></ruby>をもらいました。","speech":"私は山田さんに本をもらいました。","id":"Saya <b>dapat</b> buku <b>dari</b> Pak Yamada. <i>(に = dari)</i>"},{"jp":"<ruby>母<rt>はは</rt></ruby>からプレゼントをもらいました。","speech":"母からプレゼントをもらいました。","id":"Saya <b>dapat</b> kado <b>dari</b> ibu. <i>(から)</i>"},{"jp":"<ruby>友達<rt>ともだち</rt></ruby>にお<ruby>金<rt>かね</rt></ruby>を<ruby>借<rt>か</rt></ruby>りました。","speech":"友達にお金を借りました。","id":"Saya <b>pinjam</b> uang <b>dari</b> teman. <i>(借ります)</i>"},{"jp":"<ruby>会社<rt>かいしゃ</rt></ruby>から<ruby>時計<rt>とけい</rt></ruby>をもらいました。","speech":"会社から時計をもらいました。","id":"Saya <b>dapat</b> jam tangan <b>dari</b> perusahaan. <i>(lembaga → から)</i>"}],"dialogs":[{"jp":"いっぱい いっぱい<ruby>周<rt>あまね</rt></ruby>くんから<b>もらいました</b>","speech":"いっぱいいっぱい周くんからもらいました","id":"Aku udah <b>dapat</b> banyak banget <b>dari</b> Amane-kun. <i>(から + もらう)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP07 · 20:12"},{"jp":"ストーカー<ruby>兄<rt>にい</rt></ruby>ちゃんから <b>もらった</b>","speech":"ストーカー兄ちゃんからもらった","id":"<b>Dapat dari</b> Kakak Stalker. <i>(もらった · kasual)</i>","source":"この素晴らしい世界に爆焔を！ · EP05 · 01:31"},{"jp":"モモから<b>もらった</b>シールも","speech":"モモからもらったシールも","id":"Stiker yang <b>dikasih</b> Momo juga… <i>(もらった + KB)</i>","source":"ガールズバンドクライ · EP07 · 13:39"},{"jp":"お<ruby>父<rt>とう</rt></ruby>さんから<b><ruby>借<rt>か</rt></ruby>りた</b>ギター　ライブで<ruby>壊<rt>こわ</rt></ruby>してしまいました","speech":"お父さんから借りたギターライブで壊してしまいました","id":"Gitar yang <b>kupinjam dari</b> Ayah… rusak waktu live. <i>(借りる)</i>","source":"ぼっち・ざ・ろっく！ · EP12 · 11:10"}]},{"id":"n5_b07_04","level":"N5","bab":7,"lokasi":"第7課","titleMain":"もう〜ました","titleSub":["まだです"],"meaning":"Sudah … / belum","formula":"<b>もう</b> + Ｖ<b>ました</b>（もう送りました）<br>Tanya: <b>もう</b>〜<b>ましたか</b><br>Belum: いいえ、<b>まだです</b>","nuance":"<ol><li><b>もう〜ました</b> = aksi sudah selesai.</li><li>Jawaban \"belum\" = <b>まだです</b>.</li></ol>⚠️ ×いいえ、送りませんでした = \"tidak mengirim\" (beda makna). もう + negatif = \"sudah tidak lagi\".","examples":[{"jp":"もう <ruby>荷物<rt>にもつ</rt></ruby>を<ruby>送<rt>おく</rt></ruby>りましたか。 はい、もう <ruby>送<rt>おく</rt></ruby>りました。","speech":"もう荷物を送りましたか。はい、もう送りました。","id":"Paketnya <b>sudah</b> dikirim? ── Iya, <b>sudah</b>. <i>(sudah)</i>"},{"jp":"もう <ruby>昼<rt>ひる</rt></ruby>ごはんを<ruby>食<rt>た</rt></ruby>べましたか。 いいえ、まだです。","speech":"もう昼ごはんを食べましたか。いいえ、まだです。","id":"<b>Sudah</b> makan siang? ── <b>Belum</b>. <i>(belum)</i>"},{"jp":"もう <ruby>新幹線<rt>しんかんせん</rt></ruby>の<ruby>切符<rt>きっぷ</rt></ruby>を<ruby>買<rt>か</rt></ruby>いましたか。","speech":"もう新幹線の切符を買いましたか。","id":"<b>Sudah</b> beli tiket Shinkansen? <i>(tanya)</i>"}],"dialogs":[{"jp":"ねっ お<ruby>願<rt>ねが</rt></ruby>い<ruby>事<rt>ごと</rt></ruby><b>もう<ruby>決<rt>き</rt></ruby>めた</b>?","speech":"ねっお願い事もう決めた?","id":"Eh, permohonannya <b>udah kamu tentuin</b>? <i>(もう〜た · kasual)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 08:07"},{"jp":"<ruby>晩御飯<rt>ばんごはん</rt></ruby><b>もう<ruby>食<rt>た</rt></ruby>べちゃった</b>?","speech":"晩御飯もう食べちゃった?","id":"Makan malamnya <b>udah</b> kamu makan? <i>(もう〜ちゃった)</i>","source":"ゆるキャン△ · EP02 · 20:10"},{"jp":"<b>まだです</b>　 <ruby>急<rt>いそ</rt></ruby>いでください","speech":"まだです急いでください","id":"<b>Belum</b>. Tolong cepat. <i>(まだです)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP10 · 10:59"},{"jp":"<ruby>名前<rt>なまえ</rt></ruby>は<b>まだです</b>","speech":"名前はまだです","id":"Namanya <b>belum</b> ada. <i>(まだです)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 06:38"}]},{"id":"n5_b08_01","level":"N5","bab":8,"lokasi":"第8課","titleMain":"い形容詞","titleSub":["高いです","高くないです","高い山"],"meaning":"Kata sifat berakhiran い (高い, 寒い, おいしい) — predikat & penerang kata benda","formula":"Positif: KS-い + <b>です</b>（高いです）<br>Negatif: KS-<s>い</s> + <b>くないです</b>（高くないです）<br>+ KB langsung: <b>高い山</b> · Pengecualian: いい → <b>よくない</b>","nuance":"<ol><li>Menerangkan KB <b>tanpa</b> の/な: 高い山.</li><li>Negatif = buang い + <b>くない</b> (formal: くありません).</li></ol>⚠️ ×高いじゃありません. <b>いい → よくない</b>. きれい・きらい・ゆうめい = KS-な (jebakan!).","examples":[{"jp":"<ruby>富士山<rt>ふじさん</rt></ruby>は<ruby>高<rt>たか</rt></ruby>いです。","speech":"富士山は高いです。","id":"Gunung Fuji <b>tinggi</b>. <i>(predikat)</i>"},{"jp":"この<ruby>料理<rt>りょうり</rt></ruby>はあまりおいしくないです。","speech":"この料理はあまりおいしくないです。","id":"Masakan ini <b>kurang enak</b>. <i>(negatif)</i>"},{"jp":"<ruby>富士山<rt>ふじさん</rt></ruby>は<ruby>高<rt>たか</rt></ruby>い<ruby>山<rt>やま</rt></ruby>です。","speech":"富士山は高い山です。","id":"Gunung Fuji <b>gunung yang tinggi</b>. <i>(+ KB)</i>"},{"jp":"このカメラはよくないです。","speech":"このカメラはよくないです。","id":"Kamera ini <b>nggak bagus</b>. <i>(いい → よくない)</i>"}],"dialogs":[{"jp":"はい <b>おいしいです</b>","speech":"はいおいしいです","id":"Iya, <b>enak</b>. <i>(KS-い + です)</i>","source":"ガールズバンドクライ · EP03 · 04:11"},{"jp":"こんにちは <b><ruby>寒<rt>さむ</rt></ruby>いです</b>よね","speech":"こんにちは寒いですよね","id":"Halo, <b>dingin</b> ya. <i>(KS-い + です)</i>","source":"ゆるキャン△ SEASON２ · EP01 · 12:42"},{"jp":"<b><ruby>寒<rt>さむ</rt></ruby>くない</b>のかな…","speech":"寒くないのかな…","id":"Dia <b>nggak kedinginan</b>, ya…? <i>(くない)</i>","source":"ゆるキャン△ · EP05 · 12:03"},{"jp":"<ruby>宿<rt>やど</rt></ruby>では たっぷりと<b>おいしい<ruby>魚<rt>さかな</rt></ruby></b>を<ruby>召<rt>め</rt></ruby>し<ruby>上<rt>あ</rt></ruby>がっていただきたいのです","speech":"宿ではたっぷりとおいしい魚を召し上がっていただきたいのです","id":"Di penginapan saya ingin Anda menikmati banyak <b>ikan yang enak</b>. <i>(KS-い + KB)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP14 · 09:10"}]},{"id":"n5_b08_02","level":"N5","bab":8,"lokasi":"第8課","titleMain":"な形容詞","titleSub":["静かな町","静かじゃありません"],"meaning":"Kata sifat yang butuh な saat menerangkan kata benda (静か, きれい, 親切, 有名)","formula":"Positif: KS-な + <b>です</b>（静かです）<br>Negatif: KS-な + <b>じゃありません</b><br>+ KB: KS + <b>な</b> + KB（静か<b>な</b>町）","nuance":"<ol><li>Sebagai predikat, perilakunya <b>seperti kata benda</b>.</li><li>Saat menerangkan KB wajib <b>な</b>.</li></ol>⚠️ ×静かくない ×静か町. Jebakan berakhiran い: <b>きれい・きらい・ゆうめい</b> = KS-な.","examples":[{"jp":"<ruby>奈良<rt>なら</rt></ruby>は<ruby>静<rt>しず</rt></ruby>かな <ruby>町<rt>まち</rt></ruby>です。","speech":"奈良は静かな町です。","id":"Nara adalah kota yang <b>tenang</b>. <i>(な + KB)</i>"},{"jp":"<ruby>山田<rt>やまだ</rt></ruby>さんは<ruby>親切<rt>しんせつ</rt></ruby>な <ruby>人<rt>ひと</rt></ruby>です。","speech":"山田さんは親切な人です。","id":"Pak Yamada orang yang <b>baik hati</b>. <i>(な + KB)</i>"},{"jp":"この<ruby>部屋<rt>へや</rt></ruby>はきれいじゃありません。","speech":"この部屋はきれいじゃありません。","id":"Kamar ini <b>nggak bersih</b>. <i>(negatif)</i>"},{"jp":"ワットさんは<ruby>元気<rt>げんき</rt></ruby>です。","speech":"ワットさんは元気です。","id":"Pak Watt <b>sehat</b>. <i>(predikat)</i>"}],"dialogs":[{"jp":"<b><ruby>静<rt>しず</rt></ruby>かな</b> いい<ruby>店<rt>みせ</rt></ruby>ですね","speech":"静かないい店ですね","id":"Toko yang <b>tenang</b> dan enak, ya. <i>(な + KB)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP17 · 08:26"},{"jp":"おー <b>きれいな</b> <ruby>体育館<rt>たいいくかん</rt></ruby>だね","speech":"おーきれいな体育館だね","id":"Wah, aula olahraganya <b>bagus</b>, ya. <i>(きれいな · jebakan い)</i>","source":"ぼっち・ざ・ろっく！ · EP11 · 14:16"},{"jp":"ねえ <b><ruby>親切<rt>しんせつ</rt></ruby>な</b>お<ruby>兄<rt>にい</rt></ruby>ちゃん　お<ruby>名前<rt>なまえ</rt></ruby><ruby>教<rt>おし</rt></ruby>えて","speech":"ねえ親切なお兄ちゃんお名前教えて","id":"Hei, Kakak yang <b>baik hati</b>, kasih tahu namamu dong. <i>(な + KB)</i>","source":"この素晴らしい世界に祝福を！2 · EP08 · 21:19"},{"jp":"<ruby>別<rt>べつ</rt></ruby>に そこまで<b><ruby>有名<rt>ゆうめい</rt></ruby>じゃない</b>よ","speech":"別にそこまで有名じゃないよ","id":"Nggak <b>terkenal</b> sampai segitunya kok. <i>(negatif · kasual)</i>","source":"ガールズバンドクライ · EP13 · 06:34"},{"jp":"ここは <b><ruby>有名<rt>ゆうめい</rt></ruby>な</b>イソスタ<ruby>映<rt>ば</rt></ruby>えスポット","speech":"ここは有名なイソスタ映えスポット","id":"Ini spot foto Isusta yang <b>terkenal</b>. <i>(な + KB)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 07:21"}]},{"id":"n5_b08_03","level":"N5","bab":8,"lokasi":"第8課","titleMain":"とても・あまり〜ない","titleSub":[],"meaning":"とても = sangat · あまり + negatif = tidak terlalu / kurang / jarang","formula":"<b>とても</b> + KS positif（とてもおいしいです）<br><b>あまり</b> + KS-い<b>くない</b> ／ KS-な<b>じゃありません</b> ／ KK<b>ません</b>","nuance":"<ol><li><b>とても</b> menguatkan sifat positif; lisan: <b>とっても</b>.</li><li><b>あまり</b> selalu berpasangan dengan <b>negatif</b>.</li></ol>⚠️ ×あまりおいしいです. \"Sama sekali tidak\" = <b>ぜんぜん</b> (第9課).","examples":[{"jp":"このケーキはとてもおいしいです。","speech":"このケーキはとてもおいしいです。","id":"Kue ini <b>sangat</b> enak. <i>(とても)</i>"},{"jp":"この<ruby>料理<rt>りょうり</rt></ruby>はあまりおいしくないです。","speech":"この料理はあまりおいしくないです。","id":"Masakan ini <b>kurang</b> enak. <i>(あまり + くない)</i>"},{"jp":"<ruby>北京<rt>ペキン</rt></ruby>は<ruby>今<rt>いま</rt></ruby>、とても <ruby>寒<rt>さむ</rt></ruby>いです。","speech":"北京は今、とても寒いです。","id":"Beijing sekarang <b>sangat</b> dingin. <i>(とても)</i>"},{"jp":"この<ruby>町<rt>まち</rt></ruby>はあまり <ruby>有名<rt>ゆうめい</rt></ruby>じゃありません。","speech":"この町はあまり有名じゃありません。","id":"Kota ini <b>nggak terlalu</b> terkenal. <i>(あまり + じゃありません)</i>"}],"dialogs":[{"jp":"<b>とっても</b> <ruby>美味<rt>おい</rt></ruby>しいです","speech":"とっても美味しいです","id":"<b>Enak banget</b>. <i>(とっても · lisan)</i>","source":"トニカクカワイイ · EP10 · 06:45"},{"jp":"<ruby>標高<rt>ひょうこう</rt></ruby>は <b>あまり</b> <ruby>高<rt>たか</rt></ruby><b>くない</b>のに<ruby>意外<rt>いがい</rt></ruby>と<ruby>寒<rt>さむ</rt></ruby>いですよね ここ","speech":"標高はあまり高くないのに意外と寒いですよねここ","id":"Padahal ketinggiannya <b>nggak terlalu</b> tinggi, tapi di sini ternyata dingin, ya. <i>(あまり + くない)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 06:41"},{"jp":"だから<ruby>春<rt>はる</rt></ruby>は <b>あまり</b> <ruby>好<rt>す</rt></ruby>き<b>じゃない</b>です","speech":"だから春はあまり好きじゃないです","id":"Makanya aku <b>nggak terlalu</b> suka musim semi. <i>(あまり + じゃない)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP07 · 21:22"},{"jp":"<ruby>僕<rt>ぼく</rt></ruby><ruby>映画<rt>えいが</rt></ruby>って<b>あまり</b> <ruby>見<rt>み</rt></ruby><b>ない</b>から","speech":"僕映画ってあまり見ないから","id":"Soalnya aku <b>jarang</b> nonton film. <i>(あまり + KK negatif)</i>","source":"トニカクカワイイ · EP05 · 00:43"}]},{"id":"n5_b08_04","level":"N5","bab":8,"lokasi":"第8課","titleMain":"どう・どんな","titleSub":["〜はどうですか","どんなＮ"],"meaning":"どう = bagaimana (kesan) · どんな + N = N yang seperti apa","formula":"KB は <b>どう</b>ですか（日本の生活は<b>どう</b>ですか）<br><b>どんな</b> + KB ですか（<b>どんな</b>町ですか）<br>Juga: <b>どれ</b> = yang mana · 〜<b>が</b>、〜 = tapi","nuance":"<ol><li><b>どう</b> berdiri sendiri: menanyakan kesan / keadaan.</li><li><b>どんな</b> wajib + KB: menanyakan sifat / jenis.</li><li>〜はどうですか juga = menawarkan (コーヒーはどうですか).</li></ol>⚠️ ×どんなですか → ○どうですか. ×どう町 → ○どんな町.","examples":[{"jp":"<ruby>日本<rt>にほん</rt></ruby>の<ruby>生活<rt>せいかつ</rt></ruby>はどうですか。","speech":"日本の生活はどうですか。","id":"Kehidupan di Jepang <b>gimana</b>? <i>(どう)</i>"},{"jp":"<ruby>奈良<rt>なら</rt></ruby>はどんな<ruby>町<rt>まち</rt></ruby>ですか。 <ruby>静<rt>しず</rt></ruby>かな<ruby>町<rt>まち</rt></ruby>です。","speech":"奈良はどんな町ですか。静かな町です。","id":"Nara itu kota <b>yang seperti apa</b>? ── Kota yang tenang. <i>(どんな)</i>"},{"jp":"ワットさんはどんな<ruby>先生<rt>せんせい</rt></ruby>ですか。","speech":"ワットさんはどんな先生ですか。","id":"Pak Watt guru <b>yang seperti apa</b>? <i>(どんな)</i>"},{"jp":"コーヒーはどうですか。","speech":"コーヒーはどうですか。","id":"<b>Mau</b> kopi? <i>(どう · menawarkan)</i>"}],"dialogs":[{"jp":"<b>どうですか</b>? <ruby>似合<rt>にあ</rt></ruby>ってますか?","speech":"どうですか? 似合ってますか?","id":"<b>Gimana</b>? Cocok nggak? <i>(どうですか · minta kesan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 15:35"},{"jp":"<b>どんな<ruby>雰囲気<rt>ふんいき</rt></ruby></b>なんだろう","speech":"どんな雰囲気なんだろう","id":"Suasananya <b>kayak gimana</b>, ya? <i>(どんな + KB)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 05:11"},{"jp":"なでしこちゃんは <b>どんなバイト</b>がええん?","speech":"なでしこちゃんはどんなバイトがええん?","id":"Nadeshiko-chan mau kerja sambilan <b>yang kayak apa</b>? <i>(どんな + KB · dialek)</i>","source":"ゆるキャン△ SEASON２ · EP04 · 15:22"},{"jp":"で<ruby>今日<rt>きょう</rt></ruby>は <b>どんなご<ruby>用件<rt>ようけん</rt></ruby></b>で?","speech":"で今日はどんなご用件で?","id":"Jadi, hari ini ada <b>keperluan apa</b>? <i>(どんな + KB · sopan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP03 · 06:05"}]},{"id":"n5_b09_01","level":"N5","bab":9,"lokasi":"第9課","titleMain":"〜が好きです","titleSub":["嫌い","上手","下手"],"meaning":"Suka / nggak suka / jago / payah (dalam) … — objeknya pakai が","formula":"Orang <b>は</b> + Objek <b>が</b> + <b>好き・嫌い・上手・下手</b> です<br>（私はイタリア料理<b>が好き</b>です）<br>+ KB: 好き<b>な</b>食べ物","nuance":"<ol><li>好き・嫌い・上手・下手 = <b>KS-な</b>, objeknya <b>が</b> (bukan を).</li><li>Tanya: <b>どんな</b>〜が好きですか.</li></ol>⚠️ ×野菜を好きです. <b>上手</b> jangan untuk diri sendiri (sombong) → 得意.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>はイタリア<ruby>料理<rt>りょうり</rt></ruby>が<ruby>好<rt>す</rt></ruby>きです。","speech":"私はイタリア料理が好きです。","id":"Saya <b>suka</b> masakan Italia. <i>(好き)</i>"},{"jp":"サントスさんはサッカーが<ruby>上手<rt>じょうず</rt></ruby>です。","speech":"サントスさんはサッカーが上手です。","id":"Pak Santos <b>jago</b> sepak bola. <i>(上手)</i>"},{"jp":"どんなスポーツが<ruby>好<rt>す</rt></ruby>きですか。","speech":"どんなスポーツが好きですか。","id":"<b>Suka</b> olahraga apa? <i>(どんな〜が好き)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>料理<rt>りょうり</rt></ruby>があまり<ruby>上手<rt>じょうず</rt></ruby>じゃありません。","speech":"私は料理があまり上手じゃありません。","id":"Saya <b>nggak terlalu jago</b> masak. <i>(negatif)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby> この<ruby>街<rt>まち</rt></ruby><b>が<ruby>好<rt>す</rt></ruby>き</b>です","speech":"私この街が好きです","id":"Aku <b>suka</b> kota ini. <i>(が好き)</i>","source":"ガールズバンドクライ · EP13 · 16:14"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんは<ruby>短<rt>みじか</rt></ruby>いのと<ruby>長<rt>なが</rt></ruby>いの どっち<b>が<ruby>好<rt>す</rt></ruby>き</b>ですか?","speech":"周くんは短いのと長いのどっちが好きですか?","id":"Amane-kun <b>lebih suka</b> yang pendek atau yang panjang? <i>(どっちが好き)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 10:56"},{"jp":"<ruby>爆裂<rt>ばくれつ</rt></ruby><ruby>魔法<rt>まほう</rt></ruby>だけ<b>が<ruby>好<rt>す</rt></ruby>き</b>なのです!","speech":"爆裂魔法だけが好きなのです!","id":"Aku <b>cuma suka</b> sihir ledakan! <i>(だけが好き)</i>","source":"この素晴らしい世界に祝福を！ · EP02 · 16:51"},{"jp":"わっちゃあ<ruby>本当<rt>ほんとう</rt></ruby>に<ruby>羊飼<rt>ひつじか</rt></ruby>い<b>が<ruby>嫌<rt>きら</rt></ruby>い</b>なんじゃ","speech":"わっちゃあ本当に羊飼いが嫌いなんじゃ","id":"Aku ini betul-betul <b>benci</b> penggembala domba. <i>(が嫌い)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP12 · 07:00"},{"jp":"<ruby>手<rt>て</rt></ruby>が<ruby>温<rt>あたた</rt></ruby>かいこととか<ruby>料理<rt>りょうり</rt></ruby><b>が<ruby>上手<rt>じょうず</rt></ruby></b>なこととか","speech":"手が温かいこととか料理が上手なこととか","id":"Tangannya hangat, <b>jago</b> masak, gitu-gitu. <i>(が上手)</i>","source":"トニカクカワイイ · EP04 · 17:10"}]},{"id":"n5_b09_02","level":"N5","bab":9,"lokasi":"第9課","titleMain":"〜がわかります・〜があります","titleSub":[],"meaning":"Mengerti … · punya / ada (urusan, waktu, uang) … — objeknya pakai が","formula":"Orang <b>は</b> + Objek <b>が</b> + <b>わかります</b>（ひらがな<b>が</b>わかります）<br>Orang <b>は</b> + Benda <b>が</b> + <b>あります</b>（車<b>が</b>あります）<br>用事・約束・時間<b>があります</b>","nuance":"<ol><li>KK <b>keadaan</b> (bukan aksi) → objek pakai <b>が</b>.</li><li><b>あります</b> di sini = <b>punya</b> (benda mati / urusan).</li><li><b>わかりました</b> = \"baik, saya mengerti\".</li></ol>⚠️ ×ひらがなをわかります. Punya anak/saudara (makhluk hidup) → <b>います</b>.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>はひらがながわかります。","speech":"私はひらがながわかります。","id":"Saya <b>mengerti</b> hiragana. <i>(わかります)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>車<rt>くるま</rt></ruby>があります。","speech":"私は車があります。","id":"Saya <b>punya</b> mobil. <i>(あります = punya)</i>"},{"jp":"お<ruby>金<rt>かね</rt></ruby>がありますか。 いいえ、ありません。","speech":"お金がありますか。いいえ、ありません。","id":"<b>Punya</b> uang? ── Nggak punya. <i>(tanya)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>時間<rt>じかん</rt></ruby>がありません。","speech":"今日は時間がありません。","id":"Hari ini saya <b>nggak ada</b> waktu. <i>(negatif)</i>"}],"dialogs":[{"jp":"ごめん ちょっと<ruby>意味<rt>いみ</rt></ruby><b>が<ruby>分<rt>わ</rt></ruby>からない</b>","speech":"ごめんちょっと意味が分からない","id":"Maaf, aku agak <b>nggak ngerti</b> maksudnya. <i>(がわからない · kasual)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP08 · 14:23"},{"jp":"<ruby>気<rt>き</rt></ruby>に<ruby>入<rt>い</rt></ruby>られた<ruby>理由<rt>りゆう</rt></ruby><b>がわかりません</b>","speech":"気に入られた理由がわかりません","id":"Saya <b>nggak ngerti</b> kenapa saya disukai. <i>(がわかりません)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP08 · 17:40"},{"jp":"ちょっと<ruby>北<rt>きた</rt></ruby>のほうに<ruby>用事<rt>ようじ</rt></ruby><b>があって</b>な　 <ruby>道<rt>みち</rt></ruby>や<ruby>土地<rt>とち</rt></ruby>の<ruby>様子<rt>ようす</rt></ruby>を<ruby>知<rt>し</rt></ruby>りたいんだ","speech":"ちょっと北のほうに用事があってな道や土地の様子を知りたいんだ","id":"Aku <b>ada urusan</b> ke utara, jadi pengin tahu kondisi jalan dan daerahnya. <i>(用事がある)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP02 · 02:25"},{"jp":"お<ruby>金<rt>かね</rt></ruby><b>がない</b>んです! なんだと!","speech":"お金がないんです! なんだと!","id":"Aku <b>nggak punya</b> uang! — Apa?! <i>(がない = punya, negatif)</i>","source":"この素晴らしい世界に爆焔を！ · EP10 · 13:28"}]},{"id":"n5_b09_03","level":"N5","bab":9,"lokasi":"第9課","titleMain":"〜から","titleSub":["どうして〜か"],"meaning":"Karena … · どうして = kenapa","formula":"[Alasan] + <b>から</b>、[Hasil]（用事があります<b>から</b>、早く帰ります）<br>Jawaban: 〜<b>から</b>（です）<br>Tanya: <b>どうして</b>〜か","nuance":"<ol><li>Alasan selalu <b>di depan</b> から; nuansanya subjektif (sudut pandang pembicara).</li><li>Kasual: <b>なんで</b> (kenapa), dan 〜から sering menutup kalimat.</li></ol>⚠️ KB/waktu + から = \"dari\" (第4課). ので (N4) lebih halus/objektif.","examples":[{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>用事<rt>ようじ</rt></ruby>がありますから、 <ruby>早<rt>はや</rt></ruby>く<ruby>帰<rt>かえ</rt></ruby>ります。","speech":"今日は用事がありますから、早く帰ります。","id":"<b>Karena</b> hari ini ada urusan, saya pulang lebih awal. <i>(alasan → hasil)</i>"},{"jp":"どうして <ruby>朝<rt>あさ</rt></ruby><ruby>新聞<rt>しんぶん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>みませんか。 <ruby>時間<rt>じかん</rt></ruby>がありませんから。","speech":"どうして朝新聞を読みませんか。時間がありませんから。","id":"<b>Kenapa</b> nggak baca koran pagi? ── <b>Karena</b> nggak ada waktu. <i>(どうして → から)</i>"},{"jp":"<ruby>寒<rt>さむ</rt></ruby>いですから、 <ruby>窓<rt>まど</rt></ruby>を<ruby>閉<rt>し</rt></ruby>めます。","speech":"寒いですから、窓を閉めます。","id":"<b>Karena</b> dingin, saya tutup jendelanya. <i>(alasan)</i>"}],"dialogs":[{"jp":"スタジオで<ruby>撮<rt>と</rt></ruby>るのは お<ruby>金<rt>かね</rt></ruby>がない<b>から</b> <ruby>無理<rt>むり</rt></ruby>","speech":"スタジオで撮るのはお金がないから無理","id":"Foto di studio nggak bisa, <b>soalnya</b> nggak ada duit. <i>(alasan · kasual)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 09:17"},{"jp":"リンちゃん! <ruby>寒<rt>さむ</rt></ruby>い<b>から</b> やだ","speech":"リンちゃん! 寒いからやだ","id":"Rin-chan! Nggak mau, <b>soalnya</b> dingin. <i>(alasan)</i>","source":"ゆるキャン△ · EP07 · 15:59"},{"jp":"どうぞ たぶん<ruby>熱<rt>あつ</rt></ruby>くないです<b>から</b>","speech":"どうぞたぶん熱くないですから","id":"Silakan, <b>soalnya</b> kayaknya udah nggak panas. <i>(〜ですから)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP01 · 07:20"},{"jp":"<ruby>当然<rt>とうぜん</rt></ruby>です レメリオさん　 <ruby>私<rt>わたし</rt></ruby>も<ruby>商人<rt>しょうにん</rt></ruby>です<b>から</b>","speech":"当然ですレメリオさん私も商人ですから","id":"Tentu, Pak Lemerio. <b>Karena</b> saya juga pedagang. <i>(〜ですから · jawaban)</i>","source":"狼と香辛料 · EP10 · 09:38"},{"jp":"<b>どうして</b>ですか","speech":"どうしてですか","id":"<b>Kenapa</b>? <i>(どうして)</i>","source":"狼と香辛料 · EP12 · 10:12"}]},{"id":"n5_b09_04","level":"N5","bab":9,"lokasi":"第9課","titleMain":"よく・だいたい・少し・ぜんぜん","titleSub":["たくさん","あまり"],"meaning":"Kata keterangan kadar: dengan baik · sebagian besar · sedikit · sama sekali tidak","formula":"Positif: <b>よく</b> ＞ <b>だいたい</b> ＞ <b>少し</b> + わかります（<b>たくさん</b> = banyak）<br>Negatif: <b>あまり</b> ＞ <b>ぜんぜん</b> + わかりません","nuance":"<ol><li>よく・だいたい・たくさん・少し → <b>positif</b>.</li><li>あまり・ぜんぜん → <b>negatif</b>.</li><li><b>よく分からない</b> = \"kurang ngerti\" (sangat umum).</li></ol>⚠️ ぜんぜん + positif (全然大丈夫) itu lisan anak muda; di Minna pasangkan dengan negatif.","examples":[{"jp":"<ruby>英語<rt>えいご</rt></ruby>がよくわかります。","speech":"英語がよくわかります。","id":"Saya paham bahasa Inggris <b>dengan baik</b>. <i>(よく)</i>"},{"jp":"<ruby>日本語<rt>にほんご</rt></ruby>が<ruby>少<rt>すこ</rt></ruby>しわかります。","speech":"日本語が少しわかります。","id":"Saya ngerti bahasa Jepang <b>sedikit</b>. <i>(少し)</i>"},{"jp":"フランス<ruby>語<rt>ご</rt></ruby>がぜんぜんわかりません。","speech":"フランス語がぜんぜんわかりません。","id":"Saya <b>sama sekali nggak</b> ngerti bahasa Prancis. <i>(ぜんぜん)</i>"},{"jp":"お<ruby>金<rt>かね</rt></ruby>がたくさんあります。","speech":"お金がたくさんあります。","id":"Saya punya <b>banyak</b> uang. <i>(たくさん)</i>"}],"dialogs":[{"jp":"<b>よく</b> <ruby>分<rt>わ</rt></ruby>かりましたね","speech":"よく分かりましたね","id":"Kamu <b>tahu betul</b>, ya. <i>(よく = dengan baik)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP07 · 08:35"},{"jp":"ソロキャンの<ruby>始<rt>はじ</rt></ruby>め<ruby>方<rt>かた</rt></ruby> <b><ruby>大体<rt>だいたい</rt></ruby></b> <ruby>分<rt>わ</rt></ruby>かったよ","speech":"ソロキャンの始め方大体分かったよ","id":"Cara mulai solo camping, aku <b>udah lumayan</b> ngerti. <i>(だいたい)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 07:37"},{"jp":"<ruby>彼女<rt>かのじょ</rt></ruby>が<ruby>君<rt>きみ</rt></ruby>を<ruby>気<rt>き</rt></ruby>にかける<ruby>理由<rt>りゆう</rt></ruby>が<b><ruby>少<rt>すこ</rt></ruby>し</b> <ruby>分<rt>わ</rt></ruby>かったよ","speech":"彼女が君を気にかける理由が少し分かったよ","id":"Aku jadi <b>sedikit</b> ngerti kenapa dia peduli sama kamu. <i>(少し)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP08 · 15:22"},{"jp":"<b><ruby>全然<rt>ぜんぜん</rt></ruby></b> <ruby>意味<rt>いみ</rt></ruby><ruby>分<rt>わ</rt></ruby>かんないんだけど…","speech":"全然意味分かんないんだけど…","id":"Aku <b>sama sekali nggak</b> ngerti maksudnya… <i>(ぜんぜん + negatif)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 14:40"}]},{"id":"n5_b10_01","level":"N5","bab":10,"lokasi":"第10課","titleMain":"〜に〜があります・います","titleSub":[],"meaning":"Di [tempat] ada [sesuatu / seseorang] — memperkenalkan apa yang ada","formula":"Tempat + <b>に</b> + KB + <b>が</b> + <b>あります</b> (benda mati / tumbuhan)<br>Tempat + <b>に</b> + KB + <b>が</b> + <b>います</b> (orang / hewan)<br>Tanya: <b>何が</b>ありますか ・ <b>だれが</b>いますか","nuance":"<ol><li><b>あります</b> = benda mati & tumbuhan; <b>います</b> = makhluk hidup yang bergerak.</li><li><b>に</b> = tempat keberadaan; <b>が</b> = hal baru yang diperkenalkan.</li></ol>⚠️ ロビー<b>に</b>います (ada) vs ロビー<b>で</b>待ちます (aksi). Mobil = あります, ikan = います.","examples":[{"jp":"あそこに <ruby>銀行<rt>ぎんこう</rt></ruby>があります。","speech":"あそこに銀行があります。","id":"Di sana <b>ada</b> bank. <i>(あります)</i>"},{"jp":"ロビーに <ruby>佐藤<rt>さとう</rt></ruby>さんがいます。","speech":"ロビーに佐藤さんがいます。","id":"Di lobi <b>ada</b> Bu Sato. <i>(います)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>の<ruby>部屋<rt>へや</rt></ruby>に <ruby>机<rt>つくえ</rt></ruby>があります。","speech":"私の部屋に机があります。","id":"Di kamar saya <b>ada</b> meja. <i>(あります)</i>"},{"jp":"<ruby>庭<rt>にわ</rt></ruby>にだれもいません。","speech":"庭にだれもいません。","id":"Di taman <b>nggak ada</b> siapa-siapa. <i>(だれも + negatif)</i>"}],"dialogs":[{"jp":"<ruby>断崖<rt>だんがい</rt></ruby><b>に</b>は<ruby>露天風呂<rt>ろてんぶろ</rt></ruby><b>があります</b>","speech":"断崖には露天風呂があります","id":"Di tebing <b>ada</b> pemandian terbuka. <i>(benda → あります)</i>","source":"ゆるキャン△ SEASON２ · EP11 · 20:31"},{"jp":"こことここ<b>に</b> <ruby>経営<rt>けいえい</rt></ruby>の<ruby>無駄<rt>むだ</rt></ruby><b>があります</b>","speech":"こことここに経営の無駄があります","id":"Di sini dan sini <b>ada</b> pemborosan pengelolaan. <i>(あります)</i>","source":"トニカクカワイイ · EP03 · 19:49"},{"jp":"<ruby>部室<rt>ぶしつ</rt></ruby><b>に</b> <ruby>不審<rt>ふしん</rt></ruby><ruby>人物<rt>じんぶつ</rt></ruby><b>がいる</b>の","speech":"部室に不審人物がいるの","id":"Di ruang klub <b>ada</b> orang mencurigakan! <i>(orang → いる)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP02 · 11:17"},{"jp":"ここ<b>に</b> いい<ruby>例<rt>れい</rt></ruby><b>がいる</b>だろ","speech":"ここにいい例がいるだろ","id":"Di sini kan <b>ada</b> contoh yang bagus. <i>(orang → いる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP07 · 06:00"}]},{"id":"n5_b10_02","level":"N5","bab":10,"lokasi":"第10課","titleMain":"〜は〜にあります・います","titleSub":["〜はどこにありますか"],"meaning":"[Sesuatu / seseorang] ada di [tempat] — menjawab di mana","formula":"KB (topik) + <b>は</b> + Tempat + <b>に</b> + <b>あります／います</b><br>Tanya: 〜は<b>どこに</b>ありますか／いますか<br>Singkat: KB は Tempat <b>です</b>","nuance":"<ol><li>Benda/orang sudah diketahui → <b>は</b>; info barunya = <b>tempat</b>.</li><li>Kebalikan dari 〜に〜があります (yang fokus ke \"apa\").</li><li>Boleh disingkat: ミラーさんは会議室<b>です</b>.</li></ol>⚠️ Hal baru → が; hal yang sudah dibahas → は.","examples":[{"jp":"<ruby>本<rt>ほん</rt></ruby>は <ruby>箱<rt>はこ</rt></ruby>の<ruby>中<rt>なか</rt></ruby>にあります。","speech":"本は箱の中にあります。","id":"Bukunya <b>ada di</b> dalam kotak. <i>(あります)</i>"},{"jp":"ミラーさんはどこにいますか。 <ruby>会議室<rt>かいぎしつ</rt></ruby>にいます。","speech":"ミラーさんはどこにいますか。会議室にいます。","id":"Pak Miller <b>ada di mana</b>? ── <b>Ada di</b> ruang rapat. <i>(います)</i>"},{"jp":"<ruby>東京<rt>とうきょう</rt></ruby>ディズニーランドは <ruby>千葉県<rt>ちばけん</rt></ruby>にあります。","speech":"東京ディズニーランドは千葉県にあります。","id":"Tokyo Disneyland <b>ada di</b> Prefektur Chiba. <i>(あります)</i>"},{"jp":"<ruby>猫<rt>ねこ</rt></ruby>はいすの<ruby>下<rt>した</rt></ruby>にいます。","speech":"猫はいすの下にいます。","id":"Kucingnya <b>ada di</b> bawah kursi. <i>(います)</i>"}],"dialogs":[{"jp":"エヴァン<b>は</b> <ruby>教会<rt>きょうかい</rt></ruby><b>にいます</b>","speech":"エヴァンは教会にいます","id":"Evan <b>ada di</b> gereja. <i>(は〜にいます)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP23 · 01:41"},{"jp":"そうで あなた<b>は</b>どこ<b>にいる</b>の? <ruby>客席<rt>きゃくせき</rt></ruby>?","speech":"そうであなたはどこにいるの? 客席?","id":"Terus kamu <b>ada di mana</b>? Di kursi penonton? <i>(どこにいる)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 10:15"},{"jp":"「 <ruby>証拠<rt>しょうこ</rt></ruby><b>は</b> どこ<b>にある</b>んだ」","speech":"「証拠はどこにあるんだ」","id":"\"Buktinya <b>ada di mana</b>?\" <i>(どこにある)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP04 · 08:09"},{"jp":"ところで クロエ<b>は</b>どこ<b>にいる</b>か<ruby>分<rt>わ</rt></ruby>かりますか","speech":"ところでクロエはどこにいるか分かりますか","id":"Ngomong-ngomong, tahu Chloe <b>ada di mana</b>? <i>(どこにいるか)</i>","source":"狼と香辛料 · EP01 · 04:25"}]},{"id":"n5_b10_03","level":"N5","bab":10,"lokasi":"第10課","titleMain":"Ｎの上・下・中・隣","titleSub":["前","後ろ","間"],"meaning":"Di atas / bawah / dalam / sebelah N … — kata posisi","formula":"N (patokan) + <b>の</b> + <b>上・下・中・外・前・後ろ・右・左・隣・近く</b> + に／で<br>A と B の<b>間</b> = di antara A dan B","nuance":"<ol><li>Kata posisi = <b>kata benda</b>, disambung <b>の</b> (机の上).</li><li>Urutan kebalikan bahasa Indonesia: patokan dulu, baru posisi.</li><li>Ada → <b>に</b>; aksi → <b>で</b> (駅の前で待ちます).</li></ol>⚠️ <b>隣</b> = sebelah yang sejajar/sejenis; <b>間</b> pakai pola AとBの間.","examples":[{"jp":"<ruby>机<rt>つくえ</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>に <ruby>写真<rt>しゃしん</rt></ruby>があります。","speech":"机の上に写真があります。","id":"Di <b>atas</b> meja ada foto. <i>(上)</i>"},{"jp":"<ruby>郵便局<rt>ゆうびんきょく</rt></ruby>は<ruby>銀行<rt>ぎんこう</rt></ruby>の<ruby>隣<rt>となり</rt></ruby>にあります。","speech":"郵便局は銀行の隣にあります。","id":"Kantor pos ada di <b>sebelah</b> bank. <i>(隣)</i>"},{"jp":"<ruby>駅<rt>えき</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>で <ruby>友達<rt>ともだち</rt></ruby>を<ruby>待<rt>ま</rt></ruby>ちます。","speech":"駅の前で友達を待ちます。","id":"Saya nunggu teman di <b>depan</b> stasiun. <i>(前 + で)</i>"},{"jp":"<ruby>本屋<rt>ほんや</rt></ruby>は<ruby>花屋<rt>はなや</rt></ruby>とスーパーの<ruby>間<rt>あいだ</rt></ruby>にあります。","speech":"本屋は花屋とスーパーの間にあります。","id":"Toko buku ada <b>di antara</b> toko bunga dan supermarket. <i>(間)</i>"}],"dialogs":[{"jp":"<ruby>机<rt>つくえ</rt></ruby><b>の<ruby>上<rt>うえ</rt></ruby>に</b> <ruby>写真立<rt>しゃしんた</rt></ruby>てあったと<ruby>思<rt>おも</rt></ruby>うんですけど…","speech":"机の上に写真立てあったと思うんですけど…","id":"Kayaknya di <b>atas</b> meja ada bingkai foto deh… <i>(上)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP11 · 09:06"},{"jp":"<ruby>祭壇<rt>さいだん</rt></ruby><b>の<ruby>下<rt>した</rt></ruby>に</b> <ruby>本<rt>ほん</rt></ruby>があるらしいから<ruby>取<rt>と</rt></ruby>ってきて","speech":"祭壇の下に本があるらしいから取ってきて","id":"Katanya ada buku di <b>bawah</b> altar, ambilin dong. <i>(下)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP23 · 12:26"},{"jp":"<ruby>半日<rt>はんにち</rt></ruby>ほど<ruby>東<rt>ひがし</rt></ruby>に<ruby>行<rt>い</rt></ruby>くと<ruby>山<rt>やま</rt></ruby><b>の<ruby>中<rt>なか</rt></ruby>に</b> <ruby>小<rt>ちい</rt></ruby>さな<ruby>村<rt>むら</rt></ruby>があるんです","speech":"半日ほど東に行くと山の中に小さな村があるんです","id":"Kalau jalan ke timur sekitar setengah hari, ada desa kecil di <b>tengah</b> gunung. <i>(中)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP01 · 03:52"},{"jp":"<ruby>真昼<rt>まひる</rt></ruby><b>の<ruby>隣<rt>となり</rt></ruby>に</b> <ruby>立<rt>た</rt></ruby>っても<ruby>恥<rt>は</rt></ruby>ずかしくないように…","speech":"真昼の隣に立っても恥ずかしくないように…","id":"Biar nggak malu-maluin waktu berdiri di <b>sebelah</b> Mahiru… <i>(隣)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP10 · 09:21"}]},{"id":"n5_b10_04","level":"N5","bab":10,"lokasi":"第10課","titleMain":"〜や〜など","titleSub":[],"meaning":"… dan … (dan lain-lain) — menyebut sebagian contoh saja","formula":"KB₁ + <b>や</b> + KB₂ + （<b>など</b>）<br>Bandingkan: A <b>と</b> B = daftar lengkap<br>Lisan: 〜<b>とか</b>〜<b>とか</b>","nuance":"<ol><li><b>と</b> = semua disebut; <b>や</b> = contoh, masih ada yang lain.</li><li><b>など</b> menegaskan \"dll\".</li></ol>⚠️ Hanya untuk kata benda (×おいしいや安い).","examples":[{"jp":"<ruby>箱<rt>はこ</rt></ruby>の<ruby>中<rt>なか</rt></ruby>に<ruby>手紙<rt>てがみ</rt></ruby>や <ruby>写真<rt>しゃしん</rt></ruby>などがあります。","speech":"箱の中に手紙や写真などがあります。","id":"Di dalam kotak ada surat, foto, <b>dan lain-lain</b>. <i>(や〜など)</i>"},{"jp":"<ruby>冷蔵庫<rt>れいぞうこ</rt></ruby>に<ruby>卵<rt>たまご</rt></ruby>や <ruby>牛乳<rt>ぎゅうにゅう</rt></ruby>があります。","speech":"冷蔵庫に卵や牛乳があります。","id":"Di kulkas ada telur, susu, <b>dan sebagainya</b>. <i>(や)</i>"},{"jp":"あの<ruby>店<rt>みせ</rt></ruby>でパンや <ruby>野菜<rt>やさい</rt></ruby>などを<ruby>買<rt>か</rt></ruby>います。","speech":"あの店でパンや野菜などを買います。","id":"Di toko itu saya beli roti, sayur, <b>dan lain-lain</b>. <i>(や〜など)</i>"}],"dialogs":[{"jp":"<ruby>接客<rt>せっきゃく</rt></ruby><b>や</b> <ruby>配達<rt>はいたつ</rt></ruby><b>など</b>のバイトを<ruby>続<rt>つづ</rt></ruby>けた","speech":"接客や配達などのバイトを続けた","id":"Aku terus kerja sambilan kayak melayani pelanggan, antar barang, <b>dan lain-lain</b>. <i>(や〜など)</i>","source":"トニカクカワイイ · EP05 · 13:11"},{"jp":"<ruby>調理<rt>ちょうり</rt></ruby><b>や</b> たき<ruby>火<rt>び</rt></ruby><b>など</b> <ruby>座<rt>すわ</rt></ruby>ったままでの<ruby>作業<rt>さぎょう</rt></ruby>がしやすく-","speech":"調理やたき火など座ったままでの作業がしやすく-","id":"Masak, api unggun, <b>dan lain-lain</b> jadi gampang dikerjakan sambil duduk… <i>(や〜など)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 07:56"},{"jp":"ゆで<ruby>汁<rt>じる</rt></ruby>が<ruby>出<rt>で</rt></ruby>ないので キャンプ<b>や</b> <ruby>山<rt>やま</rt></ruby><b>など</b>でオススメです","speech":"ゆで汁が出ないのでキャンプや山などでオススメです","id":"Karena nggak ada air rebusan sisa, cocok buat kemah, naik gunung, <b>dan sebagainya</b>. <i>(や〜など)</i>","source":"ゆるキャン△ · EP05 · 09:26"},{"jp":"<ruby>野菜<rt>やさい</rt></ruby><b>や</b> <ruby>肉<rt>にく</rt></ruby>と<ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>蒸<rt>む</rt></ruby>したり<ruby>香草<rt>こうそう</rt></ruby>と<ruby>焼<rt>や</rt></ruby>いたり いろいろだ","speech":"野菜や肉と一緒に蒸したり香草と焼いたりいろいろだ","id":"Dikukus bareng sayur, daging, <b>dan lain-lain</b>, atau dipanggang pakai rempah — macam-macam. <i>(や saja)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP14 · 06:03"}]},{"id":"n5_b11_01","level":"N5","bab":11,"lokasi":"第11課","titleMain":"助数詞","titleSub":["りんごを ４つ 買う","〜つ・〜人・〜枚・〜台"],"meaning":"Kata bantu bilangan — menghitung benda sesuai jenisnya (buah, orang, lembar, unit)","formula":"Ｎ ＋ を／が ＋ <b>[angka＋counter]</b> ＋ Ｖ（りんごを<b>４つ</b>買う）<br><b>〜つ</b> benda umum (1–10) · <b>〜人</b> orang · <b>〜枚</b> benda tipis · <b>〜台</b> mesin/kendaraan · <b>〜回</b> kali<br>Tanya: <b>いくつ</b> · <b>何人</b> · <b>何枚</b> · <b>何台</b>","nuance":"<ol><li>Angka＋counter = keterangan → ditaruh <b>sebelum kata kerja, tanpa partikel</b>.</li><li>Orang: <b>ひとり・ふたり</b>・さんにん・<b>よにん</b> (tidak beraturan).</li><li>〜つ hanya sampai とお (10); selebihnya pakai <b>〜個</b> (１２個).</li></ol>⚠️ ×いちにん ×ににん ×しにん. Bunyi berubah: いっぽん・さんぼん, いっかい・じゅっかい.","examples":[{"jp":"りんごを<ruby>４<rt>よっ</rt></ruby>つ <ruby>買<rt>か</rt></ruby>いました。","speech":"りんごを４つ買いました。","id":"Saya membeli apel <b>4 buah</b>. <i>(〜つ)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>の<ruby>会社<rt>かいしゃ</rt></ruby>に<ruby>外国人<rt>がいこくじん</rt></ruby>が<ruby>５人<rt>ごにん</rt></ruby>います。","speech":"私の会社に外国人が５人います。","id":"Di kantor saya ada <b>5 orang</b> asing. <i>(〜人)</i>"},{"jp":"<ruby>８０円<rt>はちじゅうえん</rt></ruby>の<ruby>切手<rt>きって</rt></ruby>を<ruby>５枚<rt>ごまい</rt></ruby>ください。","speech":"８０円の切手を５枚ください。","id":"Minta prangko 80 yen <b>5 lembar</b>. <i>(〜枚)</i>"},{"jp":"うちに<ruby>車<rt>くるま</rt></ruby>が<ruby>２台<rt>にだい</rt></ruby>あります。","speech":"うちに車が２台あります。","id":"Di rumah ada <b>2 unit</b> mobil. <i>(〜台)</i>"},{"jp":"<ruby>兄弟<rt>きょうだい</rt></ruby>が<ruby>何人<rt>なんにん</rt></ruby>いますか。","speech":"兄弟が何人いますか。","id":"Kamu punya saudara <b>berapa orang</b>? <i>(何人)</i>"}],"dialogs":[{"jp":"じゃあ とりあえず <b><ruby>4人<rt>よにん</rt></ruby></b>いるから...","speech":"じゃあとりあえず4人いるから...","id":"Ya udah, untuk sementara kan ada <b>4 orang</b>, jadi… <i>(〜人 · orang)</i>","source":"ガールズバンドクライ · EP09 · 05:39"},{"jp":"<ruby>自転車<rt>じてんしゃ</rt></ruby>が <b><ruby>1台<rt>いちだい</rt></ruby></b>っと...","speech":"自転車が1台っと...","id":"Sepeda <b>satu unit</b>, oke… <i>(〜台 · kendaraan)</i>","source":"ゆるキャン△ · EP02 · 11:34"},{"jp":"<ruby>記念<rt>きねん</rt></ruby>で <b><ruby>一枚<rt>いちまい</rt></ruby></b> <ruby>写真<rt>しゃしん</rt></ruby><ruby>撮<rt>と</rt></ruby>っとこ","speech":"記念で一枚写真撮っとこ","id":"Buat kenang-kenangan, ambil foto <b>satu</b> dulu ah. <i>(〜枚 · posisi sebelum Ｖ)</i>","source":"ガールズバンドクライ · EP11 · 10:00"},{"jp":"てことは<ruby>婚約<rt>こんやく</rt></ruby><ruby>指輪<rt>ゆびわ</rt></ruby>と<ruby>結婚<rt>けっこん</rt></ruby><ruby>指輪<rt>ゆびわ</rt></ruby>で<ruby>合<rt>あ</rt></ruby>わせて<b><ruby>三<rt>みっ</rt></ruby>つ</b> <ruby>必要<rt>ひつよう</rt></ruby>なのか","speech":"てことは婚約指輪と結婚指輪で合わせて三つ必要なのか","id":"Berarti cincin tunangan sama cincin nikah totalnya butuh <b>tiga</b> ya. <i>(〜つ · benda umum)</i>","source":"トニカクカワイイ · EP05 · 15:31"},{"jp":"お<ruby>前<rt>まえ</rt></ruby>の<ruby>学年<rt>がくねん</rt></ruby> <b><ruby>何人<rt>なんにん</rt></ruby></b>いた?","speech":"お前の学年何人いた?","id":"Angkatanmu dulu ada <b>berapa orang</b>? <i>(何人 · tanya jumlah)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP08 · 07:36"}]},{"id":"n5_b11_02","level":"N5","bab":11,"lokasi":"第11課","titleMain":"期間・頻度","titleSub":["２か月 勉強する","１週間に ２回"],"meaning":"Lama waktu (selama…) & frekuensi (…kali per periode)","formula":"Lama: <b>[durasi]</b> ＋ Ｖ（<b>２か月</b>勉強した ／ <b>３時間</b>かかる）<br>Frekuensi: [periode] ＋ <b>に</b> ＋ [angka＋<b>回</b>]（１週間<b>に</b>２回）<br>Kira-kira: [durasi] ＋ <b>ぐらい／くらい</b>","nuance":"<ol><li>Durasi = <b>tanpa partikel</b>: ２時間 勉強する (×２時間に).</li><li>Frekuensi: periode ＋ <b>に</b> ＋ kali (１日に３回, 年に一度).</li><li>Lama perjalanan / biaya: <b>〜かかる</b>.</li></ol>⚠️ ３<b>時</b> (pukul 3) ≠ ３<b>時間</b> (selama 3 jam); ３<b>月</b> (Maret) ≠ ３<b>か月</b> (3 bulan).","examples":[{"jp":"<ruby>国<rt>くに</rt></ruby>で<ruby>２か月<rt>にかげつ</rt></ruby> <ruby>日本語<rt>にほんご</rt></ruby>を<ruby>勉強<rt>べんきょう</rt></ruby>しました。","speech":"国で２か月日本語を勉強しました。","id":"Saya belajar bahasa Jepang <b>selama 2 bulan</b> di negara saya. <i>(durasi)</i>"},{"jp":"<ruby>１週間<rt>いっしゅうかん</rt></ruby>に<ruby>２回<rt>にかい</rt></ruby> <ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>ます。","speech":"１週間に２回映画を見ます。","id":"Saya nonton film <b>2 kali seminggu</b>. <i>(frekuensi)</i>"},{"jp":"<ruby>大阪<rt>おおさか</rt></ruby>から<ruby>東京<rt>とうきょう</rt></ruby>まで<ruby>新幹線<rt>しんかんせん</rt></ruby>で<ruby>３時間<rt>さんじかん</rt></ruby>かかります。","speech":"大阪から東京まで新幹線で３時間かかります。","id":"Osaka ke Tokyo naik shinkansen <b>makan waktu 3 jam</b>. <i>(durasi ＋ かかる)</i>"},{"jp":"<ruby>１年<rt>いちねん</rt></ruby>に<ruby>１回<rt>いっかい</rt></ruby> <ruby>国<rt>くに</rt></ruby>へ<ruby>帰<rt>かえ</rt></ruby>ります。","speech":"１年に１回国へ帰ります。","id":"Saya pulang kampung <b>setahun sekali</b>. <i>(frekuensi)</i>"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>８時間<rt>はちじかん</rt></ruby>ぐらい <ruby>寝<rt>ね</rt></ruby>ます。","speech":"毎日８時間ぐらい寝ます。","id":"Tiap hari saya tidur <b>sekitar 8 jam</b>. <i>(ぐらい)</i>"}],"dialogs":[{"jp":"レンタルの<ruby>依頼<rt>いらい</rt></ruby>が<ruby>入<rt>はい</rt></ruby>るのは <b><ruby>週<rt>しゅう</rt></ruby>に<ruby>2回<rt>にかい</rt></ruby></b>ほど","speech":"レンタルの依頼が入るのは週に2回ほど","id":"Pesanan rental masuk kira-kira <b>2 kali seminggu</b>. <i>(frekuensi)</i>","source":"彼女、お借りします · EP11 · 00:45"},{"jp":"<ruby>吹奏楽<rt>すいそうがく</rt></ruby>コンクールは<b><ruby>年<rt>ねん</rt></ruby>に<ruby>一度<rt>いちど</rt></ruby></b>","speech":"吹奏楽コンクールは年に一度","id":"Kompetisi brass band itu cuma <b>setahun sekali</b>. <i>(frekuensi · 一度)</i>","source":"響け！ユーフォニアム 2 · EP05 · 06:48"},{"jp":"<b><ruby>数年<rt>すうねん</rt></ruby>に<ruby>一度<rt>いちど</rt></ruby></b> いや <b><ruby>十年<rt>じゅうねん</rt></ruby>に<ruby>一度<rt>いちど</rt></ruby></b>か","speech":"数年に一度いや十年に一度か","id":"<b>Beberapa tahun sekali</b>… bukan, <b>sepuluh tahun sekali</b> malah. <i>(frekuensi)</i>","source":"狼と香辛料 · EP03 · 07:02"},{"jp":"<ruby>東京駅<rt>とうきょうえき</rt></ruby>からここまで <b><ruby>4時間<rt>よじかん</rt></ruby>も かかって</b>","speech":"東京駅からここまで4時間もかかって","id":"Dari Stasiun Tokyo ke sini <b>makan waktu 4 jam</b>, coba… <i>(durasi ＋ かかる)</i>","source":"ガールズバンドクライ · EP12 · 05:26"},{"jp":"いやあ<ruby>私<rt>わたし</rt></ruby>らが<ruby>作<rt>つく</rt></ruby>る<ruby>料理<rt>りょうり</rt></ruby> <b><ruby>2ー3時間<rt>にさんじかん</rt></ruby> かかる</b>やつでさ","speech":"いやあ私らが作る料理2ー3時間かかるやつでさ","id":"Soalnya masakan yang kami bikin itu <b>makan waktu 2–3 jam</b>. <i>(durasi ＋ かかる)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 11:14"}]},{"id":"n5_b11_03","level":"N5","bab":11,"lokasi":"第11課","titleMain":"どのくらい","titleSub":["どのくらい かかりますか","どれくらい"],"meaning":"Berapa lama? / berapa banyak? / seberapa? — menanyakan kadar (kira-kira)","formula":"<b>どのくらい</b> ＋ Ｖ／predikat（東京まで<b>どのくらい</b>かかりますか）<br>Jawab: [angka＋counter] ＋ <b>ぐらい／くらい</b> です<br>＝ どのぐらい ＝ <b>どれくらい</b> ＝ どれぐらい","nuance":"<ol><li>Paling sering dengan <b>かかる</b>: lama / biaya perjalanan.</li><li>Juga jumlah / tingkat: どのくらい いますか, どのくらい 弾ける?</li><li>どれくらい sedikit lebih santai; artinya sama.</li></ol>⚠️ 何時間 = tepat berapa jam, いくら = berapa harga; どのくらい lebih umum &amp; \"kira-kira\".","examples":[{"jp":"ここから<ruby>東京<rt>とうきょう</rt></ruby>までどのくらいかかりますか。","speech":"ここから東京までどのくらいかかりますか。","id":"Dari sini ke Tokyo <b>makan waktu berapa lama</b>? <i>(waktu tempuh)</i>"},{"jp":"バスで<ruby>１時間<rt>いちじかん</rt></ruby>ぐらいかかります。","speech":"バスで１時間ぐらいかかります。","id":"Naik bus <b>sekitar 1 jam</b>. <i>(jawaban · ぐらい)</i>"},{"jp":"<ruby>日本語<rt>にほんご</rt></ruby>をどのくらい <ruby>勉強<rt>べんきょう</rt></ruby>しましたか。","speech":"日本語をどのくらい勉強しましたか。","id":"<b>Berapa lama</b> kamu belajar bahasa Jepang? <i>(lama waktu)</i>"},{"jp":"このクラスに<ruby>学生<rt>がくせい</rt></ruby>はどのくらいいますか。","speech":"このクラスに学生はどのくらいいますか。","id":"Di kelas ini muridnya <b>ada berapa banyak</b>? <i>(jumlah)</i>"}],"dialogs":[{"jp":"テレオの<ruby>町<rt>まち</rt></ruby>まで あと <b>どのくらい かかる</b>?","speech":"テレオの町まであとどのくらいかかる?","id":"Ke kota Tereo <b>masih berapa lama</b> lagi? <i>(waktu tempuh)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 07:53"},{"jp":"<b>どれくらい かかる</b>んだ? <ruby>5分<rt>ごふん</rt></ruby>くらい?","speech":"どれくらいかかるんだ? 5分くらい?","id":"<b>Butuh berapa lama</b>? Sekitar 5 menit? <i>(どれくらい · dijawab くらい)</i>","source":"この素晴らしい世界に祝福を！ · EP05 · 04:28"},{"jp":"<b>どのくらい</b> <ruby>寝<rt>ね</rt></ruby>た?","speech":"どのくらい寝た?","id":"Aku tidur <b>berapa lama</b>? <i>(lama waktu)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP08 · 06:46"},{"jp":"お<ruby>客<rt>きゃく</rt></ruby>さんは<b>どのくらい</b>いるんですか","speech":"お客さんはどのくらいいるんですか","id":"Penontonnya ada <b>berapa banyak</b>? <i>(jumlah)</i>","source":"ガールズバンドクライ · EP11 · 03:36"},{"jp":"ギター <b>どのくらい</b> <ruby>弾<rt>ひ</rt></ruby>ける?","speech":"ギターどのくらい弾ける?","id":"Kamu main gitar <b>sejago apa</b>? <i>(tingkat)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 09:33"}]},{"id":"n5_b11_04","level":"N5","bab":11,"lokasi":"第11課","titleMain":"〜だけ","titleSub":["一人だけ","少しだけ"],"meaning":"Hanya… / cuma… — membatasi jumlah atau hal (netral)","formula":"Angka ＋ <b>だけ</b>（一人<b>だけ</b>）<br>KB ＋ <b>だけ</b>（日曜日<b>だけ</b>）<br>少し／ちょっと ＋ <b>だけ</b> = sedikit saja (melunakkan)","nuance":"<ol><li>Menempel langsung di belakang KB/angka; が・を biasanya hilang.</li><li><b>少しだけ</b> sering dipakai untuk minta sesuatu dengan halus.</li></ol>⚠️ <b>しか〜ない</b> = \"cuma\" dengan rasa kurang & wajib negatif (一人<b>しか</b>来<b>なかった</b>); だけ netral.","examples":[{"jp":"<ruby>休<rt>やす</rt></ruby>みは<ruby>日曜日<rt>にちようび</rt></ruby>だけです。","speech":"休みは日曜日だけです。","id":"Liburnya <b>cuma</b> hari Minggu. <i>(KB ＋ だけ)</i>"},{"jp":"パーティーに<ruby>一人<rt>ひとり</rt></ruby>だけ <ruby>来<rt>き</rt></ruby>ました。","speech":"パーティーに一人だけ来ました。","id":"Yang datang ke pesta <b>cuma satu orang</b>. <i>(angka ＋ だけ)</i>"},{"jp":"<ruby>少<rt>すこ</rt></ruby>しだけ <ruby>日本語<rt>にほんご</rt></ruby>が<ruby>話<rt>はな</rt></ruby>せます。","speech":"少しだけ日本語が話せます。","id":"Saya bisa bahasa Jepang <b>sedikit saja</b>. <i>(少しだけ)</i>"},{"jp":"このかばんは<ruby>５００円<rt>ごひゃくえん</rt></ruby>だけです。","speech":"このかばんは５００円だけです。","id":"Tas ini <b>cuma 500 yen</b>. <i>(angka ＋ だけ)</i>"}],"dialogs":[{"jp":"<ruby>打開策<rt>だかいさく</rt></ruby>が<b><ruby>1<rt>ひと</rt></ruby>つだけ</b>あります","speech":"打開策が1つだけあります","id":"Ada <b>satu</b> jalan keluar <b>saja</b>! <i>(angka ＋ だけ)</i>","source":"この素晴らしい世界に爆焔を！ · EP11 · 08:41"},{"jp":"<b><ruby>一枚<rt>いちまい</rt></ruby>だけ</b>あります","speech":"一枚だけあります","id":"Ada, tapi <b>cuma satu lembar</b>. <i>(angka ＋ だけ)</i>","source":"狼と香辛料 · EP05 · 03:08"},{"jp":"だって こんなの<ruby>頼<rt>たの</rt></ruby>める<ruby>友達<rt>ともだち</rt></ruby> ゆきのん <b><ruby>一人<rt>ひとり</rt></ruby>だけ</b>なんだもん","speech":"だってこんなの頼める友達ゆきのん一人だけなんだもん","id":"Soalnya teman yang bisa kumintain tolong begini <b>cuma</b> Yukinon <b>seorang</b>. <i>(〜だけだ)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP03 · 16:16"},{"jp":"もう<b><ruby>少<rt>すこ</rt></ruby>しだけ</b> <ruby>貸<rt>か</rt></ruby>してください","speech":"もう少しだけ貸してください","id":"Pinjamkan (bahumu) <b>sebentar lagi saja</b>. <i>(少しだけ · melunakkan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP07 · 15:43"},{"jp":"<ruby>私<rt>わたし</rt></ruby>も もう<b><ruby>少<rt>すこ</rt></ruby>しだけ</b> <ruby>遊<rt>あそ</rt></ruby>びたかったかも","speech":"私ももう少しだけ遊びたかったかも","id":"Aku juga mungkin pengin main <b>sedikit lebih lama lagi</b>. <i>(少しだけ)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 20:17"}]},{"id":"n5_b12_01","level":"N5","bab":12,"lokasi":"第12課","titleMain":"〜でした・〜かったです","titleSub":["雨でした","暑くなかったです"],"meaning":"Bentuk lampau kata benda & kata sifat — keadaan di masa lalu (tadinya / kemarin itu…)","formula":"KB / KS-na: 雨<b>でした</b> · 雨<b>じゃありませんでした</b><br>KS-i: 暑<b>かったです</b> · 暑<b>くなかったです</b><br>いい → <b>よかった</b> · <b>よくなかった</b><br>Santai: <b>だった</b> · <b>じゃなかった</b> · 〜<b>かった</b>","nuance":"<ol><li>KS-i: tanda lampau ada di kata sifatnya (〜かった); <b>です tetap です</b>.</li><li>KB & KS-na: です → <b>でした</b>.</li><li><b>どうでしたか</b> = gimana (tadi/kemarin)?</li></ol>⚠️ ×暑いでした ×いかった. きれい・きらい = KS-na → きれい<b>でした</b>.","examples":[{"jp":"<ruby>昨日<rt>きのう</rt></ruby>は<ruby>雨<rt>あめ</rt></ruby>でした。","speech":"昨日は雨でした。","id":"Kemarin <b>hujan</b>. <i>(KB ＋ でした)</i>"},{"jp":"<ruby>去年<rt>きょねん</rt></ruby>の<ruby>夏<rt>なつ</rt></ruby>はあまり<ruby>暑<rt>あつ</rt></ruby>くなかったです。","speech":"去年の夏はあまり暑くなかったです。","id":"Musim panas tahun lalu <b>nggak terlalu panas</b>. <i>(KS-i negatif)</i>"},{"jp":"<ruby>旅行<rt>りょこう</rt></ruby>はとても<ruby>楽<rt>たの</rt></ruby>しかったです。","speech":"旅行はとても楽しかったです。","id":"Liburannya <b>seru banget</b>. <i>(KS-i positif)</i>"},{"jp":"テストはどうでしたか。……あまりよくなかったです。","speech":"テストはどうでしたか。……あまりよくなかったです。","id":"Ujiannya <b>gimana</b>? … <b>Kurang bagus</b>. <i>(いい → よくなかった)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby>はひまじゃありませんでした。","speech":"昨日はひまじゃありませんでした。","id":"Kemarin saya <b>nggak senggang</b>. <i>(KS-na negatif)</i>"}],"dialogs":[{"jp":"めっちゃ <b>きれいでした</b>","speech":"めっちゃきれいでした","id":"<b>Cantik</b> banget <b>tadi</b>! <i>(KS-na ＋ でした)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 03:42"},{"jp":"とても<b>おいしかったです</b>","speech":"とてもおいしかったです","id":"<b>Enak</b> banget <b>tadi</b>! <i>(KS-i ＋ かったです)</i>","source":"ガールズバンドクライ · EP01 · 12:12"},{"jp":"ああ そうでした　 <ruby>羊飼<rt>ひつじか</rt></ruby>いは もう<ruby>休<rt>やす</rt></ruby>む<b><ruby>時間<rt>じかん</rt></ruby>でした</b>ね","speech":"ああそうでした羊飼いはもう休む時間でしたね","id":"Oh iya, penggembala kan <b>sudah waktunya</b> istirahat ya. <i>(KB ＋ でした)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP08 · 09:15"},{"jp":"ライブ ホントは <b>よくなかった</b>?","speech":"ライブホントはよくなかった?","id":"Live-nya sebenarnya <b>nggak bagus</b> ya? <i>(いい → よくなかった)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 17:24"},{"jp":"イ... <b>イヤじゃなかったです</b>から","speech":"イ... イヤじゃなかったですから","id":"A-aku <b>nggak keberatan</b> kok. <i>(KS-na ＋ じゃなかったです)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP03 · 19:07"}]},{"id":"n5_b12_02","level":"N5","bab":12,"lokasi":"第12課","titleMain":"ＡはＢより〜","titleSub":["ＢよりＡのほうが〜","Ｂより ずっと〜"],"meaning":"A lebih … daripada B — membandingkan dua hal","formula":"Ａ は Ｂ <b>より</b> ＋ KS ＋ です（このかばんはそのかばん<b>より</b>軽いです）<br>Penguat: Ｂ<b>より ずっと</b>〜 (jauh lebih) · Ｂより <b>もっと</b>〜 (lebih lagi)","nuance":"<ol><li>Yang ditempeli <b>より</b> = pembanding yang <b>kalah</b>.</li><li>Kata sifat <b>tidak berubah</b> (tidak ada bentuk \"lebih\").</li><li><b>ずっと</b> = jauh lebih.</li></ol>⚠️ 私<b>より</b> 兄が高い = kakak yang lebih tinggi — jangan terbalik.","examples":[{"jp":"このかばんはそのかばんより<ruby>軽<rt>かる</rt></ruby>いです。","speech":"このかばんはそのかばんより軽いです。","id":"Tas ini <b>lebih ringan daripada</b> tas itu. <i>(perbandingan)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>昨日<rt>きのう</rt></ruby>より<ruby>寒<rt>さむ</rt></ruby>いです。","speech":"今日は昨日より寒いです。","id":"Hari ini <b>lebih dingin daripada</b> kemarin. <i>(perbandingan)</i>"},{"jp":"<ruby>兄<rt>あに</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>より ずっと <ruby>背<rt>せ</rt></ruby>が<ruby>高<rt>たか</rt></ruby>いです。","speech":"兄は私よりずっと背が高いです。","id":"Kakakku <b>jauh lebih</b> tinggi <b>daripada</b> aku. <i>(ずっと)</i>"},{"jp":"<ruby>新幹線<rt>しんかんせん</rt></ruby>は<ruby>飛行機<rt>ひこうき</rt></ruby>より<ruby>安<rt>やす</rt></ruby>いです。","speech":"新幹線は飛行機より安いです。","id":"Shinkansen <b>lebih murah daripada</b> pesawat. <i>(perbandingan)</i>"}],"dialogs":[{"jp":"<b><ruby>私<rt>わたし</rt></ruby>より ずっと</b>うまいでしょ","speech":"私よりずっとうまいでしょ","id":"Kamu kan <b>jauh lebih</b> jago <b>daripada aku</b>! <i>(より ずっと)</i>","source":"ガールズバンドクライ · EP03 · 14:56"},{"jp":"<b>ゆんゆんより ずっと</b> <ruby>優秀<rt>ゆうしゅう</rt></ruby>なんです","speech":"ゆんゆんよりずっと優秀なんです","id":"<b>Jauh lebih</b> berbakat <b>daripada Yunyun</b>. <i>(より ずっと)</i>","source":"この素晴らしい世界に爆焔を！ · EP03 · 20:24"},{"jp":"お<ruby>酒<rt>さけ</rt></ruby>とベースは<ruby>私<rt>わたし</rt></ruby>の<b><ruby>命<rt>いのち</rt></ruby>より<ruby>大事<rt>だいじ</rt></ruby></b>なものだから","speech":"お酒とベースは私の命より大事なものだから","id":"Soalnya miras sama bass itu <b>lebih penting daripada nyawaku</b>. <i>(Ｂより KS-na)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 09:34"},{"jp":"<b><ruby>僕<rt>ぼく</rt></ruby>なんかより ずっと</b> うまかったんだよ","speech":"僕なんかよりずっとうまかったんだよ","id":"Dia <b>jauh lebih</b> jago <b>daripada aku</b>, lho. <i>(より ずっと · lampau)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 17:00"},{"jp":"<b>お<ruby>化<rt>ば</rt></ruby>けより<ruby>怖<rt>こわ</rt></ruby>かったら</b>?","speech":"お化けより怖かったら?","id":"Gimana kalau aku <b>lebih seram daripada hantu</b>? <i>(Ｂより KS-i)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP08 · 17:09"}]},{"id":"n5_b12_03","level":"N5","bab":12,"lokasi":"第12課","titleMain":"ＡとＢと どちらが〜","titleSub":["Ｂのほうが〜","どっちが〜"],"meaning":"Antara A dan B, mana yang lebih …? — B yang lebih …","formula":"Tanya: Ａ<b>と</b> Ｂ<b>と どちらが</b> KS ですか（santai: <b>どっちが</b>）<br>Jawab: Ｂ<b>のほうが</b> KS です · Ａ<b>より</b> Ｂ<b>のほうが</b>〜<br>Sama: <b>どちらも</b> KS です","nuance":"<ol><li><b>どちら/どっち</b> hanya untuk <b>2 pilihan</b>.</li><li><b>のほうが</b> menegaskan pilihan saat menjawab.</li><li><b>どちらも</b> = dua-duanya.</li></ol>⚠️ 3 pilihan atau lebih → 何／どれ／だれ が <b>いちばん</b>〜.","examples":[{"jp":"テニスとサッカーと どちらがおもしろいですか。","speech":"テニスとサッカーとどちらがおもしろいですか。","id":"<b>Antara</b> tenis <b>dan</b> sepak bola, <b>mana yang lebih</b> seru? <i>(tanya)</i>"},{"jp":"サッカーのほうがおもしろいです。","speech":"サッカーのほうがおもしろいです。","id":"<b>Sepak bola yang lebih</b> seru. <i>(jawab)</i>"},{"jp":"コーヒーと <ruby>紅茶<rt>こうちゃ</rt></ruby>と どちらが <ruby>好<rt>す</rt></ruby>きですか。……どちらも <ruby>好<rt>す</rt></ruby>きです。","speech":"コーヒーと紅茶とどちらが好きですか。……どちらも好きです。","id":"Kopi <b>atau</b> teh, <b>mana yang lebih</b> kamu suka? … <b>Dua-duanya</b> suka. <i>(どちらも)</i>"},{"jp":"バスより <ruby>電車<rt>でんしゃ</rt></ruby>のほうが <ruby>速<rt>はや</rt></ruby>いです。","speech":"バスより電車のほうが速いです。","id":"<b>Kereta lebih</b> cepat <b>daripada</b> bus. <i>(より＋のほうが)</i>"}],"dialogs":[{"jp":"<ruby>暖<rt>あたた</rt></ruby>かい<ruby>部屋<rt>へや</rt></ruby><b>と</b> <ruby>明<rt>あか</rt></ruby>るい<ruby>部屋<rt>へや</rt></ruby> <b>どっちがいい</b>","speech":"暖かい部屋と明るい部屋どっちがいい","id":"Kamar hangat <b>atau</b> kamar terang, <b>mana yang kamu mau</b>? <i>(ＡとＢ どっち)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP07 · 09:24"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんは<ruby>短<rt>みじか</rt></ruby>いの<b>と</b> <ruby>長<rt>なが</rt></ruby>いの <b>どっちが<ruby>好<rt>す</rt></ruby>き</b>ですか?","speech":"周くんは短いのと長いのどっちが好きですか?","id":"Amane-kun <b>lebih suka</b> yang pendek <b>atau</b> yang panjang? <i>(どっちが好き)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 10:56"},{"jp":"<ruby>仕事<rt>しごと</rt></ruby><b>と</b> <ruby>小町<rt>こまち</rt></ruby> <b>どっちが<ruby>大事<rt>だいじ</rt></ruby></b>なの?","speech":"仕事と小町どっちが大事なの?","id":"Kerjaan <b>atau</b> Komachi, <b>mana yang lebih penting</b>? <i>(どっちが)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP05 · 08:37"},{"jp":"<ruby>中身<rt>なかみ</rt></ruby><b>より</b> <ruby>皮<rt>かわ</rt></ruby><b>のほうが</b> おいしい","speech":"中身より皮のほうがおいしい","id":"<b>Kulitnya lebih</b> enak <b>daripada</b> isinya. <i>(Ａより Ｂのほうが)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 14:26"},{"jp":"ん? わっち<b>のほうが</b> かわいい","speech":"ん? わっちのほうがかわいい","id":"Hmm? <b>Aku yang lebih</b> imut. <i>(のほうが · menegaskan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP08 · 04:06"}]},{"id":"n5_b12_04","level":"N5","bab":12,"lokasi":"第12課","titleMain":"〜で いちばん〜","titleSub":["何が いちばん〜","〜の中で いちばん〜"],"meaning":"Paling … (di / di antara …) — superlatif","formula":"[lingkup] ＋ <b>で</b> ＋ Ｘ が <b>いちばん</b> ＋ KS（日本<b>で いちばん</b>高い山）<br>Ｎ<b>の中で いちばん</b>〜<br>Tanya: <b>何／どこ／だれ／いつ が いちばん</b>〜ですか","nuance":"<ol><li>Lingkup diberi <b>で</b> (日本で, クラスで, １年で) atau <b>〜の中で</b>.</li><li>Kata tanya sebagai subjek → wajib <b>が</b>.</li><li><b>一番</b> sendirian = yang terbaik (これが一番だ).</li></ol>⚠️ ×何<b>は</b>いちばん好き → ○何<b>が</b>. 2 pilihan → どちら, bukan いちばん.","examples":[{"jp":"<ruby>１年<rt>いちねん</rt></ruby>で いつが いちばん <ruby>暑<rt>あつ</rt></ruby>いですか。","speech":"１年でいつがいちばん暑いですか。","id":"<b>Dalam</b> setahun, kapan yang <b>paling</b> panas? <i>(tanya)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>で いちばん <ruby>高<rt>たか</rt></ruby>い<ruby>山<rt>やま</rt></ruby>は<ruby>富士山<rt>ふじさん</rt></ruby>です。","speech":"日本でいちばん高い山は富士山です。","id":"Gunung <b>paling</b> tinggi <b>di</b> Jepang adalah Gunung Fuji. <i>(Ｎで)</i>"},{"jp":"スポーツの<ruby>中<rt>なか</rt></ruby>で<ruby>何<rt>なに</rt></ruby>が いちばん <ruby>好<rt>す</rt></ruby>きですか。","speech":"スポーツの中で何がいちばん好きですか。","id":"<b>Di antara</b> olahraga, kamu <b>paling</b> suka apa? <i>(の中で)</i>"},{"jp":"<ruby>家族<rt>かぞく</rt></ruby>で だれが いちばん <ruby>背<rt>せ</rt></ruby>が<ruby>高<rt>たか</rt></ruby>いですか。","speech":"家族でだれがいちばん背が高いですか。","id":"<b>Di</b> keluargamu, siapa yang <b>paling</b> tinggi? <i>(だれが)</i>"}],"dialogs":[{"jp":"ああ この<ruby>辺<rt>へん</rt></ruby><b>で<ruby>一番<rt>いちばん</rt></ruby></b>でかい<ruby>直営店<rt>ちょくえいてん</rt></ruby>らしい","speech":"ああこの辺で一番でかい直営店らしい","id":"Iya, katanya ini toko resmi <b>paling</b> gede <b>di</b> sekitar sini. <i>(Ｎで 一番)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 05:55"},{"jp":"<ruby>結局<rt>けっきょく</rt></ruby><ruby>御徒町<rt>おかちまち</rt></ruby><b>で<ruby>一番<rt>いちばん</rt></ruby><ruby>安<rt>やす</rt></ruby>い</b>ダイヤを<ruby>買<rt>か</rt></ruby>ったこととか","speech":"結局御徒町で一番安いダイヤを買ったこととか","id":"Terus akhirnya kita beli berlian <b>paling murah di</b> Okachimachi… <i>(Ｎで 一番)</i>","source":"トニカクカワイイ · EP05 · 21:08"},{"jp":"ヤバい ヤバい ヤバい!　あいつは<b><ruby>今<rt>いま</rt></ruby>までで<ruby>一番<rt>いちばん</rt></ruby></b>ヤバい!","speech":"ヤバいヤバいヤバい!　あいつは今までで一番ヤバい!","id":"Gawat, gawat, gawat! Dia yang <b>paling</b> gawat <b>sejauh ini</b>! <i>(今までで 一番)</i>","source":"この素晴らしい世界に祝福を！2 · EP10 · 10:37"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんは その<b><ruby>中<rt>なか</rt></ruby>で<ruby>一番<rt>いちばん</rt></ruby></b> <ruby>近<rt>ちか</rt></ruby>しくて<ruby>大切<rt>たいせつ</rt></ruby>な<ruby>人<rt>ひと</rt></ruby>","speech":"周くんはその中で一番近しくて大切な人","id":"Di <b>antara</b> mereka, Amane-kun orang yang <b>paling</b> dekat dan berharga buatku. <i>(の中で 一番)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP10 · 10:59"},{"jp":"<b>どれが<ruby>一番<rt>いちばん</rt></ruby><ruby>好<rt>す</rt></ruby>き</b>?","speech":"どれが一番好き?","id":"Kamu <b>paling suka yang mana</b>? <i>(tanya ＋ が 一番)</i>","source":"僕の心のヤバイやつ 第2期 · EP01 · 09:31"}]},{"id":"n5_b13_01","level":"N5","bab":13,"lokasi":"第13課","titleMain":"〜が欲しい","titleSub":["Ｎが 欲しいです","欲しくない"],"meaning":"Ingin (punya)… — keinginan pembicara untuk mendapatkan benda/hal","formula":"(私は) Ｎ ＋ <b>が</b> ＋ <b>欲しい</b>です<br>Konjugasi KS-i: <b>欲しくない</b> · <b>欲しかった</b><br>Tanya: 何が いちばん<b>欲しい</b>ですか","nuance":"<ol><li>Benda yang diinginkan ditandai <b>が</b> (bukan を).</li><li>Hanya untuk keinginan <b>diri sendiri</b>; orang ketiga → 欲しがっている (N4).</li><li>Ingin <b>melakukan</b> → 〜たい; ingin orang lain melakukan → 〜てほしい.</li></ol>⚠️ ×田中さんは車が欲しいです. Ke atasan jangan 〜が欲しいですか → 〜はいかがですか.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>友<rt>とも</rt></ruby>だちが<ruby>欲<rt>ほ</rt></ruby>しいです。","speech":"私は友だちが欲しいです。","id":"Aku <b>pengin punya</b> teman. <i>(Ｎが欲しい)</i>"},{"jp":"<ruby>今<rt>いま</rt></ruby><ruby>何<rt>なに</rt></ruby>が いちばん<ruby>欲<rt>ほ</rt></ruby>しいですか。","speech":"今何がいちばん欲しいですか。","id":"Sekarang apa yang <b>paling kamu inginkan</b>? <i>(tanya)</i>"},{"jp":"<ruby>新<rt>あたら</rt></ruby>しいパソコンが<ruby>欲<rt>ほ</rt></ruby>しいです。","speech":"新しいパソコンが欲しいです。","id":"Aku <b>pengin</b> laptop baru. <i>(Ｎが欲しい)</i>"},{"jp":"<ruby>今<rt>いま</rt></ruby>は<ruby>何<rt>なに</rt></ruby>も<ruby>欲<rt>ほ</rt></ruby>しくないです。","speech":"今は何も欲しくないです。","id":"Sekarang aku <b>nggak pengin</b> apa-apa. <i>(negatif)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は ハンモック<b>が<ruby>欲<rt>ほ</rt></ruby>しい</b>んだよな","speech":"私はハンモックが欲しいんだよな","id":"Aku tuh <b>pengin punya</b> hammock. <i>(Ｎが欲しい)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 08:18"},{"jp":"<ruby>私<rt>わたし</rt></ruby>も あの<ruby>仮面<rt>かめん</rt></ruby><b>が<ruby>欲<rt>ほ</rt></ruby>しいです</b>","speech":"私もあの仮面が欲しいです","id":"Aku juga <b>mau</b> topeng itu! <i>(sopan)</i>","source":"この素晴らしい世界に祝福を！2 · EP05 · 16:48"},{"jp":"うまいパン<b>が<ruby>欲<rt>ほ</rt></ruby>しい</b>んだ","speech":"うまいパンが欲しいんだ","id":"Aku <b>pengin</b> roti yang enak. <i>(〜んだ · menjelaskan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP15 · 03:20"},{"jp":"あれ <b><ruby>欲<rt>ほ</rt></ruby>しいです</b>","speech":"あれ欲しいです","id":"Aku <b>mau</b> yang itu. <i>(が dihilangkan · lisan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP05 · 11:31"},{"jp":"ヒッキー<ruby>君<rt>くん</rt></ruby>が<b><ruby>欲<rt>ほ</rt></ruby>しい</b>ものは<ruby>何<rt>なに</rt></ruby>かな","speech":"ヒッキー君が欲しいものは何かな","id":"Apa ya barang yang <b>diinginkan</b> Hikki-kun? <i>(欲しいもの)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP09 · 13:14"}]},{"id":"n5_b13_02","level":"N5","bab":13,"lokasi":"第13課","titleMain":"〜たい","titleSub":["Ｖます＋たい","〜たくない"],"meaning":"Ingin (melakukan)… — keinginan pembicara untuk melakukan tindakan","formula":"Ｖ<s>ます</s> ＋ <b>たい</b>です（行き<b>たい</b> ／ 食べ<b>たい</b> ／ し<b>たい</b>）<br>Konjugasi KS-i: <b>〜たくない</b> · <b>〜たかった</b><br>Objek: <b>を</b> atau <b>が</b>（水<b>が</b>飲みたい）","nuance":"<ol><li>Tempel di <b>batang ます</b>; berubah seperti KS-i.</li><li>Objek boleh <b>を/が</b>; partikel lain (へ, で) tetap.</li><li>Hanya keinginan <b>diri sendiri</b>; orang ketiga → 〜たがっている.</li></ol>⚠️ Benda → <b>欲しい</b>, tindakan → <b>たい</b>. Jangan tanya atasan 〜たいですか; tawarkan dengan 〜ませんか.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>日本<rt>にほん</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きたいです。","speech":"私は日本へ行きたいです。","id":"Aku <b>pengin pergi</b> ke Jepang. <i>(Ｖたい)</i>"},{"jp":"のどがかわきましたから、 <ruby>何<rt>なに</rt></ruby>か<ruby>飲<rt>の</rt></ruby>みたいです。","speech":"のどがかわきましたから、何か飲みたいです。","id":"Aku haus, jadi <b>pengin minum</b> sesuatu. <i>(何か ＋ たい)</i>"},{"jp":"おなかがいっぱいですから、 <ruby>何<rt>なに</rt></ruby>も<ruby>食<rt>た</rt></ruby>べたくないです。","speech":"おなかがいっぱいですから、何も食べたくないです。","id":"Perutku kenyang, jadi <b>nggak pengin makan</b> apa-apa. <i>(〜たくない)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby> どこへ<ruby>行<rt>い</rt></ruby>きたいですか。","speech":"週末どこへ行きたいですか。","id":"Akhir pekan kamu <b>pengin pergi</b> ke mana? <i>(tanya)</i>"},{"jp":"すしが<ruby>食<rt>た</rt></ruby>べたいです。","speech":"すしが食べたいです。","id":"Aku <b>pengin makan</b> sushi. <i>(objek ＋ が)</i>"}],"dialogs":[{"jp":"おすし <b><ruby>食<rt>た</rt></ruby>べたい</b>","speech":"おすし食べたい","id":"Aku <b>pengin makan</b> sushi. <i>(Ｖたい)</i>","source":"ゆるキャン△ · EP07 · 12:55"},{"jp":"わっちぁ あれ<b>が<ruby>食<rt>た</rt></ruby>べたい</b>","speech":"わっちぁあれが食べたい","id":"Aku <b>mau makan</b> yang itu. <i>(objek ＋ が)</i>","source":"狼と香辛料 · EP03 · 16:03"},{"jp":"<ruby>司<rt>つかさ</rt></ruby>ちゃん どこか<b><ruby>行<rt>い</rt></ruby>きたい</b>とこ ある?","speech":"司ちゃんどこか行きたいとこある?","id":"Tsukasa-chan, ada tempat yang kamu <b>pengin datangi</b>? <i>(どこか ＋ たい)</i>","source":"トニカクカワイイ · EP07 · 12:02"},{"jp":"<b><ruby>働<rt>はたら</rt></ruby>きたくない</b>! だって...","speech":"働きたくない! だって...","id":"Aku <b>nggak mau kerja</b>! Soalnya… <i>(〜たくない)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 09:25"},{"jp":"じゃあ <b><ruby>帰<rt>かえ</rt></ruby>りたくないです</b>","speech":"じゃあ帰りたくないです","id":"Kalau gitu, aku <b>nggak mau pulang</b>. <i>(〜たくないです · sopan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP06 · 19:40"}]},{"id":"n5_b13_03","level":"N5","bab":13,"lokasi":"第13課","titleMain":"〜に行く","titleSub":["買いに 行く","遊びに 来る"],"meaning":"Pergi / datang / pulang untuk (melakukan)… — tujuan dari gerakan","formula":"[tempat] へ／に ＋ Ｖ<s>ます</s> ＋ <b>に</b> ＋ <b>行く／来る／帰る</b>（靴を買い<b>に行く</b>）<br>KB kegiatan ＋ <b>に</b> ＋ 行く（買い物<b>に</b>行く ／ 花見<b>に</b>行く）","nuance":"<ol><li><b>に</b> = tujuan/maksud perpindahan.</li><li>Tempat tujuan tetap へ/に: デパート<b>へ</b> 靴を買い<b>に</b>行く.</li><li><b>遊びに来てください</b> = mampir/main ke sini ya.</li></ol>⚠️ Hanya dengan kata kerja <b>gerak</b> (行く・来る・帰る・出かける). KB する: 勉強に = 勉強しに.","examples":[{"jp":"<ruby>神戸<rt>こうべ</rt></ruby>へ インド<ruby>料理<rt>りょうり</rt></ruby>を<ruby>食<rt>た</rt></ruby>べに<ruby>行<rt>い</rt></ruby>きます。","speech":"神戸へインド料理を食べに行きます。","id":"Aku <b>pergi</b> ke Kobe <b>buat makan</b> masakan India. <i>(Ｖます＋に)</i>"},{"jp":"デパートへ<ruby>靴<rt>くつ</rt></ruby>を<ruby>買<rt>か</rt></ruby>いに<ruby>行<rt>い</rt></ruby>きます。","speech":"デパートへ靴を買いに行きます。","id":"Aku <b>pergi</b> ke department store <b>buat beli</b> sepatu. <i>(Ｖます＋に)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>へ<ruby>経済<rt>けいざい</rt></ruby>の<ruby>勉強<rt>べんきょう</rt></ruby>に<ruby>来<rt>き</rt></ruby>ました。","speech":"日本へ経済の勉強に来ました。","id":"Aku <b>datang</b> ke Jepang <b>untuk belajar</b> ekonomi. <i>(KB＋に)</i>"},{"jp":"<ruby>昼<rt>ひる</rt></ruby>ごはんを<ruby>食<rt>た</rt></ruby>べに うちへ<ruby>帰<rt>かえ</rt></ruby>ります。","speech":"昼ごはんを食べにうちへ帰ります。","id":"Aku <b>pulang</b> ke rumah <b>buat makan</b> siang. <i>(〜に帰る)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby>、 <ruby>友<rt>とも</rt></ruby>だちの<ruby>家<rt>いえ</rt></ruby>へ<ruby>遊<rt>あそ</rt></ruby>びに<ruby>行<rt>い</rt></ruby>きました。","speech":"週末、友だちの家へ遊びに行きました。","id":"Akhir pekan aku <b>main</b> ke rumah teman. <i>(遊びに行く)</i>"}],"dialogs":[{"jp":"さて それじゃ<ruby>服<rt>ふく</rt></ruby>を<b><ruby>買<rt>か</rt></ruby>いに<ruby>行<rt>い</rt></ruby>く</b>か","speech":"さてそれじゃ服を買いに行くか","id":"Nah, kalau gitu ayo <b>pergi beli</b> baju. <i>(Ｖます＋に行く)</i>","source":"狼と香辛料 · EP07 · 13:19"},{"jp":"いやあ<ruby>喉<rt>のど</rt></ruby> かわいたわ ジュース<b><ruby>買<rt>か</rt></ruby>いに<ruby>行<rt>い</rt></ruby>こう</b>","speech":"いやあ喉かわいたわジュース買いに行こう","id":"Aduh, haus nih. <b>Pergi beli</b> jus ah. <i>(〜に行こう)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP02 · 08:27"},{"jp":"<ruby>甲府<rt>こうふ</rt></ruby>に<ruby>部品<rt>ぶひん</rt></ruby> <b><ruby>買<rt>か</rt></ruby>いに<ruby>行<rt>い</rt></ruby>っちゃった</b>よ","speech":"甲府に部品買いに行っちゃったよ","id":"Dia <b>pergi</b> ke Kofu <b>buat beli</b> suku cadang. <i>(tempat に ＋ tujuan に)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 14:39"},{"jp":"また いつでも <b><ruby>遊<rt>あそ</rt></ruby>びに<ruby>来<rt>き</rt></ruby>て</b>くださいね","speech":"またいつでも遊びに来てくださいね","id":"Kapan-kapan <b>main ke sini</b> lagi ya. <i>(遊びに来る)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 11:41"},{"jp":"ひとりのお<ruby>友達<rt>ともだち</rt></ruby>が<b><ruby>遊<rt>あそ</rt></ruby>びに<ruby>来<rt>く</rt></ruby>る</b> <ruby>日<rt>ひ</rt></ruby>が<ruby>来<rt>く</rt></ruby>るなんて","speech":"ひとりのお友達が遊びに来る日が来るなんて","id":"Nggak nyangka bakal ada hari teman Hitori <b>datang main</b> ke rumah. <i>(遊びに来る)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 11:21"}]},{"id":"n5_b14_01","level":"N5","bab":14,"lokasi":"第14課","titleMain":"〜てください","titleSub":["待って ください","読んで ください"],"meaning":"Tolong… / silakan… — permintaan, instruksi, atau mempersilakan dengan sopan","formula":"Ｖて形 ＋ <b>ください</b><br>て形 Grup I: い・ち・り→<b>って</b> · み・び・に→<b>んで</b> · き→<b>いて</b> · ぎ→<b>いで</b> · し→<b>して</b> (行く→<b>行って</b>)<br>Grup II: 食べ<b>て</b> · Grup III: <b>して</b> · <b>来て</b>(きて)","nuance":"<ol><li><b>Permintaan</b>: 塩を取ってください.</li><li><b>Instruksi</b>: ここに名前を書いてください.</li><li><b>Mempersilakan</b>: どうぞ食べてください.</li></ol>⚠️ Tetap bernada perintah; ke atasan lebih halus 〜てくださいませんか. Grup II 見せます → 見せ<b>て</b> (×見せって).","examples":[{"jp":"ちょっと<ruby>待<rt>ま</rt></ruby>ってください。","speech":"ちょっと待ってください。","id":"<b>Tolong tunggu</b> sebentar. <i>(permintaan)</i>"},{"jp":"ここに<ruby>住所<rt>じゅうしょ</rt></ruby>と<ruby>名前<rt>なまえ</rt></ruby>を<ruby>書<rt>か</rt></ruby>いてください。","speech":"ここに住所と名前を書いてください。","id":"<b>Tolong tulis</b> alamat dan nama di sini. <i>(instruksi · き → いて)</i>"},{"jp":"すみませんが、あの<ruby>傘<rt>かさ</rt></ruby>を<ruby>見<rt>み</rt></ruby>せてください。","speech":"すみませんが、あの傘を見せてください。","id":"Permisi, <b>tolong perlihatkan</b> payung itu. <i>(permintaan)</i>"},{"jp":"もう<ruby>少<rt>すこ</rt></ruby>し ゆっくり<ruby>話<rt>はな</rt></ruby>してください。","speech":"もう少しゆっくり話してください。","id":"<b>Tolong bicara</b> lebih pelan sedikit. <i>(し → して)</i>"},{"jp":"どうぞ たくさん<ruby>食<rt>た</rt></ruby>べてください。","speech":"どうぞたくさん食べてください。","id":"<b>Silakan makan</b> yang banyak. <i>(mempersilakan)</i>"}],"dialogs":[{"jp":"ちょっと<b><ruby>待<rt>ま</rt></ruby>ってください</b>","speech":"ちょっと待ってください","id":"<b>Tolong tunggu</b> sebentar. <i>(ち → って)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 21:23"},{"jp":"えっ<ruby>見<rt>み</rt></ruby>たいです! <b><ruby>見<rt>み</rt></ruby>せてください</b>!","speech":"えっ見たいです! 見せてください!","id":"Eh, aku mau lihat! <b>Tunjukin dong</b>! <i>(Grup II · 見せて)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 15:11"},{"jp":"<ruby>理由<rt>りゆう</rt></ruby>を<b><ruby>教<rt>おし</rt></ruby>えてください</b>","speech":"理由を教えてください","id":"<b>Tolong kasih tahu</b> alasannya. <i>(permintaan)</i>","source":"ガールズバンドクライ · EP13 · 14:24"},{"jp":"<ruby>次<rt>つぎ</rt></ruby>のページを<b><ruby>読<rt>よ</rt></ruby>んでください</b>","speech":"次のページを読んでください","id":"<b>Silakan baca</b> halaman berikutnya. <i>(み → んで · instruksi)</i>","source":"ガールズバンドクライ · EP12 · 12:30"}]},{"id":"n5_b14_02","level":"N5","bab":14,"lokasi":"第14課","titleMain":"〜ています","titleSub":["雨が 降って います","何して る？"],"meaning":"Sedang… — tindakan yang sedang berlangsung","formula":"Ｖて形 ＋ <b>います</b>（降って<b>います</b> ／ 待って<b>います</b>）<br>Negatif: <b>〜ていません</b><br>Lisan: <b>〜てる / 〜でる</b>（何して<b>る</b>? ／ 待って<b>る</b>）","nuance":"<ol><li>Kata kerja aktivitas + ています = <b>sedang</b>.</li><li>Fenomena alam memakai <b>が</b>: 雨<b>が</b>降っています.</li><li>Percakapan: い hilang → <b>〜てる</b>.</li></ol>⚠️ ています juga bisa = <b>keadaan hasil / kebiasaan</b> (結婚しています, 住んでいます) — lihat 第15課.","examples":[{"jp":"<ruby>今<rt>いま</rt></ruby><ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>っています。","speech":"今雨が降っています。","id":"Sekarang <b>sedang hujan</b>. <i>(fenomena alam ＋ が)</i>"},{"jp":"ミラーさんは<ruby>今<rt>いま</rt></ruby><ruby>電話<rt>でんわ</rt></ruby>をかけています。","speech":"ミラーさんは今電話をかけています。","id":"Pak Miller <b>sedang menelepon</b> sekarang. <i>(sedang)</i>"},{"jp":"<ruby>今<rt>いま</rt></ruby><ruby>何<rt>なに</rt></ruby>をしていますか。……テレビを<ruby>見<rt>み</rt></ruby>ています。","speech":"今何をしていますか。……テレビを見ています。","id":"Sekarang <b>lagi ngapain</b>? … <b>Lagi nonton</b> TV. <i>(tanya-jawab)</i>"},{"jp":"みんなが<ruby>待<rt>ま</rt></ruby>っていますから、 <ruby>早<rt>はや</rt></ruby>く<ruby>行<rt>い</rt></ruby>きましょう。","speech":"みんなが待っていますから、早く行きましょう。","id":"Semua <b>sedang menunggu</b>, ayo cepat berangkat. <i>(sedang)</i>"}],"dialogs":[{"jp":"お<ruby>姉<rt>ねえ</rt></ruby>ちゃん<ruby>何<rt>なに</rt></ruby><b>してる</b>の? ワン ワン!","speech":"お姉ちゃん何してるの? ワンワン!","id":"Kakak <b>lagi ngapain</b>? Guk guk! <i>(してる · lisan)</i>","source":"ぼっち・ざ・ろっく！ · EP12 · 11:07"},{"jp":"<ruby>何<rt>なに</rt></ruby><b>してる</b>んですか?","speech":"何してるんですか?","id":"Kamu <b>lagi ngapain</b>? <i>(〜てるんですか)</i>","source":"この素晴らしい世界に爆焔を！ · EP09 · 08:23"},{"jp":"<ruby>早<rt>はや</rt></ruby>く<ruby>戻<rt>もど</rt></ruby>ろう みんな<b><ruby>待<rt>ま</rt></ruby>ってる</b>から","speech":"早く戻ろうみんな待ってるから","id":"Ayo cepat balik, semua <b>lagi nungguin</b>. <i>(待ってる)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP12 · 10:56"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は ここで<b><ruby>待<rt>ま</rt></ruby>ってる</b>","speech":"私はここで待ってる","id":"Aku <b>tunggu</b> di sini aja. <i>(〜てる · terus menunggu)</i>","source":"トニカクカワイイ · EP07 · 07:48"},{"jp":"<ruby>修斗<rt>しゅうと</rt></ruby>さんは お<ruby>昼<rt>ひる</rt></ruby>ごはん<ruby>作<rt>つく</rt></ruby>って<b><ruby>待<rt>ま</rt></ruby>ってる</b>わよ","speech":"修斗さんはお昼ごはん作って待ってるわよ","id":"Shuto-san lagi bikin makan siang dan <b>nungguin</b> kita, lho. <i>(待ってる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP03 · 01:00"}]},{"id":"n5_b14_03","level":"N5","bab":14,"lokasi":"第14課","titleMain":"〜ましょうか","titleSub":["呼びましょうか","手伝おうか"],"meaning":"Mau saya …-kan? — menawarkan bantuan kepada lawan bicara","formula":"Ｖ<s>ます</s> ＋ <b>ましょうか</b>（タクシーを呼び<b>ましょうか</b>）<br>Kasual: bentuk kehendak ＋ か（手伝<b>おうか</b>?）<br>Jawab: ええ、<b>お願いします</b> ／ いいえ、<b>けっこうです</b>","nuance":"<ol><li>Pelaku = <b>saya</b>, yang diuntungkan = <b>kamu</b>.</li><li>Terima: お願いします. Tolak sopan: けっこうです / 大丈夫です.</li></ol>⚠️ ましょうか juga bisa = <b>ajakan</b> \"yuk kita…?\" (行きましょうか); bedakan dari siapa pelakunya. ませんか = mengundang.","examples":[{"jp":"タクシーを<ruby>呼<rt>よ</rt></ruby>びましょうか。……すみません、お<ruby>願<rt>ねが</rt></ruby>いします。","speech":"タクシーを呼びましょうか。……すみません、お願いします。","id":"<b>Mau saya panggilkan</b> taksi? … Maaf, tolong ya. <i>(terima)</i>"},{"jp":"<ruby>荷物<rt>にもつ</rt></ruby>を<ruby>持<rt>も</rt></ruby>ちましょうか。……いいえ、けっこうです。","speech":"荷物を持ちましょうか。……いいえ、けっこうです。","id":"<b>Mau saya bawakan</b> barangnya? … Nggak usah, terima kasih. <i>(tolak)</i>"},{"jp":"<ruby>暑<rt>あつ</rt></ruby>いですね。 <ruby>窓<rt>まど</rt></ruby>を<ruby>開<rt>あ</rt></ruby>けましょうか。","speech":"暑いですね。窓を開けましょうか。","id":"Panas ya. <b>Mau saya bukakan</b> jendela? <i>(tawaran)</i>"},{"jp":"<ruby>何<rt>なに</rt></ruby>か<ruby>手伝<rt>てつだ</rt></ruby>いましょうか。","speech":"何か手伝いましょうか。","id":"<b>Ada yang bisa saya bantu?</b> <i>(tawaran)</i>"}],"dialogs":[{"jp":"お<ruby>礼<rt>れい</rt></ruby>として もう<ruby>少<rt>すこ</rt></ruby>しだけ<ruby>勧誘<rt>かんゆう</rt></ruby>のお<ruby>手伝<rt>てつだ</rt></ruby>いを<b>しましょうか</b>","speech":"お礼としてもう少しだけ勧誘のお手伝いをしましょうか","id":"Sebagai balasan, <b>gimana kalau aku bantu</b> rekrutmenmu sedikit lagi? <i>(tawaran)</i>","source":"この素晴らしい世界に爆焔を！ · EP07 · 15:03"},{"jp":"<ruby>千歳<rt>ちとせ</rt></ruby>さん<ruby>私<rt>わたし</rt></ruby>のと<ruby>少<rt>すこ</rt></ruby>し<b><ruby>交換<rt>こうかん</rt></ruby>しましょうか</b>","speech":"千歳さん私のと少し交換しましょうか","id":"Chitose-san, <b>mau kutukar</b> sedikit sama punyaku? <i>(tawaran)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP01 · 14:40"},{"jp":"なんなら そのように<b><ruby>紹介<rt>しょうかい</rt></ruby>しましょうか</b>","speech":"なんならそのように紹介しましょうか","id":"Kalau perlu, <b>mau saya perkenalkan</b> begitu saja? <i>(tawaran · menyindir)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP02 · 11:39"},{"jp":"テントの<ruby>組<rt>く</rt></ruby>み<ruby>立<rt>た</rt></ruby>て <b><ruby>手伝<rt>てつだ</rt></ruby>おうか</b>?","speech":"テントの組み立て手伝おうか?","id":"<b>Mau kubantu</b> pasang tenda? <i>(kasual 〜おうか)</i>","source":"ゆるキャン△ SEASON２ · EP01 · 04:48"},{"jp":"もっとグレードの<ruby>高<rt>たか</rt></ruby>い<ruby>石<rt>いし</rt></ruby>もご<ruby>用意<rt>ようい</rt></ruby>がありますので <b>お<ruby>持<rt>も</rt></ruby>ちいたしましょうか</b>","speech":"もっとグレードの高い石もご用意がありますのでお持ちいたしましょうか","id":"Kami juga punya batu dengan grade lebih tinggi, <b>mau saya bawakan</b>? <i>(tawaran · sangat sopan)</i>","source":"トニカクカワイイ · EP05 · 17:07"}]},{"id":"n5_b15_01","level":"N5","bab":15,"lokasi":"第15課","titleMain":"〜てもいいです","titleSub":["〜てもいいですか","〜てもいい？"],"meaning":"Boleh… (kah)? — meminta atau memberi izin","formula":"Ｖて形 ＋ <b>も いいです(か)</b>（撮って<b>もいいですか</b>）<br>Jawab: ええ、いいですよ ／ どうぞ · tolak halus: すみません、ちょっと……<br>Kasual: 〜て<b>もいい?</b> ／ 〜て<b>もいいか?</b> ／ 〜て<b>いい?</b>","nuance":"<ol><li><b>〜てもいいですか</b> = minta izin.</li><li><b>〜てもいいです</b> = memberi izin / \"boleh lah\" (kesediaan).</li><li>Menolak halus: <b>すみません、ちょっと……</b></li></ol>⚠️ \"Tidak perlu…\" = <b>〜なくてもいい</b> (第17課). いいえ、いけません terdengar kaku seperti aturan.","examples":[{"jp":"<ruby>写真<rt>しゃしん</rt></ruby>を<ruby>撮<rt>と</rt></ruby>ってもいいですか。","speech":"写真を撮ってもいいですか。","id":"<b>Boleh</b> saya ambil foto? <i>(minta izin)</i>"},{"jp":"この<ruby>本<rt>ほん</rt></ruby>を<ruby>借<rt>か</rt></ruby>りてもいいですか。……ええ、どうぞ。","speech":"この本を借りてもいいですか。……ええ、どうぞ。","id":"<b>Boleh</b> pinjam buku ini? … Iya, silakan. <i>(izin diberikan)</i>"},{"jp":"ここに<ruby>座<rt>すわ</rt></ruby>ってもいいですか。","speech":"ここに座ってもいいですか。","id":"<b>Boleh</b> saya duduk di sini? <i>(minta izin)</i>"},{"jp":"<ruby>鉛筆<rt>えんぴつ</rt></ruby>で<ruby>書<rt>か</rt></ruby>いてもいいです。","speech":"鉛筆で書いてもいいです。","id":"<b>Boleh</b> nulis pakai pensil. <i>(memberi izin)</i>"}],"dialogs":[{"jp":"<b><ruby>開<rt>あ</rt></ruby>けてもいいですか</b>?","speech":"開けてもいいですか?","id":"<b>Boleh</b> kubuka? <i>(minta izin)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP06 · 16:49"},{"jp":"<ruby>私<rt>わたし</rt></ruby><ruby>原付<rt>げんつ</rt></ruby>きで<b><ruby>行<rt>い</rt></ruby>ってもいいですか</b>?","speech":"私原付きで行ってもいいですか?","id":"<b>Boleh</b> aku pergi naik motor kecil? <i>(minta izin)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 06:42"},{"jp":"このライブのチケット <b><ruby>買<rt>か</rt></ruby>ってもいいですか</b>?","speech":"このライブのチケット買ってもいいですか?","id":"<b>Boleh</b> kami beli tiket live ini? <i>(minta izin)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 18:34"},{"jp":"<ruby>少<rt>すこ</rt></ruby>し<ruby>眠<rt>ねむ</rt></ruby>い... <b><ruby>寝<rt>ね</rt></ruby>てもいいかや</b>?","speech":"少し眠い... 寝てもいいかや?","id":"Agak ngantuk… <b>boleh</b> aku tidur? <i>(kasual · logat Holo)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 14:41"},{"jp":"そ... その<ruby>取<rt>と</rt></ruby>り<ruby>引<rt>ひ</rt></ruby>き <b><ruby>受<rt>う</rt></ruby>けてもいいわ</b>","speech":"そ... その取り引き受けてもいいわ","id":"T-transaksi itu… <b>boleh lah</b> aku terima. <i>(memberi izin / bersedia)</i>","source":"この素晴らしい世界に爆焔を！ · EP12 · 12:20"}]},{"id":"n5_b15_02","level":"N5","bab":15,"lokasi":"第15課","titleMain":"〜てはいけません","titleSub":["〜ちゃいけない","〜ちゃダメ"],"meaning":"Tidak boleh… / dilarang… — larangan (aturan, atasan ke bawahan)","formula":"Ｖて形 ＋ <b>は いけません</b>（吸って<b>はいけません</b>）<br>Lisan: て<b>は</b>→<b>ちゃ</b> · で<b>は</b>→<b>じゃ</b>（食べ<b>ちゃいけない</b> ／ 飲ん<b>じゃダメ</b>）<br><b>ダメ</b> sering menggantikan いけない","nuance":"<ol><li>Untuk <b>aturan / larangan umum</b>, atau orang tua/guru ke anak/murid.</li><li>Nada <b>tegas</b>; jangan dipakai ke atasan.</li><li>Anime: <b>〜ちゃダメ</b> / <b>〜ちゃいけない</b>.</li></ol>⚠️ Minta orang lain jangan melakukan dengan sopan → <b>〜ないでください</b> (第17課).","examples":[{"jp":"ここで たばこを<ruby>吸<rt>す</rt></ruby>ってはいけません。","speech":"ここでたばこを吸ってはいけません。","id":"<b>Dilarang</b> merokok di sini. <i>(aturan)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>、ここで<ruby>遊<rt>あそ</rt></ruby>んでもいいですか。……いいえ、いけません。","speech":"先生、ここで遊んでもいいですか。……いいえ、いけません。","id":"Bu guru, boleh main di sini? … Nggak, <b>nggak boleh</b>. <i>(jawaban larangan)</i>"},{"jp":"<ruby>美術館<rt>びじゅつかん</rt></ruby>で<ruby>写真<rt>しゃしん</rt></ruby>を<ruby>撮<rt>と</rt></ruby>ってはいけません。","speech":"美術館で写真を撮ってはいけません。","id":"Di museum seni <b>nggak boleh</b> ambil foto. <i>(aturan)</i>"},{"jp":"<ruby>試験<rt>しけん</rt></ruby>のとき、 <ruby>辞書<rt>じしょ</rt></ruby>を<ruby>見<rt>み</rt></ruby>てはいけません。","speech":"試験のとき、辞書を見てはいけません。","id":"Waktu ujian <b>nggak boleh</b> lihat kamus. <i>(aturan)</i>"}],"dialogs":[{"jp":"いいですか<ruby>私<rt>わたし</rt></ruby>のそばから<b><ruby>離<rt>はな</rt></ruby>れてはいけません</b>よ","speech":"いいですか私のそばから離れてはいけませんよ","id":"Dengar ya, kamu <b>nggak boleh</b> menjauh dari sisiku. <i>(larangan · sopan)</i>","source":"この素晴らしい世界に爆焔を！ · EP05 · 08:42"},{"jp":"<ruby>彼<rt>かれ</rt></ruby>らの<ruby>死<rt>し</rt></ruby>を ムダに<b>してはいけません</b>","speech":"彼らの死をムダにしてはいけません","id":"Kematian mereka <b>tidak boleh</b> sia-sia. <i>(larangan · tegas)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP11 · 17:18"},{"jp":"<ruby>今晩<rt>こんばん</rt></ruby><ruby>君<rt>きみ</rt></ruby>は<b>きちゃいけない</b>","speech":"今晩君はきちゃいけない","id":"Malam ini kamu <b>nggak boleh datang</b>. <i>(ちゃいけない)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP11 · 17:31"},{"jp":"<ruby>分<rt>わ</rt></ruby>かってないなら <b><ruby>謝<rt>あやま</rt></ruby>っちゃダメです</b>!","speech":"分かってないなら謝っちゃダメです!","id":"Kalau belum ngerti, <b>jangan</b> minta maaf! <i>(ちゃダメ)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP08 · 13:55"},{"jp":"お<ruby>嫁<rt>よめ</rt></ruby>さんを <b><ruby>離<rt>はな</rt></ruby>しちゃダメ</b>だぞ","speech":"お嫁さんを離しちゃダメだぞ","id":"Istrimu <b>jangan</b> sampai dilepas, ya. <i>(ちゃダメ · nasihat)</i>","source":"トニカクカワイイ · EP09 · 11:37"}]},{"id":"n5_b15_03","level":"N5","bab":15,"lokasi":"第15課","titleMain":"〜ています","titleSub":["結婚して います","知って います"],"meaning":"Keadaan yang berlanjut — status/hasil (sudah menikah, tahu, tinggal), kebiasaan, pekerjaan","formula":"Ｖて形 ＋ <b>います</b>（bentuk sama dengan \"sedang\"）<br>Status: 結婚して<b>います</b> · 知って<b>います</b> · 持って<b>います</b><br>Tempat: 大阪<b>に</b>住んでいます · 会社<b>で</b>働いています<br>Negatif 知っています → <b>知りません</b> (kasual 知らない)","nuance":"<ol><li><b>Keadaan hasil</b>: 結婚している = berstatus menikah, bukan \"sedang menikah\".</li><li><b>Kebiasaan</b>: 毎朝ジョギングしている.</li><li><b>Pekerjaan</b>: IMCで働いている.</li></ol>⚠️ ×知っていません → ○<b>知りません</b>. 住む = <b>に</b>, 働く = <b>で</b>.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>結婚<rt>けっこん</rt></ruby>しています。","speech":"私は結婚しています。","id":"Saya <b>sudah menikah</b>. <i>(status)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は IMCで<ruby>働<rt>はたら</rt></ruby>いています。","speech":"私は IMCで働いています。","id":"Saya <b>bekerja</b> di IMC. <i>(pekerjaan · で)</i>"},{"jp":"ミラーさんを<ruby>知<rt>し</rt></ruby>っていますか。……いいえ、<ruby>知<rt>し</rt></ruby>りません。","speech":"ミラーさんを知っていますか。……いいえ、知りません。","id":"Kamu <b>kenal</b> Pak Miller? … Nggak, <b>nggak kenal</b>. <i>(知りません)</i>"},{"jp":"<ruby>妹<rt>いもうと</rt></ruby>は<ruby>大阪<rt>おおさか</rt></ruby>に<ruby>住<rt>す</rt></ruby>んでいます。","speech":"妹は大阪に住んでいます。","id":"Adikku <b>tinggal</b> di Osaka. <i>(住む ＋ に)</i>"},{"jp":"<ruby>毎朝<rt>まいあさ</rt></ruby> ジョギングをしています。","speech":"毎朝ジョギングをしています。","id":"Tiap pagi aku <b>(rutin) jogging</b>. <i>(kebiasaan)</i>"}],"dialogs":[{"jp":"ん? そりゃそうでしょ　だって<ruby>二人<rt>ふたり</rt></ruby>は<b><ruby>結婚<rt>けっこん</rt></ruby>してる</b>んだから","speech":"ん? そりゃそうでしょだって二人は結婚してるんだから","id":"Hm? Ya iyalah, kan mereka berdua <b>sudah menikah</b>. <i>(status)</i>","source":"トニカクカワイイ · EP09 · 09:10"},{"jp":"なんで そうなるんだ<ruby>隣<rt>となり</rt></ruby><b>に<ruby>住<rt>す</rt></ruby>んでる</b>んだよ!","speech":"なんでそうなるんだ隣に住んでるんだよ!","id":"Kok jadi gitu sih! Dia <b>tinggal</b> di sebelah! <i>(住む ＋ に)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP03 · 07:14"},{"jp":"スカラシップって<b><ruby>知<rt>し</rt></ruby>ってる</b>?","speech":"スカラシップって知ってる?","id":"Kamu <b>tahu</b> soal beasiswa (scholarship)? <i>(知っている)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP05 · 18:48"},{"jp":"<b><ruby>知<rt>し</rt></ruby>らない</b>なら あとで URL <ruby>送<rt>おく</rt></ruby>るよ","speech":"知らないならあとで URL 送るよ","id":"Kalau <b>nggak tahu</b>, nanti kukirim URL-nya. <i>(negatif = 知らない)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 17:12"},{"jp":"イヌ<ruby>子<rt>こ</rt></ruby>が<b><ruby>働<rt>はたら</rt></ruby>いてる</b>スーパーの<ruby>隣<rt>となり</rt></ruby>だぞ","speech":"イヌ子が働いてるスーパーの隣だぞ","id":"Di sebelah supermarket tempat Inuko <b>kerja</b>. <i>(pekerjaan)</i>","source":"ゆるキャン△ · EP08 · 18:40"}]},{"id":"n5_b16_01","level":"N5","bab":16,"lokasi":"第16課","titleMain":"〜て、〜て","titleSub":["シャワーを 浴びて、会社へ 行く"],"meaning":"…, lalu …, lalu … — merangkai beberapa tindakan berurutan","formula":"Ｖ₁<b>て</b>、Ｖ₂<b>て</b>、Ｖ₃（ます／ました）<br>Kala & kesopanan = kata kerja <b>terakhir</b>","nuance":"<ol><li>Urutan kata kerja = urutan kejadian.</li><li>Hanya kata kerja terakhir yang menentukan lampau/sekarang.</li><li>Jawaban <b>どうやって</b> (cara/rute) sering memakai pola ini.</li></ol>⚠️ Sekadar contoh kegiatan tanpa urutan → <b>〜たり〜たりする</b>. Menekankan \"setelah selesai, baru\" → <b>〜てから</b>.","examples":[{"jp":"<ruby>朝<rt>あさ</rt></ruby> ジョギングをして、シャワーを<ruby>浴<rt>あ</rt></ruby>びて、 <ruby>会社<rt>かいしゃ</rt></ruby>へ<ruby>行<rt>い</rt></ruby>きます。","speech":"朝ジョギングをして、シャワーを浴びて、会社へ行きます。","id":"Pagi aku jogging, <b>lalu</b> mandi, <b>lalu</b> berangkat kerja. <i>(3 tindakan)</i>"},{"jp":"<ruby>神戸<rt>こうべ</rt></ruby>へ<ruby>行<rt>い</rt></ruby>って、 <ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>て、お<ruby>茶<rt>ちゃ</rt></ruby>を<ruby>飲<rt>の</rt></ruby>みました。","speech":"神戸へ行って、映画を見て、お茶を飲みました。","id":"Aku ke Kobe, <b>lalu</b> nonton film, <b>lalu</b> minum teh. <i>(lampau di akhir)</i>"},{"jp":"<ruby>京都駅<rt>きょうとえき</rt></ruby>から<ruby>１６番<rt>じゅうろくばん</rt></ruby>のバスに<ruby>乗<rt>の</rt></ruby>って、 <ruby>金閣寺前<rt>きんかくじまえ</rt></ruby>で<ruby>降<rt>お</rt></ruby>ります。","speech":"京都駅から１６番のバスに乗って、金閣寺前で降ります。","id":"Dari Stasiun Kyoto naik bus nomor 16, <b>lalu</b> turun di depan Kinkakuji. <i>(rute)</i>"}],"dialogs":[{"jp":"<ruby>周<rt>あまね</rt></ruby>くん　 <ruby>朝<rt>あさ</rt></ruby>ごはん<ruby>出来<rt>でき</rt></ruby>てますから <b><ruby>着替<rt>きが</rt></ruby>えて</b> <ruby>顔<rt>かお</rt></ruby>を<b><ruby>洗<rt>あら</rt></ruby>ってきて</b>ください","speech":"周くん朝ごはん出来てますから着替えて顔を洗ってきてください","id":"Amane-kun, sarapan sudah siap, jadi <b>ganti baju</b> terus <b>cuci muka</b> dulu ya. <i>(urutan · permintaan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP10 · 15:26"},{"jp":"<ruby>火<rt>ひ</rt></ruby><b>おこしして</b>-　ごはん<b><ruby>食<rt>た</rt></ruby>べたら</b>-","speech":"火おこしして-　ごはん食べたら-","id":"<b>Nyalain api</b>, <b>terus makan</b>, habis itu… <i>(urutan)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 06:17"},{"jp":"<ruby>温泉<rt>おんせん</rt></ruby> <b><ruby>入<rt>はい</rt></ruby>って</b> ごはん<b><ruby>食<rt>た</rt></ruby>べたら</b> <ruby>寝<rt>ね</rt></ruby>ちゃって...","speech":"温泉入ってごはん食べたら寝ちゃって...","id":"<b>Berendam</b> di onsen, <b>terus makan</b>, eh langsung ketiduran… <i>(urutan · lampau)</i>","source":"ユーリ!!! on ICE · EP02 · 03:05"},{"jp":"もうちょっとしたら おかゆ<b><ruby>食<rt>た</rt></ruby>べて</b> <ruby>薬<rt>くすり</rt></ruby><b>のもう</b>　それまで<ruby>寝<rt>ね</rt></ruby>てな","speech":"もうちょっとしたらおかゆ食べて薬のもうそれまで寝てな","id":"Sebentar lagi <b>makan</b> bubur, <b>terus minum</b> obat. Sampai itu, tidur dulu. <i>(urutan · ajakan)</i>","source":"３月のライオン 第2シリーズ · EP21 · 10:07"},{"jp":"たくさん<b><ruby>食<rt>た</rt></ruby>べて</b> たくさん<b><ruby>寝<rt>ね</rt></ruby>て</b>...　 <ruby>最低<rt>さいてい</rt></ruby>でも ココアさんよりは<ruby>大<rt>おお</rt></ruby>きくなります","speech":"たくさん食べてたくさん寝て...　最低でもココアさんよりは大きくなります","id":"<b>Makan</b> yang banyak, <b>tidur</b> yang banyak… minimal aku bakal lebih tinggi dari Cocoa-san. <i>(rangkaian)</i>","source":"ご注文はうさぎですか？ · EP04 · 08:42"}]},{"id":"n5_b16_02","level":"N5","bab":16,"lokasi":"第16課","titleMain":"〜てから","titleSub":["食べてから 行く","〜てからでもいい？"],"meaning":"Setelah …, (baru) … — Ｖ₂ dilakukan setelah Ｖ₁ selesai","formula":"Ｖ₁て形 ＋ <b>から</b>、Ｖ₂（お金を入れ<b>てから</b>、ボタンを押す）<br><b>〜てからでもいい?</b> = boleh nanti setelah…? · <b>〜てからだ</b> = itu nanti, setelah…","nuance":"<ol><li>Menekankan <b>urutan / syarat</b>: Ｖ₁ beres dulu, baru Ｖ₂.</li><li>Kala ditentukan <b>Ｖ₂</b>.</li><li>Juga berarti <b>sejak</b>: 日本へ来てから３年.</li></ol>⚠️ Mirip <b>〜たあとで</b> (N4), tapi てから lebih menekankan \"baru setelah itu\". Subjek beda di Ｖ₁ pakai <b>が</b>.","examples":[{"jp":"<ruby>仕事<rt>しごと</rt></ruby>が<ruby>終<rt>お</rt></ruby>わってから、 <ruby>泳<rt>およ</rt></ruby>ぎに<ruby>行<rt>い</rt></ruby>きます。","speech":"仕事が終わってから、泳ぎに行きます。","id":"<b>Setelah</b> kerjaan selesai, aku pergi berenang. <i>(subjek ＋ が)</i>"},{"jp":"お<ruby>金<rt>かね</rt></ruby>を<ruby>入<rt>い</rt></ruby>れてから、ボタンを<ruby>押<rt>お</rt></ruby>してください。","speech":"お金を入れてから、ボタンを押してください。","id":"<b>Setelah</b> masukkan uang, <b>baru</b> tekan tombolnya. <i>(instruksi)</i>"},{"jp":"うちへ<ruby>帰<rt>かえ</rt></ruby>ってから、 <ruby>宿題<rt>しゅくだい</rt></ruby>をします。","speech":"うちへ帰ってから、宿題をします。","id":"<b>Setelah</b> pulang, <b>baru</b> aku ngerjain PR. <i>(urutan)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>へ<ruby>来<rt>き</rt></ruby>てから、もう<ruby>３年<rt>さんねん</rt></ruby>です。","speech":"日本へ来てから、もう３年です。","id":"<b>Sejak</b> datang ke Jepang, sudah 3 tahun. <i>(sejak)</i>"}],"dialogs":[{"jp":"ごはん<b><ruby>食<rt>た</rt></ruby>べてから</b> キャンプ<ruby>場<rt>じょう</rt></ruby><ruby>行<rt>い</rt></ruby>こうかな","speech":"ごはん食べてからキャンプ場行こうかな","id":"<b>Habis</b> makan, <b>baru</b> ke tempat kemah kali ya. <i>(setelah…baru)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 09:22"},{"jp":"<ruby>向<rt>む</rt></ruby>こうで レコーディング<b>してから</b> <ruby>学校<rt>がっこう</rt></ruby>に<ruby>戻<rt>もど</rt></ruby>って","speech":"向こうでレコーディングしてから学校に戻って","id":"Rekaman di sana <b>dulu</b>, <b>baru</b> balik ke sekolah. <i>(urutan)</i>","source":"ガールズバンドクライ · EP08 · 00:34"},{"jp":"<ruby>家<rt>いえ</rt></ruby>に<b><ruby>帰<rt>かえ</rt></ruby>ってから</b> ちゃんと<ruby>言<rt>い</rt></ruby>おう","speech":"家に帰ってからちゃんと言おう","id":"<b>Nanti setelah</b> pulang ke rumah, aku bilang dengan benar. <i>(setelah…baru)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP12 · 16:22"},{"jp":"<ruby>笑<rt>わら</rt></ruby>うのは<ruby>金<rt>かね</rt></ruby>が<b><ruby>入<rt>はい</rt></ruby>ってから</b>　 <ruby>泣<rt>な</rt></ruby>くのは<ruby>破産<rt>はさん</rt></ruby><b>してから</b>だ","speech":"笑うのは金が入ってから泣くのは破産してからだ","id":"Ketawa itu <b>nanti setelah</b> duit masuk; nangis itu <b>nanti setelah</b> bangkrut. <i>(〜てからだ)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP05 · 18:55"},{"jp":"<ruby>決<rt>き</rt></ruby>めるの テスト<b><ruby>終<rt>お</rt></ruby>わってからでもいい</b>?","speech":"決めるのテスト終わってからでもいい?","id":"Mutusinnya <b>boleh nanti setelah</b> ujian selesai? <i>(〜てからでもいい)</i>","source":"ゆるキャン△ · EP08 · 10:43"}]},{"id":"n5_b16_03","level":"N5","bab":16,"lokasi":"第16課","titleMain":"〜くて／〜で","titleSub":["若くて、きれい","静かで、きれい"],"meaning":"… dan … — menyambung dua sifat/keterangan atau lebih","formula":"KS-i: <s>い</s> → <b>くて</b>（若<b>くて</b>） · いい → <b>よくて</b><br>KS-na / KB: ＋ <b>で</b>（きれい<b>で</b> ／ 学生<b>で</b>）<br>Kala & kesopanan = predikat <b>terakhir</b>","nuance":"<ol><li>KS-i → <b>くて</b>, KS-na & KB → <b>で</b>.</li><li>Sifat yang digabung sebaiknya <b>senada</b> (positif + positif).</li><li>Sifat berlawanan → <b>が</b>: おいしいですが、高いです.</li></ol>⚠️ ×きれいくて ×静かくて (KS-na → で). くて juga bisa = \"karena\" (暑くて眠れない).","examples":[{"jp":"マリアさんは<ruby>若<rt>わか</rt></ruby>くて、きれいです。","speech":"マリアさんは若くて、きれいです。","id":"Maria masih muda <b>dan</b> cantik. <i>(KS-i → くて)</i>"},{"jp":"この<ruby>部屋<rt>へや</rt></ruby>は<ruby>広<rt>ひろ</rt></ruby>くて、 <ruby>明<rt>あか</rt></ruby>るいです。","speech":"この部屋は広くて、明るいです。","id":"Kamar ini luas <b>dan</b> terang. <i>(KS-i → くて)</i>"},{"jp":"<ruby>奈良<rt>なら</rt></ruby>は<ruby>静<rt>しず</rt></ruby>かで、きれいな<ruby>町<rt>まち</rt></ruby>です。","speech":"奈良は静かで、きれいな町です。","id":"Nara itu kota yang tenang <b>dan</b> indah. <i>(KS-na → で)</i>"},{"jp":"カリナさんは インドネシア<ruby>人<rt>じん</rt></ruby>で、 <ruby>富士<rt>ふじ</rt></ruby><ruby>大学<rt>だいがく</rt></ruby>の<ruby>留学生<rt>りゅうがくせい</rt></ruby>です。","speech":"カリナさんはインドネシア人で、富士大学の留学生です。","id":"Karina orang Indonesia <b>dan</b> mahasiswi asing di Universitas Fuji. <i>(KB → で)</i>"}],"dialogs":[{"jp":"<b>きれいで かわいくて</b> しかも<ruby>強<rt>つよ</rt></ruby>いだなんて　 <ruby>反則<rt>はんそく</rt></ruby>だよ そけっと!","speech":"きれいでかわいくてしかも強いだなんて反則だよそけっと!","id":"<b>Cantik</b>, <b>imut</b>, terus kuat pula — curang banget kamu, Soketto! <i>(で ＋ くて)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 15:15"},{"jp":"<b><ruby>優<rt>やさ</rt></ruby>しくて</b> <ruby>常識<rt>じょうしき</rt></ruby>のある<ruby>女<rt>おんな</rt></ruby>の<ruby>子<rt>こ</rt></ruby>だ","speech":"優しくて常識のある女の子だ","id":"Cewek yang <b>baik dan</b> punya akal sehat! <i>(KS-i → くて)</i>","source":"この素晴らしい世界に祝福を！2 · EP06 · 17:41"},{"jp":"<ruby>夜景<rt>やけい</rt></ruby>が<b>きれいで</b> <ruby>1泊<rt>いっぱく</rt></ruby><ruby>1000円<rt>せんえん</rt></ruby>!","speech":"夜景がきれいで1泊1000円!","id":"Pemandangan malamnya <b>indah</b>, <b>dan</b> semalam cuma 1000 yen! <i>(KS-na → で)</i>","source":"ゆるキャン△ · EP04 · 11:43"},{"jp":"<ruby>本当<rt>ほんとう</rt></ruby><b><ruby>静<rt>しず</rt></ruby>かで</b> <ruby>誰<rt>だれ</rt></ruby>もいないねー","speech":"本当静かで誰もいないねー","id":"<b>Sepi banget</b> ya, <b>dan</b> nggak ada orang sama sekali. <i>(KS-na → で)</i>","source":"トニカクカワイイ · EP05 · 09:19"},{"jp":"<b>きれいで</b> スタイル<b>よくて</b>　 <ruby>勉強<rt>べんきょう</rt></ruby>も<ruby>運動<rt>うんどう</rt></ruby>も<ruby>家事<rt>かじ</rt></ruby>もできて おしとやかで","speech":"きれいでスタイルよくて勉強も運動も家事もできておしとやかで","id":"<b>Cantik</b>, badannya <b>bagus</b>, pinter belajar, olahraga, kerjaan rumah, terus anggun pula. <i>(いい → よくて)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP05 · 16:17"}]},{"id":"n5_b16_04","level":"N5","bab":16,"lokasi":"第16課","titleMain":"〜は 〜が＋形容詞","titleSub":["マリアさんは 髪が 長い","頭が いい"],"meaning":"N₁ itu N₂-nya … — menjelaskan ciri bagian/aspek dari suatu topik","formula":"Ｎ₁ <b>は</b> ＋ Ｎ₂ <b>が</b> ＋ KS（マリアさん<b>は</b> 髪<b>が</b> 長いです）<br>Ciri fisik: 髪が長い · 背が高い · 目が大きい · 頭がいい · 耳がいい<br>Tempat: 東京<b>は</b> 人<b>が</b> 多い","nuance":"<ol><li><b>は</b> = topik (orang/tempat), <b>が</b> = bagiannya, KS = sifat bagian itu.</li><li>Paling sering untuk <b>ciri fisik & kemampuan</b>.</li><li>Bisa digabung: 目が大きくて、髪が長い.</li></ol>⚠️ <b>頭がいい</b> = pintar, <b>頭が痛い</b> = sakit kepala. 髪が<b>いたい</b> salah → 髪が<b>長い</b>.","examples":[{"jp":"マリアさんは<ruby>髪<rt>かみ</rt></ruby>が<ruby>長<rt>なが</rt></ruby>いです。","speech":"マリアさんは髪が長いです。","id":"Maria <b>rambutnya panjang</b>. <i>(ciri fisik)</i>"},{"jp":"ミラーさんは<ruby>背<rt>せ</rt></ruby>が<ruby>高<rt>たか</rt></ruby>いです。","speech":"ミラーさんは背が高いです。","id":"Pak Miller <b>badannya tinggi</b>. <i>(ciri fisik)</i>"},{"jp":"<ruby>東京<rt>とうきょう</rt></ruby>は<ruby>人<rt>ひと</rt></ruby>が<ruby>多<rt>おお</rt></ruby>いです。","speech":"東京は人が多いです。","id":"Tokyo <b>orangnya banyak</b>. <i>(tempat)</i>"},{"jp":"マリアさんは<ruby>目<rt>め</rt></ruby>が<ruby>大<rt>おお</rt></ruby>きくて、 <ruby>髪<rt>かみ</rt></ruby>が<ruby>長<rt>なが</rt></ruby>いです。","speech":"マリアさんは目が大きくて、髪が長いです。","id":"Maria <b>matanya besar dan rambutnya panjang</b>. <i>(digabung くて)</i>"}],"dialogs":[{"jp":"あの<ruby>子<rt>こ</rt></ruby><b>は</b> <ruby>私<rt>わたし</rt></ruby>の<ruby>次<rt>つぎ</rt></ruby>に<b><ruby>頭<rt>あたま</rt></ruby>が いい</b>んです","speech":"あの子は私の次に頭がいいんです","id":"Anak itu <b>pinternya</b> nomor dua setelah aku. <i>(頭がいい)</i>","source":"この素晴らしい世界に爆焔を！ · EP04 · 13:52"},{"jp":"わっちゃあ<ruby>特別<rt>とくべつ</rt></ruby><b><ruby>耳<rt>みみ</rt></ruby>が よく</b> <ruby>内緒話<rt>ないしょばなし</rt></ruby>も<ruby>筒抜<rt>つつぬ</rt></ruby>けじゃ","speech":"わっちゃあ特別耳がよく内緒話も筒抜けじゃ","id":"Aku ini <b>telinganya</b> sangat <b>tajam</b>, bisik-bisik pun kedengaran. <i>(耳がいい)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP10 · 12:18"},{"jp":"<ruby>俺<rt>おれ</rt></ruby>の<ruby>好<rt>す</rt></ruby>きなやつ<b>は</b> <ruby>俺<rt>おれ</rt></ruby>より<b><ruby>背<rt>せ</rt></ruby>が<ruby>高<rt>たか</rt></ruby>い</b>","speech":"俺の好きなやつは俺より背が高い","id":"Orang yang kusukai itu <b>badannya lebih tinggi</b> dariku. <i>(背が高い ＋ より)</i>","source":"カードキャプターさくら · EP55 · 17:55"},{"jp":"そのお<ruby>相手<rt>あいて</rt></ruby><b>は</b> あなたより<b><ruby>髪<rt>かみ</rt></ruby>が<ruby>長<rt>なが</rt></ruby>い</b>ですか?","speech":"そのお相手はあなたより髪が長いですか?","id":"Orang itu <b>rambutnya lebih panjang</b> dari kamu? <i>(髪が長い)</i>","source":"安達としまむら · EP11 · 07:18"},{"jp":"じ... <ruby>自分<rt>じぶん</rt></ruby>の<b><ruby>髪<rt>かみ</rt></ruby>が<ruby>長<rt>なが</rt></ruby>い</b>から<ruby>髪<rt>かみ</rt></ruby>を<ruby>結<rt>むす</rt></ruby>ぶ<ruby>機会<rt>きかい</rt></ruby>が<ruby>多<rt>おお</rt></ruby>いだけで...","speech":"じ... 自分の髪が長いから髪を結ぶ機会が多いだけで...","id":"A-aku cuma sering ngikat rambut karena <b>rambutku panjang</b>… <i>(髪が長い)</i>","source":"ご注文はうさぎですか？ · EP08 · 05:27"}]},{"id":"n5_b17_01","level":"N5","bab":17,"lokasi":"第17課","titleMain":"〜ないでください","titleSub":["撮らないで ください","心配しないで"],"meaning":"Tolong jangan… — permintaan sopan agar orang lain tidak melakukan sesuatu","formula":"Ｖない形 ＋ <b>でください</b>（撮らない<b>でください</b>）<br>ない形 Grup I: -i → <b>-a＋ない</b>（書か<b>ない</b>）, い → <b>わ</b>（買わ<b>ない</b>） · Grup II: 食べ<b>ない</b> · Grup III: <b>しない</b> · <b>来ない</b>(こない)<br>Kasual: <b>〜ないで</b> ／ <b>〜ないでくれ</b>","nuance":"<ol><li>Versi negatif dari 〜てください.</li><li>Bisa bernada <b>perhatian</b>: 心配しないでください.</li><li>Objek sering jadi topik: 荷物<b>は</b>ここに置かないでください.</li></ol>⚠️ <b>てはいけません</b> = larangan/aturan (tegas); <b>ないでください</b> = permintaan. ある → <b>ない</b> (×あらない).","examples":[{"jp":"ここで<ruby>写真<rt>しゃしん</rt></ruby>を<ruby>撮<rt>と</rt></ruby>らないでください。","speech":"ここで写真を撮らないでください。","id":"<b>Tolong jangan</b> ambil foto di sini. <i>(permintaan)</i>"},{"jp":"わたしは<ruby>元気<rt>げんき</rt></ruby>ですから、<ruby>心配<rt>しんぱい</rt></ruby>しないでください。","speech":"わたしは元気ですから、心配しないでください。","id":"Aku baik-baik aja, jadi <b>jangan khawatir</b>. <i>(perhatian)</i>"},{"jp":"<ruby>約束<rt>やくそく</rt></ruby>を<ruby>忘<rt>わす</rt></ruby>れないでください。","speech":"約束を忘れないでください。","id":"<b>Jangan lupa</b> janjinya ya. <i>(permintaan)</i>"},{"jp":"<ruby>大切<rt>たいせつ</rt></ruby>な<ruby>書類<rt>しょるい</rt></ruby>ですから、なくさないでください。","speech":"大切な書類ですから、なくさないでください。","id":"Ini dokumen penting, jadi <b>jangan sampai hilang</b>. <i>(permintaan)</i>"}],"dialogs":[{"jp":"あまりジロジロ<b><ruby>見<rt>み</rt></ruby>ないでください</b>","speech":"あまりジロジロ見ないでください","id":"<b>Tolong jangan</b> ngeliatin aku terus begitu. <i>(permintaan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP01 · 20:08"},{"jp":"もう<ruby>後<rt>あと</rt></ruby>がないんです <b><ruby>見捨<rt>みす</rt></ruby>てないでください</b>!","speech":"もう後がないんです見捨てないでください!","id":"Aku udah nggak punya pilihan lain! <b>Jangan</b> tinggalkan aku! <i>(memohon)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 00:30"},{"jp":"<ruby>宿題<rt>しゅくだい</rt></ruby> <b><ruby>忘<rt>わす</rt></ruby>れないでください</b>ね","speech":"宿題忘れないでくださいね","id":"PR-nya <b>jangan lupa</b> ya. <i>(mengingatkan)</i>","source":"青春ブタ野郎はサンタクロースの夢を見ない · EP08 · 22:44"},{"jp":"そんなこと<b><ruby>心配<rt>しんぱい</rt></ruby>しないで</b>","speech":"そんなこと心配しないで","id":"<b>Nggak usah khawatir</b> soal itu. <i>(kasual 〜ないで · perhatian)</i>","source":"トニカクカワイイ · EP12 · 04:05"},{"jp":"<ruby>置<rt>お</rt></ruby>いていか<b>ないでくれ</b>よー!","speech":"置いていかないでくれよー!","id":"<b>Jangan</b> tinggalin aku dong! <i>(〜ないでくれ · kasual)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 06:35"}]},{"id":"n5_b17_02","level":"N5","bab":17,"lokasi":"第17課","titleMain":"〜なければなりません","titleSub":["〜なければならない","〜なきゃ"],"meaning":"Harus… / wajib… — keharusan (aturan, keadaan, kewajiban)","formula":"Ｖない形 → <s>い</s> ＋ <b>ければなりません</b>（飲ま<b>なければなりません</b>）<br>≈ <b>〜なければいけません</b><br>Lisan: <b>〜なきゃ</b> ／ <b>〜なくちゃ</b> ／ 〜なきゃいけない","nuance":"<ol><li>Negatif ganda (\"kalau tidak…, tidak bisa\") = <b>harus</b>.</li><li>Kewajiban umum: aturan, keadaan, juga keputusan sendiri.</li><li>Anime: <b>行かなきゃ!</b> = harus pergi!</li></ol>⚠️ Jawaban \"tidak harus\" → <b>〜なくてもいいです</b> (bukan ×なければなりません + negatif).","examples":[{"jp":"<ruby>薬<rt>くすり</rt></ruby>を<ruby>飲<rt>の</rt></ruby>まなければなりません。","speech":"薬を飲まなければなりません。","id":"Aku <b>harus</b> minum obat. <i>(kewajiban)</i>"},{"jp":"パスポートを<ruby>見<rt>み</rt></ruby>せなければなりません。","speech":"パスポートを見せなければなりません。","id":"Kamu <b>harus</b> menunjukkan paspor. <i>(aturan)</i>"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>漢字<rt>かんじ</rt></ruby>を<ruby>練習<rt>れんしゅう</rt></ruby>しなければなりません。","speech":"毎日漢字を練習しなければなりません。","id":"Tiap hari aku <b>harus</b> latihan kanji. <i>(keputusan sendiri)</i>"},{"jp":"もう<ruby>１０時<rt>じゅうじ</rt></ruby>だ。<ruby>帰<rt>かえ</rt></ruby>らなきゃ。","speech":"もう１０時だ。帰らなきゃ。","id":"Udah jam 10. <b>Harus</b> pulang. <i>(lisan)</i>"}],"dialogs":[{"jp":"<ruby>春<rt>はる</rt></ruby>に<ruby>向<rt>む</rt></ruby>けての<ruby>在庫<rt>ざいこ</rt></ruby>も<b><ruby>揃<rt>そろ</rt></ruby>えなければなりません</b>し","speech":"春に向けての在庫も揃えなければなりませんし","id":"Aku juga <b>harus</b> nyiapin stok buat musim semi. <i>(sopan)</i>","source":"狼と香辛料 · EP10 · 18:35"},{"jp":"つまり お<ruby>前<rt>まえ</rt></ruby>の<ruby>借金<rt>しゃっきん</rt></ruby>は お<ruby>前<rt>まえ</rt></ruby>の<ruby>力<rt>ちから</rt></ruby>で<b><ruby>返<rt>かえ</rt></ruby>さなければならない</b>","speech":"つまりお前の借金はお前の力で返さなければならない","id":"Artinya, utangmu <b>harus</b> kamu bayar dengan kekuatanmu sendiri. <i>(biasa)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP09 · 17:18"},{"jp":"<ruby>忘<rt>わす</rt></ruby>れ<ruby>物<rt>もの</rt></ruby>だよ すぐ<b><ruby>行<rt>い</rt></ruby>かなきゃ</b>","speech":"忘れ物だよすぐ行かなきゃ","id":"Ada barang ketinggalan! <b>Harus</b> cepat pergi! <i>(なきゃ · lisan)</i>","source":"ガールズバンドクライ · EP04 · 20:29"},{"jp":"<ruby>肝臓<rt>かんぞう</rt></ruby> <b><ruby>売<rt>う</rt></ruby>りに<ruby>行<rt>い</rt></ruby>かなきゃ</b>","speech":"肝臓売りに行かなきゃ","id":"Aku <b>harus</b> pergi jual hati (organ)ku… <i>(なきゃ · lisan)</i>","source":"ぼっち・ざ・ろっく！ · EP05 · 01:34"},{"jp":"また<ruby>浜名湖<rt>はまなこ</rt></ruby>まで <b><ruby>来<rt>こ</rt></ruby>なきゃいけなく</b>なる","speech":"また浜名湖まで来なきゃいけなくなる","id":"Nanti aku <b>harus</b> datang lagi ke Danau Hamana. <i>(なきゃいけない)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 11:51"}]},{"id":"n5_b17_03","level":"N5","bab":17,"lokasi":"第17課","titleMain":"〜なくてもいいです","titleSub":["来なくても いい","〜なくていい"],"meaning":"Tidak perlu… / tidak usah… — tidak ada kewajiban","formula":"Ｖない形 → <s>い</s> ＋ <b>くても いいです</b>（来<b>なくてもいいです</b>）<br>Lisan: <b>〜なくていい(よ)</b><br>Jawaban dari 〜なければなりませんか","nuance":"<ol><li>〜なくて (て形 dari ない) ＋ もいい = boleh <b>tidak</b> melakukan.</li><li>Sering untuk menenangkan: 心配しなくていいよ.</li></ol>⚠️ 〜て<b>も</b>いい = boleh melakukan; 〜な<b>くて</b>もいい = tidak perlu. ないでください = melarang, なくてもいい = membebaskan.","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby><ruby>来<rt>こ</rt></ruby>なくてもいいです。","speech":"明日来なくてもいいです。","id":"Besok <b>nggak perlu datang</b>. <i>(tidak perlu)</i>"},{"jp":"<ruby>土曜日<rt>どようび</rt></ruby>の<ruby>午後<rt>ごご</rt></ruby>は<ruby>勉強<rt>べんきょう</rt></ruby>しなくてもいいです。","speech":"土曜日の午後は勉強しなくてもいいです。","id":"Sabtu sore <b>nggak perlu belajar</b>. <i>(tidak perlu)</i>"},{"jp":"お<ruby>金<rt>かね</rt></ruby>を<ruby>払<rt>はら</rt></ruby>わなければなりませんか。……いいえ、<ruby>払<rt>はら</rt></ruby>わなくてもいいです。","speech":"お金を払わなければなりませんか。……いいえ、払わなくてもいいです。","id":"Harus bayar? … Nggak, <b>nggak perlu bayar</b>. <i>(jawaban)</i>"},{"jp":"<ruby>靴<rt>くつ</rt></ruby>を<ruby>脱<rt>ぬ</rt></ruby>がなくてもいいですよ。","speech":"靴を脱がなくてもいいですよ。","id":"<b>Nggak usah</b> lepas sepatu kok. <i>(tidak perlu)</i>"}],"dialogs":[{"jp":"<b>しゃべらなくてもいい</b>　ただ<ruby>聞<rt>き</rt></ruby>いておいて","speech":"しゃべらなくてもいいただ聞いておいて","id":"<b>Nggak usah ngomong</b>, dengerin aja. <i>(なくてもいい)</i>","source":"ガールズバンドクライ · EP08 · 19:36"},{"jp":"<ruby>無理<rt>むり</rt></ruby>して<b><ruby>来<rt>こ</rt></ruby>なくてもいい</b>と<ruby>言<rt>い</rt></ruby>ったじゃない","speech":"無理して来なくてもいいと言ったじゃない","id":"Kan udah kubilang <b>nggak usah</b> maksa <b>datang</b>. <i>(来なくてもいい)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP08 · 12:40"},{"jp":"<b><ruby>分<rt>わ</rt></ruby>からなくてもいいです</b>!","speech":"分からなくてもいいです!","id":"Kamu <b>nggak perlu ngerti</b>! <i>(sopan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP07 · 05:11"},{"jp":"そんなに<ruby>辛<rt>から</rt></ruby>くないから <b><ruby>心配<rt>しんぱい</rt></ruby>しなくていい</b>よ","speech":"そんなに辛くないから心配しなくていいよ","id":"Nggak terlalu pedas kok, <b>nggak usah khawatir</b>. <i>(なくていい · menenangkan)</i>","source":"ゆるキャン△ · EP03 · 09:44"},{"jp":"もう お<ruby>仕事<rt>しごと</rt></ruby>なんか <b>しなくていい</b>から","speech":"もうお仕事なんかしなくていいから","id":"Kamu <b>nggak usah kerja</b> lagi, deh. <i>(なくていい · lisan)</i>","source":"ぼっち・ざ・ろっく！ · EP08 · 14:57"}]},{"id":"n5_b17_04","level":"N5","bab":17,"lokasi":"第17課","titleMain":"〜までに","titleSub":["５時までに 帰る","５時まで 働く"],"meaning":"Paling lambat… / sebelum (batas waktu)… — tenggat sebuah tindakan","formula":"[waktu／Ｖる] ＋ <b>までに</b> ＋ tindakan sekali（５時<b>までに</b>帰る）<br>Bandingkan: [waktu] ＋ <b>まで</b> ＋ tindakan berlanjut（５時<b>まで</b>働く）","nuance":"<ol><li><b>までに</b> = selesai pada/sebelum batas waktu (deadline).</li><li><b>まで</b> = berlangsung terus sampai waktu itu.</li><li>Sering dengan 〜なければなりません / 〜てください.</li></ol>⚠️ ×５時までに働きます (働く berlanjut → まで). ×５時まで帰ります (帰る sekali → までに).","examples":[{"jp":"<ruby>会議<rt>かいぎ</rt></ruby>は<ruby>５時<rt>ごじ</rt></ruby>までに <ruby>終<rt>お</rt></ruby>わります。","speech":"会議は５時までに終わります。","id":"Rapatnya selesai <b>paling lambat</b> jam 5. <i>(batas waktu)</i>"},{"jp":"<ruby>土曜日<rt>どようび</rt></ruby>までに <ruby>本<rt>ほん</rt></ruby>を<ruby>返<rt>かえ</rt></ruby>さなければなりません。","speech":"土曜日までに本を返さなければなりません。","id":"Aku harus balikin buku <b>paling lambat</b> hari Sabtu. <i>(＋ なければ)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>までに レポートを<ruby>出<rt>だ</rt></ruby>してください。","speech":"明日までにレポートを出してください。","id":"Tolong kumpulkan laporan <b>paling lambat</b> besok. <i>(＋ てください)</i>"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby> <ruby>５時<rt>ごじ</rt></ruby>まで <ruby>働<rt>はたら</rt></ruby>きます。","speech":"毎日５時まで働きます。","id":"Tiap hari aku kerja <b>sampai</b> jam 5. <i>(まで · kontras)</i>"}],"dialogs":[{"jp":"<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>だって　<b><ruby>朝<rt>あさ</rt></ruby>までに</b> <ruby>全部<rt>ぜんぶ</rt></ruby><ruby>飲<rt>の</rt></ruby>み...","speech":"大丈夫だって朝までに全部飲み...","id":"Tenang aja, <b>sebelum pagi</b> semuanya kuminum habis… <i>(batas waktu)</i>","source":"ガールズバンドクライ · EP09 · 07:24"},{"jp":"<b><ruby>来週<rt>らいしゅう</rt></ruby>までに</b> もう<ruby>少<rt>すこ</rt></ruby>し<ruby>稼<rt>かせ</rt></ruby>ごうと<ruby>思<rt>おも</rt></ruby>って","speech":"来週までにもう少し稼ごうと思って","id":"Aku mau cari duit sedikit lagi <b>sebelum minggu depan</b>. <i>(tenggat)</i>","source":"ゆるキャン△ · EP04 · 02:21"},{"jp":"<b><ruby>明日<rt>あした</rt></ruby>までには</b> <ruby>形<rt>かたち</rt></ruby>にするわ","speech":"明日までには形にするわ","id":"<b>Paling lambat besok</b> sudah kubikin jadi. <i>(までには · penegasan)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP05 · 22:38"},{"jp":"じゃあ<ruby>今度<rt>こんど</rt></ruby><ruby>来<rt>く</rt></ruby>る<b>ときまでに</b> <ruby>練習<rt>れんしゅう</rt></ruby>しとくね","speech":"じゃあ今度来るときまでに練習しとくね","id":"Kalau gitu, aku latihan dulu <b>sebelum</b> kamu datang lagi ya. <i>(Ｖる＋ときまでに)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 07:16"},{"jp":"とにかく <b><ruby>明日<rt>あした</rt></ruby>の<ruby>日没<rt>にちぼつ</rt></ruby>までに</b> あいつが<ruby>買<rt>か</rt></ruby>い<ruby>込<rt>こ</rt></ruby>んだ<ruby>黄鉄鉱<rt>おうてっこう</rt></ruby>を　ただの<ruby>石<rt>いし</rt></ruby>ころにしなきゃ ならないんだ","speech":"とにかく明日の日没までにあいつが買い込んだ黄鉄鉱をただの石ころにしなきゃならないんだ","id":"Pokoknya <b>paling lambat matahari terbenam besok</b>, pirit yang dia borong harus jadi batu biasa. <i>(までに ＋ なきゃならない)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP17 · 03:41"}]},{"id":"n5_b18_01","level":"N5","bab":18,"lokasi":"第18課","titleMain":"〜ことができる","titleSub":["読む ことが できます","日本語が できます"],"meaning":"Bisa… / dapat… — kemampuan atau kemungkinan (situasi)","formula":"Ｖ辞書形 ＋ <b>ことが できます</b>（読む<b>ことができます</b>）<br>KB ＋ <b>が できます</b>（日本語<b>ができます</b>）<br>辞書形: Grup I -i→<b>-u</b>（書き→書<b>く</b>） · II ＋<b>る</b>（食べ<b>る</b>） · III <b>する</b> · <b>来る</b>(くる)","nuance":"<ol><li><b>Kemampuan</b>: 漢字を読むことができる.</li><li><b>Kemungkinan</b> (situasi/tempat): ここでお金を換えることができる.</li><li>Negatif: <b>〜ことができません</b>; なかなか〜ことができない = susah sekali bisa.</li></ol>⚠️ Lebih formal dari potensial (読める). <b>こと</b> wajib: ×読むができる.","examples":[{"jp":"ミラーさんは<ruby>漢字<rt>かんじ</rt></ruby>を<ruby>読<rt>よ</rt></ruby>むことができます。","speech":"ミラーさんは漢字を読むことができます。","id":"Pak Miller <b>bisa</b> membaca kanji. <i>(kemampuan)</i>"},{"jp":"このホテルで お<ruby>金<rt>かね</rt></ruby>を<ruby>換<rt>か</rt></ruby>えることができます。","speech":"このホテルでお金を換えることができます。","id":"Di hotel ini <b>bisa</b> tukar uang. <i>(kemungkinan)</i>"},{"jp":"<ruby>車<rt>くるま</rt></ruby>の<ruby>運転<rt>うんてん</rt></ruby>ができますか。……いいえ、できません。","speech":"車の運転ができますか。……いいえ、できません。","id":"Kamu <b>bisa</b> nyetir mobil? … Nggak, <b>nggak bisa</b>. <i>(KB ＋ ができる)</i>"},{"jp":"なかなか<ruby>日本<rt>にほん</rt></ruby>で<ruby>馬<rt>うま</rt></ruby>を<ruby>見<rt>み</rt></ruby>ることができません。","speech":"なかなか日本で馬を見ることができません。","id":"Di Jepang <b>susah sekali bisa</b> lihat kuda. <i>(なかなか ＋ negatif)</i>"}],"dialogs":[{"jp":"<ruby>干潮時<rt>かんちょうじ</rt></ruby>には<ruby>海岸<rt>かいがん</rt></ruby>から<ruby>島<rt>しま</rt></ruby>へ<ruby>歩<rt>ある</rt></ruby>いて<b><ruby>渡<rt>わた</rt></ruby>ることができます</b>","speech":"干潮時には海岸から島へ歩いて渡ることができます","id":"Saat surut, kita <b>bisa</b> menyeberang ke pulau jalan kaki dari pantai. <i>(kemungkinan)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 03:56"},{"jp":"えっと<ruby>羊<rt>ひつじ</rt></ruby>を<ruby>育<rt>そだ</rt></ruby>てる<ruby>以外<rt>いがい</rt></ruby>にも<ruby>狼<rt>おおかみ</rt></ruby>を<b><ruby>払<rt>はら</rt></ruby>うことができます</b>","speech":"えっと羊を育てる以外にも狼を払うことができます","id":"Eh… selain beternak domba, aku juga <b>bisa</b> mengusir serigala. <i>(kemampuan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP08 · 03:35"},{"jp":"とても<ruby>弱<rt>よわ</rt></ruby>いモンスターで<ruby>簡単<rt>かんたん</rt></ruby>に<b><ruby>倒<rt>たお</rt></ruby>すことができます</b>が","speech":"とても弱いモンスターで簡単に倒すことができますが","id":"Monsternya lemah banget, jadi <b>bisa</b> dikalahkan dengan mudah, tapi… <i>(kemungkinan)</i>","source":"この素晴らしい世界に祝福を！ · EP07 · 05:32"},{"jp":"<ruby>少<rt>すく</rt></ruby>なくとも<ruby>第一歩<rt>だいいっぽ</rt></ruby>は<b><ruby>踏<rt>ふ</rt></ruby>み<ruby>出<rt>だ</rt></ruby>すことができる</b>","speech":"少なくとも第一歩は踏み出すことができる","id":"Setidaknya kita <b>bisa</b> melangkah langkah pertama. <i>(bentuk biasa)</i>","source":"ガールズバンドクライ · EP08 · 09:00"},{"jp":"<ruby>見<rt>み</rt></ruby>ることはできても<ruby>手<rt>て</rt></ruby>に<b><ruby>入<rt>い</rt></ruby>れることができない</b>もの","speech":"見ることはできても手に入れることができないもの","id":"Sesuatu yang bisa dilihat, tapi <b>nggak bisa</b> didapatkan. <i>(negatif)</i>","source":"トニカクカワイイ · EP04 · 14:30"}]},{"id":"n5_b18_02","level":"N5","bab":18,"lokasi":"第18課","titleMain":"趣味は〜ことです","titleSub":["趣味は 映画を見る ことです","夢は〜ことだ"],"meaning":"Hobi (mimpi, tugas, tujuan) saya adalah …-ing — menjadikan kata kerja sebagai predikat","formula":"[趣味／夢／仕事／目的] <b>は</b> ＋ Ｖ辞書形 ＋ <b>ことです</b><br>（趣味は 映画を見る<b>ことです</b>）<br>Tanya sopan: <b>ご趣味は?</b>","nuance":"<ol><li>Kata kerja perlu <b>こと</b> agar bisa jadi \"adalah …\".</li><li>Pola sama untuk <b>夢は</b> (mimpi), <b>仕事は</b> (tugas), <b>目的は</b> (tujuan).</li><li>Lebih spesifik dari KB: 趣味は音楽 → 趣味はピアノを弾くこと.</li></ol>⚠️ ×趣味は映画を見るです → wajib <b>こと</b>.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>の<ruby>趣味<rt>しゅみ</rt></ruby>は <ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>ることです。","speech":"私の趣味は映画を見ることです。","id":"Hobiku <b>nonton</b> film. <i>(趣味は〜こと)</i>"},{"jp":"<ruby>趣味<rt>しゅみ</rt></ruby>は <ruby>何<rt>なん</rt></ruby>ですか。…… <ruby>写真<rt>しゃしん</rt></ruby>を<ruby>撮<rt>と</rt></ruby>ることです。","speech":"趣味は何ですか。…… 写真を撮ることです。","id":"Hobimu apa? … <b>Motret</b>. <i>(tanya-jawab)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>の<ruby>夢<rt>ゆめ</rt></ruby>は <ruby>日本<rt>にほん</rt></ruby>で<ruby>働<rt>はたら</rt></ruby>くことです。","speech":"私の夢は日本で働くことです。","id":"Mimpiku <b>kerja</b> di Jepang. <i>(夢は〜こと)</i>"}],"dialogs":[{"jp":"<b>ご<ruby>趣味<rt>しゅみ</rt></ruby>は</b>? お...","speech":"ご趣味は? お...","id":"<b>Hobinya apa</b>? Eh… <i>(tanya sopan)</i>","source":"この素晴らしい世界に祝福を！2 · EP04 · 12:47"},{"jp":"オレの<b><ruby>夢<rt>ゆめ</rt></ruby>は</b>な あいつの<ruby>商会<rt>しょうかい</rt></ruby>を<b><ruby>超<rt>こ</rt></ruby>えることだ</b>","speech":"オレの夢はなあいつの商会を超えることだ","id":"<b>Mimpiku</b> itu <b>melampaui</b> perusahaan dagang dia. <i>(夢は〜ことだ)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP11 · 08:33"},{"jp":"<b><ruby>仕事<rt>しごと</rt></ruby>は</b> <ruby>羊<rt>ひつじ</rt></ruby>を<ruby>連<rt>つ</rt></ruby>れて<b><ruby>歩<rt>ある</rt></ruby>くこと</b>　そして<ruby>無事<rt>ぶじ</rt></ruby>に<b><ruby>連<rt>つ</rt></ruby>れ<ruby>戻<rt>もど</rt></ruby>すことです</b>","speech":"仕事は羊を連れて歩くことそして無事に連れ戻すことです","id":"<b>Tugasmu</b> adalah <b>membawa</b> domba berjalan, dan <b>membawanya pulang</b> dengan selamat. <i>(仕事は〜ことです)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP10 · 16:23"},{"jp":"だが<ruby>今回<rt>こんかい</rt></ruby>のあいつの<b><ruby>目的<rt>もくてき</rt></ruby>は もうけることじゃない</b>","speech":"だが今回のあいつの目的はもうけることじゃない","id":"Tapi <b>tujuan</b> dia kali ini <b>bukan cari untung</b>. <i>(目的は〜ことじゃない)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP18 · 19:37"},{"jp":"フィトリアの<b><ruby>役目<rt>やくめ</rt></ruby>は</b> <ruby>世界<rt>せかい</rt></ruby>を<b><ruby>守<rt>まも</rt></ruby>ること</b>","speech":"フィトリアの役目は世界を守ること","id":"<b>Tugas</b> Fitoria adalah <b>melindungi</b> dunia. <i>(役目は〜こと)</i>","source":"盾の勇者の成り上がり · EP16 · 19:32"}]},{"id":"n5_b18_03","level":"N5","bab":18,"lokasi":"第18課","titleMain":"〜まえに","titleSub":["寝る まえに","食事の まえに","３年 まえに"],"meaning":"Sebelum… / … yang lalu","formula":"Ｖ<b>辞書形</b> ＋ <b>まえに</b>（寝る<b>まえに</b>）<br>Ｎ ＋ <b>の</b> ＋ <b>まえに</b>（食事<b>のまえに</b>）<br>[durasi] ＋ <b>まえに</b> = … yang lalu（３年<b>まえに</b>）","nuance":"<ol><li>Kata kerja sebelum まえに <b>selalu bentuk kamus</b>, walau kalimatnya lampau.</li><li>Kata benda pakai <b>の</b>; durasi tanpa の.</li><li>Kala ditentukan kata kerja di akhir.</li></ol>⚠️ ×寝<b>た</b>まえに → ○寝<b>る</b>まえに. Kebalikan urutan dari 〜てから.","examples":[{"jp":"<ruby>寝<rt>ね</rt></ruby>るまえに、 <ruby>本<rt>ほん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>みます。","speech":"寝るまえに、本を読みます。","id":"<b>Sebelum tidur</b>, aku baca buku. <i>(Ｖるまえに)</i>"},{"jp":"<ruby>食事<rt>しょくじ</rt></ruby>のまえに、 <ruby>手<rt>て</rt></ruby>を<ruby>洗<rt>あら</rt></ruby>います。","speech":"食事のまえに、手を洗います。","id":"<b>Sebelum makan</b>, aku cuci tangan. <i>(Ｎのまえに)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>へ<ruby>来<rt>く</rt></ruby>るまえに、 <ruby>日本語<rt>にほんご</rt></ruby>を<ruby>勉強<rt>べんきょう</rt></ruby>しました。","speech":"日本へ来るまえに、日本語を勉強しました。","id":"<b>Sebelum datang</b> ke Jepang, aku belajar bahasa Jepang. <i>(tetap 辞書形)</i>"},{"jp":"<ruby>田中<rt>たなか</rt></ruby>さんは<ruby>１時間<rt>いちじかん</rt></ruby>まえに <ruby>出<rt>で</rt></ruby>かけました。","speech":"田中さんは１時間まえに出かけました。","id":"Pak Tanaka pergi <b>satu jam yang lalu</b>. <i>(durasi ＋ まえに)</i>"}],"dialogs":[{"jp":"おい <b><ruby>寝<rt>ね</rt></ruby>る<ruby>前<rt>まえ</rt></ruby>に</b> <ruby>歯<rt>は</rt></ruby><ruby>磨<rt>みが</rt></ruby>いたか?","speech":"おい寝る前に歯磨いたか?","id":"Hei, <b>sebelum tidur</b> udah sikat gigi belum? <i>(辞書形 ＋ lampau di akhir)</i>","source":"ヒナまつり · EP01 · 08:16"},{"jp":"たき<ruby>火<rt>び</rt></ruby>は<b><ruby>寝<rt>ね</rt></ruby>る<ruby>前<rt>まえ</rt></ruby>に</b> <ruby>必<rt>かなら</rt></ruby>ず<ruby>水<rt>みず</rt></ruby>をかけて<ruby>完全<rt>かんぜん</rt></ruby>に<ruby>消<rt>け</rt></ruby>すこと","speech":"たき火は寝る前に必ず水をかけて完全に消すこと","id":"Api unggun wajib disiram air sampai padam total <b>sebelum tidur</b>. <i>(aturan)</i>","source":"ゆるキャン△ · EP05 · 13:10"},{"jp":"<b><ruby>帰<rt>かえ</rt></ruby>る<ruby>前<rt>まえ</rt></ruby>に</b> ライブする<ruby>所<rt>ところ</rt></ruby> みんなで<ruby>見<rt>み</rt></ruby>ておきたくて","speech":"帰る前にライブする所みんなで見ておきたくて","id":"<b>Sebelum pulang</b>, aku pengin kita semua lihat tempat live-nya dulu. <i>(sebelum)</i>","source":"ぼっち・ざ・ろっく！ · EP11 · 14:12"},{"jp":"さて<ruby>花火<rt>はなび</rt></ruby>も<ruby>終<rt>お</rt></ruby>わりだね　 <ruby>私<rt>わたし</rt></ruby>は<b><ruby>混<rt>こ</rt></ruby>む<ruby>前<rt>まえ</rt></ruby>に</b> <ruby>帰<rt>かえ</rt></ruby>るけど","speech":"さて花火も終わりだね私は混む前に帰るけど","id":"Nah, kembang apinya udah selesai. Aku pulang <b>sebelum ramai</b> ya. <i>(sebelum)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP09 · 15:24"},{"jp":"<b><ruby>食事<rt>しょくじ</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>に</b> <ruby>話<rt>はな</rt></ruby>さなきゃいけないことがある","speech":"食事の前に話さなきゃいけないことがある","id":"Ada yang harus kubicarakan <b>sebelum makan</b>. <i>(Ｎのまえに)</i>","source":"紫雲寺家の子供たち · EP01 · 12:37"}]},{"id":"n5_b19_01","level":"N5","bab":19,"lokasi":"第19課","titleMain":"〜たことがある","titleSub":["行った ことが あります","〜たこと ない"],"meaning":"Pernah… / belum pernah… — pengalaman di masa lalu","formula":"Ｖた形 ＋ <b>ことが あります</b>（行った<b>ことがあります</b>）<br>Negatif: <b>〜たことが ありません</b> · kasual: 〜たこと<b>ある</b> ／ 〜たこと<b>ない</b><br>た形 = て形 dengan て→<b>た</b>, で→<b>だ</b>","nuance":"<ol><li>Pengalaman yang <b>istimewa / tidak rutin</b>.</li><li><b>一度も〜ない</b> = belum pernah sekali pun; <b>何度も</b> = berkali-kali.</li><li>Kasual: が sering hilang (見たことある).</li></ol>⚠️ Bukan untuk hal rutin/baru saja: ×今朝パンを食べたことがある. Beda dengan <b>Ｖることがある</b> (kadang-kadang).","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>北海道<rt>ほっかいどう</rt></ruby>へ<ruby>行<rt>い</rt></ruby>ったことがあります。","speech":"私は北海道へ行ったことがあります。","id":"Aku <b>pernah</b> ke Hokkaido. <i>(pengalaman)</i>"},{"jp":"<ruby>馬<rt>うま</rt></ruby>に<ruby>乗<rt>の</rt></ruby>ったことがありますか。……いいえ、 <ruby>一度<rt>いちど</rt></ruby>もありません。","speech":"馬に乗ったことがありますか。……いいえ、一度もありません。","id":"<b>Pernah naik</b> kuda? … Nggak, <b>belum pernah sekali pun</b>. <i>(一度も)</i>"},{"jp":"すしを<ruby>食<rt>た</rt></ruby>べたことがありますか。……ええ、 <ruby>何度<rt>なんど</rt></ruby>もあります。","speech":"すしを食べたことがありますか。……ええ、何度もあります。","id":"<b>Pernah makan</b> sushi? … Iya, <b>sering</b>. <i>(何度も)</i>"},{"jp":"<ruby>富士山<rt>ふじさん</rt></ruby>に<ruby>登<rt>のぼ</rt></ruby>ったことがありません。","speech":"富士山に登ったことがありません。","id":"Aku <b>belum pernah mendaki</b> Gunung Fuji. <i>(negatif)</i>"}],"dialogs":[{"jp":"これ <b><ruby>見<rt>み</rt></ruby>たことある</b>","speech":"これ見たことある","id":"Aku <b>pernah lihat</b> ini. <i>(kasual · が hilang)</i>","source":"ガールズバンドクライ · EP06 · 12:52"},{"jp":"で...でもターミネーターぐらいは<b><ruby>見<rt>み</rt></ruby>たことある</b>わよね","speech":"で...でもターミネーターぐらいは見たことあるわよね","id":"T-tapi kalau Terminator sih <b>pernah nonton</b> kan? <i>(pernah)</i>","source":"トニカクカワイイ · EP05 · 00:47"},{"jp":"<ruby>葉山<rt>はやま</rt></ruby> お<ruby>前<rt>まえ</rt></ruby>は お<ruby>前<rt>まえ</rt></ruby>がいないときの<ruby>3人<rt>さんにん</rt></ruby>を<b><ruby>見<rt>み</rt></ruby>たことがあるか</b>?","speech":"葉山お前はお前がいないときの3人を見たことがあるか?","id":"Hayama, kamu <b>pernah lihat</b> mereka bertiga waktu kamu nggak ada? <i>(tanya)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP04 · 19:18"},{"jp":"<ruby>私<rt>わたし</rt></ruby> きりたんぽ <b><ruby>食<rt>た</rt></ruby>べたことない</b>んだよね","speech":"私きりたんぽ食べたことないんだよね","id":"Aku <b>belum pernah makan</b> kiritanpo, lho. <i>(negatif kasual)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 13:22"},{"jp":"ああいうの <b>したことない</b>ですし...","speech":"ああいうのしたことないですし...","id":"Soalnya aku <b>belum pernah</b> main yang begituan… <i>(negatif)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP03 · 20:14"}]},{"id":"n5_b19_02","level":"N5","bab":19,"lokasi":"第19課","titleMain":"〜たり〜たりする","titleSub":["テニスを したり、映画を 見たり します"],"meaning":"…lah, …lah, dan lain-lain — menyebut beberapa contoh kegiatan tanpa urutan","formula":"Ｖ₁た形 ＋ <b>り</b>、Ｖ₂た形 ＋ <b>り</b> ＋ <b>します</b><br>Kala = します／しました di akhir<br>Bolak-balik: 行っ<b>たり</b> 来<b>たり</b>（mondar-mandir）","nuance":"<ol><li>Contoh <b>representatif</b> dari banyak kegiatan.</li><li><b>Tidak ada urutan waktu</b> (beda dengan Ｖて、Ｖて).</li><li>Juga untuk hal yang <b>berganti-ganti</b>: 笑ったり泣いたり.</li></ol>⚠️ Tutup dengan <b>〜たりします</b>. ×テニスをしたり、映画を見ました.","examples":[{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>は テニスをしたり、 <ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>たりしました。","speech":"日曜日はテニスをしたり、映画を見たりしました。","id":"Hari Minggu aku main tenis, <b>nonton film, dan lain-lain</b>. <i>(lampau)</i>"},{"jp":"<ruby>休<rt>やす</rt></ruby>みの<ruby>日<rt>ひ</rt></ruby>は<ruby>掃除<rt>そうじ</rt></ruby>したり、<ruby>洗濯<rt>せんたく</rt></ruby>したりします。","speech":"休みの日は掃除したり、洗濯したりします。","id":"Hari libur aku <b>bersih-bersih, nyuci, dan sebagainya</b>. <i>(kebiasaan)</i>"},{"jp":"<ruby>夏休<rt>なつやす</rt></ruby>みは<ruby>国<rt>くに</rt></ruby>へ<ruby>帰<rt>かえ</rt></ruby>ったり、<ruby>旅行<rt>りょこう</rt></ruby>したりしたいです。","speech":"夏休みは国へ帰ったり、旅行したりしたいです。","id":"Liburan musim panas aku pengin <b>pulang kampung, jalan-jalan, dan lain-lain</b>. <i>(〜たりしたい)</i>"}],"dialogs":[{"jp":"みんなでテント<b><ruby>張<rt>は</rt></ruby>ったり</b>　 <ruby>料理<rt>りょうり</rt></ruby><b><ruby>作<rt>つく</rt></ruby>ったり</b>　 <ruby>焚<rt>た</rt></ruby>き<ruby>火<rt>び</rt></ruby>して<ruby>夜更<rt>よふ</rt></ruby>かし<b>したり</b>","speech":"みんなでテント張ったり料理作ったり焚き火して夜更かししたり","id":"Bareng-bareng <b>pasang</b> tenda, <b>masak</b>, begadang di depan api unggun, <b>dan lain-lain</b>. <i>(contoh kegiatan)</i>","source":"ゆるキャン△ · EP02 · 03:00"},{"jp":"<b><ruby>笑<rt>わら</rt></ruby>ったり<ruby>泣<rt>な</rt></ruby>いたりして</b>くれる<ruby>仲間<rt>なかま</rt></ruby>と<ruby>出会<rt>であ</rt></ruby>えた この<ruby>街<rt>まち</rt></ruby>が","speech":"笑ったり泣いたりしてくれる仲間と出会えたこの街が","id":"Kota tempat aku ketemu teman-teman yang mau <b>tertawa dan menangis</b> bersamaku. <i>(berganti-ganti)</i>","source":"ガールズバンドクライ · EP13 · 16:17"},{"jp":"<ruby>多分<rt>たぶん</rt></ruby><ruby>祭<rt>まつ</rt></ruby>りの<ruby>儀式<rt>ぎしき</rt></ruby>を<b>したり</b>　<b><ruby>踊<rt>おど</rt></ruby>ったり</b> <ruby>会議<rt>かいぎ</rt></ruby>を<b>したり</b>... といった<ruby>所<rt>ところ</rt></ruby>だろうな","speech":"多分祭りの儀式をしたり踊ったり会議をしたり... といった所だろうな","id":"Mungkin tempat buat <b>upacara</b> festival, <b>menari</b>, <b>rapat</b>, dan semacamnya. <i>(contoh kegiatan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 12:00"},{"jp":"けどそれ<ruby>以上<rt>いじょう</rt></ruby>に <b><ruby>楽<rt>たの</rt></ruby>しかったり<ruby>嬉<rt>うれ</rt></ruby>しかったりして</b>","speech":"けどそれ以上に楽しかったり嬉しかったりして","id":"Tapi lebih dari itu, <b>kadang seru, kadang bikin senang</b>. <i>(KS ＋ たり)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 15:41"}]},{"id":"n5_b19_03","level":"N5","bab":19,"lokasi":"第19課","titleMain":"〜くなる／〜になる","titleSub":["暑く なります","元気に なります"],"meaning":"Menjadi… — perubahan keadaan","formula":"KS-i: <s>い</s> → <b>く ＋ なる</b>（暑<b>く</b>なる） · いい → <b>よく</b>なる<br>KS-na / KB: ＋ <b>に ＋ なる</b>（元気<b>に</b>なる ／ 25歳<b>に</b>なる）<br>Sering: <b>だんだん</b> 〜なる","nuance":"<ol><li>KS-i → <b>く</b>なる; KS-na & KB → <b>に</b>なる.</li><li><b>だんだん</b> = lambat laun; <b>〜てきた</b> = mulai jadi (N4).</li><li>Ingin menjadi: <b>〜になりたい</b> (医者になりたい).</li></ol>⚠️ ×きれいくなる → ○きれい<b>に</b>なる. Kata kerja → <b>〜ようになる</b> (N4).","examples":[{"jp":"これから だんだん<ruby>暑<rt>あつ</rt></ruby>くなります。","speech":"これからだんだん暑くなります。","id":"Mulai sekarang lambat laun <b>jadi panas</b>. <i>(KS-i)</i>"},{"jp":"テレサちゃんは<ruby>背<rt>せ</rt></ruby>が<ruby>高<rt>たか</rt></ruby>くなりました。","speech":"テレサちゃんは背が高くなりました。","id":"Teresa-chan <b>jadi lebih tinggi</b>. <i>(KS-i)</i>"},{"jp":"<ruby>２５歳<rt>にじゅうごさい</rt></ruby>になりました。","speech":"２５歳になりました。","id":"Aku <b>sudah berumur</b> 25 tahun. <i>(KB)</i>"},{"jp":"<ruby>体<rt>からだ</rt></ruby>が<ruby>元気<rt>げんき</rt></ruby>になりました。","speech":"体が元気になりました。","id":"Badanku <b>sudah sehat</b> lagi. <i>(KS-na)</i>"},{"jp":"<ruby>医者<rt>いしゃ</rt></ruby>になりたいです。","speech":"医者になりたいです。","id":"Aku pengin <b>jadi</b> dokter. <i>(になりたい)</i>"}],"dialogs":[{"jp":"フフッ...　 <ruby>周<rt>あまね</rt></ruby>くんは<b><ruby>強<rt>つよ</rt></ruby>くなりました</b>し<b><ruby>大<rt>おお</rt></ruby>きくなりました</b>よ","speech":"フフッ...　周くんは強くなりましたし大きくなりましたよ","id":"Hehe… Amane-kun sudah <b>jadi kuat</b> dan <b>jadi besar</b>, lho. <i>(KS-i → くなる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP03 · 17:49"},{"jp":"<b><ruby>寒<rt>さむ</rt></ruby>くなったら</b> <ruby>寝袋<rt>ねぶくろ</rt></ruby><ruby>被<rt>かぶ</rt></ruby>るか","speech":"寒くなったら寝袋被るか","id":"Kalau <b>jadi dingin</b>, tinggal pakai sleeping bag. <i>(くなる ＋ たら)</i>","source":"ゆるキャン△ · EP02 · 14:51"},{"jp":"なのに ダイヤモンドダスト<b><ruby>好<rt>す</rt></ruby>きになった</b>んだ","speech":"なのにダイヤモンドダスト好きになったんだ","id":"Tapi kamu tetap <b>jadi suka</b> Diamond Dust, kan. <i>(KS-na → になる)</i>","source":"ガールズバンドクライ · EP01 · 18:56"},{"jp":"<ruby>僕<rt>ぼく</rt></ruby>は<b><ruby>18歳<rt>じゅうはっさい</rt></ruby>になった</b>","speech":"僕は18歳になった","id":"Aku <b>sudah berumur</b> 18 tahun. <i>(KB → になる)</i>","source":"トニカクカワイイ · EP01 · 13:28"},{"jp":"あかり あんたも<b><ruby>大人<rt>おとな</rt></ruby>になった</b>んやな","speech":"あかりあんたも大人になったんやな","id":"Akari, kamu juga <b>sudah jadi dewasa</b> ya. <i>(KB → になる · logat Kansai)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 07:07"}]},{"id":"n5_b20_01","level":"N5","bab":20,"lokasi":"第20課","titleMain":"普通体（動詞）","titleSub":["する？——うん、する","行かなかった"],"meaning":"Bentuk biasa kata kerja — gaya santai ke teman/keluarga","formula":"ます → <b>辞書形</b>（行く） · ません → <b>ない</b>（行かない）<br>ました → <b>た</b>（行った） · ませんでした → <b>なかった</b>（行かなかった）<br>Tanya: か hilang, <b>intonasi naik</b>（行く?） · はい → <b>うん</b> · いいえ → <b>ううん</b>","nuance":"<ol><li>Untuk teman akrab, keluarga, bawahan; juga tulisan (diari, berita).</li><li>Partikel は・を・へ・が sering <b>dihilangkan</b>.</li><li>Dasar banyak pola N4 (〜と思う, 〜とき).</li></ol>⚠️ ある → <b>ない</b> (×あらない). Jangan dipakai ke atasan / orang baru.","examples":[{"jp":"サッカー、する？……うん、する。","speech":"サッカー、する？……うん、する。","id":"Kamu <b>main</b> bola? … Iya, <b>main</b>. <i>(辞書形)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>、 <ruby>学校<rt>がっこう</rt></ruby>へ<ruby>来<rt>く</rt></ruby>る？……ううん、<ruby>来<rt>こ</rt></ruby>ない。","speech":"明日、学校へ来る？……ううん、来ない。","id":"Besok <b>datang</b> ke sekolah? … Nggak, <b>nggak datang</b>. <i>(ない)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby>、 <ruby>何<rt>なに</rt></ruby>した？…… <ruby>映画<rt>えいが</rt></ruby>、<ruby>見<rt>み</rt></ruby>た。","speech":"昨日、何した？…… 映画、見た。","id":"Kemarin <b>ngapain</b>? … <b>Nonton</b> film. <i>(た · partikel hilang)</i>"},{"jp":"<ruby>宿題<rt>しゅくだい</rt></ruby>、もう<ruby>出<rt>だ</rt></ruby>した？……ううん、まだ<ruby>出<rt>だ</rt></ruby>してない。","speech":"宿題、もう出した？……ううん、まだ出してない。","id":"PR udah <b>dikumpulin</b>? … Belum, <b>belum kukumpulin</b>. <i>(〜てない)</i>"}],"dialogs":[{"jp":"うん <b><ruby>行<rt>い</rt></ruby>く<ruby>行<rt>い</rt></ruby>く</b>!","speech":"うん行く行く!","id":"Iya, <b>ikut, ikut</b>! <i>(辞書形 · うん)</i>","source":"ゆるキャン△ · EP09 · 00:40"},{"jp":"<ruby>真昼<rt>まひる</rt></ruby>は かき<ruby>氷<rt>ごおり</rt></ruby><ruby>何<rt>なに</rt></ruby> <b><ruby>食<rt>た</rt></ruby>べる</b>?","speech":"真昼はかき氷何食べる?","id":"Mahiru, es serutnya <b>mau makan</b> rasa apa? <i>(tanya · か hilang)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP05 · 14:48"},{"jp":"うん もう<ruby>少<rt>すこ</rt></ruby>ししたら<b><ruby>帰<rt>かえ</rt></ruby>る</b>","speech":"うんもう少ししたら帰る","id":"Iya, sebentar lagi aku <b>pulang</b>. <i>(辞書形)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 20:54"},{"jp":"あれ? <ruby>今<rt>いま</rt></ruby> お<ruby>父<rt>とう</rt></ruby>さん <b><ruby>来<rt>こ</rt></ruby>なかった</b>?","speech":"あれ? 今お父さん来なかった?","id":"Lho? Barusan Ayah <b>datang</b> nggak sih? <i>(なかった · tanya)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 14:36"},{"jp":"<ruby>頭<rt>あたま</rt></ruby><ruby>良<rt>よ</rt></ruby>かったんだ <b><ruby>知<rt>し</rt></ruby>らなかった</b>","speech":"頭良かったんだ知らなかった","id":"Ternyata kamu pinter ya. Aku <b>nggak tahu</b>. <i>(なかった)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP03 · 15:44"}]},{"id":"n5_b20_02","level":"N5","bab":20,"lokasi":"第20課","titleMain":"普通体（形容詞・名詞）","titleSub":["暇だよ","どうだった？"],"meaning":"Bentuk biasa kata sifat & kata benda — gaya santai","formula":"KS-i: buang です（忙しい · 忙し<b>くない</b> · 忙し<b>かった</b>）<br>KS-na / KB: <b>だ</b> · <b>じゃない</b> · <b>だった</b> · <b>じゃなかった</b><br>Tanya: だ hilang（<b>暇?</b> ×暇だ?）","nuance":"<ol><li>KS-i cukup buang です; KS-na & KB pakai だ.</li><li>だ di akhir terdengar tegas → sering <b>だよ / だね</b> atau dibuang.</li><li><b>どうだった?</b> = gimana tadi/kemarin?</li></ol>⚠️ ×暇だ? → ○暇? 〜<b>じゃない↗</b> bisa = \"bukankah…?\" (konfirmasi).","examples":[{"jp":"その<ruby>辞書<rt>じしょ</rt></ruby>、いい？……ううん、あまりよくない。","speech":"その辞書、いい？……ううん、あまりよくない。","id":"Kamus itu <b>bagus</b>? … Nggak, <b>kurang bagus</b>. <i>(KS-i)</i>"},{"jp":"<ruby>今<rt>いま</rt></ruby>、<ruby>忙<rt>いそが</rt></ruby>しい？……ううん、<ruby>暇<rt>ひま</rt></ruby>だよ。","speech":"今、忙しい？……ううん、暇だよ。","id":"Lagi <b>sibuk</b>? … Nggak, <b>lagi senggang</b> kok. <i>(KS-na ＋ だよ)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby>のパーティー、どうだった？……すごく<ruby>楽<rt>たの</rt></ruby>しかった。","speech":"昨日のパーティー、どうだった？……すごく楽しかった。","id":"Pesta kemarin <b>gimana</b>? … <b>Seru banget</b>. <i>(lampau)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>雨<rt>あめ</rt></ruby>じゃないよ。","speech":"明日は雨じゃないよ。","id":"Besok <b>nggak hujan</b> kok. <i>(KB ＋ じゃない)</i>"}],"dialogs":[{"jp":"あおいちゃん<ruby>高山<rt>たかやま</rt></ruby> <b>どうだった</b>?","speech":"あおいちゃん高山どうだった?","id":"Aoi-chan, Takayama <b>gimana</b>? <i>(だった · partikel hilang)</i>","source":"ゆるキャン△ SEASON２ · EP04 · 00:04"},{"jp":"ゆきのん <b><ruby>大丈夫<rt>だいじょうぶ</rt></ruby>だよ</b>","speech":"ゆきのん大丈夫だよ","id":"Yukinon, <b>nggak apa-apa kok</b>. <i>(KS-na ＋ だよ)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP08 · 20:42"},{"jp":"そんなに<b><ruby>簡単<rt>かんたん</rt></ruby>じゃない</b>わよ","speech":"そんなに簡単じゃないわよ","id":"<b>Nggak segampang</b> itu, tahu. <i>(KS-na ＋ じゃない)</i>","source":"ガールズバンドクライ · EP12 · 11:04"},{"jp":"すき<ruby>焼<rt>や</rt></ruby>き <b>おいしかった</b>ね","speech":"すき焼きおいしかったね","id":"Sukiyakinya <b>enak</b> ya tadi. <i>(KS-i lampau)</i>","source":"ゆるキャン△ · EP12 · 09:25"}]},{"id":"n5_b20_03","level":"N5","bab":20,"lokasi":"第20課","titleMain":"〜ない？","titleSub":["一緒に 行かない？","〜ませんか"],"meaning":"Mau … nggak? / yuk …? — ajakan santai (versi kasual 〜ませんか)","formula":"Ｖない形 ＋ <b>?</b> (intonasi naik)（一緒に行か<b>ない?</b>）<br>Sopan: 〜<b>ませんか</b> · ajakan tegas: 〜<b>よう</b>（行こう!）","nuance":"<ol><li>Intonasi naik = <b>ajakan</b>; turun = negatif biasa.</li><li>Setara 〜ませんか dalam gaya santai.</li><li>Tolak halus: ごめん、ちょっと……</li></ol>⚠️ 行かない↗ = yuk pergi?; 行かない↘ = (aku) nggak pergi.","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby> みんなで<ruby>京都<rt>きょうと</rt></ruby>へ<ruby>行<rt>い</rt></ruby>かない？……いいね。","speech":"明日みんなで京都へ行かない？……いいね。","id":"Besok ke Kyoto bareng-bareng <b>yuk</b>? … Boleh tuh. <i>(ajakan)</i>"},{"jp":"お<ruby>茶<rt>ちゃ</rt></ruby>、<ruby>飲<rt>の</rt></ruby>まない？","speech":"お茶、飲まない？","id":"<b>Minum teh yuk</b>? <i>(ajakan)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby>、 <ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>ない？……ごめん、ちょっと<ruby>用事<rt>ようじ</rt></ruby>があって……。","speech":"週末、一緒に映画を見ない？……ごめん、ちょっと用事があって……。","id":"Akhir pekan <b>nonton film bareng yuk</b>? … Maaf, lagi ada urusan… <i>(ajakan · ditolak halus)</i>"}],"dialogs":[{"jp":"<ruby>花火<rt>はなび</rt></ruby><ruby>大会<rt>たいかい</rt></ruby><ruby>一緒<rt>いっしょ</rt></ruby>に<b><ruby>行<rt>い</rt></ruby>かない</b>?","speech":"花火大会一緒に行かない?","id":"<b>Mau pergi</b> ke festival kembang api bareng <b>nggak</b>? <i>(ajakan)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP09 · 03:17"},{"jp":"ごっ ごごご... <ruby>後藤<rt>ごとう</rt></ruby>さん <b><ruby>遊<rt>あそ</rt></ruby>び<ruby>行<rt>い</rt></ruby>かない</b>?","speech":"ごっごごご... 後藤さん遊び行かない?","id":"G-G-Gotoh-san, <b>main yuk</b>? <i>(ajakan · partikel hilang)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 06:50"},{"jp":"やっぱり<ruby>二人<rt>ふたり</rt></ruby>で<ruby>記念<rt>きねん</rt></ruby><ruby>撮影<rt>さつえい</rt></ruby><b>しない</b>?","speech":"やっぱり二人で記念撮影しない?","id":"Gimana kalau kita foto kenang-kenangan berdua, <b>yuk</b>? <i>(〜しない?)</i>","source":"トニカクカワイイ · EP08 · 17:48"},{"jp":"あっ そろそろ<ruby>具材<rt>ぐざい</rt></ruby> <b><ruby>追加<rt>ついか</rt></ruby>しない</b>?","speech":"あっそろそろ具材追加しない?","id":"Eh, <b>tambahin</b> bahan lagi <b>yuk</b>? <i>(usulan)</i>","source":"ゆるキャン△ · EP11 · 18:27"},{"jp":"ねえ<ruby>恵那<rt>えな</rt></ruby>ちゃん<ruby>私<rt>わたし</rt></ruby>たち<ruby>3人<rt>さんにん</rt></ruby>で<ruby>臨時<rt>りんじ</rt></ruby><ruby>野<rt>の</rt></ruby>クルを<b>やらない</b>?","speech":"ねえ恵那ちゃん私たち3人で臨時野クルをやらない?","id":"Hei Ena-chan, kita bertiga <b>bikin</b> Noukuru dadakan <b>yuk</b>? <i>(ajakan)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 03:15"}]},{"id":"n5_b21_01","level":"N5","bab":21,"lokasi":"第21課","titleMain":"〜と思います","titleSub":["〜と思う"],"meaning":"Menurutku… / aku pikir… / kayaknya… — pendapat atau tebakan pembicara","formula":"Ｖ / KS-i (普通形) + <b>と思います</b>（降ると思います ／ 高いと思います）<br>KB / KS-na + <b>だ</b> + <b>と思います</b>（休みだと思います）<br>Tanya pendapat: 〜について<b>どう思いますか</b>","nuance":"<ol><li><b>Pendapat</b>: opini supaya tidak terdengar memaksa (物価が高いと思います).</li><li><b>Tebakan</b>: hal yang belum pasti, sering dengan たぶん (雨が降ると思います).</li><li><b>Negatif</b>: negasikan bagian sebelum と → <b>〜ないと思います</b>.</li></ol>⚠️ KB/KS-na wajib <b>だ</b> (×便利と思います). Pikiran orang ketiga → <b>〜と思っています</b>.","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>ると<ruby>思<rt>おも</rt></ruby>います。","speech":"明日は雨が降ると思います。","id":"<b>Kurasa</b> besok bakal hujan. <i>(tebakan)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>は<ruby>物価<rt>ぶっか</rt></ruby>が<ruby>高<rt>たか</rt></ruby>いと<ruby>思<rt>おも</rt></ruby>います。","speech":"日本は物価が高いと思います。","id":"<b>Menurutku</b> harga-harga di Jepang mahal. <i>(pendapat)</i>"},{"jp":"ミラーさんはもう<ruby>帰<rt>かえ</rt></ruby>ったと<ruby>思<rt>おも</rt></ruby>います。","speech":"ミラーさんはもう帰ったと思います。","id":"<b>Kayaknya</b> Miller-san sudah pulang. <i>(tebakan · lampau)</i>"},{"jp":"この<ruby>漢字<rt>かんじ</rt></ruby>はあまり<ruby>使<rt>つか</rt></ruby>わないと<ruby>思<rt>おも</rt></ruby>います。","speech":"この漢字はあまり使わないと思います。","id":"<b>Kurasa</b> kanji ini jarang dipakai. <i>(negatif sebelum と)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>の<ruby>生活<rt>せいかつ</rt></ruby>についてどう<ruby>思<rt>おも</rt></ruby>いますか。","speech":"日本の生活についてどう思いますか。","id":"<b>Bagaimana pendapatmu</b> soal hidup di Jepang? <i>(tanya pendapat)</i>"}],"dialogs":[{"jp":"リンなら<ruby>大丈夫<rt>だいじょうぶ</rt></ruby><b>だと<ruby>思<rt>おも</rt></ruby>います</b>よ","speech":"リンなら大丈夫だと思いますよ","id":"Kalau Rin sih, <b>kurasa</b> dia baik-baik aja kok. <i>(KS-na + だと思います)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 07:05"},{"jp":"それは<ruby>難<rt>むずか</rt></ruby>しい<b>と<ruby>思<rt>おも</rt></ruby>います</b>","speech":"それは難しいと思います","id":"<b>Menurut saya</b> itu sulit. <i>(KS-i · pendapat)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP12 · 04:13"},{"jp":"あっ いい<b>と<ruby>思<rt>おも</rt></ruby>います</b>","speech":"あっいいと思います","id":"Ah, <b>menurutku</b> bagus kok. <i>(pendapat)</i>","source":"ぼっち・ざ・ろっく！ · EP11 · 15:41"},{"jp":"たぶん うまく<ruby>焼<rt>や</rt></ruby>けた<b>と<ruby>思<rt>おも</rt></ruby>う</b>よ","speech":"たぶんうまく焼けたと思うよ","id":"<b>Kayaknya</b> sih kepanggang dengan baik. <i>(たぶん + tebakan · lampau)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 15:14"},{"jp":"どうなる<b>と<ruby>思<rt>おも</rt></ruby>います</b>","speech":"どうなると思います","id":"<b>Menurutmu</b> bakal jadi gimana? <i>(tanya pendapat)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP00 · 05:25"}]},{"id":"n5_b21_02","level":"N5","bab":21,"lokasi":"第21課","titleMain":"〜と言いました","titleSub":["「…」と言う","〜って言った"],"meaning":"(Seseorang) bilang… / berkata… — mengutip ucapan","formula":"「kutipan persis」 + <b>と言いました</b>（直接引用）<br>普通形 + <b>と言いました</b>（間接引用 · KB/KS-na + だ）<br>Lawan bicara: 人<b>に</b>〜と言う · kasual: 〜<b>って</b>言った","nuance":"<ol><li><b>Kutipan langsung</b>: ucapan persis dalam 「 」, bentuk sopan dipertahankan.</li><li><b>Kutipan tidak langsung</b>: isi diubah ke bentuk biasa, tanpa 「 」.</li><li><b>Ungkapan rutin</b>: 寝る前に「おやすみなさい」と言います.</li></ol>⚠️ Dalam percakapan santai と → <b>って</b> (やるって言った). <b>〜と言います</b> juga = \"disebut\" (これは「すし」と言います).","examples":[{"jp":"<ruby>寝<rt>ね</rt></ruby>る<ruby>前<rt>まえ</rt></ruby>に、「おやすみなさい」と<ruby>言<rt>い</rt></ruby>います。","speech":"寝る前に、「おやすみなさい」と言います。","id":"Sebelum tidur, kita <b>bilang</b> \"selamat tidur\". <i>(ungkapan rutin)</i>"},{"jp":"ミラーさんは「 <ruby>来週<rt>らいしゅう</rt></ruby><ruby>東京<rt>とうきょう</rt></ruby>へ<ruby>出張<rt>しゅっちょう</rt></ruby>します」と<ruby>言<rt>い</rt></ruby>いました。","speech":"ミラーさんは「来週東京へ出張します」と言いました。","id":"Miller-san <b>bilang</b>, \"Minggu depan saya dinas ke Tokyo.\" <i>(kutipan langsung)</i>"},{"jp":"ミラーさんは<ruby>来週<rt>らいしゅう</rt></ruby><ruby>東京<rt>とうきょう</rt></ruby>へ<ruby>出張<rt>しゅっちょう</rt></ruby>すると<ruby>言<rt>い</rt></ruby>いました。","speech":"ミラーさんは来週東京へ出張すると言いました。","id":"Miller-san <b>bilang</b> minggu depan dia dinas ke Tokyo. <i>(kutipan tidak langsung)</i>"},{"jp":"ご<ruby>飯<rt>はん</rt></ruby>を<ruby>食<rt>た</rt></ruby>べる<ruby>前<rt>まえ</rt></ruby>に、「いただきます」と<ruby>言<rt>い</rt></ruby>います。","speech":"ご飯を食べる前に、「いただきます」と言います。","id":"Sebelum makan, kita <b>mengucapkan</b> \"itadakimasu\". <i>(ungkapan rutin)</i>"},{"jp":"<ruby>田中<rt>たなか</rt></ruby>さんは<ruby>明日<rt>あした</rt></ruby><ruby>来<rt>こ</rt></ruby>ないと<ruby>言<rt>い</rt></ruby>いました。","speech":"田中さんは明日来ないと言いました。","id":"Tanaka-san <b>bilang</b> besok dia nggak datang. <i>(kutipan tidak langsung)</i>"}],"dialogs":[{"jp":"ちゅんちゅん<ruby>丸<rt>まる</rt></ruby><b>と<ruby>言<rt>い</rt></ruby>いました</b>","speech":"ちゅんちゅん丸と言いました","id":"Aku <b>bilang</b> Chunchunmaru. <i>(kutipan · sopan)</i>","source":"この素晴らしい世界に祝福を！2 · EP06 · 10:48"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんが<ruby>甘<rt>あま</rt></ruby>えていい<b>と<ruby>言<rt>い</rt></ruby>った</b>のです","speech":"周くんが甘えていいと言ったのです","id":"Amane-kun sendiri yang <b>bilang</b> aku boleh manja. <i>(kutipan tidak langsung)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 19:36"},{"jp":"レメリオは どうにかしろ<b>と<ruby>言<rt>い</rt></ruby>った</b>","speech":"レメリオはどうにかしろと言った","id":"Remerio <b>bilang</b> \"urus ini gimana caranya\". <i>(kutipan perintah)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP12 · 12:07"},{"jp":"やる<b>って<ruby>言<rt>い</rt></ruby>った</b>だろ","speech":"やるって言っただろ","id":"Kamu kan udah <b>bilang</b> mau ngelakuin. <i>(kasual って)</i>","source":"ガールズバンドクライ · EP02 · 03:38"},{"jp":"こら! <ruby>誰<rt>だれ</rt></ruby>が<ruby>自由<rt>じゆう</rt></ruby><ruby>行動<rt>こうどう</rt></ruby><b>って<ruby>言<rt>い</rt></ruby>った</b>?","speech":"こら! 誰が自由行動って言った?","id":"Hei! Siapa yang <b>bilang</b> ini waktu bebas? <i>(kasual って)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 10:52"}]},{"id":"n5_b21_03","level":"N5","bab":21,"lokasi":"第21課","titleMain":"〜でしょう？","titleSub":["〜でしょ？"],"meaning":"…kan? / …ya, kan? — minta persetujuan atau konfirmasi (intonasi naik)","formula":"Ｖ / KS-i (普通形) + <b>でしょう？</b>（勝ったでしょう？）<br>KS-na / KB + <b>でしょう？</b>（tanpa だ: 学校でしょう？）<br>Kasual: <b>でしょ？</b> ／ <b>だろ？</b>","nuance":"<ol><li>Pembicara <b>yakin</b> lawan bicara tahu/setuju, lalu minta konfirmasi.</li><li>Intonasi <b>naik ↗</b>; kalau turun ↘ artinya jadi tebakan \"mungkin\" (Bab 32).</li></ol>⚠️ ×学生<b>だ</b>でしょう. Mirip <b>〜ね</b>, tapi でしょう？ lebih menegaskan \"kamu pasti tahu, kan\" — ke atasan lebih aman 〜ですよね.","examples":[{"jp":"<ruby>日本<rt>にほん</rt></ruby>のチームが<ruby>勝<rt>か</rt></ruby>ったでしょう？","speech":"日本のチームが勝ったでしょう？","id":"Tim Jepang menang, <b>kan</b>? <i>(Ｖ-た)</i>"},{"jp":"このケーキ、おいしいでしょう？","speech":"このケーキ、おいしいでしょう？","id":"Kue ini enak, <b>kan</b>? <i>(KS-i)</i>"},{"jp":"<ruby>７月<rt>しちがつ</rt></ruby>に<ruby>京都<rt>きょうと</rt></ruby>でお<ruby>祭<rt>まつ</rt></ruby>りがあるでしょう？","speech":"７月に京都でお祭りがあるでしょう？","id":"Bulan Juli ada festival di Kyoto, <b>kan</b>? <i>(Ｖ)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>休<rt>やす</rt></ruby>みでしょ？ <ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>行<rt>い</rt></ruby>こうよ。","speech":"明日は休みでしょ？一緒に行こうよ。","id":"Besok libur, <b>kan</b>? Pergi bareng yuk. <i>(KB · kasual)</i>"}],"dialogs":[{"jp":"<ruby>分<rt>わ</rt></ruby>かりやすい<b>でしょう?</b>","speech":"分かりやすいでしょう?","id":"Gampang dimengerti, <b>kan</b>? <i>(KS-i · konfirmasi)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP05 · 10:14"},{"jp":"だから<ruby>雪乃<rt>ゆきの</rt></ruby>　 <ruby>安直<rt>あんちょく</rt></ruby><b>でしょう?</b>","speech":"だから雪乃安直でしょう?","id":"Makanya \"Yukino\". Gampangan banget, <b>kan</b>? <i>(KS-na tanpa だ)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP01 · 05:29"},{"jp":"あんた<ruby>明後日<rt>あさって</rt></ruby>から<ruby>学校<rt>がっこう</rt></ruby><b>でしょ?</b>","speech":"あんた明後日から学校でしょ?","id":"Kamu lusa udah mulai sekolah, <b>kan</b>? <i>(KB · kasual でしょ)</i>","source":"ゆるキャン△ · EP01 · 20:35"},{"jp":"ほら<ruby>本当<rt>ほんとう</rt></ruby>に いる<b>でしょ?</b>","speech":"ほら本当にいるでしょ?","id":"Tuh, beneran ada, <b>kan</b>? <i>(menegaskan)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 11:11"},{"jp":"それは<ruby>分<rt>わ</rt></ruby>かる<b>でしょ?</b>","speech":"それは分かるでしょ?","id":"Itu kamu ngerti, <b>kan</b>? <i>(konfirmasi)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP04 · 09:35"}]},{"id":"n5_b22_01","level":"N5","bab":22,"lokasi":"第22課","titleMain":"Ｖ(普通形)＋Ｎ","titleSub":["〜がＶた＋Ｎ","〜ている＋Ｎ"],"meaning":"N yang … — kalimat bentuk biasa ditempel langsung di depan kata benda (tanpa kata \"yang\")","formula":"Ｖ (る / ない / た / なかった / ている) + <b>Ｎ</b>（昨日買った傘）<br>Subjek dalam keterangan pakai <b>が</b>: 私<b>が</b>作った料理<br>KB yang diterangkan bisa jadi subjek / objek / tempat","nuance":"<ol><li>Keterangan <b>selalu di depan</b> KB: ミラーさんが住んでいる<b>家</b> = rumah yang ditinggali Miller-san.</li><li>Tidak ada kata ganti relatif (\"yang / which\") — cukup bentuk biasa.</li><li>Sama logikanya dengan 高い山 / きれいな花 / 日本の車.</li></ol>⚠️ ×私<b>は</b>作った料理 → 私<b>が</b>（/の）作った料理. Bentuk sopan tidak dipakai di keterangan (×買いました傘).","examples":[{"jp":"これはミラーさんが<ruby>住<rt>す</rt></ruby>んでいる<ruby>家<rt>いえ</rt></ruby>です。","speech":"これはミラーさんが住んでいる家です。","id":"Ini rumah <b>yang ditinggali</b> Miller-san. <i>(Ｖている＋Ｎ)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>が<ruby>作<rt>つく</rt></ruby>った<ruby>料理<rt>りょうり</rt></ruby>を<ruby>食<rt>た</rt></ruby>べてください。","speech":"私が作った料理を食べてください。","id":"Silakan makan masakan <b>yang aku buat</b>. <i>(subjek が)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>昨日<rt>きのう</rt></ruby><ruby>買<rt>か</rt></ruby>った<ruby>傘<rt>かさ</rt></ruby>をなくしました。","speech":"私は昨日買った傘をなくしました。","id":"Aku menghilangkan payung <b>yang kubeli kemarin</b>. <i>(Ｖた＋Ｎ)</i>"},{"jp":"<ruby>市役所<rt>しやくしょ</rt></ruby>へ<ruby>行<rt>い</rt></ruby>くバスはどれですか。","speech":"市役所へ行くバスはどれですか。","id":"Bus <b>yang ke balai kota</b> yang mana? <i>(Ｖる＋Ｎ)</i>"},{"jp":"パーティーに<ruby>来<rt>こ</rt></ruby>なかった<ruby>人<rt>ひと</rt></ruby>は<ruby>誰<rt>だれ</rt></ruby>ですか。","speech":"パーティーに来なかった人は誰ですか。","id":"Siapa orang <b>yang nggak datang</b> ke pesta? <i>(Ｖなかった＋Ｎ)</i>"}],"dialogs":[{"jp":"<b><ruby>私<rt>わたし</rt></ruby>が<ruby>作<rt>つく</rt></ruby>った</b> <ruby>日本<rt>にほん</rt></ruby>の<ruby>朝<rt>あさ</rt></ruby>ごはん","speech":"私が作った日本の朝ごはん","id":"Sarapan Jepang <b>yang aku buat</b>. <i>(〜がＶた＋Ｎ)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 15:26"},{"jp":"まッ <b>お<ruby>前<rt>まえ</rt></ruby>が<ruby>作<rt>つく</rt></ruby>った</b>クッキーなんだけどな","speech":"まッお前が作ったクッキーなんだけどな","id":"Yah, padahal itu kue kering <b>yang kamu bikin</b> sih. <i>(〜がＶた＋Ｎ)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP01 · 18:50"},{"jp":"そうそう! <b><ruby>昨日<rt>きのう</rt></ruby><ruby>買<rt>か</rt></ruby>った</b> <ruby>本<rt>ほん</rt></ruby>のおかげで","speech":"そうそう! 昨日買った本のおかげで","id":"Oh iya! Berkat buku <b>yang kubeli kemarin</b>… <i>(Ｖた＋Ｎ)</i>","source":"カードキャプターさくら · EP22 · 09:12"},{"jp":"<b><ruby>麦畑<rt>むぎばたけ</rt></ruby>に<ruby>住<rt>す</rt></ruby>んでる</b> <ruby>狼<rt>おおかみ</rt></ruby>なんか いやしない","speech":"麦畑に住んでる狼なんかいやしない","id":"Mana ada serigala <b>yang tinggal di ladang gandum</b>. <i>(Ｖている＋Ｎ)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP01 · 14:52"},{"jp":"し... しかも<ruby>学校<rt>がっこう</rt></ruby>での<ruby>私<rt>わたし</rt></ruby>を <b><ruby>知<rt>し</rt></ruby>ってる</b> <ruby>人<rt>ひと</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>でライブするのが　こ... <ruby>怖<rt>こわ</rt></ruby>くて","speech":"し... しかも学校での私を知ってる人の前でライブするのがこ... 怖くて","id":"Ma-mana lagi, tampil live di depan orang <b>yang kenal</b> aku di sekolah tuh… se-serem. <i>(Ｖている＋Ｎ)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 10:35"}]},{"id":"n5_b22_02","level":"N5","bab":22,"lokasi":"第22課","titleMain":"Ｖる＋時間／約束","titleSub":["〜する時間がない","用事がある"],"meaning":"Waktu untuk… / janji untuk… / ada urusan — KB abstrak yang diterangkan kata kerja","formula":"Ｖ-る + <b>時間が ありません</b>（食べる時間がない）<br>Ｖ-る + <b>約束が あります</b>（会う約束がある）<br><b>用事が あります</b> · Ｖ-る + <b>時間だ</b>（寝る時間だ）","nuance":"<ol><li><b>時間がない</b>: tidak sempat melakukan sesuatu.</li><li><b>約束がある / 用事がある</b>: alasan sopan untuk menolak ajakan.</li><li><b>Ｖる時間だ</b>: sudah waktunya (寝る時間だ).</li></ol>⚠️ <b>時間</b> = waktu untuk kegiatan tertentu; <b>暇</b> = waktu luang umum. 約束 biasanya pakai 〜と / 〜に (友達と会う約束).","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby><ruby>友達<rt>ともだち</rt></ruby>に<ruby>会<rt>あ</rt></ruby>う<ruby>時間<rt>じかん</rt></ruby>がありません。","speech":"明日友達に会う時間がありません。","id":"Besok aku <b>nggak punya waktu buat</b> ketemu teman. <i>(時間がない)</i>"},{"jp":"<ruby>忙<rt>いそが</rt></ruby>しくて、 <ruby>朝<rt>あさ</rt></ruby>ご<ruby>飯<rt>はん</rt></ruby>を<ruby>食<rt>た</rt></ruby>べる<ruby>時間<rt>じかん</rt></ruby>がありません。","speech":"忙しくて、朝ご飯を食べる時間がありません。","id":"Sibuk banget sampai <b>nggak sempat</b> sarapan. <i>(時間がない)</i>"},{"jp":"すみません、 <ruby>今日<rt>きょう</rt></ruby>は<ruby>友達<rt>ともだち</rt></ruby>と<ruby>映画<rt>えいが</rt></ruby>を<ruby>見<rt>み</rt></ruby>る<ruby>約束<rt>やくそく</rt></ruby>があります。","speech":"すみません、今日は友達と映画を見る約束があります。","id":"Maaf, hari ini aku <b>ada janji</b> nonton film sama teman. <i>(約束 · menolak)</i>"},{"jp":"<ruby>今晩<rt>こんばん</rt></ruby>はちょっと<ruby>用事<rt>ようじ</rt></ruby>があるんです。","speech":"今晩はちょっと用事があるんです。","id":"Malam ini aku <b>ada sedikit urusan</b>. <i>(用事 · menolak)</i>"},{"jp":"もう<ruby>寝<rt>ね</rt></ruby>る<ruby>時間<rt>じかん</rt></ruby>ですよ。","speech":"もう寝る時間ですよ。","id":"Sudah <b>waktunya tidur</b>, lho. <i>(Ｖる時間だ)</i>"}],"dialogs":[{"jp":"もう <b><ruby>寝<rt>ね</rt></ruby>る<ruby>時間<rt>じかん</rt></ruby></b>じゃ","speech":"もう寝る時間じゃ","id":"Sudah <b>waktunya tidur</b>. <i>(Ｖる時間だ)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP25 · 23:12"},{"jp":"ごめんなあ <b><ruby>寝<rt>ね</rt></ruby>る<ruby>時間<rt>じかん</rt></ruby></b>もないねん<ruby>最近<rt>さいきん</rt></ruby>","speech":"ごめんなあ寝る時間もないねん最近","id":"Maaf ya, belakangan ini <b>waktu buat tidur</b> aja nggak ada. <i>(時間がない · logat Kansai)</i>","source":"オッドタクシー · EP06 · 20:56"},{"jp":"<ruby>去年<rt>きょねん</rt></ruby> デビューが<ruby>決<rt>き</rt></ruby>まってから<ruby>高校<rt>こうこう</rt></ruby>の<ruby>友達<rt>ともだち</rt></ruby>とは　<b><ruby>遊<rt>あそ</rt></ruby>ぶ<ruby>時間<rt>じかん</rt></ruby>がなくなって</b>。","speech":"去年デビューが決まってから高校の友達とは遊ぶ時間がなくなって。","id":"Sejak debutku diputuskan tahun lalu, aku jadi <b>nggak punya waktu main</b> sama teman SMA. <i>(時間がない)</i>","source":"青春ブタ野郎はバニーガール先輩の夢を見ない · EP09 · 06:43"},{"jp":"ちょっと<ruby>人<rt>ひと</rt></ruby>と<b><ruby>会<rt>あ</rt></ruby>う<ruby>約束<rt>やくそく</rt></ruby>があって</b>","speech":"ちょっと人と会う約束があって","id":"Aku <b>ada janji ketemu</b> seseorang. <i>(約束がある · alasan)</i>","source":"ソードアート・オンライン · EP07 · 00:28"}]},{"id":"n5_b23_01","level":"N5","bab":23,"lokasi":"第23課","titleMain":"〜とき","titleSub":["Ｎのとき","暇なとき","小さいとき"],"meaning":"Waktu… / ketika… / saat… — waktu atau situasi terjadinya kalimat utama","formula":"KB + <b>の</b> + <b>とき</b>（子供のとき）<br>KS-na + <b>な</b> + <b>とき</b>（暇なとき） · KS-i + <b>とき</b>（小さいとき）<br>Ｖ (る / ない / た) + <b>とき</b>（困ったとき）","nuance":"<ol><li>とき (時) = kata benda \"waktu\" → disambung seperti menerangkan KB.</li><li>Untuk masa lalu (子供のとき), kebiasaan (暇なとき), situasi umum (借りるとき).</li><li><b>〜ときに</b> = tepat pada saat itu; <b>〜ときは</b> = topik / kontras.</li></ol>⚠️ ×子供とき / ×暇とき — wajib <b>の / な</b>. Untuk \"andai / kalau\" pakai <b>〜たら</b>.","examples":[{"jp":"<ruby>子供<rt>こども</rt></ruby>のとき、よく<ruby>川<rt>かわ</rt></ruby>で<ruby>泳<rt>およ</rt></ruby>ぎました。","speech":"子供のとき、よく川で泳ぎました。","id":"<b>Waktu kecil</b>, aku sering berenang di sungai. <i>(Ｎのとき · masa lalu)</i>"},{"jp":"<ruby>暇<rt>ひま</rt></ruby>なとき、 <ruby>本<rt>ほん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>んだり、 <ruby>音楽<rt>おんがく</rt></ruby>を<ruby>聞<rt>き</rt></ruby>いたりします。","speech":"暇なとき、本を読んだり、音楽を聞いたりします。","id":"<b>Kalau lagi senggang</b>, aku baca buku, dengar musik, dan lain-lain. <i>(なとき · kebiasaan)</i>"},{"jp":"<ruby>眠<rt>ねむ</rt></ruby>いとき、コーヒーを<ruby>飲<rt>の</rt></ruby>みます。","speech":"眠いとき、コーヒーを飲みます。","id":"<b>Kalau lagi ngantuk</b>, aku minum kopi. <i>(KS-i とき)</i>"},{"jp":"<ruby>図書館<rt>としょかん</rt></ruby>で<ruby>本<rt>ほん</rt></ruby>を<ruby>借<rt>か</rt></ruby>りるとき、カードが<ruby>要<rt>い</rt></ruby>ります。","speech":"図書館で本を借りるとき、カードが要ります。","id":"<b>Waktu meminjam</b> buku di perpustakaan, perlu kartu. <i>(Ｖるとき · situasi umum)</i>"},{"jp":"わからないとき、 <ruby>先生<rt>せんせい</rt></ruby>に<ruby>聞<rt>き</rt></ruby>いてください。","speech":"わからないとき、先生に聞いてください。","id":"<b>Kalau nggak ngerti</b>, tanya ke guru ya. <i>(Ｖないとき)</i>"}],"dialogs":[{"jp":"<ruby>比企谷<rt>ひきがや</rt></ruby>って<b><ruby>中学<rt>ちゅうがく</rt></ruby>のとき</b> <ruby>生徒会<rt>せいとかい</rt></ruby>とかやってたっけ?","speech":"比企谷って中学のとき生徒会とかやってたっけ?","id":"Hikigaya, <b>waktu SMP</b> kamu ikut OSIS atau semacamnya ya? <i>(Ｎのとき)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP06 · 21:06"},{"jp":"<b><ruby>小<rt>ちい</rt></ruby>さいとき</b> <ruby>私<rt>わたし</rt></ruby>のこと<ruby>何<rt>なん</rt></ruby>て<ruby>呼<rt>よ</rt></ruby>んでた?","speech":"小さいとき私のこと何て呼んでた?","id":"<b>Waktu kecil</b> kamu manggil aku apa? <i>(KS-i とき)</i>","source":"安達としまむら · EP09 · 12:13"},{"jp":"<b><ruby>暇<rt>ひま</rt></ruby>なとき</b>とかでいいんで","speech":"暇なときとかでいいんで","id":"<b>Pas lagi senggang</b> aja juga nggak apa-apa kok. <i>(KS-na なとき)</i>","source":"薫る花は凛と咲く · EP03 · 11:41"},{"jp":"べつにいいよ　<b><ruby>困<rt>こま</rt></ruby>ったときは</b> お<ruby>互<rt>たが</rt></ruby>いさまってやつだし","speech":"べつにいいよ困ったときはお互いさまってやつだし","id":"Nggak apa-apa. <b>Waktu lagi susah</b> kan harus saling bantu. <i>(Ｖたとき · ときは)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP06 · 10:09"},{"jp":"テント<ruby>使<rt>つか</rt></ruby>うの<b><ruby>寝<rt>ね</rt></ruby>る<ruby>時<rt>とき</rt></ruby></b>だけだし-","speech":"テント使うの寝る時だけだし-","id":"Tendanya kan cuma dipakai <b>waktu tidur</b>. <i>(Ｖるとき)</i>","source":"ゆるキャン△ · EP11 · 10:56"}]},{"id":"n5_b23_02","level":"N5","bab":23,"lokasi":"第23課","titleMain":"Ｖるとき ／ Ｖたとき","titleSub":["帰るとき","帰ったとき"],"meaning":"Ｖるとき = saat mau/sedang (aksi belum selesai) · Ｖたとき = saat sudah (aksi selesai)","formula":"<b>Ｖ-る</b> + とき、B → B terjadi <b>sebelum / selama</b> A<br><b>Ｖ-た</b> + とき、B → B terjadi <b>setelah</b> A selesai<br>国へ<b>帰る</b>とき買った (sebelum pulang) ／ 国へ<b>帰った</b>とき買った (setelah sampai)","nuance":"<ol><li>Bentuknya ditentukan <b>urutan</b> dengan kalimat utama, bukan \"sekarang / dulu\".</li><li>うちを<b>出る</b>とき「行ってきます」 ／ うちへ<b>帰った</b>とき「ただいま」.</li></ol>⚠️ Kalimat utama boleh lampau walau sebelumnya Ｖる (帰るとき、かばんを買いました = benar).","examples":[{"jp":"うちを<ruby>出<rt>で</rt></ruby>るとき、「 <ruby>行<rt>い</rt></ruby>ってきます」と<ruby>言<rt>い</rt></ruby>います。","speech":"うちを出るとき、「行ってきます」と言います。","id":"<b>Waktu mau keluar</b> rumah, kita bilang \"aku pergi dulu\". <i>(Ｖる · sebelum)</i>"},{"jp":"うちへ<ruby>帰<rt>かえ</rt></ruby>ったとき、「ただいま」と<ruby>言<rt>い</rt></ruby>います。","speech":"うちへ帰ったとき、「ただいま」と言います。","id":"<b>Waktu sudah sampai</b> rumah, kita bilang \"aku pulang\". <i>(Ｖた · sesudah)</i>"},{"jp":"<ruby>国<rt>くに</rt></ruby>へ<ruby>帰<rt>かえ</rt></ruby>るとき、かばんを<ruby>買<rt>か</rt></ruby>いました。","speech":"国へ帰るとき、かばんを買いました。","id":"Aku beli tas <b>sebelum pulang</b> ke negaraku. <i>(Ｖる · beli di Jepang)</i>"},{"jp":"<ruby>国<rt>くに</rt></ruby>へ<ruby>帰<rt>かえ</rt></ruby>ったとき、かばんを<ruby>買<rt>か</rt></ruby>いました。","speech":"国へ帰ったとき、かばんを買いました。","id":"Aku beli tas <b>setelah sampai</b> di negaraku. <i>(Ｖた · beli di kampung)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>へ<ruby>来<rt>き</rt></ruby>たとき、 <ruby>空港<rt>くうこう</rt></ruby>で<ruby>友達<rt>ともだち</rt></ruby>に<ruby>会<rt>あ</rt></ruby>いました。","speech":"日本へ来たとき、空港で友達に会いました。","id":"<b>Waktu sampai</b> di Jepang, aku ketemu teman di bandara. <i>(Ｖた · sesudah)</i>"}],"dialogs":[{"jp":"じゃあ <b><ruby>出<rt>で</rt></ruby>かける<ruby>時<rt>とき</rt></ruby></b> <ruby>何<rt>なん</rt></ruby>て<ruby>言<rt>い</rt></ruby>うんだ?","speech":"じゃあ出かける時何て言うんだ?","id":"Terus <b>waktu mau berangkat</b>, kamu bilang apa? <i>(Ｖる · belum berangkat)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 04:52"},{"jp":"じゃあ<ruby>今度<rt>こんど</rt></ruby><b><ruby>来<rt>く</rt></ruby>るとき</b>までに<ruby>練習<rt>れんしゅう</rt></ruby>しとくね","speech":"じゃあ今度来るときまでに練習しとくね","id":"Kalau gitu, aku latihan dulu sebelum <b>kamu datang</b> lagi ya. <i>(Ｖる · belum datang)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 07:16"},{"jp":"<b><ruby>帰<rt>かえ</rt></ruby>るときにも</b> ぜひ<ruby>寄<rt>よ</rt></ruby>ってくれよ!","speech":"帰るときにもぜひ寄ってくれよ!","id":"<b>Waktu pulang nanti</b> mampir juga ya! <i>(Ｖる · dalam perjalanan pulang)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 09:45"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby> <b><ruby>出<rt>で</rt></ruby>かけたときに</b> <ruby>何<rt>なに</rt></ruby>かあったのかしら","speech":"昨日出かけたときに何かあったのかしら","id":"Apa ada sesuatu <b>waktu dia pergi</b> kemarin, ya? <i>(Ｖた · sudah di luar)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 04:49"},{"jp":"<ruby>友達<rt>ともだち</rt></ruby>が<ruby>来<rt>く</rt></ruby>るって<b><ruby>聞<rt>き</rt></ruby>いたとき</b>","speech":"友達が来るって聞いたとき","id":"<b>Waktu</b> aku <b>dengar</b> temanmu mau datang… <i>(Ｖた · setelah dengar)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 12:18"}]},{"id":"n5_b23_03","level":"N5","bab":23,"lokasi":"第23課","titleMain":"〜と","titleSub":["Ｖると、〜","押すと出ます"],"meaning":"Kalau / begitu …, (pasti) … — akibat otomatis (mesin, arah, alam, fakta umum)","formula":"Ｖ-る / Ｖ-ない + <b>と</b>、hasil（押すと、お釣りが出ます）<br>Arah: 右へ曲がる<b>と</b>、郵便局があります<br>Alam: 春になる<b>と</b>、桜が咲きます","nuance":"<ol><li><b>Mesin / alat</b>: tombol, tuas, kunci.</li><li><b>Petunjuk arah</b>: belok / jalan lurus → ada ….</li><li><b>Alam / fakta umum</b>: musim, kebiasaan tubuh.</li></ol>⚠️ Setelah と <b>tidak boleh</b> kehendak / permintaan / ajakan (×着くと電話してください → ○着い<b>たら</b>). Subjek hasil pakai <b>が</b>.","examples":[{"jp":"このボタンを<ruby>押<rt>お</rt></ruby>すと、お<ruby>釣<rt>つ</rt></ruby>りが<ruby>出<rt>で</rt></ruby>ます。","speech":"このボタンを押すと、お釣りが出ます。","id":"<b>Kalau</b> tombol ini <b>ditekan</b>, kembaliannya keluar. <i>(mesin)</i>"},{"jp":"<ruby>右<rt>みぎ</rt></ruby>へ<ruby>曲<rt>ま</rt></ruby>がると、 <ruby>郵便局<rt>ゆうびんきょく</rt></ruby>があります。","speech":"右へ曲がると、郵便局があります。","id":"<b>Kalau belok</b> kanan, ada kantor pos. <i>(arah)</i>"},{"jp":"これを<ruby>回<rt>まわ</rt></ruby>すと、 <ruby>音<rt>おと</rt></ruby>が<ruby>大<rt>おお</rt></ruby>きくなります。","speech":"これを回すと、音が大きくなります。","id":"<b>Kalau</b> ini <b>diputar</b>, suaranya jadi keras. <i>(alat)</i>"},{"jp":"<ruby>春<rt>はる</rt></ruby>になると、 <ruby>桜<rt>さくら</rt></ruby>が<ruby>咲<rt>さ</rt></ruby>きます。","speech":"春になると、桜が咲きます。","id":"<b>Begitu</b> musim semi <b>tiba</b>, bunga sakura mekar. <i>(alam)</i>"},{"jp":"この<ruby>橋<rt>はし</rt></ruby>を<ruby>渡<rt>わた</rt></ruby>ると、 <ruby>駅<rt>えき</rt></ruby>があります。","speech":"この橋を渡ると、駅があります。","id":"<b>Kalau menyeberangi</b> jembatan ini, ada stasiun. <i>(arah)</i>"}],"dialogs":[{"jp":"ボタンを<b><ruby>押<rt>お</rt></ruby>すと</b> かわいい<ruby>鳴<rt>な</rt></ruby>き<ruby>声<rt>ごえ</rt></ruby>がします","speech":"ボタンを押すとかわいい鳴き声がします","id":"<b>Kalau</b> tombolnya <b>ditekan</b>, keluar suara imut. <i>(mesin)</i>","source":"ヤニねこ · EP11 · 14:53"},{"jp":"ここから まっすぐ<b><ruby>行<rt>い</rt></ruby>くと</b> <ruby>無法<rt>むほう</rt></ruby><ruby>都市<rt>とし</rt></ruby>って<ruby>街<rt>まち</rt></ruby>があるから","speech":"ここからまっすぐ行くと無法都市って街があるから","id":"Dari sini <b>kalau jalan</b> lurus, ada kota namanya \"Kota Tanpa Hukum\". <i>(arah)</i>","source":"陰の実力者になりたくて！ 2nd season · EP06 · 05:56"},{"jp":"<ruby>冬<rt>ふゆ</rt></ruby>に<b>なると</b> たくさん<ruby>集<rt>あつ</rt></ruby>まってくるんだよ ここ","speech":"冬になるとたくさん集まってくるんだよここ","id":"<b>Begitu</b> musim dingin <b>tiba</b>, banyak yang ngumpul di sini lho. <i>(alam)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 08:34"},{"jp":"<ruby>今<rt>いま</rt></ruby> <b><ruby>寝<rt>ね</rt></ruby>ると</b> <ruby>丑三<rt>うしみ</rt></ruby>つ<ruby>時<rt>どき</rt></ruby>に<ruby>目<rt>め</rt></ruby>がさえるよ","speech":"今寝ると丑三つ時に目がさえるよ","id":"<b>Kalau tidur</b> sekarang, nanti tengah malam malah melek lho. <i>(akibat pasti)</i>","source":"ゆるキャン△ · EP07 · 05:23"},{"jp":"<ruby>眠<rt>ねむ</rt></ruby>くなるし こたつで<b><ruby>寝<rt>ね</rt></ruby>ると</b>カゼひくぞ","speech":"眠くなるしこたつで寝るとカゼひくぞ","id":"Nanti ngantuk, terus <b>kalau tidur</b> di kotatsu bisa masuk angin. <i>(akibat pasti)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP07 · 02:23"}]},{"id":"n5_b24_01","level":"N5","bab":24,"lokasi":"第24課","titleMain":"くれます","titleSub":["〜は 私に Ｎを くれる"],"meaning":"(Orang lain) memberi (kepadaku / keluargaku) — barang bergerak menuju aku","formula":"[Pemberi] は/が (私に) Ｎ を <b>くれます</b>（佐藤さんは私に花をくれました）<br>Aku ➔ orang lain: <b>あげます</b> · aku menerima: <b>もらいます</b>","nuance":"<ol><li>Penerimanya <b>aku / keluarga / kelompokku</b> → wajib くれる, bukan あげる.</li><li>私に sering dihilangkan karena sudah jelas (母が時計をくれました).</li></ol>⚠️ ×私は佐藤さんに花を<b>くれました</b>. Dari atasan → <b>くださいます</b> (Bab 41).","examples":[{"jp":"<ruby>佐藤<rt>さとう</rt></ruby>さんは<ruby>私<rt>わたし</rt></ruby>に<ruby>花<rt>はな</rt></ruby>をくれました。","speech":"佐藤さんは私に花をくれました。","id":"Sato-san <b>memberiku</b> bunga. <i>(orang lain ➔ aku)</i>"},{"jp":"<ruby>母<rt>はは</rt></ruby>は<ruby>誕生日<rt>たんじょうび</rt></ruby>に<ruby>時計<rt>とけい</rt></ruby>をくれました。","speech":"母は誕生日に時計をくれました。","id":"Ibu <b>memberiku</b> jam tangan waktu ulang tahun. <i>(私に dihilangkan)</i>"},{"jp":"<ruby>友達<rt>ともだち</rt></ruby>が<ruby>妹<rt>いもうと</rt></ruby>にお<ruby>菓子<rt>かし</rt></ruby>をくれました。","speech":"友達が妹にお菓子をくれました。","id":"Temanku <b>memberi</b> adikku camilan. <i>(➔ keluargaku)</i>"},{"jp":"これ、くれるの？ありがとう！","speech":"これ、くれるの？ありがとう！","id":"Ini <b>buat aku</b>? Makasih! <i>(kasual)</i>"}],"dialogs":[{"jp":"はい　 <ruby>周<rt>あまね</rt></ruby><ruby>君<rt>くん</rt></ruby>が<b>くれた</b>もの<ruby>全部<rt>ぜんぶ</rt></ruby><ruby>大切<rt>たいせつ</rt></ruby>にします","speech":"はい周君がくれたもの全部大切にします","id":"Iya. Semua yang <b>dikasih</b> Amane-kun bakal aku jaga baik-baik. <i>(orang lain ➔ aku)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP06 · 12:58"},{"jp":"えっ <b>くれるの?</b> 1500<ruby>円<rt>えん</rt></ruby>","speech":"えっくれるの? 1500円","id":"Eh, <b>buat aku</b>? Yang 1500 yen? <i>(kasual · くれるの?)</i>","source":"ゆるキャン△ · EP01 · 14:05"},{"jp":"<ruby>前<rt>まえ</rt></ruby><ruby>使<rt>つか</rt></ruby>ってたやつ <b>くれたんだ</b>","speech":"前使ってたやつくれたんだ","id":"Dia <b>ngasih aku</b> yang dulu dia pakai. <i>(barang bekas ➔ aku)</i>","source":"ゆるキャン△ · EP07 · 06:19"},{"jp":"これは<ruby>小町<rt>こまち</rt></ruby>が<b>くれた</b>1つの<ruby>答<rt>こた</rt></ruby>えだ","speech":"これは小町がくれた1つの答えだ","id":"Ini satu jawaban yang <b>diberikan</b> Komachi padaku. <i>(abstrak ➔ aku)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP05 · 05:39"},{"jp":"<ruby>毎年<rt>まいとし</rt></ruby><ruby>撫子<rt>なでしこ</rt></ruby>が<b>くれた</b>わね お<ruby>誕生日<rt>たんじょうび</rt></ruby>のプレゼント","speech":"毎年撫子がくれたわねお誕生日のプレゼント","id":"Tiap tahun Nadeshiko <b>ngasih aku</b> kado ulang tahun, ya. <i>(orang lain ➔ aku)</i>","source":"カードキャプターさくら · EP54 · 16:49"}]},{"id":"n5_b24_02","level":"N5","bab":24,"lokasi":"第24課","titleMain":"〜てあげます","titleSub":["Ｖてあげる"],"meaning":"Melakukan sesuatu untuk orang lain — aku memberi kebaikan / jasa","formula":"Ｖ-て + <b>あげます</b>（地図をかいてあげました）<br>Penerima pakai partikel kata kerja aslinya: 人<b>に</b>貸す ／ 人<b>を</b>送る ／ 人<b>の</b>荷物を持つ","nuance":"<ol><li>Arah kebaikan: <b>aku ➔ orang lain</b> (atau orang ketiga ➔ orang ketiga).</li><li>Nuansa \"aku berbaik hati\" — akrab ke teman / adik / anak.</li></ol>⚠️ Jangan langsung ke atasan (×先生、持ってあげます) → <b>持ちましょうか</b> / お持ちしましょうか.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>木村<rt>きむら</rt></ruby>さんに<ruby>地図<rt>ちず</rt></ruby>をかいてあげました。","speech":"私は木村さんに地図をかいてあげました。","id":"Aku <b>menggambarkan</b> peta <b>untuk</b> Kimura-san. <i>(aku ➔ orang lain)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>友達<rt>ともだち</rt></ruby>に<ruby>傘<rt>かさ</rt></ruby>を<ruby>貸<rt>か</rt></ruby>してあげました。","speech":"私は友達に傘を貸してあげました。","id":"Aku <b>meminjamkan</b> payung ke temanku. <i>(人に貸す)</i>"},{"jp":"<ruby>太郎<rt>たろう</rt></ruby><ruby>君<rt>くん</rt></ruby>におもちゃを<ruby>買<rt>か</rt></ruby>ってあげました。","speech":"太郎君におもちゃを買ってあげました。","id":"Aku <b>membelikan</b> mainan untuk Taro. <i>(ke anak)</i>"},{"jp":"<ruby>妹<rt>いもうと</rt></ruby>の<ruby>宿題<rt>しゅくだい</rt></ruby>を<ruby>見<rt>み</rt></ruby>てあげました。","speech":"妹の宿題を見てあげました。","id":"Aku <b>bantu cek</b> PR adikku. <i>(人の〜)</i>"}],"dialogs":[{"jp":"<ruby>今<rt>いま</rt></ruby>コーヒー<b><ruby>入<rt>い</rt></ruby>れてあげる</b>","speech":"今コーヒー入れてあげる","id":"Sebentar, <b>aku buatin</b> kopi. <i>(jasa ke orang lain)</i>","source":"ガールズバンドクライ · EP01 · 13:03"},{"jp":"<ruby>暖<rt>あたた</rt></ruby>かくなったら <b><ruby>連<rt>つ</rt></ruby>れてってあげる</b>から-","speech":"暖かくなったら連れてってあげるから-","id":"Nanti kalau udah hangat, <b>aku ajak</b> ke sana deh. <i>(janji · kasual てって)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 10:25"},{"jp":"<ruby>遊<rt>あそ</rt></ruby>んでません　ただ<ruby>木<rt>き</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>で<ruby>立往生<rt>たちおうじょう</rt></ruby>していた<ruby>猫<rt>ねこ</rt></ruby>を <b><ruby>下<rt>お</rt></ruby>ろしてあげた</b>だけです","speech":"遊んでませんただ木の上で立往生していた猫を下ろしてあげただけです","id":"Aku nggak main-main. Aku cuma <b>nurunin</b> kucing yang terjebak di atas pohon. <i>(menolong)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP02 · 00:26"},{"jp":"だし<ruby>巻<rt>ま</rt></ruby>き<ruby>卵<rt>たまご</rt></ruby>は<ruby>明日<rt>あした</rt></ruby>の<ruby>朝<rt>あさ</rt></ruby>に<b><ruby>作<rt>つく</rt></ruby>ってあげます</b>ね","speech":"だし巻き卵は明日の朝に作ってあげますね","id":"Telur gulungnya <b>aku bikinin</b> besok pagi ya. <i>(sopan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP12 · 12:05"},{"jp":"いつも あぶれてるからね <b><ruby>入<rt>い</rt></ruby>れてあげる</b>よ","speech":"いつもあぶれてるからね入れてあげるよ","id":"Kamu kan selalu kesisih, jadi <b>kami masukin</b> deh. <i>(berbaik hati)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 09:08"}]},{"id":"n5_b24_03","level":"N5","bab":24,"lokasi":"第24課","titleMain":"〜てもらいます","titleSub":["人に Ｖてもらう"],"meaning":"Dibantu / diajari / dibelikan (oleh orang lain) — aku menerima kebaikan","formula":"[Aku] は [pemberi jasa] <b>に</b> Ｖ-て + <b>もらいます</b><br>山田さん<b>に</b>漢字を教えて<b>もらいました</b>","nuance":"<ol><li>Sudut pandang <b>penerima</b> (subjek = aku), ada rasa terima kasih.</li><li>Bahasa Indonesia lebih natural pakai \"di-…\": diajari, dibantu, dibelikan.</li></ol>⚠️ Pemberi jasa pakai <b>に</b>. Isi sama dengan てくれる, beda fokus: 山田さん<b>に</b>〜てもらった ＝ 山田さん<b>が</b>〜てくれた.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>山田<rt>やまだ</rt></ruby>さんに<ruby>漢字<rt>かんじ</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えてもらいました。","speech":"私は山田さんに漢字を教えてもらいました。","id":"Aku <b>diajari</b> kanji <b>oleh</b> Yamada-san. <i>(人に)</i>"},{"jp":"<ruby>友達<rt>ともだち</rt></ruby>に<ruby>引<rt>ひ</rt></ruby>っ<ruby>越<rt>こ</rt></ruby>しを<ruby>手伝<rt>てつだ</rt></ruby>ってもらいました。","speech":"友達に引っ越しを手伝ってもらいました。","id":"Aku <b>dibantu</b> temanku pindahan. <i>(dibantu)</i>"},{"jp":"<ruby>父<rt>ちち</rt></ruby>に<ruby>自転車<rt>じてんしゃ</rt></ruby>を<ruby>買<rt>か</rt></ruby>ってもらいました。","speech":"父に自転車を買ってもらいました。","id":"Aku <b>dibelikan</b> sepeda <b>oleh</b> ayah. <i>(dibelikan)</i>"},{"jp":"<ruby>駅員<rt>えきいん</rt></ruby>さんに<ruby>道<rt>みち</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えてもらいました。","speech":"駅員さんに道を教えてもらいました。","id":"Aku <b>ditunjukkan</b> jalan oleh petugas stasiun. <i>(ditunjukkan)</i>"}],"dialogs":[{"jp":"<ruby>村長<rt>そんちょう</rt></ruby>に<ruby>銀貨<rt>ぎんか</rt></ruby>を<b><ruby>見<rt>み</rt></ruby>せてもらった</b>よ","speech":"村長に銀貨を見せてもらったよ","id":"Aku <b>ditunjukkan</b> koin perak sama kepala desa. <i>(人に〜てもらう)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP01 · 15:14"},{"jp":"\" <ruby>今日<rt>きょう</rt></ruby>はお<ruby>姉<rt>ねえ</rt></ruby>ちゃんに ギターを<b><ruby>教<rt>おし</rt></ruby>えてもらいました</b>\"","speech":"\" 今日はお姉ちゃんにギターを教えてもらいました\"","id":"\"Hari ini aku <b>diajari</b> gitar sama kakak.\" <i>(sopan · diajari)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 05:40"},{"jp":"<ruby>本当<rt>ほんとう</rt></ruby>に ありがとう　たくさん<b><ruby>助<rt>たす</rt></ruby>けてもらった</b>","speech":"本当にありがとうたくさん助けてもらった","id":"Makasih banget. Aku udah <b>banyak ditolong</b>. <i>(terima kasih)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 17:31"},{"jp":"それ <b><ruby>買<rt>か</rt></ruby>ってもらった</b>のか","speech":"それ買ってもらったのか","id":"Itu <b>dibeliin</b> (sama dia)? <i>(dibelikan)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP02 · 18:32"},{"jp":"<ruby>私<rt>わたし</rt></ruby><ruby>昔<rt>むかし</rt></ruby><ruby>小雪<rt>こゆき</rt></ruby>さんに いろいろと<b><ruby>教<rt>おし</rt></ruby>えてもらいました</b>けど","speech":"私昔小雪さんにいろいろと教えてもらいましたけど","id":"Dulu aku <b>diajari</b> macam-macam sama Koyuki-san, sih… <i>(人に〜てもらう)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP02 · 10:07"}]},{"id":"n5_b24_04","level":"N5","bab":24,"lokasi":"第24課","titleMain":"〜てくれます","titleSub":["人が Ｖてくれる"],"meaning":"(Orang lain) berbaik hati melakukan … untukku — rasa terima kasih","formula":"[Pemberi jasa] は/が (私に) Ｖ-て + <b>くれます</b><br>母がセーターを送って<b>くれました</b> · 来て<b>くれて</b>ありがとう","nuance":"<ol><li>Arah: <b>orang lain ➔ aku / kelompokku</b>; subjek = orang yang berbuat baik.</li><li>Tanpa てくれる kalimat terasa datar (母はセーターを送りました = cuma fakta).</li><li>送る = mengirim (barang) <b>atau</b> mengantar (orang).</li></ol>⚠️ Aku ➔ orang lain: <b>てあげる</b> · aku sebagai subjek penerima: <b>てもらう</b>.","examples":[{"jp":"<ruby>母<rt>はは</rt></ruby>はセーターを<ruby>送<rt>おく</rt></ruby>ってくれました。","speech":"母はセーターを送ってくれました。","id":"Ibu <b>mengirimiku</b> sweter. <i>(送る = mengirim)</i>"},{"jp":"ミラーさんは<ruby>私<rt>わたし</rt></ruby>を<ruby>駅<rt>えき</rt></ruby>まで<ruby>送<rt>おく</rt></ruby>ってくれました。","speech":"ミラーさんは私を駅まで送ってくれました。","id":"Miller-san <b>mengantarku</b> sampai stasiun. <i>(送る = mengantar)</i>"},{"jp":"<ruby>佐藤<rt>さとう</rt></ruby>さんが<ruby>京都<rt>きょうと</rt></ruby>を<ruby>案内<rt>あんない</rt></ruby>してくれました。","speech":"佐藤さんが京都を案内してくれました。","id":"Sato-san <b>mengajakku keliling</b> Kyoto. <i>(terima kasih)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>来<rt>き</rt></ruby>てくれて、ありがとう。","speech":"今日は来てくれて、ありがとう。","id":"Makasih ya <b>sudah mau datang</b> hari ini. <i>(てくれて ありがとう)</i>"}],"dialogs":[{"jp":"<ruby>店長<rt>てんちょう</rt></ruby>が<b><ruby>代<rt>か</rt></ruby>わってくれた</b>","speech":"店長が代わってくれた","id":"Manajer <b>mau gantiin</b> aku. <i>(orang lain ➔ aku)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 17:24"},{"jp":"そう <b><ruby>送<rt>おく</rt></ruby>ってくれた</b>のね ありがとう","speech":"そう送ってくれたのねありがとう","id":"Oh, kamu <b>nganterin</b> dia ya. Makasih. <i>(送る = mengantar)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP12 · 20:42"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんも お<ruby>手伝<rt>てつだ</rt></ruby>い<b>してくれました</b>ので","speech":"周くんもお手伝いしてくれましたので","id":"Soalnya Amane-kun juga <b>bantuin aku</b>. <i>(sopan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP07 · 01:07"},{"jp":"<b><ruby>分<rt>わ</rt></ruby>かってくれた</b>んだね あきちゃん","speech":"分かってくれたんだねあきちゃん","id":"Akhirnya kamu <b>mau ngerti</b> ya, Aki-chan. <i>(lega · terima kasih)</i>","source":"ゆるキャン△ · EP10 · 23:13"},{"jp":"<ruby>由比<rt>ゆい</rt></ruby>ヶ<ruby>浜<rt>はま</rt></ruby>さん<b><ruby>来<rt>き</rt></ruby>てくれた</b>の","speech":"由比ヶ浜さん来てくれたの","id":"Yuigahama-san, kamu <b>datang</b> (buat kami)? <i>(来てくれる)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP12 · 22:20"}]},{"id":"n5_b25_01","level":"N5","bab":25,"lokasi":"第25課","titleMain":"もし〜たら","titleSub":["〜かったら","〜だったら"],"meaning":"Kalau… / seandainya… — syarat yang belum tentu terjadi","formula":"Ｖ-た + <b>ら</b>（降ったら） · Ｖ-なかった + <b>ら</b><br>KS-i → <b>〜かったら</b>（安かったら） · いい → <b>よかったら</b><br>KS-na / KB + <b>だったら</b>（暇だったら）","nuance":"<ol><li><b>もし</b> menegaskan pengandaian (opsional).</li><li>Setelah たら boleh keinginan, ajakan, permintaan — bebas, beda dengan <b>と</b>.</li><li>Pengandaian paling serbaguna & paling sering di percakapan.</li></ol>⚠️ KS-i = 〜<b>かったら</b>, bukan 〜ければ (itu bentuk ば, Bab 35). <b>よかったら</b> = kalau berkenan.","examples":[{"jp":"お<ruby>金<rt>かね</rt></ruby>があったら、 <ruby>旅行<rt>りょこう</rt></ruby>に<ruby>行<rt>い</rt></ruby>きたいです。","speech":"お金があったら、旅行に行きたいです。","id":"<b>Kalau</b> punya uang, aku ingin jalan-jalan. <i>(+ keinginan)</i>"},{"jp":"もし <ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>ったら、 <ruby>試合<rt>しあい</rt></ruby>は<ruby>中止<rt>ちゅうし</rt></ruby>です。","speech":"もし雨が降ったら、試合は中止です。","id":"<b>Seandainya</b> hujan, pertandingannya dibatalkan. <i>(もし)</i>"},{"jp":"<ruby>安<rt>やす</rt></ruby>かったら、 <ruby>買<rt>か</rt></ruby>います。","speech":"安かったら、買います。","id":"<b>Kalau murah</b>, aku beli. <i>(KS-i かったら)</i>"},{"jp":"<ruby>暇<rt>ひま</rt></ruby>だったら、 <ruby>手伝<rt>てつだ</rt></ruby>ってください。","speech":"暇だったら、手伝ってください。","id":"<b>Kalau senggang</b>, tolong bantu ya. <i>(+ permintaan)</i>"},{"jp":"<ruby>意見<rt>いけん</rt></ruby>が<ruby>合<rt>あ</rt></ruby>わなかったら、よく<ruby>話<rt>はな</rt></ruby>し<ruby>合<rt>あ</rt></ruby>いましょう。","speech":"意見が合わなかったら、よく話し合いましょう。","id":"<b>Kalau</b> pendapat kita <b>nggak cocok</b>, ayo bicarakan baik-baik. <i>(+ ajakan)</i>"}],"dialogs":[{"jp":"<b><ruby>暇<rt>ひま</rt></ruby>だったら</b>な","speech":"暇だったらな","id":"<b>Kalau lagi senggang</b> ya. <i>(KS-na だったら)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP09 · 11:11"},{"jp":"<b>もし</b> <b><ruby>足<rt>た</rt></ruby>りなかったら</b> <ruby>自腹<rt>じばら</rt></ruby>で<ruby>補填<rt>ほてん</rt></ruby>しなさいね","speech":"もし足りなかったら自腹で補填しなさいね","id":"<b>Kalau</b> nanti <b>kurang</b>, tutupi pakai uangmu sendiri ya. <i>(もし + Ｖなかったら)</i>","source":"この素晴らしい世界に爆焔を！ · EP11 · 10:30"},{"jp":"<b><ruby>気<rt>き</rt></ruby>に<ruby>入<rt>い</rt></ruby>らなかったら</b> <ruby>言<rt>い</rt></ruby>ってね","speech":"気に入らなかったら言ってね","id":"<b>Kalau nggak suka</b>, bilang ya. <i>(たら + permintaan)</i>","source":"ガールズバンドクライ · EP05 · 20:14"},{"jp":"<b>もし</b> <b><ruby>並<rt>なら</rt></ruby>んだら?</b>","speech":"もし並んだら?","id":"<b>Seandainya</b> mereka <b>sejajar</b>? <i>(もし〜たら)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP07 · 07:30"},{"jp":"<b><ruby>入<rt>はい</rt></ruby>りきらなかったら</b> <ruby>後部<rt>こうぶ</rt></ruby><ruby>座席<rt>ざせき</rt></ruby>も<ruby>使<rt>つか</rt></ruby>ってね","speech":"入りきらなかったら後部座席も使ってね","id":"<b>Kalau nggak muat</b>, pakai jok belakang juga ya. <i>(たら + permintaan)</i>","source":"ゆるキャン△ · EP06 · 09:24"}]},{"id":"n5_b25_02","level":"N5","bab":25,"lokasi":"第25課","titleMain":"〜たら","titleSub":["10時になったら、〜","着いたら、〜てください"],"meaning":"Setelah… / begitu… / nanti kalau sudah… — syarat yang PASTI terjadi","formula":"Ｖ-た + <b>ら</b>、[kehendak / ajakan / permintaan]<br>10時に<b>なったら</b>、出かけましょう · 駅に<b>着いたら</b>、電話してください<br>Penemuan: Ｖ<b>たら</b>、〜た (開けたら、雪が降っていた)","nuance":"<ol><li>Bagian たら <b>pasti</b> terjadi → artinya \"begitu itu terjadi, lalu…\".</li><li>Tidak bisa pakai <b>もし</b> (bukan pengandaian).</li><li>Ｖたら、〜た = \"begitu…, ternyata…\" (penemuan).</li></ol>⚠️ ×着く<b>と</b>電話してください → ○着い<b>たら</b>. <b>てから</b> = menekankan urutan A dulu baru B.","examples":[{"jp":"10<ruby>時<rt>じ</rt></ruby>になったら、 <ruby>出<rt>で</rt></ruby>かけましょう。","speech":"10時になったら、出かけましょう。","id":"<b>Nanti kalau sudah</b> jam 10, ayo berangkat. <i>(waktu pasti tiba)</i>"},{"jp":"<ruby>駅<rt>えき</rt></ruby>に<ruby>着<rt>つ</rt></ruby>いたら、 <ruby>電話<rt>でんわ</rt></ruby>してください。","speech":"駅に着いたら、電話してください。","id":"<b>Begitu sampai</b> di stasiun, tolong telepon ya. <i>(+ permintaan)</i>"},{"jp":"<ruby>仕事<rt>しごと</rt></ruby>が<ruby>終<rt>お</rt></ruby>わったら、 <ruby>飲<rt>の</rt></ruby>みに<ruby>行<rt>い</rt></ruby>きませんか。","speech":"仕事が終わったら、飲みに行きませんか。","id":"<b>Habis</b> kerja <b>selesai</b>, mau minum bareng? <i>(+ ajakan)</i>"},{"jp":"<ruby>大学<rt>だいがく</rt></ruby>を<ruby>卒業<rt>そつぎょう</rt></ruby>したら、 <ruby>日本<rt>にほん</rt></ruby>で<ruby>働<rt>はたら</rt></ruby>きたいです。","speech":"大学を卒業したら、日本で働きたいです。","id":"<b>Setelah lulus</b> kuliah, aku ingin kerja di Jepang. <i>(+ keinginan)</i>"},{"jp":"<ruby>窓<rt>まど</rt></ruby>を<ruby>開<rt>あ</rt></ruby>けたら、 <ruby>雪<rt>ゆき</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>っていました。","speech":"窓を開けたら、雪が降っていました。","id":"<b>Begitu</b> kubuka jendela, <b>ternyata</b> salju sedang turun. <i>(penemuan)</i>"}],"dialogs":[{"jp":"<ruby>夕方<rt>ゆうがた</rt></ruby>に<b>なったら</b> <ruby>迎<rt>むか</rt></ruby>えに<ruby>来<rt>く</rt></ruby>るよ","speech":"夕方になったら迎えに来るよ","id":"<b>Nanti sore</b> aku jemput ya. <i>(になったら · waktu pasti tiba)</i>","source":"ゆるキャン△ SEASON２ · EP01 · 04:57"},{"jp":"<ruby>下北<rt>しもきた</rt></ruby> <b><ruby>着<rt>つ</rt></ruby>いたら</b> <ruby>起<rt>お</rt></ruby>こして","speech":"下北着いたら起こして","id":"<b>Begitu sampai</b> Shimokita, bangunin aku. <i>(+ permintaan)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 19:54"},{"jp":"<ruby>家<rt>いえ</rt></ruby>に<b><ruby>着<rt>つ</rt></ruby>いたら</b> <ruby>教<rt>おし</rt></ruby>えてねー","speech":"家に着いたら教えてねー","id":"<b>Kalau udah sampai</b> rumah, kabarin ya! <i>(+ permintaan)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 14:11"},{"jp":"ホロ<ruby>全部<rt>ぜんぶ</rt></ruby><b><ruby>終<rt>お</rt></ruby>わったら</b> <ruby>買<rt>か</rt></ruby>い<ruby>物<rt>もの</rt></ruby>に<ruby>行<rt>い</rt></ruby>こう","speech":"ホロ全部終わったら買い物に行こう","id":"Holo, <b>habis semua ini beres</b>, ayo belanja. <i>(+ ajakan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP04 · 13:45"},{"jp":"<ruby>高校<rt>こうこう</rt></ruby>に<b>なったら</b> <ruby>絶対<rt>ぜったい</rt></ruby>バンドやるんだぁ!","speech":"高校になったら絶対バンドやるんだぁ!","id":"<b>Nanti pas</b> SMA, aku pasti bakal nge-band! <i>(+ tekad)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 04:50"}]},{"id":"n5_b25_03","level":"N5","bab":25,"lokasi":"第25課","titleMain":"〜ても","titleSub":["〜くても","〜でも"],"meaning":"Walaupun… / meskipun… / biarpun… — hasilnya berlawanan dengan harapan","formula":"Ｖ-て + <b>も</b>（降っても） · Ｖ-なくて + <b>も</b>（行かなくても）<br>KS-i → <b>〜くても</b>（安くても）<br>KS-na / KB + <b>でも</b>（便利でも ／ 日曜日でも）","nuance":"<ol><li>Normalnya A → B; <b>〜ても</b>: walau A terjadi, B tetap tidak berubah.</li><li>もし / たとえ bisa ditambahkan: \"walaupun seandainya…\".</li></ol>⚠️ <b>たら</b> = kalau (sesuai harapan) vs <b>ても</b> = walaupun (berlawanan). <b>〜てもいい</b> (Bab 15) = boleh — pola lain.","examples":[{"jp":"<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>っても、サッカーをします。","speech":"雨が降っても、サッカーをします。","id":"<b>Walaupun</b> hujan, aku tetap main sepak bola. <i>(Ｖても)</i>"},{"jp":"<ruby>安<rt>やす</rt></ruby>くても、このパソコンは<ruby>買<rt>か</rt></ruby>いません。","speech":"安くても、このパソコンは買いません。","id":"<b>Walaupun murah</b>, aku nggak akan beli PC ini. <i>(KS-i くても)</i>"},{"jp":"<ruby>便利<rt>べんり</rt></ruby>でも、 <ruby>高<rt>たか</rt></ruby>いから<ruby>使<rt>つか</rt></ruby>いません。","speech":"便利でも、高いから使いません。","id":"<b>Walaupun praktis</b>, aku nggak pakai karena mahal. <i>(KS-na でも)</i>"},{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>でも、 <ruby>働<rt>はたら</rt></ruby>かなければなりません。","speech":"日曜日でも、働かなければなりません。","id":"<b>Walaupun hari Minggu</b>, aku harus kerja. <i>(KB でも)</i>"},{"jp":"<ruby>失敗<rt>しっぱい</rt></ruby>しても、またやればいいよ。","speech":"失敗しても、またやればいいよ。","id":"<b>Walaupun gagal</b>, coba lagi aja. <i>(menyemangati)</i>"}],"dialogs":[{"jp":"ダメだと<b><ruby>言<rt>い</rt></ruby>っても</b> どうせ<ruby>行<rt>い</rt></ruby>くだろう?","speech":"ダメだと言ってもどうせ行くだろう?","id":"<b>Biarpun</b> aku <b>bilang</b> nggak boleh, toh kamu bakal tetap pergi, kan? <i>(Ｖても)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP15 · 04:31"},{"jp":"<ruby>私<rt>わたし</rt></ruby>だけだから <b><ruby>失敗<rt>しっぱい</rt></ruby>しても</b> <ruby>迷惑<rt>めいわく</rt></ruby>かからないしね","speech":"私だけだから失敗しても迷惑かからないしね","id":"Kan cuma buat aku sendiri, jadi <b>walaupun gagal</b> nggak ngerepotin siapa-siapa. <i>(Ｖても)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 05:41"},{"jp":"<ruby>何<rt>なに</rt></ruby>が<b>あっても</b> <ruby>支<rt>ささ</rt></ruby>えるから","speech":"何があっても支えるから","id":"Apa pun <b>yang terjadi</b>, aku bakal dukung kamu. <i>(何があっても)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP06 · 19:18"},{"jp":"<ruby>姉<rt>あね</rt></ruby><b>じゃなくても</b> <ruby>母<rt>はは</rt></ruby><b>じゃなくても</b>　 <ruby>見<rt>み</rt></ruby>れば<ruby>誰<rt>だれ</rt></ruby>だって<ruby>分<rt>わ</rt></ruby>かるわ","speech":"姉じゃなくても母じゃなくても見れば誰だって分かるわ","id":"<b>Biarpun bukan</b> kakak <b>atau</b> ibunya, siapa pun yang lihat pasti ngerti. <i>(KB じゃなくても)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 19:21"},{"jp":"それに<ruby>失敗<rt>しっぱい</rt></ruby>して<ruby>変<rt>へん</rt></ruby>なのが<b>できても</b> ちょっと<ruby>面白<rt>おもしろ</rt></ruby>いし","speech":"それに失敗して変なのができてもちょっと面白いし","id":"Lagian, <b>walaupun</b> gagal dan <b>jadinya</b> aneh, itu agak seru juga. <i>(Ｖても)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 15:45"}]},{"id":"n5_b25_04","level":"N5","bab":25,"lokasi":"第25課","titleMain":"いくら〜ても","titleSub":["何度〜ても"],"meaning":"Mau sebanyak / sekeras apa pun…, tetap… — usaha seberapa pun, hasil tak berubah","formula":"<b>いくら</b> + Ｖ-て + <b>も</b>（いくら考えても）<br><b>いくら</b> + KS-くて <b>も</b> ／ KS-na・KB <b>でも</b><br>Variasi: <b>何度</b>〜ても ／ <b>どんなに</b>〜ても","nuance":"<ol><li>いくら = \"seberapa pun\" — menekankan derajat usaha/keadaan.</li><li>Hasilnya sering negatif: わかりません / 見つかりません.</li></ol>⚠️ <b>いくら</b> juga = \"berapa (harga)?\" (これはいくらですか) — di pola ini artinya seberapa pun.","examples":[{"jp":"いくら<ruby>考<rt>かんが</rt></ruby>えても、わかりません。","speech":"いくら考えても、わかりません。","id":"<b>Mau dipikir sekeras apa pun</b>, aku tetap nggak ngerti. <i>(Ｖても)</i>"},{"jp":"いくら<ruby>探<rt>さが</rt></ruby>しても、 <ruby>鍵<rt>かぎ</rt></ruby>が<ruby>見<rt>み</rt></ruby>つかりません。","speech":"いくら探しても、鍵が見つかりません。","id":"<b>Dicari sampai mana pun</b>, kuncinya nggak ketemu. <i>(Ｖても)</i>"},{"jp":"いくら<ruby>高<rt>たか</rt></ruby>くても、この<ruby>本<rt>ほん</rt></ruby>は<ruby>買<rt>か</rt></ruby>いたいです。","speech":"いくら高くても、この本は買いたいです。","id":"<b>Semahal apa pun</b>, aku tetap mau beli buku ini. <i>(KS-i くても)</i>"},{"jp":"いくら<ruby>好<rt>す</rt></ruby>きでも、 <ruby>毎日<rt>まいにち</rt></ruby>は<ruby>食<rt>た</rt></ruby>べられません。","speech":"いくら好きでも、毎日は食べられません。","id":"<b>Sesuka apa pun</b>, aku nggak bisa makan itu tiap hari. <i>(KS-na でも)</i>"},{"jp":"<ruby>何度<rt>なんど</rt></ruby><ruby>言<rt>い</rt></ruby>っても、 <ruby>弟<rt>おとうと</rt></ruby>は<ruby>部屋<rt>へや</rt></ruby>を<ruby>片付<rt>かたづ</rt></ruby>けません。","speech":"何度言っても、弟は部屋を片付けません。","id":"<b>Berapa kali pun</b> dibilangin, adikku nggak beresin kamarnya. <i>(何度〜ても)</i>"}],"dialogs":[{"jp":"<b>いくら<ruby>探<rt>さが</rt></ruby>しても</b>なかった","speech":"いくら探してもなかった","id":"<b>Dicari sampai mana pun</b>, nggak ada. <i>(いくら〜ても · hasil negatif)</i>","source":"文豪ストレイドッグス 第2シーズン · EP03 · 00:31"},{"jp":"<b>いくら<ruby>考<rt>かんが</rt></ruby>えても</b> <ruby>分<rt>わ</rt></ruby>かる<ruby>気<rt>き</rt></ruby>がしない","speech":"いくら考えても分かる気がしない","id":"<b>Dipikir sekeras apa pun</b>, rasanya nggak bakal ngerti. <i>(いくら〜ても)</i>","source":"僕の心のヤバイやつ 第2期 · EP04 · 03:47"},{"jp":"<ruby>分<rt>わ</rt></ruby>からない<ruby>問題<rt>もんだい</rt></ruby>を<b>いくら<ruby>考<rt>かんが</rt></ruby>えても</b> <ruby>時間<rt>じかん</rt></ruby>のムダだろ?","speech":"分からない問題をいくら考えても時間のムダだろ?","id":"Soal yang nggak dimengerti, <b>mau dipikir sekeras apa pun</b> ya buang waktu, kan? <i>(いくら〜ても)</i>","source":"時々ボソッとロシア語でデレる隣のアーリャさん · EP09 · 16:03"},{"jp":"<b>いくら</b> <ruby>節約<rt>せつやく</rt></ruby>だって<b><ruby>言<rt>い</rt></ruby>っても</b> これは...","speech":"いくら節約だって言ってもこれは...","id":"<b>Mau</b> hemat <b>segimana pun</b>, ini sih… <i>(いくら〜と言っても)</i>","source":"ガールズバンドクライ · EP07 · 12:38"},{"jp":"ルフィ <b><ruby>何度<rt>なんど</rt></ruby><ruby>言<rt>い</rt></ruby>っても</b> <ruby>懲<rt>こ</rt></ruby>りねえんだな","speech":"ルフィ何度言っても懲りねえんだな","id":"Luffy, <b>berapa kali pun dibilangin</b>, kamu nggak kapok-kapok ya. <i>(何度〜ても)</i>","source":"ONE PIECE · EP54 · 10:04"}]},{"id":"n4_b26_01","level":"N4","bab":26,"lokasi":"第26課","titleMain":"〜んですか","titleSub":["どうして〜んですか","〜なんですか"],"meaning":"Kok…? / memangnya…? / kenapa sih…? — tanya minta penjelasan atas situasi yang dilihat/didengar","formula":"Ｖ / KS-i (普通形) + <b>んですか</b>（遅れたんですか）<br>KS-na / KB + <b>な</b> + <b>んですか</b>（大丈夫なんですか）<br>Kasual: <b>〜の？</b> ／ <b>〜んだ？</b>","nuance":"<ol><li>Berdasarkan <b>apa yang dilihat / didengar</b>: いい靴ですね。どこで買ったんですか.</li><li><b>どうして〜んですか</b> = minta alasan.</li><li>Nuansa heran / ingin tahu latar belakang (〜ますか = tanya datar).</li></ol>⚠️ Terlalu sering → terdengar <b>menginterogasi</b>. Fakta umum cukup 〜ますか (毎朝何時に起きますか).","examples":[{"jp":"どうして<ruby>遅<rt>おく</rt></ruby>れたんですか。","speech":"どうして遅れたんですか。","id":"<b>Kenapa (sih)</b> telat? <i>(minta alasan)</i>"},{"jp":"いい<ruby>靴<rt>くつ</rt></ruby>ですね。どこで<ruby>買<rt>か</rt></ruby>ったんですか。","speech":"いい靴ですね。どこで買ったんですか。","id":"Sepatunya bagus. <b>Belinya di mana</b>? <i>(berdasarkan yang dilihat)</i>"},{"jp":"<ruby>元気<rt>げんき</rt></ruby>がないですね。どうしたんですか。","speech":"元気がないですね。どうしたんですか。","id":"Kamu kelihatan lesu. <b>Kenapa</b>? <i>(khawatir)</i>"},{"jp":"きれいな<ruby>写真<rt>しゃしん</rt></ruby>ですね。 <ruby>自分<rt>じぶん</rt></ruby>で<ruby>撮<rt>と</rt></ruby>ったんですか。","speech":"きれいな写真ですね。自分で撮ったんですか。","id":"Fotonya bagus. <b>Kamu ambil sendiri</b>? <i>(tertarik)</i>"}],"dialogs":[{"jp":"<ruby>一体<rt>いったい</rt></ruby> <b>どうしたんですか?</b>","speech":"一体どうしたんですか?","id":"Sebenarnya <b>kamu kenapa sih</b>? <i>(heran · minta penjelasan)</i>","source":"この素晴らしい世界に爆焔を！ · EP04 · 01:54"},{"jp":"じゃあ なんで<b>やめたんですか</b>","speech":"じゃあなんでやめたんですか","id":"Kalau gitu, <b>kenapa berhenti</b>? <i>(minta alasan)</i>","source":"ガールズバンドクライ · EP04 · 05:13"},{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby> いつキャンプ<b>やるんですか?</b>","speech":"部長いつキャンプやるんですか?","id":"Ketua, kita <b>jadinya kapan</b> kemahnya? <i>(ingin tahu)</i>","source":"ゆるキャン△ · EP04 · 00:16"},{"jp":"えっ! <b><ruby>大丈夫<rt>だいじょうぶ</rt></ruby>なんですか?</b>","speech":"えっ! 大丈夫なんですか?","id":"Hah?! Dia <b>beneran nggak apa-apa</b>? <i>(KS-na + なんですか · kaget)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 01:05"},{"jp":"<ruby>先輩<rt>せんぱい</rt></ruby> また<b><ruby>買<rt>か</rt></ruby>うんですか?</b>","speech":"先輩また買うんですか?","id":"Senpai, <b>mau beli lagi</b>? <i>(lihat situasi → heran)</i>","source":"ぼっち・ざ・ろっく！ · EP12 · 16:34"}]},{"id":"n4_b26_02","level":"N4","bab":26,"lokasi":"第26課","titleMain":"〜んです","titleSub":["〜なんです","〜んだ"],"meaning":"Soalnya… / begini lho… / sebenarnya… — memberi penjelasan atau alasan","formula":"Ｖ / KS-i (普通形) + <b>んです</b>（バスが来なかったんです）<br>KS-na / KB + <b>な</b> + <b>んです</b>（試験なんです）<br>Kasual: <b>〜んだ</b> ／ <b>〜の</b>","nuance":"<ol><li>Menjawab 〜んですか: どうして遅れたんですか → バスが来なかったんです.</li><li>Menjelaskan alasan tanpa ditanya (izin / menolak): 頭が痛いんです.</li><li>Penegasan / curhat: すごく好きなんです.</li></ol>⚠️ Jangan untuk fakta datar tanpa konteks (×私はインドネシア人なんです saat perkenalan biasa).","examples":[{"jp":"すみません、バスが<ruby>来<rt>こ</rt></ruby>なかったんです。","speech":"すみません、バスが来なかったんです。","id":"Maaf, <b>soalnya</b> busnya <b>nggak datang</b>. <i>(menjawab どうして遅れたんですか)</i>"},{"jp":"すみません、 <ruby>今日<rt>きょう</rt></ruby>は<ruby>早<rt>はや</rt></ruby>く<ruby>帰<rt>かえ</rt></ruby>ります。 <ruby>頭<rt>あたま</rt></ruby>が<ruby>痛<rt>いた</rt></ruby>いんです。","speech":"すみません、今日は早く帰ります。頭が痛いんです。","id":"Maaf, hari ini saya pulang cepat. <b>Soalnya</b> kepala saya <b>sakit</b>. <i>(alasan izin)</i>"},{"jp":"パーティーには<ruby>行<rt>い</rt></ruby>きません。 <ruby>明日<rt>あした</rt></ruby>は<ruby>試験<rt>しけん</rt></ruby>なんです。","speech":"パーティーには行きません。明日は試験なんです。","id":"Aku nggak ikut pesta. <b>Soalnya</b> besok <b>ujian</b>. <i>(KB + なんです)</i>"},{"jp":"ええ、 <ruby>辛<rt>から</rt></ruby>い<ruby>物<rt>もの</rt></ruby>は<ruby>苦手<rt>にがて</rt></ruby>なんです。","speech":"ええ、辛い物は苦手なんです。","id":"Iya, aku <b>nggak kuat</b> makanan pedas. <i>(KS-na + なんです)</i>"}],"dialogs":[{"jp":"ロレンスさんだから <b><ruby>決<rt>き</rt></ruby>めたんです</b>","speech":"ロレンスさんだから決めたんです","id":"Aku <b>memutuskannya</b> justru <b>karena</b> itu kamu, Lawrence-san. <i>(alasan)</i>","source":"狼と香辛料 · EP11 · 19:58"},{"jp":"<ruby>帰<rt>かえ</rt></ruby>り<ruby>際<rt>ぎわ</rt></ruby>に<b>もらったんです</b>","speech":"帰り際にもらったんです","id":"<b>Aku dikasih</b> pas mau pulang. <i>(menjelaskan asal-usul)</i>","source":"ガールズバンドクライ · EP08 · 06:37"},{"jp":"すすす... すいません もう<b><ruby>決<rt>き</rt></ruby>まったんです</b>","speech":"すすす... すいませんもう決まったんです","id":"Ma-ma-maaf, <b>soalnya udah ada</b> yang terpilih. <i>(alasan menolak)</i>","source":"この素晴らしい世界に爆焔を！ · EP10 · 18:30"},{"jp":"すごく いい<ruby>景色<rt>けしき</rt></ruby><b>なんです</b>よ","speech":"すごくいい景色なんですよ","id":"Pemandangannya <b>bagus banget lho</b>. <i>(KB + なんです · penegasan)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 05:45"},{"jp":"フフッ いじめるつもりは <b>なかったんです</b>よ","speech":"フフッいじめるつもりはなかったんですよ","id":"Hehe, aku <b>nggak bermaksud</b> ngerjain kamu kok. <i>(menjelaskan maksud)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP01 · 17:28"}]},{"id":"n4_b26_03","level":"N4","bab":26,"lokasi":"第26課","titleMain":"〜んですが、〜","titleSub":["〜ていただけませんか","〜たらいいですか"],"meaning":"Begini, (sebenarnya)…, (bisakah…?) — pembuka sebelum minta tolong / izin / saran","formula":"[situasi] + <b>んですが</b>、Ｖ-て + <b>いただけませんか</b><br>[situasi] + <b>んですが</b>、どう Ｖ-<b>たら</b> / <b>すれば いいですか</b><br>Kasual: <b>〜んだけど</b>","nuance":"<ol><li>が di sini = <b>pembuka</b> (\"begini…\"), bukan \"tetapi\".</li><li><b>〜ていただけませんか</b> = permintaan sangat sopan; <b>〜たらいいですか</b> = minta saran.</li><li>Kalimat kedua sering <b>dipotong</b>: ちょっとお願いがあるんですが….</li></ol>⚠️ ていただけませんか ＞ てくださいませんか ＞ てください (tingkat sopan).","examples":[{"jp":"<ruby>日本語<rt>にほんご</rt></ruby>で<ruby>手紙<rt>てがみ</rt></ruby>を<ruby>書<rt>か</rt></ruby>いたんですが、ちょっと<ruby>見<rt>み</rt></ruby>ていただけませんか。","speech":"日本語で手紙を書いたんですが、ちょっと見ていただけませんか。","id":"<b>Begini</b>, saya menulis surat dalam bahasa Jepang. <b>Bisakah</b> Anda mengeceknya sebentar? <i>(ていただけませんか)</i>"},{"jp":"<ruby>資料<rt>しりょう</rt></ruby>が<ruby>欲<rt>ほ</rt></ruby>しいんですが、どうすればいいですか。","speech":"資料が欲しいんですが、どうすればいいですか。","id":"Saya <b>mau dapat</b> materinya, <b>sebaiknya bagaimana</b>? <i>(minta saran)</i>"},{"jp":"<ruby>道<rt>みち</rt></ruby>に<ruby>迷<rt>まよ</rt></ruby>ったんですが、 <ruby>駅<rt>えき</rt></ruby>はどこですか。","speech":"道に迷ったんですが、駅はどこですか。","id":"<b>Saya tersesat nih</b>, stasiunnya di mana ya? <i>(pembuka + pertanyaan)</i>"},{"jp":"すみません、ちょっとお<ruby>願<rt>ねが</rt></ruby>いがあるんですが…。","speech":"すみません、ちょっとお願いがあるんですが…。","id":"Permisi, <b>begini</b>, saya ada sedikit permintaan… <i>(kalimat dipotong)</i>"}],"dialogs":[{"jp":"ヤレイに<ruby>会<rt>あ</rt></ruby>いに<b><ruby>来<rt>き</rt></ruby>たんですが</b>　どこにいますか?","speech":"ヤレイに会いに来たんですがどこにいますか?","id":"<b>Begini</b>, aku datang mau ketemu Yarei. Dia di mana ya? <i>(pembuka + pertanyaan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP01 · 05:06"},{"jp":"<ruby>今日<rt>きょう</rt></ruby><ruby>不動産屋<rt>ふどうさんや</rt></ruby>さんでもらう<ruby>予定<rt>よてい</rt></ruby><b>だったんですが</b>","speech":"今日不動産屋さんでもらう予定だったんですが","id":"Rencananya <b>sih</b> hari ini aku ambil (kuncinya) di agen properti… <i>(menjelaskan masalah)</i>","source":"ガールズバンドクライ · EP01 · 05:22"},{"jp":"<ruby>歌詞<rt>かし</rt></ruby> <b><ruby>出来<rt>でき</rt></ruby>たんですけど</b>","speech":"歌詞出来たんですけど","id":"<b>Anu</b>, liriknya <b>udah jadi</b>… <i>(kalimat dipotong)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 20:46"},{"jp":"<ruby>体育祭<rt>たいいくさい</rt></ruby><ruby>関係<rt>かんけい</rt></ruby>の プリント<b>なんですけど</b>","speech":"体育祭関係のプリントなんですけど","id":"<b>Ini</b> lembaran soal festival olahraga… <i>(KB + なんですけど · pembuka)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP11 · 15:22"},{"jp":"<ruby>少<rt>すこ</rt></ruby>し<b><ruby>考<rt>かんが</rt></ruby>えたんですけど</b>","speech":"少し考えたんですけど","id":"<b>Begini</b>, aku sempat mikir sedikit… <i>(membuka topik)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP10 · 16:26"}]},{"id":"n4_b27_01","level":"N4","bab":27,"lokasi":"第27課","titleMain":"可能形","titleSub":["書ける","食べられる","来られる"],"meaning":"Bisa / dapat (melakukan) — kemampuan, atau kemungkinan karena situasi","formula":"Gol.1: -u → <b>-e る</b>（書く→書<b>ける</b> ／ 読む→読<b>める</b>）<br>Gol.2: る → <b>られる</b>（食べ<b>られる</b>） · する → <b>できる</b> · 来る → <b><ruby>来<rt>こ</rt></ruby>られる</b><br>Objek: N <b>が</b> + potensial（漢字<b>が</b>読めます）","nuance":"<ol><li><b>Kemampuan</b>: 漢字が読めます. <b>Kemungkinan situasi</b>: この銀行でドルが換えられます.</li><li>Hasilnya KK golongan 2 baru → 読めない / 読めて / 読めた.</li><li>≈ Ｖる<b>ことができる</b>, tapi lebih ringkas & lisan.</li></ol>⚠️ ら抜き (食べ<b>れる</b> / 来<b>れる</b>) umum di lisan, tapi bentuk baku pakai ら. わかる / できる tidak punya bentuk potensial.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>漢字<rt>かんじ</rt></ruby>が<ruby>読<rt>よ</rt></ruby>めます。","speech":"私は漢字が読めます。","id":"Aku <b>bisa baca</b> kanji. <i>(kemampuan · が)</i>"},{"jp":"<ruby>一人<rt>ひとり</rt></ruby>で<ruby>病院<rt>びょういん</rt></ruby>へ<ruby>行<rt>い</rt></ruby>けますか。","speech":"一人で病院へ行けますか。","id":"<b>Bisa pergi</b> ke rumah sakit sendirian? <i>(Gol.1)</i>"},{"jp":"この<ruby>銀行<rt>ぎんこう</rt></ruby>でドルが<ruby>換<rt>か</rt></ruby>えられます。","speech":"この銀行でドルが換えられます。","id":"Di bank ini dolar <b>bisa ditukar</b>. <i>(Gol.2 · situasi)</i>"},{"jp":"<ruby>忙<rt>いそが</rt></ruby>しいですから、テニスができません。","speech":"忙しいですから、テニスができません。","id":"Karena sibuk, aku <b>nggak bisa</b> main tenis. <i>(する → できる)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>のパーティーに<ruby>来<rt>こ</rt></ruby>られますか。","speech":"明日のパーティーに来られますか。","id":"<b>Bisa datang</b> ke pesta besok? <i>(来る → 来られる)</i>"}],"dialogs":[{"jp":"ギター どのくらい<b><ruby>弾<rt>ひ</rt></ruby>ける?</b>","speech":"ギターどのくらい弾ける?","id":"Gitarnya kamu <b>bisa main</b> sejauh apa? <i>(Gol.1 · kemampuan)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 09:33"},{"jp":"<ruby>失礼<rt>しつれい</rt></ruby>な オムレツは<b><ruby>作<rt>つく</rt></ruby>れる</b>","speech":"失礼なオムレツは作れる","id":"Sembarangan! Omelet sih aku <b>bisa bikin</b>. <i>(Gol.1 · は kontras)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP08 · 17:09"},{"jp":"まだいけるかも... これは<b><ruby>食<rt>た</rt></ruby>べられない</b>よ","speech":"まだいけるかも... これは食べられないよ","id":"Mungkin masih oke… Nggak, ini <b>nggak bisa dimakan</b>! <i>(Gol.2 · られる)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 16:00"},{"jp":"ごめん<ruby>理由<rt>りゆう</rt></ruby>は<b><ruby>言<rt>い</rt></ruby>えない</b>けど　そこには どうしても<b><ruby>行<rt>い</rt></ruby>けない</b>","speech":"ごめん理由は言えないけどそこにはどうしても行けない","id":"Maaf, aku <b>nggak bisa bilang</b> alasannya, tapi ke sana aku bener-bener <b>nggak bisa pergi</b>. <i>(Gol.1 · negatif)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 10:01"},{"jp":"トンカツって うちでも<b><ruby>作<rt>つく</rt></ruby>れる</b>んだね","speech":"トンカツってうちでも作れるんだね","id":"Ternyata tonkatsu <b>bisa dibikin</b> di rumah juga, ya. <i>(kemungkinan)</i>","source":"トニカクカワイイ · EP10 · 02:27"}]},{"id":"n4_b27_02","level":"N4","bab":27,"lokasi":"第27課","titleMain":"見えます ／ 聞こえます","titleSub":["見られます","聞けます"],"meaning":"Kelihatan / kedengaran — masuk ke mata/telinga dengan sendirinya","formula":"N <b>が</b> + <b>見えます</b>（海が見えます）<br>N <b>が</b> + <b>聞こえます</b>（声が聞こえます）<br>vs <b>見られます / 聞けます</b> = bisa menonton / mendengarkan (ada kesempatan)","nuance":"<ol><li><b>見える / 聞こえる</b>: indera, tanpa usaha (窓から海が見えます).</li><li><b>見られる / 聞ける</b>: potensial biasa — ada sarana / kesempatan (ここで映画が見られます).</li></ol>⚠️ ×見え<b>られる</b> / ×聞こえ<b>られる</b>. Objek pakai <b>が</b>.","examples":[{"jp":"<ruby>新<rt>あたら</rt></ruby>しい<ruby>窓<rt>まど</rt></ruby>から<ruby>海<rt>うみ</rt></ruby>が<ruby>見<rt>み</rt></ruby>えます。","speech":"新しい窓から海が見えます。","id":"Dari jendela baru, laut <b>kelihatan</b>. <i>(見える)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>天気<rt>てんき</rt></ruby>がいいから、 <ruby>富士山<rt>ふじさん</rt></ruby>がよく<ruby>見<rt>み</rt></ruby>えます。","speech":"今日は天気がいいから、富士山がよく見えます。","id":"Hari ini cerah, jadi Gunung Fuji <b>kelihatan jelas</b>. <i>(見える)</i>"},{"jp":"ラジオの<ruby>音<rt>おと</rt></ruby>が<ruby>小<rt>ちい</rt></ruby>さくて、よく<ruby>聞<rt>き</rt></ruby>こえません。","speech":"ラジオの音が小さくて、よく聞こえません。","id":"Suara radionya kecil, jadi <b>nggak kedengaran</b> jelas. <i>(聞こえない)</i>"},{"jp":"<ruby>駅<rt>えき</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>で<ruby>新<rt>あたら</rt></ruby>しい<ruby>映画<rt>えいが</rt></ruby>が<ruby>見<rt>み</rt></ruby>られます。","speech":"駅の前で新しい映画が見られます。","id":"Di depan stasiun, film baru <b>bisa ditonton</b>. <i>(見られる · kesempatan)</i>"}],"dialogs":[{"jp":"<ruby>富士山<rt>ふじさん</rt></ruby> よく<b><ruby>見<rt>み</rt></ruby>える</b>ね","speech":"富士山よく見えるね","id":"Gunung Fuji <b>kelihatan</b> jelas, ya. <i>(見える · pemandangan)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 10:22"},{"jp":"おお! よく<b><ruby>見<rt>み</rt></ruby>える</b>のう","speech":"おお! よく見えるのう","id":"Ooh! <b>Kelihatan</b> jelas sekali! <i>(見える)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP16 · 12:06"},{"jp":"<ruby>曇<rt>くも</rt></ruby>ってて<ruby>全然<rt>ぜんぜん</rt></ruby><b><ruby>見<rt>み</rt></ruby>えない</b>んだもん","speech":"曇ってて全然見えないんだもん","id":"Soalnya mendung, jadi sama sekali <b>nggak kelihatan</b>. <i>(見えない)</i>","source":"ゆるキャン△ · EP01 · 17:50"},{"jp":"カズマー! カズマ <b><ruby>聞<rt>き</rt></ruby>こえる?</b>","speech":"カズマー! カズマ聞こえる?","id":"Kazuma! Kazuma, <b>kedengaran</b> nggak? <i>(聞こえる)</i>","source":"この素晴らしい世界に祝福を！2 · EP06 · 18:02"},{"jp":"えッ<ruby>何<rt>なに</rt></ruby>? <b><ruby>聞<rt>き</rt></ruby>こえない</b>んだけど","speech":"えッ何? 聞こえないんだけど","id":"Hah? Apa? <b>Nggak kedengaran</b> nih. <i>(聞こえない)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP03 · 11:44"}]},{"id":"n4_b27_03","level":"N4","bab":27,"lokasi":"第27課","titleMain":"〜しか〜ない","titleSub":["Ｎしか Ｖない","Ｎにしか"],"meaning":"Hanya… / cuma… (saja) — menekankan jumlahnya sedikit / kurang","formula":"N + <b>しか</b> + Ｖ-<b>ない</b>（ひらがなしか書けません）<br>が / を hilang; partikel lain tetap: <b>にしか / でしか / としか</b><br>vs <b>だけ</b> + positif (netral)","nuance":"<ol><li>Selalu dengan <b>negatif</b>, tapi artinya \"hanya\".</li><li>Nuansa <b>kurang / sedikit / sayang</b> (3時間しか寝ませんでした).</li><li>Menggantikan が/を; menempel di belakang に/で/と.</li></ol>⚠️ ×しか + positif. <b>だけ</b> = netral. <b>Ｖるしかない</b> (tak ada pilihan lain) = pola lain.","examples":[{"jp":"ローマ<ruby>字<rt>じ</rt></ruby>しか<ruby>書<rt>か</rt></ruby>けません。","speech":"ローマ字しか書けません。","id":"Aku <b>cuma</b> bisa nulis romaji. <i>(を → しか)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby>は３<ruby>時間<rt>じかん</rt></ruby>しか<ruby>寝<rt>ね</rt></ruby>ませんでした。","speech":"昨日は３時間しか寝ませんでした。","id":"Kemarin aku <b>cuma</b> tidur 3 jam. <i>(kurang)</i>"},{"jp":"<ruby>財布<rt>さいふ</rt></ruby>に100<ruby>円<rt>えん</rt></ruby>しかありません。","speech":"財布に100円しかありません。","id":"Di dompet <b>cuma ada</b> 100 yen. <i>(が → しか)</i>"},{"jp":"このお<ruby>菓子<rt>かし</rt></ruby>は<ruby>日本<rt>にほん</rt></ruby>でしか<ruby>買<rt>か</rt></ruby>えません。","speech":"このお菓子は日本でしか買えません。","id":"Camilan ini <b>cuma bisa</b> dibeli di Jepang. <i>(でしか)</i>"},{"jp":"クラスに<ruby>男<rt>おとこ</rt></ruby>の<ruby>学生<rt>がくせい</rt></ruby>は<ruby>２人<rt>ふたり</rt></ruby>しかいません。","speech":"クラスに男の学生は２人しかいません。","id":"Di kelas, murid laki-laki <b>cuma ada</b> 2 orang. <i>(が → しか)</i>"}],"dialogs":[{"jp":"ふーん 11<ruby>人<rt>にん</rt></ruby><b>しかいない</b>んだね","speech":"ふーん11人しかいないんだね","id":"Hmm, <b>cuma ada</b> 11 orang, ya. <i>(jumlah sedikit)</i>","source":"この素晴らしい世界に爆焔を！ · EP01 · 10:48"},{"jp":"お<ruby>前<rt>まえ</rt></ruby><b>しかいない</b>んだ","speech":"お前しかいないんだ","id":"<b>Cuma</b> kamu <b>yang bisa</b>. <i>(hanya satu)</i>","source":"狼と香辛料 · EP13 · 04:20"},{"jp":"<ruby>君<rt>きみ</rt></ruby>はそういうやり<ruby>方<rt>かた</rt></ruby><b>しか<ruby>知<rt>し</rt></ruby>らない</b>んだと<ruby>分<rt>わ</rt></ruby>かっていたのに...","speech":"君はそういうやり方しか知らないんだと分かっていたのに...","id":"Padahal aku tahu kamu <b>cuma tahu</b> cara begitu… <i>(しか + Ｖない)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP02 · 17:03"},{"jp":"<ruby>好<rt>す</rt></ruby>きな<ruby>人<rt>ひと</rt></ruby>は<ruby>手<rt>て</rt></ruby>のひらに<ruby>収<rt>おさ</rt></ruby>まるくらい<b>しかいない</b>","speech":"好きな人は手のひらに収まるくらいしかいない","id":"Orang yang kusuka <b>cuma</b> segelintir, muat di telapak tangan. <i>(くらいしか)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP10 · 10:53"},{"jp":"ごく<ruby>親<rt>した</rt></ruby>しい<ruby>人<rt>ひと</rt></ruby><b>にしか</b> <b><ruby>知<rt>し</rt></ruby>られてなかった</b> <ruby>真昼<rt>まひる</rt></ruby>の<ruby>素顔<rt>すがお</rt></ruby>が","speech":"ごく親しい人にしか知られてなかった真昼の素顔が","id":"Wajah asli Mahiru yang tadinya <b>cuma</b> diketahui orang yang sangat dekat… <i>(にしか)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP01 · 18:40"}]},{"id":"n4_b28_01","level":"N4","bab":28,"lokasi":"第28課","titleMain":"〜ながら","titleSub":["Ｖ(ます)ながら"],"meaning":"Sambil… — satu orang melakukan dua aktivitas dalam waktu yang sama","formula":"Ｖ-ます (buang ます) + <b>ながら</b>（聞き<b>ながら</b> ／ し<b>ながら</b>）<br>[aksi sampingan]<b>ながら</b>、[aksi UTAMA]","nuance":"<ol><li>Aksi <b>utama di belakang</b>: 音楽を聞きながら<b>食事します</b> (fokus makan).</li><li>Bisa periode panjang: 働きながら大学で勉強しています.</li></ol>⚠️ Subjek kedua aksi <b>harus sama</b> (subjek beda → 〜ている間). 〜ながら \"walaupun\" (知っていながら) = pemakaian lanjut.","examples":[{"jp":"<ruby>音楽<rt>おんがく</rt></ruby>を<ruby>聞<rt>き</rt></ruby>きながら <ruby>食事<rt>しょくじ</rt></ruby>します。","speech":"音楽を聞きながら食事します。","id":"Aku makan <b>sambil</b> dengar musik. <i>(aksi utama: makan)</i>"},{"jp":"<ruby>働<rt>はたら</rt></ruby>きながら <ruby>大学<rt>だいがく</rt></ruby>で<ruby>勉強<rt>べんきょう</rt></ruby>しています。","speech":"働きながら大学で勉強しています。","id":"Aku kuliah <b>sambil</b> bekerja. <i>(periode panjang)</i>"},{"jp":"<ruby>歩<rt>ある</rt></ruby>きながらスマホを<ruby>見<rt>み</rt></ruby>ないでください。","speech":"歩きながらスマホを見ないでください。","id":"Tolong jangan main HP <b>sambil</b> jalan. <i>(larangan)</i>"},{"jp":"コーヒーを<ruby>飲<rt>の</rt></ruby>みながら <ruby>話<rt>はな</rt></ruby>しましょう。","speech":"コーヒーを飲みながら話しましょう。","id":"Ayo ngobrol <b>sambil</b> minum kopi. <i>(ajakan)</i>"}],"dialogs":[{"jp":"<ruby>本<rt>ほん</rt></ruby>を<b><ruby>読<rt>よ</rt></ruby>みながら</b> <ruby>食<rt>た</rt></ruby>べるな","speech":"本を読みながら食べるな","id":"Jangan makan <b>sambil</b> baca buku. <i>(larangan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP25 · 14:52"},{"jp":"<ruby>優美子<rt>ゆみこ</rt></ruby> もう1<ruby>曲<rt>きょく</rt></ruby> <b><ruby>弾<rt>ひ</rt></ruby>きながら</b> <ruby>歌<rt>うた</rt></ruby>える?","speech":"優美子もう1曲弾きながら歌える?","id":"Yumiko, bisa nyanyi <b>sambil</b> main satu lagu lagi? <i>(dua aksi bersamaan)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP12 · 04:53"},{"jp":"<ruby>食事<rt>しょくじ</rt></ruby><b>しながら</b> <ruby>決<rt>き</rt></ruby>めようって<ruby>言<rt>い</rt></ruby>って それっきり","speech":"食事しながら決めようって言ってそれっきり","id":"Katanya mau diputusin <b>sambil</b> makan, tapi habis itu nggak ada kabar. <i>(しながら)</i>","source":"ガールズバンドクライ · EP07 · 19:58"},{"jp":"モジモジ<b>しながら</b> <ruby>言<rt>い</rt></ruby>うな!","speech":"モジモジしながら言うな!","id":"Jangan ngomong <b>sambil</b> malu-malu gitu! <i>(cara melakukan)</i>","source":"この素晴らしい世界に祝福を！ · EP06 · 00:50"},{"jp":"<ruby>修道院<rt>しゅうどういん</rt></ruby><ruby>併設<rt>へいせつ</rt></ruby>の<ruby>貧民<rt>ひんみん</rt></ruby><ruby>救済院<rt>きゅうさいいん</rt></ruby>で　お<ruby>手伝<rt>てつだ</rt></ruby>いを<b>しながら</b> <ruby>住<rt>す</rt></ruby>まわせてもらっていました","speech":"修道院併設の貧民救済院でお手伝いをしながら住まわせてもらっていました","id":"Saya tinggal di rumah penampungan orang miskin di biara, <b>sambil</b> bantu-bantu di sana. <i>(periode panjang)</i>","source":"狼と香辛料 · EP09 · 07:10"}]},{"id":"n4_b28_02","level":"N4","bab":28,"lokasi":"第28課","titleMain":"Ｖています","titleSub":["毎朝〜ています","〜で働いています"],"meaning":"(Rutin / biasanya) melakukan… — kebiasaan, pekerjaan, aktivitas jangka panjang","formula":"[毎日 / いつも / 週に〜回] + Ｖ-て + <b>います</b><br>Pekerjaan: 〜で<b>働いています</b> · 〜に<b>通っています</b><br>Kebiasaan dulu: Ｖ-て + <b>いました</b>","nuance":"<ol><li>Selain \"sedang\" & \"keadaan\", ている juga = <b>kebiasaan</b>.</li><li>Sering dengan kata frekuensi: 毎朝, いつも, よく, 週に2回.</li><li>Kebiasaan masa lalu → <b>〜ていました</b>.</li></ol>⚠️ 〜ます juga bisa untuk kebiasaan umum; 〜ています menekankan rutinitas yang sedang dijalani periode ini.","examples":[{"jp":"<ruby>毎朝<rt>まいあさ</rt></ruby>ジョギングをしています。","speech":"毎朝ジョギングをしています。","id":"<b>Tiap pagi</b> aku <b>rutin</b> jogging. <i>(kebiasaan)</i>"},{"jp":"<ruby>週<rt>しゅう</rt></ruby>に２<ruby>回<rt>かい</rt></ruby>、 <ruby>日本語<rt>にほんご</rt></ruby>を<ruby>習<rt>なら</rt></ruby>っています。","speech":"週に２回、日本語を習っています。","id":"<b>Seminggu dua kali</b> aku belajar bahasa Jepang. <i>(frekuensi)</i>"},{"jp":"<ruby>兄<rt>あに</rt></ruby>は<ruby>銀行<rt>ぎんこう</rt></ruby>で<ruby>働<rt>はたら</rt></ruby>いています。","speech":"兄は銀行で働いています。","id":"Kakak laki-lakiku <b>kerja</b> di bank. <i>(pekerjaan)</i>"},{"jp":"<ruby>子供<rt>こども</rt></ruby>のとき、 <ruby>毎晩<rt>まいばん</rt></ruby>８<ruby>時<rt>じ</rt></ruby>に<ruby>寝<rt>ね</rt></ruby>ていました。","speech":"子供のとき、毎晩８時に寝ていました。","id":"Waktu kecil, aku <b>dulu biasa</b> tidur jam 8 tiap malam. <i>(kebiasaan dulu)</i>"}],"dialogs":[{"jp":"これを<ruby>毎日<rt>まいにち</rt></ruby><ruby>欠<rt>か</rt></ruby>かさず<b><ruby>続<rt>つづ</rt></ruby>けている</b>っす","speech":"これを毎日欠かさず続けているっす","id":"Ini aku <b>lakuin terus</b> tiap hari tanpa absen. <i>(毎日 · kebiasaan)</i>","source":"トニカクカワイイ · EP10 · 11:31"},{"jp":"いつもどんなこと<b>してる</b>の?","speech":"いつもどんなことしてるの?","id":"Kalian <b>biasanya ngapain</b> aja? <i>(いつも · rutinitas)</i>","source":"ゆるキャン△ · EP02 · 06:18"},{"jp":"<ruby>毎晩<rt>まいばん</rt></ruby> <b><ruby>踊<rt>おど</rt></ruby>り<ruby>狂<rt>くる</rt></ruby>ってる</b>んですよね?","speech":"毎晩踊り狂ってるんですよね?","id":"Kamu <b>tiap malam joget</b> gila-gilaan, kan? <i>(毎晩 · kebiasaan)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 19:07"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>毎日<rt>まいにち</rt></ruby> この<ruby>酒場<rt>さかば</rt></ruby>で<ruby>1人<rt>ひとり</rt></ruby>で<b><ruby>過<rt>す</rt></ruby>ごしてる</b>んだし","speech":"毎日毎日この酒場で1人で過ごしてるんだし","id":"Dia <b>tiap hari</b> nongkrong sendirian di bar ini, kok. <i>(毎日 · kebiasaan)</i>","source":"この素晴らしい世界に爆焔を！ · EP10 · 20:09"},{"jp":"それでも いつも<b><ruby>頑張<rt>がんば</rt></ruby>ってる</b>し","speech":"それでもいつも頑張ってるし","id":"Tapi tetap aja kamu <b>selalu berusaha keras</b>. <i>(いつも)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP03 · 12:16"}]},{"id":"n4_b28_03","level":"N4","bab":28,"lokasi":"第28課","titleMain":"〜し、〜し","titleSub":["〜だし","〜も〜し"],"meaning":"Udah…, … juga, (jadi)… — mendaftar beberapa alasan / ciri sekaligus","formula":"Ｖ / KS-i (普通形) + <b>し</b>（安い<b>し</b>）<br>KS-na / KB + <b>だ</b> + <b>し</b>（暇<b>だし</b> ／ 雨<b>だし</b>）<br>〜し、〜し、[kesimpulan]","nuance":"<ol><li><b>Mendaftar alasan</b>: 安いし、おいしいし、いつも客が多い.</li><li><b>Mendaftar ciri</b>: 熱心だし、まじめだし、いい先生.</li><li>Satu し pun menyiratkan \"masih ada alasan lain\" (もう遅いし、帰ろう).</li></ol>⚠️ ×雨し → 雨<b>だ</b>し. <b>から</b> = satu alasan langsung; <b>し</b> = beberapa, lebih lembut. Sering pakai <b>も</b>.","examples":[{"jp":"あの<ruby>店<rt>みせ</rt></ruby>は<ruby>安<rt>やす</rt></ruby>いし、おいしいし、いつも<ruby>客<rt>きゃく</rt></ruby>が<ruby>多<rt>おお</rt></ruby>いです。","speech":"あの店は安いし、おいしいし、いつも客が多いです。","id":"Toko itu <b>udah murah, enak pula</b>, jadi selalu ramai. <i>(alasan)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>雨<rt>あめ</rt></ruby>だし、お<ruby>金<rt>かね</rt></ruby>もないし、 <ruby>出<rt>で</rt></ruby>かけません。","speech":"今日は雨だし、お金もないし、出かけません。","id":"Hari ini <b>hujan, uang juga nggak ada</b>, jadi aku nggak keluar. <i>(KB だし)</i>"},{"jp":"ミラーさんは<ruby>熱心<rt>ねっしん</rt></ruby>だし、まじめだし、いい<ruby>先生<rt>せんせい</rt></ruby>です。","speech":"ミラーさんは熱心だし、まじめだし、いい先生です。","id":"Miller-san <b>rajin, serius pula</b>, pokoknya guru yang baik. <i>(ciri)</i>"},{"jp":"この<ruby>部屋<rt>へや</rt></ruby>は<ruby>駅<rt>えき</rt></ruby>にも<ruby>近<rt>ちか</rt></ruby>いし、<ruby>広<rt>ひろ</rt></ruby>いし、 <ruby>気<rt>き</rt></ruby>に<ruby>入<rt>い</rt></ruby>っています。","speech":"この部屋は駅にも近いし、広いし、気に入っています。","id":"Kamar ini <b>dekat stasiun, luas juga</b>, jadi aku suka. <i>(も〜し)</i>"},{"jp":"もう<ruby>遅<rt>おそ</rt></ruby>いし、 <ruby>帰<rt>かえ</rt></ruby>ろうか。","speech":"もう遅いし、帰ろうか。","id":"<b>Udah malam juga</b>, pulang yuk. <i>(alasan lain tersirat)</i>"}],"dialogs":[{"jp":"<ruby>先輩<rt>せんぱい</rt></ruby>も<b><ruby>優<rt>やさ</rt></ruby>しいし</b> <ruby>接客<rt>せっきゃく</rt></ruby><ruby>楽<rt>たの</rt></ruby>しいよ","speech":"先輩も優しいし接客楽しいよ","id":"Senior-seniornya <b>baik juga</b>, ngelayanin tamu juga seru. <i>(も〜し · alasan)</i>","source":"ゆるキャン△ SEASON２ · EP06 · 23:05"},{"jp":"<ruby>特<rt>とく</rt></ruby>には...　 <ruby>年齢層<rt>ねんれいそう</rt></ruby>が<ruby>高<rt>たか</rt></ruby>くて<ruby>落<rt>お</rt></ruby>ち<ruby>着<rt>つ</rt></ruby>いてるお<ruby>客<rt>きゃく</rt></ruby>さんが<b><ruby>多<rt>おお</rt></ruby>いし</b>　 <ruby>先輩<rt>せんぱい</rt></ruby>たちも<b><ruby>優<rt>やさ</rt></ruby>しいし</b>な","speech":"特には...　年齢層が高くて落ち着いてるお客さんが多いし先輩たちも優しいしな","id":"Nggak juga… Pelanggannya kebanyakan orang dewasa yang kalem, <b>senior-seniornya juga baik</b>. <i>(〜し、〜し)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP12 · 08:43"},{"jp":"<ruby>顔<rt>かお</rt></ruby>だち<b><ruby>整<rt>ととの</rt></ruby>ってるし</b> すごく<ruby>肌<rt>はだ</rt></ruby><ruby>白<rt>しろ</rt></ruby>くて <b>きれいだし</b>","speech":"顔だち整ってるしすごく肌白くてきれいだし","id":"Wajahnya <b>rapi</b>, kulitnya putih, <b>cantik pula</b>. <i>(mendaftar ciri · だし)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP04 · 03:45"},{"jp":"<b><ruby>寒<rt>さむ</rt></ruby>いし</b> <ruby>絶対<rt>ぜったい</rt></ruby><ruby>変<rt>か</rt></ruby>えるからー!","speech":"寒いし絶対変えるからー!","id":"<b>Udah garing gitu</b>, pokoknya bakal kuganti! <i>(alasan)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 19:42"},{"jp":"<b>せっかくだし</b> もっと<ruby>派手<rt>はで</rt></ruby>なことしたいよね","speech":"せっかくだしもっと派手なことしたいよね","id":"<b>Mumpung ada kesempatan</b>, pengin bikin sesuatu yang lebih heboh, ya. <i>(だし · alasan tersirat)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP06 · 18:05"}]},{"id":"n4_b29_01","level":"N4","bab":29,"lokasi":"第29課","titleMain":"自動詞＋ています","titleSub":["Ｎが 開いています","壊れています"],"meaning":"(Dalam keadaan) sudah ter-… — keadaan sekarang hasil perubahan sebelumnya","formula":"N <b>が</b> + 自動詞-て + <b>います</b>（窓が閉まっています）<br>Topik / kontras: N <b>は</b>（この椅子は壊れています）<br>開く・閉まる・つく・消える・壊れる・破れる・落ちる・込む","nuance":"<ol><li>自動詞 = perubahan pada benda tanpa menyebut pelaku (ドアが開く).</li><li>+ ています = perubahan <b>sudah terjadi</b>, hasilnya <b>masih bertahan</b>.</li><li>Cara natural mendeskripsikan yang terlihat: 電気がついています.</li></ol>⚠️ Bukan \"sedang menutup\" — tapi \"sudah tertutup\". Sengaja dilakukan orang → <b>他動詞＋てあります</b> (Bab 30).","examples":[{"jp":"<ruby>窓<rt>まど</rt></ruby>が<ruby>閉<rt>し</rt></ruby>まっています。","speech":"窓が閉まっています。","id":"Jendelanya <b>(dalam keadaan) tertutup</b>. <i>(閉まる)</i>"},{"jp":"<ruby>電気<rt>でんき</rt></ruby>がついています。","speech":"電気がついています。","id":"Lampunya <b>menyala</b>. <i>(つく)</i>"},{"jp":"この<ruby>椅子<rt>いす</rt></ruby>は<ruby>壊<rt>こわ</rt></ruby>れています。","speech":"この椅子は壊れています。","id":"Kursi ini <b>rusak</b>. <i>(壊れる · topik は)</i>"},{"jp":"<ruby>袋<rt>ふくろ</rt></ruby>が<ruby>破<rt>やぶ</rt></ruby>れています。","speech":"袋が破れています。","id":"Kantongnya <b>sobek</b>. <i>(破れる)</i>"},{"jp":"あそこに<ruby>財布<rt>さいふ</rt></ruby>が<ruby>落<rt>お</rt></ruby>ちていますよ。","speech":"あそこに財布が落ちていますよ。","id":"Di sana ada dompet <b>jatuh</b>, lho. <i>(落ちる)</i>"}],"dialogs":[{"jp":"<b><ruby>開<rt>あ</rt></ruby>いています</b>ので どうぞ","speech":"開いていますのでどうぞ","id":"(Pintunya) <b>nggak dikunci</b>, silakan masuk. <i>(開く → terbuka)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 08:22"},{"jp":"あー<ruby>冬<rt>ふゆ</rt></ruby>は<b><ruby>閉<rt>し</rt></ruby>まってる</b>んだって","speech":"あー冬は閉まってるんだって","id":"Ah, katanya kalau musim dingin <b>tutup</b>. <i>(閉まる → tertutup)</i>","source":"ゆるキャン△ · EP10 · 13:10"},{"jp":"<ruby>火<rt>ひ</rt></ruby>が<b><ruby>消<rt>き</rt></ruby>えてる</b>","speech":"火が消えてる","id":"Apinya <b>(udah) padam</b>. <i>(消える → padam)</i>","source":"ゆるキャン△ · EP07 · 08:19"},{"jp":"それ <b><ruby>壊<rt>こわ</rt></ruby>れてる</b>んじゃないの?","speech":"それ壊れてるんじゃないの?","id":"Itu jangan-jangan <b>rusak</b>? <i>(壊れる → rusak)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP09 · 02:19"},{"jp":"ポスト<b><ruby>壊<rt>こわ</rt></ruby>れてる</b>んで　お<ruby>願<rt>ねが</rt></ruby>いします","speech":"ポスト壊れてるんでお願いします","id":"Kotak posnya <b>rusak</b>, jadi tolong ya. <i>(keadaan · alasan)</i>","source":"ガールズバンドクライ · EP09 · 03:20"}]},{"id":"n4_b29_02","level":"N4","bab":29,"lokasi":"第29課","titleMain":"〜てしまいます","titleSub":["全部〜てしまいました","〜てしまいましょう"],"meaning":"Menyelesaikan (sampai habis / tuntas)… — aksi selesai sepenuhnya","formula":"Ｖ-て + <b>しまいました</b>（全部食べてしまいました）<br>Ｖ-て + <b>しまいます / しまいましょう</b>（今晩書いてしまいます）<br>Kasual: <b>〜ちゃう / 〜じゃう</b>（食べちゃった ／ 読んじゃう）","nuance":"<ol><li><b>Sudah tuntas</b>: sering dengan 全部 / もう.</li><li><b>Akan dituntaskan</b>: 宿題は今日中にやってしまいます.</li><li><b>Ajakan</b>: 先に片付けてしまいましょう.</li></ol>⚠️ Fungsi ini <b>netral</b> (beres), bukan menyesal — bedakan dari konteks.","examples":[{"jp":"ワインは<ruby>全部<rt>ぜんぶ</rt></ruby><ruby>飲<rt>の</rt></ruby>んでしまいました。","speech":"ワインは全部飲んでしまいました。","id":"Wine-nya sudah <b>habis</b> kami minum. <i>(tuntas)</i>"},{"jp":"この<ruby>本<rt>ほん</rt></ruby>はもう<ruby>読<rt>よ</rt></ruby>んでしまいました。","speech":"この本はもう読んでしまいました。","id":"Buku ini sudah <b>selesai</b> kubaca. <i>(もう · tuntas)</i>"},{"jp":"レポートは<ruby>今晩<rt>こんばん</rt></ruby><ruby>書<rt>か</rt></ruby>いてしまいます。","speech":"レポートは今晩書いてしまいます。","id":"Laporannya akan <b>kuselesaikan</b> malam ini. <i>(rencana)</i>"},{"jp":"<ruby>昼<rt>ひる</rt></ruby>ご<ruby>飯<rt>はん</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>に、この<ruby>仕事<rt>しごと</rt></ruby>をやってしまいましょう。","speech":"昼ご飯の前に、この仕事をやってしまいましょう。","id":"Sebelum makan siang, ayo <b>beresin</b> pekerjaan ini. <i>(ajakan)</i>"}],"dialogs":[{"jp":"<ruby>全部<rt>ぜんぶ</rt></ruby> <b><ruby>食<rt>た</rt></ruby>べちゃった</b>","speech":"全部食べちゃった","id":"<b>Udah kuhabisin</b> semua. <i>(全部 · tuntas)</i>","source":"ゆるキャン△ · EP08 · 20:56"},{"jp":"お<ruby>姉<rt>ねえ</rt></ruby>ちゃん<ruby>全部<rt>ぜんぶ</rt></ruby><b><ruby>食<rt>た</rt></ruby>べちゃった</b>","speech":"お姉ちゃん全部食べちゃった","id":"Kakak <b>udah ngabisin</b> semuanya. <i>(全部 · tuntas)</i>","source":"時をかける少女 · EP01 · 45:22"},{"jp":"えっ もう? <ruby>全部<rt>ぜんぶ</rt></ruby><b><ruby>食<rt>た</rt></ruby>べちゃう</b>よ?","speech":"えっもう? 全部食べちゃうよ?","id":"Eh, udahan? Aku <b>habisin semua</b> ya? <i>(akan dituntaskan)</i>","source":"俺だけレベルアップな件 · EP07 · 04:22"},{"jp":"<ruby>文化祭<rt>ぶんかさい</rt></ruby>のセトリ <b><ruby>決<rt>き</rt></ruby>めちゃおう!</b>","speech":"文化祭のセトリ決めちゃおう!","id":"Ayo <b>langsung putusin</b> setlist buat festival sekolah! <i>(ajakan · ちゃおう)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 18:58"}]},{"id":"n4_b29_03","level":"N4","bab":29,"lokasi":"第29課","titleMain":"〜てしまいました","titleSub":["〜ちゃった","〜じゃった"],"meaning":"Yah, (malah)… / tanpa sengaja… / sayangnya… — kejadian yang disesali","formula":"Ｖ-て + <b>しまいました</b>（なくしてしまいました）<br>Kasual: 〜て → <b>〜ちゃった</b> ／ 〜で → <b>〜じゃった</b>","nuance":"<ol><li><b>Penyesalan</b>: パスポートをなくしてしまいました.</li><li><b>Tidak sengaja / di luar kendali</b>: 寝坊してしまいました.</li><li>Lisan hampir selalu <b>ちゃった / じゃった</b>.</li></ol>⚠️ なくしました = fakta; なくし<b>てしまいました</b> = \"yah, hilang\" (ada rasa sesal).","examples":[{"jp":"パスポートをなくしてしまいました。","speech":"パスポートをなくしてしまいました。","id":"<b>Yah</b>, paspor saya <b>hilang</b>. <i>(menyesal)</i>"},{"jp":"<ruby>電車<rt>でんしゃ</rt></ruby>に<ruby>傘<rt>かさ</rt></ruby>を<ruby>忘<rt>わす</rt></ruby>れてしまいました。","speech":"電車に傘を忘れてしまいました。","id":"Payungku <b>ketinggalan</b> di kereta. <i>(tidak sengaja)</i>"},{"jp":"パソコンが<ruby>故障<rt>こしょう</rt></ruby>してしまいました。","speech":"パソコンが故障してしまいました。","id":"<b>Sayangnya</b> PC-ku <b>rusak</b>. <i>(di luar kendali)</i>"},{"jp":"<ruby>寝坊<rt>ねぼう</rt></ruby>しちゃった！ <ruby>遅刻<rt>ちこく</rt></ruby>だ！","speech":"寝坊しちゃった！遅刻だ！","id":"<b>Aduh, kesiangan!</b> Telat nih! <i>(kasual · ちゃった)</i>"}],"dialogs":[{"jp":"お<ruby>父<rt>とう</rt></ruby>さんから<ruby>借<rt>か</rt></ruby>りたギター　ライブで<b><ruby>壊<rt>こわ</rt></ruby>してしまいました</b>","speech":"お父さんから借りたギターライブで壊してしまいました","id":"Gitar yang kupinjam dari ayah <b>malah rusak</b> pas live… <i>(menyesal · sopan)</i>","source":"ぼっち・ざ・ろっく！ · EP12 · 11:10"},{"jp":"すき<ruby>焼<rt>や</rt></ruby>きに<ruby>合<rt>あ</rt></ruby>う<ruby>日本酒<rt>にほんしゅ</rt></ruby> <b><ruby>忘<rt>わす</rt></ruby>れちゃった</b>","speech":"すき焼きに合う日本酒忘れちゃった","id":"Yah, sake yang cocok buat sukiyaki <b>ketinggalan</b>. <i>(tidak sengaja · ちゃった)</i>","source":"ゆるキャン△ · EP11 · 16:59"},{"jp":"しまった バスの<ruby>中<rt>なか</rt></ruby>だ <b><ruby>忘<rt>わす</rt></ruby>れてきちゃった</b>","speech":"しまったバスの中だ忘れてきちゃった","id":"Gawat, di bus! <b>Ketinggalan</b>! <i>(しまった! · ちゃった)</i>","source":"トニカクカワイイ · EP07 · 02:29"},{"jp":"<ruby>小町<rt>こまち</rt></ruby>ったらお<ruby>守<rt>まも</rt></ruby>りを<b><ruby>買<rt>か</rt></ruby>い<ruby>忘<rt>わす</rt></ruby>れてしまいました</b>","speech":"小町ったらお守りを買い忘れてしまいました","id":"Duh, Komachi <b>lupa beli</b> jimatnya. <i>(menyesal)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP10 · 16:26"},{"jp":"ハッ... <b><ruby>寝坊<rt>ねぼう</rt></ruby>しちゃった</b>","speech":"ハッ... 寝坊しちゃった","id":"Hah… <b>Aduh, kesiangan</b>. <i>(tidak sengaja)</i>","source":"藤本タツキ 17-26 · EP01 · 01:00"}]},{"id":"n4_b30_01","level":"N4","bab":30,"lokasi":"第30課","titleMain":"〜てあります","titleSub":["Ｎが 他動詞てある","〜と書いてある"],"meaning":"Sudah di-… (sengaja, oleh seseorang) — keadaan hasil tindakan yang punya tujuan","formula":"[Tempat] に N <b>が</b> 他動詞-て + <b>あります</b>（壁にカレンダーが掛けてあります）<br>N <b>は</b> もう Ｖ-て + <b>あります</b>（切符はもう買ってあります）<br>〜と<b>書いてあります</b>","nuance":"<ol><li>Hanya <b>他動詞</b>; objek を → <b>が</b> (deskripsi) / <b>は</b> (topik).</li><li>Ada pelaku & <b>tujuan</b> di baliknya, tapi pelaku tidak disebut.</li><li>Sering untuk persiapan: ホテルはもう予約してあります.</li></ol>⚠️ 窓が<b>開いています</b> (keadaan saja) vs 窓が<b>開けてあります</b> (sengaja dibuka). ×開いてあります.","examples":[{"jp":"<ruby>壁<rt>かべ</rt></ruby>にカレンダーが<ruby>掛<rt>か</rt></ruby>けてあります。","speech":"壁にカレンダーが掛けてあります。","id":"Di dinding <b>sudah terpasang</b> kalender. <i>(deskripsi · が)</i>"},{"jp":"<ruby>交番<rt>こうばん</rt></ruby>に<ruby>町<rt>まち</rt></ruby>の<ruby>地図<rt>ちず</rt></ruby>が<ruby>貼<rt>は</rt></ruby>ってあります。","speech":"交番に町の地図が貼ってあります。","id":"Di pos polisi <b>tertempel</b> peta kota. <i>(deskripsi)</i>"},{"jp":"メモは<ruby>机<rt>つくえ</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>に<ruby>置<rt>お</rt></ruby>いてあります。","speech":"メモは机の上に置いてあります。","id":"Memonya <b>sudah ditaruh</b> di atas meja. <i>(topik は)</i>"},{"jp":"ホテルはもう<ruby>予約<rt>よやく</rt></ruby>してあります。","speech":"ホテルはもう予約してあります。","id":"Hotelnya <b>sudah dipesan</b>. <i>(persiapan)</i>"},{"jp":"ここに「 <ruby>禁煙<rt>きんえん</rt></ruby>」と<ruby>書<rt>か</rt></ruby>いてあります。","speech":"ここに「禁煙」と書いてあります。","id":"Di sini <b>tertulis</b> \"dilarang merokok\". <i>(と書いてある)</i>"}],"dialogs":[{"jp":"それ<ruby>名前<rt>なまえ</rt></ruby><b><ruby>書<rt>か</rt></ruby>いてあります</b>よね","speech":"それ名前書いてありますよね","id":"Itu <b>ada</b> namaku <b>tertulis</b>, kan? <i>(書いてある)</i>","source":"ガールズバンドクライ · EP02 · 00:48"},{"jp":"まあいいか<ruby>裏<rt>うら</rt></ruby>に<ruby>作<rt>つく</rt></ruby>り<ruby>方<rt>かた</rt></ruby> <b><ruby>書<rt>か</rt></ruby>いてある</b>し","speech":"まあいいか裏に作り方書いてあるし","id":"Ya sudahlah, di belakangnya <b>ada tulisan</b> cara bikinnya. <i>(書いてある)</i>","source":"ゆるキャン△ · EP09 · 11:24"},{"jp":"<ruby>机<rt>つくえ</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>に<b><ruby>置<rt>お</rt></ruby>いてある</b> <ruby>写真<rt>しゃしん</rt></ruby><ruby>立<rt>た</rt></ruby>てには","speech":"机の上に置いてある写真立てには","id":"Bingkai foto yang <b>ditaruh</b> di atas meja itu… <i>(置いてある)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 18:51"},{"jp":"あと そっちの お<ruby>札<rt>ふだ</rt></ruby>とかは　お<ruby>姉<rt>ねえ</rt></ruby>ちゃんが この<ruby>前<rt>まえ</rt></ruby> お<ruby>化<rt>ば</rt></ruby>けに<ruby>取<rt>と</rt></ruby>りつかれたから　<b><ruby>貼<rt>は</rt></ruby>ってある</b>んだ","speech":"あとそっちのお札とかはお姉ちゃんがこの前お化けに取りつかれたから貼ってあるんだ","id":"Terus jimat-jimat di sana itu <b>sengaja ditempel</b> karena kakak kemarin kerasukan hantu. <i>(tujuan jelas)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 06:42"},{"jp":"<ruby>着替<rt>きが</rt></ruby>えは<b><ruby>用意<rt>ようい</rt></ruby>してある</b>","speech":"着替えは用意してある","id":"Baju gantinya <b>sudah disiapkan</b>. <i>(persiapan)</i>","source":"Re:ゼロから始める異世界生活 3rd season · EP05 · 01:22"}]},{"id":"n4_b30_02","level":"N4","bab":30,"lokasi":"第30課","titleMain":"〜ておきます","titleSub":["〜前に〜ておく","〜とく"],"meaning":"… dulu (persiapan) / … (sesudahnya) dibereskan","formula":"Ｖ-て + <b>おきます</b>（切符を買っておきます）<br>Beres-beres: Ｖ-て + <b>おいてください</b>（片付けておいてください）<br>Kasual: 〜て<b>おく</b> → <b>〜とく</b> · 〜で<b>おく</b> → <b>〜どく</b>","nuance":"<ol><li><b>Persiapan</b> untuk masa depan: 旅行の前に切符を買っておく.</li><li><b>Beres-beres</b> sesudah memakai: 使ったはさみは戻しておいてください.</li><li>おく berkonjugasi Gol.1: おきます / おいて / おいた.</li></ol>⚠️ <b>ておく</b> = tindakan menyiapkan; <b>てある</b> = keadaan sudah siap (買っておきました → 買ってあります).","examples":[{"jp":"<ruby>旅行<rt>りょこう</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>に、 <ruby>切符<rt>きっぷ</rt></ruby>を<ruby>買<rt>か</rt></ruby>っておきます。","speech":"旅行の前に、切符を買っておきます。","id":"Sebelum trip, aku <b>beli</b> tiket <b>dulu</b>. <i>(persiapan)</i>"},{"jp":"<ruby>次<rt>つぎ</rt></ruby>の<ruby>会議<rt>かいぎ</rt></ruby>までに<ruby>何<rt>なに</rt></ruby>をしておいたらいいですか。","speech":"次の会議までに何をしておいたらいいですか。","id":"Sebelum rapat berikutnya, sebaiknya <b>siapkan apa dulu</b>? <i>(persiapan)</i>"},{"jp":"パーティーの<ruby>前<rt>まえ</rt></ruby>に、 <ruby>飲<rt>の</rt></ruby>み<ruby>物<rt>もの</rt></ruby>を<ruby>冷<rt>ひ</rt></ruby>やしておきます。","speech":"パーティーの前に、飲み物を冷やしておきます。","id":"Sebelum pesta, minumannya <b>didinginkan dulu</b>. <i>(persiapan)</i>"},{"jp":"<ruby>道具<rt>どうぐ</rt></ruby>を<ruby>片付<rt>かたづ</rt></ruby>けておいてください。","speech":"道具を片付けておいてください。","id":"Tolong peralatannya <b>dibereskan</b>. <i>(beres-beres)</i>"},{"jp":"<ruby>使<rt>つか</rt></ruby>ったはさみは<ruby>元<rt>もと</rt></ruby>の<ruby>所<rt>ところ</rt></ruby>に<ruby>戻<rt>もど</rt></ruby>しておいてください。","speech":"使ったはさみは元の所に戻しておいてください。","id":"Gunting yang sudah dipakai tolong <b>dikembalikan</b> ke tempat semula. <i>(beres-beres)</i>"}],"dialogs":[{"jp":"<ruby>俺<rt>おれ</rt></ruby>も<ruby>今<rt>いま</rt></ruby>のうちに<b><ruby>買<rt>か</rt></ruby>っておく</b>か","speech":"俺も今のうちに買っておくか","id":"Aku juga <b>beli dulu</b> mumpung sekarang, ah. <i>(persiapan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP19 · 01:04"},{"jp":"ほら ローストビーフのおいしい<ruby>店<rt>みせ</rt></ruby> <b><ruby>予約<rt>よやく</rt></ruby>しておいた</b>よ","speech":"ほらローストビーフのおいしい店予約しておいたよ","id":"Nih, aku <b>udah pesan duluan</b> restoran roast beef yang enak. <i>(persiapan · sudah)</i>","source":"斉木楠雄のΨ難 · EP21 · 11:43"},{"jp":"その<ruby>間<rt>あいだ</rt></ruby>に<ruby>私<rt>わたし</rt></ruby>は いちごを<b><ruby>準備<rt>じゅんび</rt></ruby>しておく</b>わ。","speech":"その間に私はいちごを準備しておくわ。","id":"Sementara itu aku <b>siapin</b> stroberinya <b>dulu</b>. <i>(persiapan)</i>","source":"上伊那ぼたん、酔へる姿は百合の花 · EP05 · 11:39"},{"jp":"というわけで<ruby>細<rt>こま</rt></ruby>かいとこは<b>やっとく</b>ので","speech":"というわけで細かいとこはやっとくので","id":"Jadi, urusan detailnya <b>biar kami beresin</b>. <i>(kasual とく)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP12 · 11:17"},{"jp":"<ruby>食<rt>た</rt></ruby>べたら<b><ruby>片付<rt>かたづ</rt></ruby>けておいて</b> <ruby>下<rt>くだ</rt></ruby>さいね","speech":"食べたら片付けておいて下さいね","id":"Habis makan, tolong <b>dibereskan</b> ya. <i>(beres-beres sesudahnya)</i>","source":"Summer Pockets · EP02 · 11:21"}]},{"id":"n4_b30_03","level":"N4","bab":30,"lokasi":"第30課","titleMain":"〜ておきます","titleSub":["そのままにしておく","ほっとく"],"meaning":"Biarkan saja… / tetap di-… / simpan… — mempertahankan keadaan","formula":"<b>そのままにしておきます</b>（biarkan apa adanya）<br>開けて / つけて + <b>おきます</b>（biarkan terbuka / menyala）<br><b>取っておく</b> = simpan · <b>放っておく / ほっとく</b> = biarkan","nuance":"<ol><li><b>Membiarkan keadaan</b>: まだ使っていますから、そのままにしておいてください.</li><li><b>Simpan untuk nanti</b>: 取っておいたお酒.</li><li><b>ほっといて</b> = biarin aku (sering ketus).</li></ol>⚠️ 窓を開けておく bisa \"buka dulu (persiapan)\" atau \"biarkan terbuka\" — lihat konteks.","examples":[{"jp":"まだ<ruby>使<rt>つか</rt></ruby>っていますから、そのままにしておいてください。","speech":"まだ使っていますから、そのままにしておいてください。","id":"Masih saya pakai, jadi tolong <b>biarkan saja seperti itu</b>. <i>(そのまま)</i>"},{"jp":"<ruby>暑<rt>あつ</rt></ruby>いから、 <ruby>窓<rt>まど</rt></ruby>を<ruby>開<rt>あ</rt></ruby>けておきましょう。","speech":"暑いから、窓を開けておきましょう。","id":"Panas, jadi jendelanya <b>dibiarkan terbuka</b> saja. <i>(biarkan terbuka)</i>"},{"jp":"<ruby>妹<rt>いもうと</rt></ruby>の<ruby>分<rt>ぶん</rt></ruby>のケーキを<ruby>取<rt>と</rt></ruby>っておきました。","speech":"妹の分のケーキを取っておきました。","id":"Aku <b>sisihkan</b> kue bagian adikku. <i>(simpan)</i>"},{"jp":"まだ<ruby>使<rt>つか</rt></ruby>いますから、<ruby>出<rt>だ</rt></ruby>しておいてください。","speech":"まだ使いますから、出しておいてください。","id":"Masih mau dipakai, jadi <b>biarkan di luar</b> saja. <i>(biarkan)</i>"}],"dialogs":[{"jp":"<ruby>鍵<rt>かぎ</rt></ruby>は<b><ruby>開<rt>あ</rt></ruby>けておく</b>ので","speech":"鍵は開けておくので","id":"Kuncinya <b>kubiarkan terbuka</b> ya. <i>(biarkan terbuka)</i>","source":"ヲタクに恋は難しい · EP10 · 06:33"},{"jp":"これは<ruby>大事<rt>だいじ</rt></ruby>に<b><ruby>取<rt>と</rt></ruby>っておいた</b> すごく<ruby>高<rt>たか</rt></ruby>いお<ruby>酒<rt>さけ</rt></ruby>なのよ","speech":"これは大事に取っておいたすごく高いお酒なのよ","id":"Ini sake mahal banget yang <b>kusimpan</b> baik-baik, tahu! <i>(取っておく · simpan)</i>","source":"この素晴らしい世界に祝福を！ · EP08 · 13:40"},{"jp":"<ruby>別<rt>べつ</rt></ruby>に<ruby>何<rt>なん</rt></ruby>でもないから <b><ruby>放<rt>ほう</rt></ruby>っておいて</b>","speech":"別に何でもないから放っておいて","id":"Nggak ada apa-apa kok, <b>biarin aja</b>. <i>(放っておく)</i>","source":"トニカクカワイイ · EP04 · 06:47"},{"jp":"もうよい <b>ほっといて</b>くりゃれ!","speech":"もうよいほっといてくりゃれ!","id":"Sudah cukup, <b>biarkan aku</b>! <i>(ほっとく · ketus)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP13 · 09:18"},{"jp":"だから<b>ほっといて</b>いい","speech":"だからほっといていい","id":"Jadi <b>dibiarin aja</b> nggak apa-apa. <i>(ほっとく)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP08 · 07:10"}]},{"id":"n4_b31_01","level":"N4","bab":31,"lokasi":"第31課","titleMain":"意向形","titleSub":["〜よう","〜おう"],"meaning":"Ayo… / yuk… (ajakan kasual) · aku mau… ah (niat sendiri) — bentuk kasual 〜ましょう","formula":"Grup 1: -u → -o + <b>う</b>（書く → 書<b>こう</b> ／ 行く → 行<b>こう</b>）<br>Grup 2: -る → <b>よう</b>（食べる → 食べ<b>よう</b>）<br>Grup 3: する → <b>しよう</b> ／ 来る → <b>こよう</b><br>Tawaran: Ｖ-volitional + <b>か</b>（持<b>とうか</b>）","nuance":"<ol><li><b>Ajakan</b> ke teman/keluarga: 休もう = 休みましょう versi santai.</li><li><b>Niat sendiri</b> / monolog: よし、頑張ろう.</li><li><b>〜ようか</b>: ajakan lembut / menawarkan bantuan (持とうか).</li></ol>⚠️ Jangan tertukar dengan potensial: 書<b>こう</b> (ayo nulis) ≠ 書<b>ける</b> (bisa nulis). 来る → <b>こよう</b> (bukan ×きよう). Ke atasan tetap 〜ましょう.","examples":[{"jp":"ちょっと<ruby>休<rt>やす</rt></ruby>もう。","speech":"ちょっと休もう。","id":"<b>Istirahat bentar yuk.</b> <i>(ajakan)</i>"},{"jp":"<ruby>疲<rt>つか</rt></ruby>れたね。もう<ruby>帰<rt>かえ</rt></ruby>ろう。","speech":"疲れたね。もう帰ろう。","id":"Capek ya. <b>Pulang yuk.</b> <i>(ajakan)</i>"},{"jp":"<ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>晩<rt>ばん</rt></ruby>ご<ruby>飯<rt>はん</rt></ruby>を<ruby>食<rt>た</rt></ruby>べよう。","speech":"一緒に晩ご飯を食べよう。","id":"<b>Yuk makan malam bareng.</b> <i>(ajakan)</i>"},{"jp":"<ruby>荷物<rt>にもつ</rt></ruby>、<ruby>持<rt>も</rt></ruby>とうか。","speech":"荷物、持とうか。","id":"Barangnya, <b>mau kubawain</b>? <i>(menawarkan)</i>"},{"jp":"よし、 <ruby>明日<rt>あした</rt></ruby>から<ruby>頑張<rt>がんば</rt></ruby>ろう！","speech":"よし、明日から頑張ろう！","id":"Oke, mulai besok <b>aku mau berjuang</b>! <i>(niat sendiri)</i>"}],"dialogs":[{"jp":"よし <b><ruby>行<rt>い</rt></ruby>こう</b>! うん","speech":"よし行こう! うん","id":"Oke, <b>ayo berangkat</b>! Iya. <i>(ajakan)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 20:09"},{"jp":"また<b><ruby>行<rt>い</rt></ruby>こう</b> キャンプ","speech":"また行こうキャンプ","id":"<b>Yuk</b> camping <b>lagi</b>! <i>(ajakan)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 21:03"},{"jp":"シュークリーム<ruby>一緒<rt>いっしょ</rt></ruby>に<b><ruby>食<rt>た</rt></ruby>べようか</b>","speech":"シュークリーム一緒に食べようか","id":"Kue sus-nya <b>dimakan bareng yuk</b>? <i>(〜ようか · ajakan lembut)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP03 · 11:57"},{"jp":"<ruby>真昼<rt>まひる</rt></ruby> もう<ruby>遅<rt>おそ</rt></ruby>いから<b><ruby>帰<rt>かえ</rt></ruby>ろうか</b>","speech":"真昼もう遅いから帰ろうか","id":"Mahiru, udah malam, <b>pulang yuk</b>. <i>(〜ようか · ajakan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP11 · 06:57"},{"jp":"<ruby>肉<rt>にく</rt></ruby>まん<ruby>買<rt>か</rt></ruby>って<b><ruby>帰<rt>かえ</rt></ruby>ろう</b>","speech":"肉まん買って帰ろう","id":"Beli bakpao daging dulu ah, <b>terus pulang</b>. <i>(niat sendiri · monolog)</i>","source":"ゆるキャン△ · EP10 · 02:56"}]},{"id":"n4_b31_02","level":"N4","bab":31,"lokasi":"第31課","titleMain":"〜ようと思っています","titleSub":["〜ようと思います"],"meaning":"Aku berniat… / rencananya mau… / kepikiran mau…","formula":"Ｖ-volitional + <b>と思います</b>（行こう<b>と思います</b>）= niat baru diputuskan<br>Ｖ-volitional + <b>と思っています</b>（おろそう<b>と思っています</b>）= niat yang sudah dipegang","nuance":"<ol><li><b>〜ようと思います</b>: niat yang baru diputuskan, hanya untuk diri sendiri.</li><li><b>〜ようと思っています</b>: niat yang sudah lama dipikirkan; bisa untuk <b>orang ketiga</b> (兄は辞めようと思っています).</li></ol>⚠️ Bentuk kamus + と思います = dugaan (行くと思います = kurasa dia pergi), bukan niat. Lebih lembut dari <b>つもり</b> / <b>予定</b>.","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>病院<rt>びょういん</rt></ruby>へ<ruby>行<rt>い</rt></ruby>こうと<ruby>思<rt>おも</rt></ruby>っています。","speech":"明日は病院へ行こうと思っています。","id":"Besok <b>aku berniat pergi</b> ke rumah sakit. <i>(niat yang dipegang)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby>は<ruby>海<rt>うみ</rt></ruby>に<ruby>行<rt>い</rt></ruby>こうと<ruby>思<rt>おも</rt></ruby>います。","speech":"週末は海に行こうと思います。","id":"Akhir pekan ini <b>kayaknya aku mau pergi</b> ke laut. <i>(niat baru)</i>"},{"jp":"<ruby>銀行<rt>ぎんこう</rt></ruby>でお<ruby>金<rt>かね</rt></ruby>をおろそうと<ruby>思<rt>おも</rt></ruby>っています。","speech":"銀行でお金をおろそうと思っています。","id":"<b>Aku berniat menarik uang</b> di bank. <i>(rencana)</i>"},{"jp":"<ruby>兄<rt>あに</rt></ruby>は<ruby>会社<rt>かいしゃ</rt></ruby>を<ruby>辞<rt>や</rt></ruby>めようと<ruby>思<rt>おも</rt></ruby>っています。","speech":"兄は会社を辞めようと思っています。","id":"Kakakku <b>berniat keluar</b> dari perusahaan. <i>(orang ketiga)</i>"}],"dialogs":[{"jp":"とある<ruby>新人賞<rt>しんじんしょう</rt></ruby>に<b><ruby>応募<rt>おうぼ</rt></ruby>しようと<ruby>思<rt>おも</rt></ruby>っている</b>が","speech":"とある新人賞に応募しようと思っているが","id":"Aku <b>berniat ikut</b> lomba pendatang baru tertentu, tapi… <i>(niat yang dipegang)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP02 · 15:52"},{"jp":"<ruby>小町<rt>こまち</rt></ruby>の<ruby>合格祝<rt>ごうかくいわ</rt></ruby>いか<ruby>誕生日祝<rt>たんじょうびいわ</rt></ruby>いか　 <ruby>何<rt>なに</rt></ruby>か<b><ruby>用意<rt>ようい</rt></ruby>しようと<ruby>思<rt>おも</rt></ruby>ってて</b>な","speech":"小町の合格祝いか誕生日祝いか何か用意しようと思っててな","id":"Buat perayaan lulusnya Komachi atau ulang tahunnya, aku <b>rencananya mau nyiapin</b> sesuatu. <i>(〜と思っている · kasual)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP04 · 02:22"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんに ひと<ruby>言<rt>こと</rt></ruby><ruby>言<rt>い</rt></ruby>って<b><ruby>帰<rt>かえ</rt></ruby>ろうと<ruby>思<rt>おも</rt></ruby>った</b>んです","speech":"周くんにひと言言って帰ろうと思ったんです","id":"Aku <b>tadinya mau</b> pamit sepatah kata ke Amane-kun, <b>terus pulang</b>. <i>(〜ようと思った · niat lampau)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP02 · 06:25"},{"jp":"というわけで-　このガラクタを<b><ruby>返品<rt>へんぴん</rt></ruby>しようと<ruby>思<rt>おも</rt></ruby>って</b> <ruby>箱詰<rt>はこづ</rt></ruby>め<ruby>中<rt>ちゅう</rt></ruby>なのだが...","speech":"というわけで-　このガラクタを返品しようと思って箱詰め中なのだが...","id":"Jadi, aku <b>berniat mengembalikan</b> barang rongsokan ini, makanya lagi kupak ke kardus… <i>(niat)</i>","source":"この素晴らしい世界に祝福を！2 · EP07 · 11:24"}]},{"id":"n4_b31_03","level":"N4","bab":31,"lokasi":"第31課","titleMain":"〜つもりです","titleSub":["〜ないつもりです","〜予定です"],"meaning":"つもり = berniat (tekad pribadi) · 予定 = dijadwalkan / rencananya (sudah ditetapkan)","formula":"Ｖ-る + <b>つもりです</b>（帰る<b>つもりです</b>）<br>Ｖ-ない + <b>つもりです</b>（吸わない<b>つもりです</b>）<br>Ｖ-る ／ Ｎ<b>の</b> + <b>予定です</b>（出張する<b>予定です</b> ／ 旅行<b>の予定です</b>）","nuance":"<ol><li><b>つもり</b>: niat yang sudah mantap di hati, lebih tegas dari 〜ようと思っています.</li><li><b>予定</b>: jadwal yang sudah ditetapkan (kantor, pesawat, acara).</li><li><b>〜つもりはない</b>: sama sekali tidak ada niat (lebih tegas dari 〜ないつもり).</li></ol>⚠️ Keduanya kata benda → KB + <b>の</b> (旅行の予定). Tanya ke atasan lebih aman <b>〜予定ですか</b> daripada 〜つもりですか.","examples":[{"jp":"<ruby>来年<rt>らいねん</rt></ruby>、 <ruby>国<rt>くに</rt></ruby>へ<ruby>帰<rt>かえ</rt></ruby>るつもりです。","speech":"来年、国へ帰るつもりです。","id":"Tahun depan <b>aku berniat pulang</b> ke negaraku. <i>(つもり)</i>"},{"jp":"もうタバコは<ruby>吸<rt>す</rt></ruby>わないつもりです。","speech":"もうタバコは吸わないつもりです。","id":"<b>Aku berniat nggak</b> merokok lagi. <i>(ないつもり)</i>"},{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>は<ruby>７月<rt>しちがつ</rt></ruby>にアメリカへ<ruby>出張<rt>しゅっちょう</rt></ruby>する<ruby>予定<rt>よてい</rt></ruby>です。","speech":"部長は７月にアメリカへ出張する予定です。","id":"Manajer <b>dijadwalkan</b> dinas ke Amerika bulan Juli. <i>(予定)</i>"},{"jp":"<ruby>会議<rt>かいぎ</rt></ruby>は<ruby>３時<rt>さんじ</rt></ruby>に<ruby>終<rt>お</rt></ruby>わる<ruby>予定<rt>よてい</rt></ruby>です。","speech":"会議は３時に終わる予定です。","id":"Rapatnya <b>dijadwalkan selesai</b> jam tiga. <i>(予定)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby>は<ruby>旅行<rt>りょこう</rt></ruby>の<ruby>予定<rt>よてい</rt></ruby>です。","speech":"週末は旅行の予定です。","id":"Akhir pekan <b>rencananya jalan-jalan</b>. <i>(Ｎの予定)</i>"}],"dialogs":[{"jp":"いいか<ruby>俺<rt>おれ</rt></ruby>はできる<ruby>限<rt>かぎ</rt></ruby>り<b><ruby>協力<rt>きょうりょく</rt></ruby>するつもりだ</b>","speech":"いいか俺はできる限り協力するつもりだ","id":"Dengar ya, aku <b>berniat membantu</b> sebisa mungkin. <i>(つもり · tekad)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP01 · 20:45"},{"jp":"<b>どうするつもり</b>","speech":"どうするつもり","id":"Kamu <b>niatnya mau gimana</b>? <i>(menanyakan niat)</i>","source":"ガールズバンドクライ · EP01 · 11:51"},{"jp":"<ruby>真昼<rt>まひる</rt></ruby>には<ruby>当分<rt>とうぶん</rt></ruby><b><ruby>見<rt>み</rt></ruby>せるつもりはない</b>し","speech":"真昼には当分見せるつもりはないし","id":"Untuk sementara aku <b>sama sekali nggak berniat</b> nunjukin ke Mahiru. <i>(つもりはない)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP11 · 17:23"},{"jp":"<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>ですよ<ruby>妹<rt>いもうと</rt></ruby>にミニバン<b><ruby>借<rt>か</rt></ruby>りる<ruby>予定<rt>よてい</rt></ruby>です</b>から","speech":"大丈夫ですよ妹にミニバン借りる予定ですから","id":"Tenang aja, <b>rencananya</b> aku <b>pinjam</b> minivan adikku kok. <i>(予定)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 06:33"},{"jp":"レノスに<b><ruby>向<rt>む</rt></ruby>かう<ruby>予定<rt>よてい</rt></ruby>な</b>のですが","speech":"レノスに向かう予定なのですが","id":"<b>Rencananya</b> saya <b>menuju</b> ke Lenos, tapi… <i>(予定)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 05:26"}]},{"id":"n4_b31_04","level":"N4","bab":31,"lokasi":"第31課","titleMain":"まだ〜ていません","titleSub":[],"meaning":"Belum… (sampai sekarang belum terjadi)","formula":"<b>まだ</b> + Ｖ-て + <b>いません</b>（まだ食べ<b>ていません</b>）<br>Kasual: <b>まだ〜てない</b> · Jawaban singkat: <b>まだです</b><br>Pasangannya: もう〜ましたか → はい、もう〜ました","nuance":"<ol><li>Menjawab <b>もう〜ましたか</b> (sudah…?) dengan \"belum\".</li><li>Lampau <b>まだ〜てなかった</b>: baru sadar ternyata belum (まだ食べてなかった!).</li></ol>⚠️ ×まだ食べませんでした — itu \"(waktu itu) tidak makan\". <b>まだ</b> + positif = \"masih\" (まだ寝ています).","examples":[{"jp":"まだ<ruby>決<rt>き</rt></ruby>めていません。","speech":"まだ決めていません。","id":"<b>Belum</b> kuputuskan. <i>(belum)</i>"},{"jp":"レポートはまだ<ruby>書<rt>か</rt></ruby>いていません。","speech":"レポートはまだ書いていません。","id":"Laporannya <b>belum</b> kutulis. <i>(belum)</i>"},{"jp":"いいえ、まだ<ruby>食<rt>た</rt></ruby>べていません。","speech":"いいえ、まだ食べていません。","id":"Belum, <b>aku belum makan</b>. <i>(jawaban もう〜ましたか)</i>"},{"jp":"まだ <ruby>何<rt>なに</rt></ruby>も<ruby>買<rt>か</rt></ruby>っていない。","speech":"まだ何も買っていない。","id":"Aku <b>belum</b> beli apa-apa. <i>(kasual)</i>"}],"dialogs":[{"jp":"します <b>まだ<ruby>決<rt>き</rt></ruby>めてません</b>けど","speech":"しますまだ決めてませんけど","id":"Mau kok, cuma <b>belum kuputuskan</b> aja. <i>(〜てません · sopan ringkas)</i>","source":"ガールズバンドクライ · EP01 · 16:35"},{"jp":"<b>まだ</b> <ruby>泊<rt>と</rt></ruby>まる<ruby>所<rt>ところ</rt></ruby><b><ruby>決<rt>き</rt></ruby>めてない</b>ですけど ふーん","speech":"まだ泊まる所決めてないですけどふーん","id":"Tempat nginapnya sih <b>belum kutentuin</b>. Hmm. <i>(belum)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 20:06"},{"jp":"<b>まだ</b> <ruby>何<rt>なに</rt></ruby>も<b><ruby>言<rt>い</rt></ruby>ってない</b>!","speech":"まだ何も言ってない!","id":"Aku <b>belum</b> ngomong apa-apa! <i>(まだ何も〜てない)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 10:13"},{"jp":"<b>まだ</b> <ruby>誰<rt>だれ</rt></ruby>にも<b><ruby>言<rt>い</rt></ruby>ってない</b>んですか","speech":"まだ誰にも言ってないんですか","id":"Kamu <b>belum bilang</b> ke siapa pun? <i>(belum · pertanyaan)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP04 · 16:52"},{"jp":"そういえば <b>まだ</b> <ruby>朝<rt>あさ</rt></ruby>ごはん<b><ruby>食<rt>た</rt></ruby>べてなかった</b>わね","speech":"そういえばまだ朝ごはん食べてなかったわね","id":"Oh iya, aku <b>belum</b> sarapan ya. <i>(〜てなかった · baru sadar)</i>","source":"この素晴らしい世界に祝福を！2 · EP04 · 00:19"}]},{"id":"n4_b32_01","level":"N4","bab":32,"lokasi":"第32課","titleMain":"〜ほうがいい","titleSub":["〜たほうがいい","〜ないほうがいい"],"meaning":"Sebaiknya… / lebih baik… · sebaiknya jangan… — memberi saran","formula":"Ｖ-<b>た</b> + <b>ほうがいいです</b>（運動し<b>たほうがいい</b>）<br>Ｖ-<b>ない</b> + <b>ほうがいいです</b>（無理をし<b>ないほうがいい</b>）<br>Kasual: 〜ほうがいい<b>よ</b> · Lunak: 〜ほうがいい<b>と思う</b>","nuance":"<ol><li>Saran positif = <b>bentuk た</b> (bukan lampau!), saran negatif = <b>bentuk ない</b>.</li><li>Nadanya cukup tegas (\"kalau nggak, nanti repot\"); dilunakkan dengan 〜よ / 〜と思う.</li></ol>⚠️ ×〜なかったほうがいい. Jangan dipakai menasihati atasan (menggurui) → 〜たらどうですか ke teman.","examples":[{"jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>運動<rt>うんどう</rt></ruby>したほうがいいです。","speech":"毎日運動したほうがいいです。","id":"<b>Sebaiknya olahraga</b> setiap hari. <i>(saran positif)</i>"},{"jp":"<ruby>無理<rt>むり</rt></ruby>をしないほうがいいですよ。","speech":"無理をしないほうがいいですよ。","id":"<b>Sebaiknya jangan</b> terlalu memaksakan diri, lho. <i>(saran negatif)</i>"},{"jp":"<ruby>熱<rt>ねつ</rt></ruby>があるなら、 <ruby>早<rt>はや</rt></ruby>く<ruby>寝<rt>ね</rt></ruby>たほうがいいよ。","speech":"熱があるなら、早く寝たほうがいいよ。","id":"Kalau demam, <b>mending cepat tidur</b>. <i>(kasual)</i>"},{"jp":"<ruby>夜<rt>よる</rt></ruby>、 <ruby>一人<rt>ひとり</rt></ruby>で<ruby>公園<rt>こうえん</rt></ruby>へ<ruby>行<rt>い</rt></ruby>かないほうがいいです。","speech":"夜、一人で公園へ行かないほうがいいです。","id":"Malam-malam <b>sebaiknya jangan</b> pergi ke taman sendirian. <i>(saran negatif)</i>"},{"jp":"<ruby>予約<rt>よやく</rt></ruby>したほうがいいですか。","speech":"予約したほうがいいですか。","id":"<b>Sebaiknya</b> saya <b>reservasi</b>? <i>(minta saran)</i>"}],"dialogs":[{"jp":"やっぱりベース<b><ruby>探<rt>さが</rt></ruby>したほうがいい</b>よ","speech":"やっぱりベース探したほうがいいよ","id":"Kayaknya <b>mending</b> kita <b>cari</b> pemain bass deh. <i>(saran positif)</i>","source":"ガールズバンドクライ · EP05 · 00:26"},{"jp":"いや<ruby>真面目<rt>まじめ</rt></ruby>に<b><ruby>気<rt>き</rt></ruby>をつけたほうがいい</b>","speech":"いや真面目に気をつけたほうがいい","id":"Nggak, serius, <b>sebaiknya</b> kamu <b>hati-hati</b>. <i>(peringatan)</i>","source":"狼と香辛料 · EP08 · 02:21"},{"jp":"<b>やめたほうがいい</b>と<ruby>思<rt>おも</rt></ruby>う","speech":"やめたほうがいいと思う","id":"Menurutku <b>mending nggak usah</b> (dihentikan aja). <i>(〜ほうがいいと思う · lunak)</i>","source":"ゆるキャン△ · EP03 · 07:51"},{"jp":"<ruby>喜多<rt>きた</rt></ruby>ちゃーん　 <ruby>気軽<rt>きがる</rt></ruby>に そういうこと<b><ruby>言<rt>い</rt></ruby>わないほうがいい</b>よー","speech":"喜多ちゃーん気軽にそういうこと言わないほうがいいよー","id":"Kita-chan~ <b>sebaiknya jangan</b> ngomong begitu seenaknya lho~ <i>(saran negatif)</i>","source":"ぼっち・ざ・ろっく！ · EP10 · 15:57"},{"jp":"ですが これ<ruby>以上<rt>いじょう</rt></ruby>は あまり<b><ruby>詮索<rt>せんさく</rt></ruby>しないほうがいいです</b>よ","speech":"ですがこれ以上はあまり詮索しないほうがいいですよ","id":"Tapi <b>sebaiknya jangan</b> mengorek lebih jauh dari ini. <i>(saran negatif · sopan)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 11:25"}]},{"id":"n4_b32_02","level":"N4","bab":32,"lokasi":"第32課","titleMain":"〜でしょう","titleSub":["〜でしょうか"],"meaning":"Mungkin / kemungkinan besar… (perkiraan cukup yakin) · でしょうか = kira-kira…? (tanya pendapat sopan)","formula":"Ｖ / KS-i (bentuk biasa) + <b>でしょう</b>（降る<b>でしょう</b> ／ 寒い<b>でしょう</b>）<br>KS-na / KB (<b>tanpa だ</b>) + <b>でしょう</b>（静か<b>でしょう</b> ／ 雨<b>でしょう</b>）<br>Kasual: <b>だろう</b>","nuance":"<ol><li><b>Perkiraan ± 70–80%</b>: khas ramalan cuaca (明日は雨が降るでしょう). Sering dengan たぶん / きっと.</li><li><b>〜でしょうか</b>: menanyakan perkiraan/pendapat lawan bicara dengan sopan.</li></ol>⚠️ ×静かだでしょう. Tingkat yakin: です (pasti) > <b>でしょう</b> > <b>かもしれません</b>. でしょ？(nada naik) = minta persetujuan \"kan?\".","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>るでしょう。","speech":"明日は雨が降るでしょう。","id":"Besok <b>kemungkinan</b> hujan. <i>(ramalan cuaca)</i>"},{"jp":"<ruby>北海道<rt>ほっかいどう</rt></ruby>は<ruby>今<rt>いま</rt></ruby>、<ruby>寒<rt>さむ</rt></ruby>いでしょう。","speech":"北海道は今、寒いでしょう。","id":"Hokkaido sekarang <b>pasti dingin</b> ya. <i>(perkiraan)</i>"},{"jp":"あしたの<ruby>試験<rt>しけん</rt></ruby>は<ruby>難<rt>むずか</rt></ruby>しいでしょうか。","speech":"あしたの試験は難しいでしょうか。","id":"<b>Kira-kira</b> ujian besok susah nggak ya? <i>(でしょうか)</i>"},{"jp":"<ruby>彼<rt>かれ</rt></ruby>はたぶん<ruby>来<rt>こ</rt></ruby>ないでしょう。","speech":"彼はたぶん来ないでしょう。","id":"Dia <b>mungkin</b> nggak datang. <i>(たぶん〜でしょう)</i>"}],"dialogs":[{"jp":"<ruby>山<rt>やま</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>は もっと<b><ruby>寒<rt>さむ</rt></ruby>いでしょう</b>ね","speech":"山の上はもっと寒いでしょうね","id":"Di atas gunung <b>pasti</b> lebih <b>dingin</b> ya. <i>(perkiraan)</i>","source":"ゆるキャン△ SEASON２ · EP02 · 13:13"},{"jp":"<ruby>間違<rt>まちが</rt></ruby>いなく<ruby>食<rt>く</rt></ruby>いついて<b>くるでしょう</b>","speech":"間違いなく食いついてくるでしょう","id":"<b>Pasti</b> dia bakal tertarik dan menyambar (tawaran itu). <i>(perkiraan yakin)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP10 · 11:17"},{"jp":"<ruby>裏側<rt>うらがわ</rt></ruby>にいる<ruby>黒幕<rt>くろまく</rt></ruby>のもうけは<ruby>莫大<rt>ばくだい</rt></ruby>なものに<b>なるでしょう</b>","speech":"裏側にいる黒幕のもうけは莫大なものになるでしょう","id":"Keuntungan dalang di balik layar <b>kemungkinan besar</b> bakal sangat besar. <i>(perkiraan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP04 · 02:51"},{"jp":"あの<ruby>人<rt>ひと</rt></ruby>も<b><ruby>喜<rt>よろこ</rt></ruby>んでるでしょう</b>ね","speech":"あの人も喜んでるでしょうね","id":"Orang itu juga <b>pasti</b> lagi senang ya. <i>(perkiraan)</i>","source":"この素晴らしい世界に爆焔を！ · EP01 · 08:31"},{"jp":"ロレンスさん<b><ruby>大丈夫<rt>だいじょうぶ</rt></ruby>でしょうか</b>?","speech":"ロレンスさん大丈夫でしょうか?","id":"Lawrence-san <b>kira-kira nggak apa-apa</b> ya? <i>(でしょうか · tanya pendapat)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP19 · 00:11"}]},{"id":"n4_b32_03","level":"N4","bab":32,"lokasi":"第32課","titleMain":"〜かもしれません","titleSub":["〜かもしれない","〜かも"],"meaning":"Mungkin… / bisa jadi… (± 50%, tidak yakin)","formula":"Ｖ / KS-i (bentuk biasa) + <b>かもしれません</b>（間に合わない<b>かもしれません</b>）<br>KS-na / KB (<b>tanpa だ</b>) + <b>かもしれません</b>（うそ<b>かもしれません</b>）<br>Kasual: <b>かもしれない</b> → <b>かも</b>","nuance":"<ol><li>Kemungkinan <b>lebih rendah</b> dari でしょう — bisa ya, bisa tidak.</li><li>Sering dengan <b>もしかしたら / もしかすると</b>.</li></ol>⚠️ ×うそだかもしれません. Urutan yakin: です > でしょう (70–80%) > <b>かもしれません</b> (± 50%).","examples":[{"jp":"<ruby>約束<rt>やくそく</rt></ruby>の<ruby>時間<rt>じかん</rt></ruby>に<ruby>間<rt>ま</rt></ruby>に<ruby>合<rt>あ</rt></ruby>わないかもしれません。","speech":"約束の時間に間に合わないかもしれません。","id":"<b>Mungkin</b> aku <b>nggak keburu</b> sampai di jam janjian. <i>(kemungkinan)</i>"},{"jp":"ミラーさんは<ruby>来<rt>こ</rt></ruby>ないかもしれません。","speech":"ミラーさんは来ないかもしれません。","id":"Pak Miller <b>mungkin nggak datang</b>. <i>(kemungkinan)</i>"},{"jp":"<ruby>午後<rt>ごご</rt></ruby>から<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>るかもしれないから、 <ruby>傘<rt>かさ</rt></ruby>を<ruby>持<rt>も</rt></ruby>っていこう。","speech":"午後から雨が降るかもしれないから、傘を持っていこう。","id":"<b>Bisa jadi</b> hujan mulai siang, jadi bawa payung yuk. <i>(kasual)</i>"},{"jp":"あの<ruby>人<rt>ひと</rt></ruby>は<ruby>先生<rt>せんせい</rt></ruby>かもしれません。","speech":"あの人は先生かもしれません。","id":"Orang itu <b>mungkin guru</b>. <i>(KB + かもしれません)</i>"}],"dialogs":[{"jp":"<ruby>帰<rt>かえ</rt></ruby>るのが<b><ruby>遅<rt>おそ</rt></ruby>くなるかもしれません</b>","speech":"帰るのが遅くなるかもしれません","id":"Pulangnya <b>mungkin</b> bakal <b>telat</b>. <i>(kemungkinan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP11 · 03:13"},{"jp":"<ruby>磐田<rt>いわた</rt></ruby>でしたら<ruby>福田<rt>ふくで</rt></ruby><ruby>海岸<rt>かいがん</rt></ruby>が<b>いいかもしれません</b>ね","speech":"磐田でしたら福田海岸がいいかもしれませんね","id":"Kalau ke Iwata, Pantai Fukude <b>mungkin bagus</b> tuh. <i>(saran tak pasti)</i>","source":"ゆるキャン△ SEASON２ · EP02 · 04:11"},{"jp":"ただ もう<ruby>宿<rt>やど</rt></ruby>には<b>いないかもしれません</b>が","speech":"ただもう宿にはいないかもしれませんが","id":"Cuma, <b>bisa jadi</b> dia <b>udah nggak ada</b> di penginapan. <i>(kemungkinan negatif)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP02 · 07:30"},{"jp":"<ruby>今<rt>いま</rt></ruby><ruby>始<rt>はじ</rt></ruby>めれば<b><ruby>間<rt>ま</rt></ruby>に<ruby>合<rt>あ</rt></ruby>うかもしれない</b>から","speech":"今始めれば間に合うかもしれないから","id":"Kalau mulai sekarang, <b>mungkin</b> masih <b>keburu</b>. <i>(kasual)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP02 · 17:19"},{"jp":"もしかしたら<b><ruby>違<rt>ちが</rt></ruby>うかもしれない</b>","speech":"もしかしたら違うかもしれない","id":"<b>Bisa jadi</b> aku <b>salah</b> sih. <i>(もしかしたら〜かもしれない)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP01 · 09:02"}]},{"id":"n4_b33_01","level":"N4","bab":33,"lokasi":"第33課","titleMain":"命令形","titleSub":["書け","食べろ","しろ","来い"],"meaning":"…! — perintah keras/langsung (Berhenti! Lari! Semangat!)","formula":"Grup 1: -u → <b>-e</b>（書く → 書<b>け</b> ／ 止まる → 止ま<b>れ</b>）<br>Grup 2: -る → <b>ろ</b>（食べる → 食べ<b>ろ</b> ／ 逃げる → 逃げ<b>ろ</b>）<br>Grup 3: する → <b>しろ</b> ／ 来る → <b>来い（こい）</b>","nuance":"<ol><li>Laki-laki kasual ke yang setara/lebih muda; atasan ke bawahan.</li><li><b>Darurat</b> (逃げろ!), <b>sorakan</b> (頑張れ!), <b>rambu</b> (止まれ).</li></ol>⚠️ Sangat kasar bila diucapkan langsung. Lebih halus: <b>〜なさい</b> (orang tua/guru), <b>〜て</b>, <b>〜てください</b>. Grup 1 berakhiran る: 帰る → 帰<b>れ</b> (bukan ×帰ろ).","examples":[{"jp":"<ruby>止<rt>と</rt></ruby>まれ！","speech":"止まれ！","id":"<b>Berhenti!</b> <i>(rambu · Grup 1)</i>"},{"jp":"<ruby>頑張<rt>がんば</rt></ruby>れ！","speech":"頑張れ！","id":"<b>Semangat!</b> <i>(sorakan)</i>"},{"jp":"<ruby>早<rt>はや</rt></ruby>く<ruby>起<rt>お</rt></ruby>きろ！ <ruby>遅刻<rt>ちこく</rt></ruby>するぞ。","speech":"早く起きろ！遅刻するぞ。","id":"<b>Cepat bangun!</b> Nanti telat. <i>(kasual pria · Grup 2)</i>"},{"jp":"<ruby>危<rt>あぶ</rt></ruby>ない！<ruby>逃<rt>に</rt></ruby>げろ！","speech":"危ない！逃げろ！","id":"Bahaya! <b>Lari!</b> <i>(darurat)</i>"},{"jp":"ちょっとこっちへ<ruby>来<rt>こ</rt></ruby>い。","speech":"ちょっとこっちへ来い。","id":"<b>Sini</b> bentar. <i>(来い · Grup 3)</i>"}],"dialogs":[{"jp":"ぼっち<b><ruby>頑張<rt>がんば</rt></ruby>れ</b> ぼっち<b><ruby>頑張<rt>がんば</rt></ruby>れ</b>","speech":"ぼっち頑張れぼっち頑張れ","id":"Bocchi, <b>semangat</b>! Bocchi, <b>semangat</b>! <i>(sorakan)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 12:41"},{"jp":"もう そんなんいいから とっとと<b><ruby>逃<rt>に</rt></ruby>げろ</b>!","speech":"もうそんなんいいからとっとと逃げろ!","id":"Udah, lupain itu, cepetan <b>lari</b>! <i>(darurat · Grup 2)</i>","source":"この素晴らしい世界に祝福を！2 · EP10 · 14:10"},{"jp":"お... お<ruby>前<rt>まえ</rt></ruby>ら<b><ruby>起<rt>お</rt></ruby>きろ</b>! <ruby>大変<rt>たいへん</rt></ruby>だ!","speech":"お... お前ら起きろ! 大変だ!","id":"K-kalian, <b>bangun</b>! Gawat! <i>(darurat · Grup 2)</i>","source":"ゆるキャン△ SEASON２ · EP11 · 21:10"},{"jp":"ほれー はよ<b><ruby>来<rt>こ</rt></ruby>い</b> <ruby>何<rt>なに</rt></ruby>している","speech":"ほれーはよ来い何している","id":"Hei, cepat <b>sini</b>! Lagi ngapain sih? <i>(来い · Grup 3)</i>","source":"狼と香辛料 · EP02 · 16:41"},{"jp":"さあ あと<ruby>二人<rt>ふたり</rt></ruby>だ　 <ruby>早<rt>はや</rt></ruby>く<b>しろ</b>","speech":"さああと二人だ早くしろ","id":"Ayo, tinggal dua orang. Cepat <b>lakukan</b>! <i>(しろ · Grup 3)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP08 · 15:37"}]},{"id":"n4_b33_02","level":"N4","bab":33,"lokasi":"第33課","titleMain":"禁止形","titleSub":["Ｖるな"],"meaning":"Jangan…! — larangan keras","formula":"Ｖ-<b>る</b> (bentuk kamus) + <b>な</b><br>（触る<b>な</b> ／ 遅れる<b>な</b> ／ 心配する<b>な</b> ／ 来る<b>な</b>）<br>Kasual lebih lunak: 〜<b>なよ</b>","nuance":"<ol><li>Kebalikan 命令形: dipakai pria kasual, darurat, sorakan, rambu (入るな).</li><li><b>〜なよ</b>: masih tegas tapi lebih akrab (泣くなよ).</li></ol>⚠️ Bedakan <b>食べるな</b> (jangan makan!) vs <b>食べなさい</b> (makanlah). な akhir kalimat juga bisa partikel perasaan (いい天気だな). Halus: <b>〜ないで（ください）</b>.","examples":[{"jp":"<ruby>遅<rt>おく</rt></ruby>れるな！","speech":"遅れるな！","id":"<b>Jangan telat!</b> <i>(larangan)</i>"},{"jp":"<ruby>触<rt>さわ</rt></ruby>るな！","speech":"触るな！","id":"<b>Jangan sentuh!</b> <i>(larangan)</i>"},{"jp":"ここに<ruby>車<rt>くるま</rt></ruby>を<ruby>止<rt>と</rt></ruby>めるな。","speech":"ここに車を止めるな。","id":"<b>Jangan</b> parkir mobil di sini. <i>(rambu / larangan)</i>"},{"jp":"<ruby>心配<rt>しんぱい</rt></ruby>するな。 <ruby>大丈夫<rt>だいじょうぶ</rt></ruby>だ。","speech":"心配するな。大丈夫だ。","id":"<b>Jangan khawatir.</b> Nggak apa-apa. <i>(menenangkan)</i>"}],"dialogs":[{"jp":"もう<b><ruby>泣<rt>な</rt></ruby>くな</b>よ なでしこ","speech":"もう泣くなよなでしこ","id":"Udah, <b>jangan nangis</b> dong, Nadeshiko. <i>(〜なよ · akrab)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 00:02"},{"jp":"あと ヒッキーって<b><ruby>言<rt>い</rt></ruby>うな</b>","speech":"あとヒッキーって言うな","id":"Satu lagi, <b>jangan</b> panggil aku \"Hikki\". <i>(larangan)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP01 · 22:02"},{"jp":"<b><ruby>心配<rt>しんぱい</rt></ruby>するな</b> <ruby>私<rt>わたし</rt></ruby>が<ruby>保証<rt>ほしょう</rt></ruby>する","speech":"心配するな私が保証する","id":"<b>Jangan khawatir</b>, aku yang jamin. <i>(menenangkan)</i>","source":"ガールズバンドクライ · EP03 · 20:54"},{"jp":"んー? ほ... <ruby>本当<rt>ほんとう</rt></ruby>だ　だから そんな<ruby>目<rt>め</rt></ruby>で<b><ruby>見<rt>み</rt></ruby>るな</b>!","speech":"んー? ほ... 本当だだからそんな目で見るな!","id":"Hm? B-beneran kok! Makanya <b>jangan lihat</b> aku dengan tatapan begitu! <i>(larangan)</i>","source":"この素晴らしい世界に祝福を！2 · EP07 · 20:10"},{"jp":"<b><ruby>逃<rt>に</rt></ruby>げるな</b>ロレンス<ruby>男<rt>おとこ</rt></ruby>の<ruby>恥<rt>はじ</rt></ruby>だぞ","speech":"逃げるなロレンス男の恥だぞ","id":"<b>Jangan kabur</b>, Lawrence! Memalukan sebagai laki-laki! <i>(larangan tegas)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP03 · 02:56"}]},{"id":"n4_b33_03","level":"N4","bab":33,"lokasi":"第33課","titleMain":"〜と読みます","titleSub":["〜と書いてあります","〜という意味です"],"meaning":"Dibaca… · tertulis… · X artinya Y — menanyakan/menjelaskan tulisan & arti","formula":"「…」<b>と読みます</b>（何<b>と読みますか</b>）<br>「…」<b>と書いてあります</b>（何<b>と書いてありますか</b>）<br>Ｘは Ｙ<b>という意味です</b> ／ Ｘは<b>どういう意味ですか</b>","nuance":"<ol><li><b>と</b> = penanda kutipan isi bacaan/tulisan.</li><li>Kasual: 〜<b>って書いてある</b>, 〜<b>って読む</b>.</li></ol>⚠️ Tanya isi tulisan/bacaan pakai <b>何と</b> (nan to), bukan ×何を. Tanya arti: <b>どういう意味ですか</b>.","examples":[{"jp":"あの<ruby>漢字<rt>かんじ</rt></ruby>は<ruby>何<rt>なん</rt></ruby>と<ruby>読<rt>よ</rt></ruby>むんですか。","speech":"あの漢字は何と読むんですか。","id":"Kanji itu <b>dibaca</b> apa? <i>(tanya bacaan)</i>"},{"jp":"あそこに「 <ruby>止<rt>と</rt></ruby>まれ」と<ruby>書<rt>か</rt></ruby>いてあります。","speech":"あそこに「止まれ」と書いてあります。","id":"Di sana <b>tertulis</b> \"Berhenti\". <i>(isi tulisan)</i>"},{"jp":"このマークはどういう<ruby>意味<rt>いみ</rt></ruby>ですか。","speech":"このマークはどういう意味ですか。","id":"Tanda ini <b>artinya apa</b>? <i>(tanya arti)</i>"},{"jp":"「 <ruby>禁煙<rt>きんえん</rt></ruby>」はたばこを<ruby>吸<rt>す</rt></ruby>ってはいけないという<ruby>意味<rt>いみ</rt></ruby>です。","speech":"「禁煙」はたばこを吸ってはいけないという意味です。","id":"\"Kin'en\" <b>artinya</b> dilarang merokok. <i>(という意味)</i>"}],"dialogs":[{"jp":"<ruby>僕<rt>ぼく</rt></ruby>の<ruby>名前<rt>なまえ</rt></ruby>は<ruby>由崎<rt>ゆざき</rt></ruby>ナサ<ruby>星空<rt>ほしぞら</rt></ruby>と<ruby>書<rt>か</rt></ruby>いてナサ<b>と<ruby>読<rt>よ</rt></ruby>む</b>んだ","speech":"僕の名前は由崎ナサ星空と書いてナサと読むんだ","id":"Namaku Yuzaki Nasa — ditulis \"langit berbintang\", <b>dibaca</b> \"Nasa\". <i>(と読む)</i>","source":"トニカクカワイイ · EP01 · 08:55"},{"jp":"あっ でも この<ruby>木皿<rt>きざら</rt></ruby><ruby>熱<rt>あつ</rt></ruby>い<ruby>料理<rt>りょうり</rt></ruby>ダメ<b>って<ruby>書<rt>か</rt></ruby>いてある</b>で","speech":"あっでもこの木皿熱い料理ダメって書いてあるで","id":"Eh, tapi di piring kayu ini <b>tertulis</b> nggak boleh buat makanan panas lho. <i>(って書いてある · kasual)</i>","source":"ゆるキャン△ · EP08 · 05:15"},{"jp":"で<b>なんと<ruby>書<rt>か</rt></ruby>いてあった</b>んじゃ?","speech":"でなんと書いてあったんじゃ?","id":"Terus, <b>isinya tertulis apa</b>? <i>(何と書いてある)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP14 · 10:28"},{"jp":"<b>どういう<ruby>意味<rt>いみ</rt></ruby>ですか</b>?","speech":"どういう意味ですか?","id":"<b>Maksudnya apa</b>? <i>(tanya arti)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP11 · 18:30"},{"jp":"いや そういう<ruby>意味<rt>いみ</rt></ruby>じゃない　 <ruby>細<rt>こま</rt></ruby>かい<ruby>金<rt>かね</rt></ruby>がない<b>という<ruby>意味<rt>いみ</rt></ruby>だ</b>","speech":"いやそういう意味じゃない細かい金がないという意味だ","id":"Bukan, bukan gitu. <b>Maksudku</b> aku nggak punya uang receh. <i>(という意味)</i>","source":"狼と香辛料 · EP07 · 07:31"}]},{"id":"n4_b33_04","level":"N4","bab":33,"lokasi":"第33課","titleMain":"〜と言っていました","titleSub":["〜と伝えていただけませんか"],"meaning":"(Dia) bilang… (menyampaikan pesan orang lain) · bisa tolong sampaikan bahwa…?","formula":"Ｎ<b>が</b> + 〜(bentuk biasa) + <b>と言っていました</b><br>Ｎ<b>に</b> + 〜(bentuk biasa) + <b>と伝えていただけませんか</b> ／ <b>と伝えてください</b><br>Kasual: 〜<b>って言ってたよ</b>","nuance":"<ol><li><b>と言っていました</b>: menyampaikan pesan/omongan orang ketiga (\"dia titip bilang\").</li><li><b>と伝えていただけませんか</b>: minta lawan bicara meneruskan pesan, sopan.</li></ol>⚠️ KB / KS-na + <b>だ</b> sebelum と (10時から<b>だ</b>と). Bandingkan <b>と言いました</b> = sekadar melaporkan ucapan.","examples":[{"jp":"<ruby>田中<rt>たなか</rt></ruby>さんが<ruby>明日<rt>あした</rt></ruby><ruby>休<rt>やす</rt></ruby>むと<ruby>言<rt>い</rt></ruby>っていました。","speech":"田中さんが明日休むと言っていました。","id":"Tanaka-san <b>bilang</b> besok dia libur. <i>(menyampaikan pesan)</i>"},{"jp":"ミラーさんに、あしたの<ruby>会議<rt>かいぎ</rt></ruby>は<ruby>１０時<rt>じゅうじ</rt></ruby>からだと<ruby>伝<rt>つた</rt></ruby>えていただけませんか。","speech":"ミラーさんに、あしたの会議は１０時からだと伝えていただけませんか。","id":"<b>Bisa tolong sampaikan</b> ke Pak Miller <b>bahwa</b> rapat besok mulai jam 10? <i>(minta sampaikan · sopan)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>が「 <ruby>宿題<rt>しゅくだい</rt></ruby>を<ruby>忘<rt>わす</rt></ruby>れるな」と<ruby>言<rt>い</rt></ruby>っていましたよ。","speech":"先生が「宿題を忘れるな」と言っていましたよ。","id":"Guru <b>bilang</b> \"jangan lupa PR\", lho. <i>(perintah dikutip)</i>"},{"jp":"<ruby>母<rt>はは</rt></ruby>に、 <ruby>今日<rt>きょう</rt></ruby>は<ruby>遅<rt>おそ</rt></ruby>くなると<ruby>伝<rt>つた</rt></ruby>えてください。","speech":"母に、今日は遅くなると伝えてください。","id":"<b>Tolong sampaikan</b> ke ibuku <b>bahwa</b> hari ini aku pulang telat. <i>(minta sampaikan)</i>"}],"dialogs":[{"jp":"<ruby>学校<rt>がっこう</rt></ruby>でお<ruby>礼<rt>れい</rt></ruby><ruby>言<rt>い</rt></ruby>う<b>って<ruby>言<rt>い</rt></ruby>ってた</b>よ","speech":"学校でお礼言うって言ってたよ","id":"<b>Katanya</b> dia mau bilang makasih di sekolah. <i>(って言ってた · menyampaikan pesan)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP04 · 02:12"},{"jp":"でも<ruby>隼人<rt>はやと</rt></ruby><ruby>君<rt>くん</rt></ruby> チョコ<ruby>受<rt>う</rt></ruby>け<ruby>取<rt>と</rt></ruby>らない<b>って<ruby>言<rt>い</rt></ruby>ってた</b>よ","speech":"でも隼人君チョコ受け取らないって言ってたよ","id":"Tapi Hayato-kun <b>bilang</b> dia nggak bakal nerima cokelat. <i>(omongan orang ketiga)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP12 · 05:08"},{"jp":"ありがとうございました<b>って<ruby>伝<rt>つた</rt></ruby>えてください</b>","speech":"ありがとうございましたって伝えてください","id":"<b>Tolong sampaikan</b> \"terima kasih banyak\" ya. <i>(minta sampaikan)</i>","source":"純情ロマンチカ2(に) · EP09 · 10:54"},{"jp":"<ruby>父<rt>ちち</rt></ruby>と<ruby>母<rt>はは</rt></ruby>には　 <ruby>以前<rt>いぜん</rt></ruby>から<ruby>時<rt>とき</rt></ruby>が<ruby>満<rt>み</rt></ruby>ちた<ruby>暁<rt>あかつき</rt></ruby>には<ruby>旅立<rt>たびだ</rt></ruby>つ<b>と<ruby>伝<rt>つた</rt></ruby>えてあります</b>","speech":"父と母には以前から時が満ちた暁には旅立つと伝えてあります","id":"Ke ayah dan ibu, sudah lama <b>kusampaikan bahwa</b> kalau saatnya tiba aku akan berangkat. <i>(と伝える)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 15:45"}]},{"id":"n4_b34_01","level":"N4","bab":34,"lokasi":"第34課","titleMain":"〜とおりに","titleSub":["言ったとおりに","Ｎのとおりに","Ｎどおりに"],"meaning":"Persis seperti… / sesuai (dengan)…","formula":"Ｖ-<b>た</b> + <b>とおりに</b>（言った<b>とおりに</b>）= sesuai yang sudah terjadi<br>Ｖ-<b>る</b> + <b>とおりに</b>（やる<b>とおりに</b>）= sesuai yang akan dilakukan<br>Ｎ + <b>の とおりに</b> ／ Ｎ + <b>どおりに</b>（図<b>のとおりに</b> ／ 予定<b>どおりに</b>）","nuance":"<ol><li>Melakukan sesuatu dengan cara yang <b>sama persis</b> dengan yang dilihat/didengar/ditulis.</li><li>Akhir kalimat <b>〜とおりだ</b> = memang persis begitu (思ったとおりだ, その通りです).</li></ol>⚠️ とおり = kata benda (通り) → KB + <b>の</b>, atau tempel langsung jadi <b>どおり</b>. Mirip <b>言ったように</b>, tapi とおり terasa lebih persis.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>が<ruby>言<rt>い</rt></ruby>ったとおりに、 <ruby>書<rt>か</rt></ruby>いてください。","speech":"私が言ったとおりに、書いてください。","id":"Tolong tulis <b>persis seperti yang</b> saya katakan. <i>(Ｖたとおりに)</i>"},{"jp":"<ruby>図<rt>ず</rt></ruby>のとおりに、 <ruby>紙<rt>かみ</rt></ruby>を<ruby>切<rt>き</rt></ruby>ってください。","speech":"図のとおりに、紙を切ってください。","id":"Tolong potong kertasnya <b>sesuai</b> gambar. <i>(Ｎのとおりに)</i>"},{"jp":"<ruby>今<rt>いま</rt></ruby>から<ruby>私<rt>わたし</rt></ruby>がやるとおりに、やってください。","speech":"今から私がやるとおりに、やってください。","id":"Tolong lakukan <b>persis seperti yang</b> akan saya peragakan. <i>(Ｖるとおりに)</i>"},{"jp":"<ruby>説明書<rt>せつめいしょ</rt></ruby>どおりに <ruby>組<rt>く</rt></ruby>み<ruby>立<rt>た</rt></ruby>てたのに、 <ruby>動<rt>うご</rt></ruby>かない。","speech":"説明書どおりに組み立てたのに、動かない。","id":"Padahal sudah kurakit <b>sesuai</b> buku petunjuk, tapi nggak jalan. <i>(Ｎどおりに)</i>"},{"jp":"やっぱり、<ruby>思<rt>おも</rt></ruby>ったとおりだ。","speech":"やっぱり、思ったとおりだ。","id":"Tuh kan, <b>persis seperti dugaanku</b>. <i>(〜とおりだ)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<b><ruby>言<rt>い</rt></ruby>われたとおりに</b>やっただけで","speech":"私は言われたとおりにやっただけで","id":"Aku cuma ngelakuin <b>persis seperti yang disuruh</b>… <i>(Ｖたとおりに)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 00:25"},{"jp":"なんかわかんないけど<b><ruby>思<rt>おも</rt></ruby>った<ruby>通<rt>とお</rt></ruby>りに</b> <ruby>動<rt>うご</rt></ruby>いてくれた","speech":"なんかわかんないけど思った通りに動いてくれた","id":"Nggak tahu kenapa, tapi dia bergerak <b>persis seperti yang kubayangkan</b>. <i>(思ったとおりに)</i>","source":"機動戦士Gundam GQuuuuuuX · EP03 · 04:20"},{"jp":"わっちの<b><ruby>言<rt>い</rt></ruby>ったとおり</b>じゃろ?","speech":"わっちの言ったとおりじゃろ?","id":"<b>Persis seperti yang</b> kubilang, kan? <i>(〜とおりだ)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP11 · 11:05"},{"jp":"えー<ruby>私<rt>わたし</rt></ruby>は<b>ご<ruby>覧<rt>らん</rt></ruby>のとおり</b>の<ruby>行商人<rt>ぎょうしょうにん</rt></ruby>で　 <ruby>羊<rt>ひつじ</rt></ruby>は<ruby>商<rt>あきな</rt></ruby>っていません","speech":"えー私はご覧のとおりの行商人で羊は商っていません","id":"Eh, <b>seperti yang Anda lihat</b>, saya pedagang keliling, dan nggak berdagang domba. <i>(ご覧のとおり)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP08 · 03:22"},{"jp":"<ruby>座<rt>すわ</rt></ruby>れてよかったね<b><ruby>計画<rt>けいかく</rt></ruby>どおり</b>だぜ","speech":"座れてよかったね計画どおりだぜ","id":"Syukur bisa dapat duduk ya. <b>Sesuai rencana</b>! <i>(Ｎどおり)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 04:09"}]},{"id":"n4_b34_02","level":"N4","bab":34,"lokasi":"第34課","titleMain":"〜あとで","titleSub":["Ｖたあとで","Ｎのあとで"],"meaning":"Setelah… (urutan waktu: A selesai, lalu B)","formula":"Ｖ-<b>た</b> + <b>あとで</b>（終わっ<b>たあとで</b>）<br>Ｎ + <b>の あとで</b>（ご飯<b>のあとで</b>）<br><b>あとで</b> saja = nanti（あとで電話します）","nuance":"<ol><li>Fokus pada <b>urutan waktu</b>; bisa dipakai dengan kata benda.</li><li><b>〜てから</b> lebih menekankan A harus selesai dulu (persiapan) sebelum B.</li></ol>⚠️ KK selalu bentuk <b>た</b>: ×食べるあとで → ○食べたあとで. Kebalikannya: <b>Ｖる + まえに</b>.","examples":[{"jp":"<ruby>仕事<rt>しごと</rt></ruby>が<ruby>終<rt>お</rt></ruby>わったあとで、 <ruby>飲<rt>の</rt></ruby>みに<ruby>行<rt>い</rt></ruby>きませんか。","speech":"仕事が終わったあとで、飲みに行きませんか。","id":"<b>Setelah</b> kerjaan selesai, mau minum-minum bareng? <i>(Ｖたあとで)</i>"},{"jp":"<ruby>説明<rt>せつめい</rt></ruby>を<ruby>聞<rt>き</rt></ruby>いたあとで、 <ruby>質問<rt>しつもん</rt></ruby>してください。","speech":"説明を聞いたあとで、質問してください。","id":"Silakan bertanya <b>setelah</b> mendengarkan penjelasan. <i>(Ｖたあとで)</i>"},{"jp":"ご<ruby>飯<rt>はん</rt></ruby>のあとで、コーヒーを<ruby>飲<rt>の</rt></ruby>みます。","speech":"ご飯のあとで、コーヒーを飲みます。","id":"<b>Sesudah</b> makan, saya minum kopi. <i>(Ｎのあとで)</i>"},{"jp":"<ruby>新<rt>あたら</rt></ruby>しいのを<ruby>買<rt>か</rt></ruby>ったあとで、なくした<ruby>時計<rt>とけい</rt></ruby>が<ruby>見<rt>み</rt></ruby>つかりました。","speech":"新しいのを買ったあとで、なくした時計が見つかりました。","id":"<b>Setelah</b> beli yang baru, jam yang hilang malah ketemu. <i>(Ｖたあとで)</i>"}],"dialogs":[{"jp":"<ruby>市場<rt>いちば</rt></ruby>が<b><ruby>閉<rt>し</rt></ruby>まったあとで</b> <ruby>恐縮<rt>きょうしゅく</rt></ruby>なのですが...","speech":"市場が閉まったあとで恐縮なのですが...","id":"Maaf merepotkan <b>setelah</b> pasar <b>tutup</b>… <i>(Ｖたあとで)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP09 · 22:00"},{"jp":"じゃあ <b>バイトのあとで</b>いいから!","speech":"じゃあバイトのあとでいいから!","id":"Kalau gitu, <b>habis kerja part-time</b> juga nggak apa-apa! <i>(Ｎのあとで)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 08:46"},{"jp":"ご<ruby>飯<rt>はん</rt></ruby><b><ruby>食<rt>た</rt></ruby>べた<ruby>後<rt>あと</rt></ruby>で</b>な","speech":"ご飯食べた後でな","id":"<b>Setelah makan</b> ya. <i>(Ｖたあとで)</i>","source":"無職転生 ～異世界行ったら本気だす～ 第2クール · EP12 · 12:04"},{"jp":"まッ いいんじゃない?　<b><ruby>部活<rt>ぶかつ</rt></ruby>の<ruby>後<rt>あと</rt></ruby>で</b>なら<ruby>俺<rt>おれ</rt></ruby>もつきあうよ","speech":"まッいいんじゃない?　部活の後でなら俺もつきあうよ","id":"Ya, boleh aja kan? Kalau <b>setelah kegiatan klub</b>, aku juga ikut nemenin. <i>(Ｎのあとで)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP02 · 05:10"}]},{"id":"n4_b34_03","level":"N4","bab":34,"lokasi":"第34課","titleMain":"Ｖ１て／Ｖ１ないで Ｖ２","titleSub":["持って出かける","持たないで出かける"],"meaning":"(Melakukan V2) dengan V1 · (melakukan V2) tanpa V1 — cara/keadaan","formula":"Ｖ1-<b>て</b> + Ｖ2（傘を持っ<b>て</b>出かけます）= dengan<br>Ｖ1-<b>ない</b> + <b>で</b> + Ｖ2（傘を持た<b>ないで</b>出かけます）= tanpa","nuance":"<ol><li>V1 menjelaskan <b>cara/keadaan</b> saat V2 dilakukan; keduanya berlangsung bersamaan.</li><li>しょうゆをつけて食べる (dengan kecap) ↔ しょうゆをつけないで食べる (tanpa kecap).</li></ol>⚠️ ×持たなくて出かけた — <b>〜なくて</b> = sebab (S39). Versi tulis: <b>〜ずに</b> (持たずに).","examples":[{"jp":"しょうゆをつけて <ruby>食<rt>た</rt></ruby>べます。","speech":"しょうゆをつけて食べます。","id":"Dimakan <b>dengan</b> dicocol kecap asin. <i>(dengan)</i>"},{"jp":"しょうゆをつけないで <ruby>食<rt>た</rt></ruby>べます。","speech":"しょうゆをつけないで食べます。","id":"Dimakan <b>tanpa</b> kecap asin. <i>(tanpa)</i>"},{"jp":"<ruby>傘<rt>かさ</rt></ruby>を<ruby>持<rt>も</rt></ruby>たないで <ruby>出<rt>で</rt></ruby>かけました。","speech":"傘を持たないで出かけました。","id":"Aku keluar <b>tanpa bawa</b> payung. <i>(tanpa)</i>"},{"jp":"めがねをかけないで <ruby>本<rt>ほん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>みます。","speech":"めがねをかけないで本を読みます。","id":"Aku baca buku <b>tanpa pakai</b> kacamata. <i>(tanpa)</i>"},{"jp":"<ruby>辞書<rt>じしょ</rt></ruby>を<ruby>使<rt>つか</rt></ruby>わないで <ruby>新聞<rt>しんぶん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>みました。","speech":"辞書を使わないで新聞を読みました。","id":"Aku baca koran <b>tanpa pakai</b> kamus. <i>(tanpa)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby>たちに<ruby>何<rt>なん</rt></ruby>にも<b><ruby>言<rt>い</rt></ruby>わないで</b>　いきなりやめるとか<ruby>最後<rt>さいご</rt></ruby>だとか","speech":"私たちに何にも言わないでいきなりやめるとか最後だとか","id":"<b>Tanpa bilang</b> apa-apa ke kami, tiba-tiba ngomong berhenti lah, terakhir lah… <i>(tanpa)</i>","source":"ガールズバンドクライ · EP08 · 04:21"},{"jp":"でも お<ruby>金<rt>かね</rt></ruby><b><ruby>使<rt>つか</rt></ruby>わないで</b> <ruby>外<rt>そと</rt></ruby>って　ほんっと<ruby>退屈<rt>たいくつ</rt></ruby>なの","speech":"でもお金使わないで外ってほんっと退屈なの","id":"Tapi di luar <b>tanpa pakai</b> uang itu bener-bener ngebosenin. <i>(tanpa)</i>","source":"ガールズバンドクライ · EP09 · 07:01"},{"jp":"ノックも<b>しないで</b> <ruby>入<rt>はい</rt></ruby>り<ruby>込<rt>こ</rt></ruby>んで-　 <ruby>随分<rt>ずいぶん</rt></ruby>と<ruby>無礼<rt>ぶれい</rt></ruby>なやつなのよ","speech":"ノックもしないで入り込んで-　随分と無礼なやつなのよ","id":"Masuk <b>tanpa</b> ngetuk pintu segala — orang yang kurang ajar banget. <i>(tanpa)</i>","source":"Re:ゼロから始める異世界生活 · EP03 · 25:49"},{"jp":"<ruby>遠慮<rt>えんりょ</rt></ruby><b>しないで</b> <ruby>言<rt>い</rt></ruby>ってみて","speech":"遠慮しないで言ってみて","id":"Coba bilang aja <b>tanpa</b> sungkan. <i>(tanpa)</i>","source":"この素晴らしい世界に爆焔を！ · EP01 · 02:25"},{"jp":"<ruby>湖<rt>みずうみ</rt></ruby>の<ruby>周<rt>まわ</rt></ruby>りを<b><ruby>歩<rt>ある</rt></ruby>いて</b> <ruby>行<rt>い</rt></ruby>ってください","speech":"湖の周りを歩いて行ってください","id":"Silakan pergi <b>dengan jalan kaki</b> mengitari danau. <i>(Ｖて · dengan cara)</i>","source":"ゆるキャン△ · EP06 · 18:57"}]},{"id":"n4_b34_04","level":"N4","bab":34,"lokasi":"第34課","titleMain":"Ｖ１ないで、Ｖ２","titleSub":["どこも行かないで、うちにいる"],"meaning":"Bukannya V1, (malah/tapi) V2 · tidak V1, melainkan V2 — alih-alih","formula":"Ｖ1-<b>ない</b> + <b>で</b>、Ｖ2<br>（どこも行か<b>ないで</b>、うちにいます）<br>（バスに乗ら<b>ないで</b>、歩いて帰ります）","nuance":"<ol><li>Dari dua alternatif, V1 <b>tidak dipilih</b> dan V2 dilakukan sebagai gantinya.</li><li>Kasual: <b>〜てないで</b> (ばかりしてないで, 早く行こう) = jangan cuma…, mending….</li></ol>⚠️ Beda dengan \"tanpa\" (cara): di sana V1 & V2 bersamaan (傘を持たないで出かける); di sini V1 <b>diganti</b> V2. Bukan <b>〜ないでください</b> (tolong jangan).","examples":[{"jp":"<ruby>日曜日<rt>にちようび</rt></ruby>はどこも<ruby>行<rt>い</rt></ruby>かないで、うちでゆっくりします。","speech":"日曜日はどこも行かないで、うちでゆっくりします。","id":"Hari Minggu aku <b>nggak pergi ke mana-mana, tapi</b> santai di rumah. <i>(alih-alih)</i>"},{"jp":"バスに<ruby>乗<rt>の</rt></ruby>らないで、 <ruby>歩<rt>ある</rt></ruby>いて<ruby>帰<rt>かえ</rt></ruby>りました。","speech":"バスに乗らないで、歩いて帰りました。","id":"<b>Bukannya</b> naik bus, aku pulang jalan kaki. <i>(alih-alih)</i>"},{"jp":"<ruby>昨日<rt>きのう</rt></ruby>は<ruby>寝<rt>ね</rt></ruby>ないで、レポートを<ruby>書<rt>か</rt></ruby>きました。","speech":"昨日は寝ないで、レポートを書きました。","id":"Kemarin aku <b>nggak tidur, malah</b> nulis laporan. <i>(alih-alih)</i>"},{"jp":"<ruby>勉強<rt>べんきょう</rt></ruby>しないで、ゲームばかりしている。","speech":"勉強しないで、ゲームばかりしている。","id":"<b>Bukannya</b> belajar, malah main game terus. <i>(alih-alih)</i>"}],"dialogs":[{"jp":"<b><ruby>待<rt>ま</rt></ruby>たないで</b> こっちから<ruby>行<rt>い</rt></ruby>くの","speech":"待たないでこっちから行くの","id":"<b>Bukannya nunggu</b>, aku yang bakal datang duluan. <i>(alih-alih)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP09 · 14:08"},{"jp":"もう こんなことばっか<b>してないで</b> <ruby>早<rt>はや</rt></ruby>く<ruby>行<rt>い</rt></ruby>くわよ","speech":"もうこんなことばっかしてないで早く行くわよ","id":"Ih, <b>jangan cuma</b> ngelakuin ginian terus, ayo cepat berangkat! <i>(〜てないで · alih-alih)</i>","source":"トニカクカワイイ · EP12 · 13:52"},{"jp":"だからこういうこと<b>しないで</b> <ruby>私<rt>わたし</rt></ruby>のことを<ruby>思<rt>おも</rt></ruby>うならさっさと<ruby>寝<rt>ね</rt></ruby>てくれる?","speech":"だからこういうことしないで私のことを思うならさっさと寝てくれる?","id":"Jadi, <b>bukannya</b> ngelakuin hal kayak gini, kalau kamu mikirin aku, cepetan tidur deh? <i>(alih-alih)</i>","source":"トニカクカワイイ · EP12 · 10:39"}]},{"id":"n4_b35_01","level":"N4","bab":35,"lokasi":"第35課","titleMain":"条件形","titleSub":["〜ば","〜ければ","〜なら"],"meaning":"Kalau… / jika… (maka)… — syarat yang dibutuhkan agar hasil terjadi","formula":"Grup 1: -u → -e + <b>ば</b>（行<b>けば</b> ／ あ<b>れば</b>）<br>Grup 2: -る → <b>れば</b>（食べ<b>れば</b>） · する → <b>すれば</b> ／ 来る → <b>くれば</b><br>-ない → <b>なければ</b> · KS-i: -い → <b>ければ</b>（安<b>ければ</b> ／ いい → <b>よければ</b>）<br>KS-na / KB + <b>なら</b>（暇<b>なら</b> ／ 雨<b>なら</b>）","nuance":"<ol><li>Menekankan <b>syarat</b> → hasil; cocok untuk kebenaran umum/logis (春になれば桜が咲く).</li><li>Klausa ば berupa <b>keadaan</b> (KS, ある, potensial) → belakang boleh niat/permintaan (時間があれば来てください).</li></ol>⚠️ Klausa ば berupa <b>KK aksi</b> → belakang ×permintaan/ajakan (×東京へ行けば電話してください → ○行ったら). いい → <b>よければ</b> (bukan ×いければ).","examples":[{"jp":"<ruby>安<rt>やす</rt></ruby>ければ、 <ruby>買<rt>か</rt></ruby>います。","speech":"安ければ、買います。","id":"<b>Kalau murah</b>, kubeli. <i>(KS-i)</i>"},{"jp":"<ruby>春<rt>はる</rt></ruby>になれば、 <ruby>桜<rt>さくら</rt></ruby>が<ruby>咲<rt>さ</rt></ruby>きます。","speech":"春になれば、桜が咲きます。","id":"<b>Kalau</b> musim semi <b>tiba</b>, sakura mekar. <i>(kebenaran umum)</i>"},{"jp":"<ruby>天気<rt>てんき</rt></ruby>が<ruby>良<rt>よ</rt></ruby>ければ、 <ruby>明日<rt>あした</rt></ruby><ruby>行<rt>い</rt></ruby>きましょう。","speech":"天気が良ければ、明日行きましょう。","id":"<b>Kalau</b> cuacanya <b>bagus</b>, ayo pergi besok. <i>(keadaan → ajakan)</i>"},{"jp":"<ruby>時間<rt>じかん</rt></ruby>がなければ、 <ruby>来<rt>こ</rt></ruby>なくてもいいです。","speech":"時間がなければ、来なくてもいいです。","id":"<b>Kalau nggak ada</b> waktu, nggak datang juga nggak apa-apa. <i>(なければ)</i>"},{"jp":"このボタンを<ruby>押<rt>お</rt></ruby>せば、 <ruby>窓<rt>まど</rt></ruby>が<ruby>開<rt>あ</rt></ruby>きます。","speech":"このボタンを押せば、窓が開きます。","id":"<b>Kalau</b> tombol ini <b>ditekan</b>, jendelanya terbuka. <i>(KK · mekanisme)</i>"}],"dialogs":[{"jp":"<ruby>下手<rt>へた</rt></ruby>っぴでも<b><ruby>頑張<rt>がんば</rt></ruby>れば</b> <ruby>熱意<rt>ねつい</rt></ruby>は<ruby>伝<rt>つた</rt></ruby>わるって","speech":"下手っぴでも頑張れば熱意は伝わるって","id":"Katanya walau payah pun, <b>asal berusaha</b> semangatnya bakal tersampaikan. <i>(KK · syarat)</i>","source":"ぼっち・ざ・ろっく！ · EP05 · 07:40"},{"jp":"ここを<ruby>道<rt>みち</rt></ruby>なりに...　 <ruby>突<rt>つ</rt></ruby>き<ruby>当<rt>あ</rt></ruby>たりを<ruby>右<rt>みぎ</rt></ruby>に<b><ruby>行<rt>い</rt></ruby>けば</b> キャンプ<ruby>場<rt>じょう</rt></ruby>","speech":"ここを道なりに...　突き当たりを右に行けばキャンプ場","id":"Ikuti jalan ini… <b>kalau</b> belok kanan di ujung, sampai di tempat kemah. <i>(KK · petunjuk arah)</i>","source":"ゆるキャン△ · EP10 · 03:03"},{"jp":"<ruby>明日<rt>あした</rt></ruby>に<b>なれば</b> <ruby>分<rt>わ</rt></ruby>かるって","speech":"明日になれば分かるって","id":"<b>Kalau</b> udah besok, nanti juga ketahuan. <i>(なれば · pasti terjadi)</i>","source":"ガールズバンドクライ · EP04 · 04:47"},{"jp":"<ruby>何<rt>なに</rt></ruby>かできること<b>あれば</b> <ruby>手伝<rt>てつだ</rt></ruby>うけど","speech":"何かできることあれば手伝うけど","id":"<b>Kalau ada</b> yang bisa kulakuin, aku bantu kok. <i>(あれば · keadaan → niat)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP05 · 12:51"},{"jp":"<ruby>運<rt>うん</rt></ruby>が<b>よければ</b>だぞ","speech":"運がよければだぞ","id":"Itu <b>kalau</b> lagi <b>beruntung</b>, ya. <i>(よければ · KS-i)</i>","source":"狼と香辛料 · EP08 · 05:45"}]},{"id":"n4_b35_02","level":"N4","bab":35,"lokasi":"第35課","titleMain":"Ｎなら","titleSub":["温泉なら、〜がいいです"],"meaning":"Kalau (soal)… sih, … — memberi saran/info tentang topik yang baru disebut lawan bicara","formula":"Ｎ + <b>なら</b>、〜がいいです ／ 〜ですよ<br>（温泉<b>なら</b>、白馬がいいですよ）<br>Ｖる + <b>なら</b>（パソコンを買う<b>なら</b>、秋葉原がいい）","nuance":"<ol><li>Mengambil <b>topik dari omongan lawan bicara</b>, lalu memberi saran / info / pendapat.</li><li>Juga untuk membatasi: 赤いペン<b>なら</b>ある (kalau pulpen merah sih ada).</li></ol>⚠️ Bukan syarat logis seperti 〜ば — <b>なら</b> di sini merespons topik.","examples":[{"jp":"<ruby>温泉<rt>おんせん</rt></ruby>なら、 <ruby>白馬<rt>はくば</rt></ruby>がいいですよ。","speech":"温泉なら、白馬がいいですよ。","id":"<b>Kalau onsen</b>, Hakuba bagus lho. <i>(saran)</i>"},{"jp":"パソコンを<ruby>買<rt>か</rt></ruby>うなら、 <ruby>秋葉原<rt>あきはばら</rt></ruby>がいいですよ。","speech":"パソコンを買うなら、秋葉原がいいですよ。","id":"<b>Kalau mau beli</b> komputer, Akihabara bagus lho. <i>(Ｖるなら · saran)</i>"},{"jp":"<ruby>赤<rt>あか</rt></ruby>いペンならあるよ。","speech":"赤いペンならあるよ。","id":"<b>Kalau pulpen merah sih</b> ada. <i>(membatasi)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby><ruby>料理<rt>りょうり</rt></ruby>なら、すしが<ruby>一番<rt>いちばん</rt></ruby><ruby>好<rt>す</rt></ruby>きです。","speech":"日本料理なら、すしが一番好きです。","id":"<b>Kalau soal</b> masakan Jepang, aku paling suka sushi. <i>(topik)</i>"}],"dialogs":[{"jp":"<b>いろはなら</b> さっき<ruby>用<rt>よう</rt></ruby>があるからって<ruby>抜<rt>ぬ</rt></ruby>けたよ","speech":"いろはならさっき用があるからって抜けたよ","id":"<b>Kalau Iroha sih</b>, tadi dia cabut katanya ada urusan. <i>(topik dari lawan bicara)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP07 · 06:51"},{"jp":"そうだ <b><ruby>総武<rt>そうぶ</rt></ruby><ruby>高<rt>こう</rt></ruby>なら</b> <ruby>葉山<rt>はやま</rt></ruby><ruby>君<rt>くん</rt></ruby>って<ruby>知<rt>し</rt></ruby>ってる","speech":"そうだ総武高なら葉山君って知ってる","id":"Oh iya, <b>kalau</b> kamu <b>anak SMA Sobu</b>, kenal Hayama-kun? <i>(Ｎなら)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP03 · 17:30"},{"jp":"<b><ruby>豚串<rt>ぶたくし</rt></ruby>とかなら</b>あるよ<ruby>焼<rt>や</rt></ruby>き<ruby>鳥<rt>とり</rt></ruby>も!","speech":"豚串とかならあるよ焼き鳥も!","id":"<b>Kalau</b> sate babi <b>sih</b> ada! Yakitori juga! <i>(membatasi · ada kalau itu)</i>","source":"ゆるキャン△ · EP06 · 13:47"},{"jp":"けど<ruby>梨<rt>なし</rt></ruby>も<ruby>今<rt>いま</rt></ruby>の<ruby>時期<rt>じき</rt></ruby>は<ruby>出<rt>で</rt></ruby>てないのよね　まあ<b><ruby>桃<rt>もも</rt></ruby>なら</b> <ruby>缶詰<rt>かんづめ</rt></ruby>があるけど","speech":"けど梨も今の時期は出てないのよねまあ桃なら缶詰があるけど","id":"Tapi pir juga lagi nggak musim ya. Yah, <b>kalau persik sih</b> ada kalengan. <i>(membatasi)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP09 · 14:43"},{"jp":"<b><ruby>焼<rt>や</rt></ruby>くくらいなら</b> <ruby>任<rt>まか</rt></ruby>せてください","speech":"焼くくらいなら任せてください","id":"<b>Kalau</b> cuma manggang <b>sih</b>, serahkan ke kami. <i>(Ｖくらいなら)</i>","source":"ゆるキャン△ SEASON２ · EP11 · 11:37"}]},{"id":"n4_b35_03","level":"N4","bab":35,"lokasi":"第35課","titleMain":"疑問詞＋〜ばいいですか","titleSub":["どうすればいいですか"],"meaning":"Sebaiknya (aku) … apa / bagaimana / di mana? — minta petunjuk atau saran","formula":"Kata tanya + Ｖ-<b>ば</b> + <b>いいですか</b><br>（<b>どう</b>す<b>ればいいですか</b> ／ <b>どこで</b>買<b>えばいいですか</b>）<br>Jawaban: Ｖ-<b>ば</b> + <b>いいです</b> = cukup… saja","nuance":"<ol><li>Meminta <b>instruksi/saran</b>. Hampir sama dengan <b>〜たらいいですか</b> (S26).</li><li>Kasual: <b>どうすればいい?</b> ／ <b>何すればいいんだ?</b></li></ol>⚠️ <b>〜ばいいのに</b> artinya lain: \"padahal kalau… kan enak\" (menyayangkan).","examples":[{"jp":"どうすればいいですか。","speech":"どうすればいいですか。","id":"<b>Sebaiknya aku gimana?</b> <i>(minta saran)</i>"},{"jp":"<ruby>切符<rt>きっぷ</rt></ruby>はどこで<ruby>買<rt>か</rt></ruby>えばいいですか。","speech":"切符はどこで買えばいいですか。","id":"Tiketnya <b>sebaiknya dibeli di mana</b>? <i>(どこで)</i>"},{"jp":"だれに<ruby>聞<rt>き</rt></ruby>けばいいですか。","speech":"だれに聞けばいいですか。","id":"<b>Sebaiknya tanya ke siapa</b>? <i>(だれに)</i>"},{"jp":"このボタンを<ruby>押<rt>お</rt></ruby>せばいいです。","speech":"このボタンを押せばいいです。","id":"<b>Cukup tekan</b> tombol ini. <i>(jawaban 〜ばいいです)</i>"}],"dialogs":[{"jp":"そうだ あの<ruby>麦<rt>むぎ</rt></ruby>は<b>どうすればいい</b>?","speech":"そうだあの麦はどうすればいい?","id":"Oh iya, gandum itu <b>sebaiknya diapain</b>? <i>(どうすればいい)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP02 · 04:11"},{"jp":"カズマさん<b>どうすればいい</b>の?","speech":"カズマさんどうすればいいの?","id":"Kazuma-san, <b>kita harus gimana</b>? <i>(minta petunjuk)</i>","source":"この素晴らしい世界に祝福を！2 · EP05 · 20:23"},{"jp":"<ruby>雪乃<rt>ゆきの</rt></ruby><ruby>先輩<rt>せんぱい</rt></ruby><b><ruby>何<rt>なに</rt></ruby>からお<ruby>手伝<rt>てつだ</rt></ruby>いすればいいですか</b>","speech":"雪乃先輩何からお手伝いすればいいですか","id":"Yukino-senpai, <b>sebaiknya</b> kami <b>bantu mulai dari mana</b>? <i>(何から〜ばいいですか · sopan)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP12 · 05:19"},{"jp":"<ruby>付<rt>つ</rt></ruby>き<ruby>合<rt>あ</rt></ruby>うって<ruby>具体的<rt>ぐたいてき</rt></ruby>に<b><ruby>何<rt>なに</rt></ruby>すればいい</b>んだ?","speech":"付き合うって具体的に何すればいいんだ?","id":"Pacaran itu konkretnya <b>harus ngapain</b> sih? <i>(何すればいい)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP01 · 02:51"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<b>どこまで<ruby>頑張<rt>がんば</rt></ruby>れば いい</b>のですか...","speech":"私はどこまで頑張ればいいのですか...","id":"<b>Sampai sejauh mana</b> aku <b>harus berusaha</b>…? <i>(どこまで〜ばいい)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP08 · 22:37"}]},{"id":"n4_b35_04","level":"N4","bab":35,"lokasi":"第35課","titleMain":"〜ば〜ほど","titleSub":["〜すればするほど","〜ければ〜いほど"],"meaning":"Semakin… semakin…","formula":"Ｖ-<b>ば</b> + Ｖ-<b>る</b> + <b>ほど</b>（練習す<b>れば</b>練習する<b>ほど</b>）<br>KS-<b>ければ</b> + KS-<b>い</b> + <b>ほど</b>（安<b>ければ</b>安い<b>ほど</b>）<br>KS-na: 静か<b>なら</b>静かな<b>ほど</b>","nuance":"<ol><li>Kata yang sama <b>diulang</b>: bentuk ば + bentuk kamus + ほど.</li><li>Bagian belakang = perubahan/penilaian yang sebanding (上手になる, 便利だ, いい).</li></ol>⚠️ Bagian ば boleh dihilangkan: <b>練習するほど</b>上手になる (artinya sama).","examples":[{"jp":"<ruby>多<rt>おお</rt></ruby>ければ<ruby>多<rt>おお</rt></ruby>いほどいいです。","speech":"多ければ多いほどいいです。","id":"<b>Makin banyak makin</b> bagus. <i>(KS-i)</i>"},{"jp":"<ruby>練習<rt>れんしゅう</rt></ruby>すれば<ruby>練習<rt>れんしゅう</rt></ruby>するほど、 <ruby>上手<rt>じょうず</rt></ruby>になります。","speech":"練習すれば練習するほど、上手になります。","id":"<b>Makin banyak latihan, makin</b> jago. <i>(KK)</i>"},{"jp":"パソコンは<ruby>軽<rt>かる</rt></ruby>ければ<ruby>軽<rt>かる</rt></ruby>いほど <ruby>便利<rt>べんり</rt></ruby>です。","speech":"パソコンは軽ければ軽いほど便利です。","id":"Laptop itu <b>makin ringan makin</b> praktis. <i>(KS-i)</i>"},{"jp":"<ruby>考<rt>かんが</rt></ruby>えれば<ruby>考<rt>かんが</rt></ruby>えるほど、わからなくなる。","speech":"考えれば考えるほど、わからなくなる。","id":"<b>Makin dipikir, makin</b> nggak ngerti. <i>(KK)</i>"}],"dialogs":[{"jp":"<ruby>時間<rt>じかん</rt></ruby>が<b>たてば たつほど</b>","speech":"時間がたてばたつほど","id":"<b>Makin lama</b> waktu berlalu… <i>(KK)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 16:01"},{"jp":"<b><ruby>続<rt>つづ</rt></ruby>ければ<ruby>続<rt>つづ</rt></ruby>けるほど</b> <ruby>結果<rt>けっか</rt></ruby>ははっきりしてくるからね","speech":"続ければ続けるほど結果ははっきりしてくるからね","id":"<b>Makin</b> terus dijalani, <b>makin</b> jelas hasilnya kok. <i>(KK)</i>","source":"ガールズバンドクライ · EP07 · 16:46"},{"jp":"その<ruby>企<rt>たくら</rt></ruby>みが<b><ruby>大<rt>おお</rt></ruby>きければ<ruby>大<rt>おお</rt></ruby>きいほど</b>...","speech":"その企みが大きければ大きいほど...","id":"<b>Makin besar</b> rencana licik itu… <i>(KS-i)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP10 · 08:22"},{"jp":"<b><ruby>知<rt>し</rt></ruby>れば<ruby>知<rt>し</rt></ruby>るほど</b> かわいいんですよねえ!","speech":"知れば知るほどかわいいんですよねえ!","id":"<b>Makin</b> kenal, <b>makin</b> imut, tahu nggak! <i>(KK)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP09 · 04:08"}]},{"id":"n4_b36_01","level":"N4","bab":36,"lokasi":"第36課","titleMain":"〜ように","titleSub":["忘れないように、〜","泳げるように、〜"],"meaning":"Supaya… / agar… / biar… — melakukan sesuatu demi tercapainya suatu keadaan","formula":"Ｖ-potensial + <b>ように</b>（泳げる<b>ように</b>）<br>Ｖる (non-kehendak) + <b>ように</b>（見える<b>ように</b>）<br>Ｖ-ない + <b>ように</b>（忘れない<b>ように</b>）<br>Pola: [keadaan target]<b>ように</b>、[tindakan sadar]","nuance":"<ol><li>Target di luar kendali langsung: <b>potensial</b>, KK <b>non-kehendak</b> (見える, わかる, なる), atau <b>〜ない</b>.</li><li>Subjek target & tindakan boleh beda (後ろの人に見えるように、私が大きく書く).</li></ol>⚠️ ×泳ぐように練習する → ○泳げるように. <b>〜ために</b> (S42) = tujuan dengan KK kehendak & subjek sama.","examples":[{"jp":"<ruby>忘<rt>わす</rt></ruby>れないように、メモします。","speech":"忘れないように、メモします。","id":"Aku catat <b>supaya nggak lupa</b>. <i>(ないように)</i>"},{"jp":"<ruby>速<rt>はや</rt></ruby>く<ruby>泳<rt>およ</rt></ruby>げるように、 <ruby>毎日<rt>まいにち</rt></ruby><ruby>練習<rt>れんしゅう</rt></ruby>しています。","speech":"速く泳げるように、毎日練習しています。","id":"Aku latihan tiap hari <b>supaya bisa</b> berenang cepat. <i>(potensial)</i>"},{"jp":"<ruby>後<rt>うし</rt></ruby>ろの<ruby>人<rt>ひと</rt></ruby>にも<ruby>見<rt>み</rt></ruby>えるように、 <ruby>字<rt>じ</rt></ruby>を<ruby>大<rt>おお</rt></ruby>きく<ruby>書<rt>か</rt></ruby>いてください。","speech":"後ろの人にも見えるように、字を大きく書いてください。","id":"Tolong tulis besar-besar <b>supaya</b> orang di belakang juga <b>bisa lihat</b>. <i>(non-kehendak)</i>"},{"jp":"<ruby>風邪<rt>かぜ</rt></ruby>をひかないように、セーターを<ruby>着<rt>き</rt></ruby>ます。","speech":"風邪をひかないように、セーターを着ます。","id":"Aku pakai sweter <b>biar nggak</b> masuk angin. <i>(ないように)</i>"}],"dialogs":[{"jp":"<ruby>脇見<rt>わきみ</rt></ruby>に<b>ならないように</b> <ruby>気<rt>き</rt></ruby>をつけるんだよ","speech":"脇見にならないように気をつけるんだよ","id":"Hati-hati ya, <b>biar nggak</b> lengah lihat ke samping. <i>(ないように)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 13:29"},{"jp":"<ruby>当然<rt>とうぜん</rt></ruby>だ お<ruby>前<rt>まえ</rt></ruby>も<ruby>唆<rt>そそのか</rt></ruby><b>されないように</b> <ruby>注意<rt>ちゅうい</rt></ruby>しろ","speech":"当然だお前も唆されないように注意しろ","id":"Jelas. Kamu juga hati-hati <b>supaya nggak</b> terhasut. <i>(ないように)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP10 · 21:36"},{"jp":"まあ<ruby>外<rt>はず</rt></ruby><b>れないように</b> <ruby>誰<rt>だれ</rt></ruby>か<ruby>蹴落<rt>けお</rt></ruby>とすよな","speech":"まあ外れないように誰か蹴落とすよな","id":"Yah, <b>biar nggak</b> tersingkir, pasti ada yang dijatuhkan. <i>(ないように)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP04 · 12:04"},{"jp":"<ruby>来年<rt>らいねん</rt></ruby><ruby>以降<rt>いこう</rt></ruby> お<ruby>前<rt>まえ</rt></ruby>らも<ruby>納得<rt>なっとく</rt></ruby>できるプロムが<b>できるように</b> <ruby>働<rt>はたら</rt></ruby>きかけると<ruby>約束<rt>やくそく</rt></ruby>しよう","speech":"来年以降お前らも納得できるプロムができるように働きかけると約束しよう","id":"Aku janji akan mengusahakan <b>supaya</b> tahun depan dan seterusnya <b>bisa diadakan</b> prom yang kalian setujui. <i>(potensial + ように)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP07 · 02:52"},{"jp":"それから<ruby>霜<rt>しも</rt></ruby>が<b><ruby>降<rt>お</rt></ruby>りないように</b> <ruby>祈<rt>いの</rt></ruby>る<ruby>祭<rt>まつ</rt></ruby>りと","speech":"それから霜が降りないように祈る祭りと","id":"Lalu festival berdoa <b>supaya</b> embun beku <b>nggak turun</b>… <i>(non-kehendak · subjek beda)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP13 · 05:10"}]},{"id":"n4_b36_02","level":"N4","bab":36,"lokasi":"第36課","titleMain":"〜ようになります","titleSub":["〜ようになりました"],"meaning":"Jadi (bisa)… / mulai (jadi)… — perubahan kemampuan atau kebiasaan","formula":"Ｖ-potensial + <b>ようになりました</b>（話せる<b>ようになりました</b>）= jadi bisa<br>Ｖる + <b>ようになりました</b>（食べる<b>ようになりました</b>）= jadi melakukan<br>Kebalikan: Ｖ-<b>なくなりました</b>（泳げ<b>なくなりました</b>）","nuance":"<ol><li><b>Kemampuan</b>: dulu tidak bisa → sekarang bisa.</li><li><b>Kebiasaan</b>: dulu tidak → sekarang jadi melakukan.</li></ol>⚠️ KB/KS cukup <b>〜になる / 〜くなる</b> (上手になる). <b>ようになる</b> = berubah sendiri; <b>ようにする</b> = sengaja diusahakan. Sering dengan <b>やっと</b> (akhirnya).","examples":[{"jp":"やっと<ruby>日本語<rt>にほんご</rt></ruby>が<ruby>話<rt>はな</rt></ruby>せるようになりました。","speech":"やっと日本語が話せるようになりました。","id":"Akhirnya aku <b>jadi bisa</b> bicara bahasa Jepang. <i>(kemampuan)</i>"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>練習<rt>れんしゅう</rt></ruby>して、 <ruby>自転車<rt>じてんしゃ</rt></ruby>に<ruby>乗<rt>の</rt></ruby>れるようになりました。","speech":"毎日練習して、自転車に乗れるようになりました。","id":"Latihan tiap hari, aku <b>jadi bisa</b> naik sepeda. <i>(kemampuan)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>へ<ruby>来<rt>き</rt></ruby>てから、 <ruby>朝<rt>あさ</rt></ruby>ご<ruby>飯<rt>はん</rt></ruby>を<ruby>食<rt>た</rt></ruby>べるようになりました。","speech":"日本へ来てから、朝ご飯を食べるようになりました。","id":"Sejak datang ke Jepang, aku <b>jadi</b> sarapan. <i>(kebiasaan)</i>"},{"jp":"<ruby>泳<rt>およ</rt></ruby>げるようになりましたか。","speech":"泳げるようになりましたか。","id":"Sudah <b>bisa berenang</b>? <i>(tanya perubahan)</i>"}],"dialogs":[{"jp":"どうやって こんなに<ruby>料理<rt>りょうり</rt></ruby>を<b><ruby>作<rt>つく</rt></ruby>れるようになった</b>んだ?","speech":"どうやってこんなに料理を作れるようになったんだ?","id":"Gimana caranya kamu <b>jadi bisa</b> masak sebanyak ini? <i>(kemampuan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP04 · 08:27"},{"jp":"<ruby>今度<rt>こんど</rt></ruby>こそ ちゃんと ギター<b><ruby>弾<rt>ひ</rt></ruby>けるようになって</b>","speech":"今度こそちゃんとギター弾けるようになって","id":"Kali ini aku mau <b>jadi bisa</b> main gitar dengan bener… <i>(kemampuan)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 08:35"},{"jp":"<ruby>狼<rt>おおかみ</rt></ruby>は そのあと<ruby>羊<rt>ひつじ</rt></ruby>をうまく<b><ruby>扱<rt>あつか</rt></ruby>えるようになった</b>の?","speech":"狼はそのあと羊をうまく扱えるようになったの?","id":"Terus si serigala <b>jadi bisa</b> ngurus domba dengan baik nggak? <i>(kemampuan · tanya)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP13 · 23:18"},{"jp":"<ruby>去年<rt>きょねん</rt></ruby>から<ruby>原付<rt>げんつ</rt></ruby>きで いろんな<ruby>所<rt>ところ</rt></ruby><b><ruby>行<rt>い</rt></ruby>くようになった</b>からじゃない?","speech":"去年から原付きでいろんな所行くようになったからじゃない?","id":"Bukannya karena sejak tahun lalu kamu <b>jadi sering pergi</b> ke banyak tempat naik motor? <i>(kebiasaan)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 10:40"},{"jp":"いつかのし<ruby>上<rt>あ</rt></ruby>がって　 <ruby>自分<rt>じぶん</rt></ruby>たちのやりたいことが<b>できるようになる</b>","speech":"いつかのし上がって自分たちのやりたいことができるようになる","id":"Suatu hari kita naik dan <b>jadi bisa</b> ngelakuin apa yang kita mau. <i>(kemampuan · masa depan)</i>","source":"ガールズバンドクライ · EP05 · 16:25"}]},{"id":"n4_b36_03","level":"N4","bab":36,"lokasi":"第36課","titleMain":"〜ようにします","titleSub":["〜ようにしています","〜ようにしてください"],"meaning":"Berusaha (agar)… / membiasakan diri… · tolong usahakan…","formula":"Ｖる / Ｖない + <b>ようにしています</b> = kebiasaan yang dijaga<br>Ｖる / Ｖない + <b>ようにします</b> = niat mulai sekarang<br>Ｖる / Ｖない + <b>ようにしてください</b> = minta orang lain berusaha","nuance":"<ol><li><b>ようにしています</b>: usaha sadar yang sudah jadi kebiasaan (野菜を食べるようにしています).</li><li><b>ようにします</b>: janji/niat (遅れないようにします).</li><li><b>ようにしてください</b>: lebih lembut dari 〜てください, untuk kebiasaan/kehati-hatian.</li></ol>⚠️ Bukan untuk aksi sekali yang langsung bisa dilakukan (×今すぐ窓を開けるようにしてください → ○開けてください).","examples":[{"jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>野菜<rt>やさい</rt></ruby>を<ruby>食<rt>た</rt></ruby>べるようにしています。","speech":"毎日野菜を食べるようにしています。","id":"Aku <b>membiasakan diri</b> makan sayur tiap hari. <i>(kebiasaan)</i>"},{"jp":"<ruby>甘<rt>あま</rt></ruby>い<ruby>物<rt>もの</rt></ruby>を<ruby>食<rt>た</rt></ruby>べないようにしてください。","speech":"甘い物を食べないようにしてください。","id":"<b>Tolong usahakan jangan</b> makan yang manis-manis. <i>(permintaan)</i>"},{"jp":"これからは、<ruby>遅<rt>おく</rt></ruby>れないようにします。","speech":"これからは、遅れないようにします。","id":"Mulai sekarang <b>saya akan berusaha nggak</b> telat. <i>(niat)</i>"},{"jp":"<ruby>寝<rt>ね</rt></ruby>る<ruby>前<rt>まえ</rt></ruby>にスマホを<ruby>見<rt>み</rt></ruby>ないようにしています。","speech":"寝る前にスマホを見ないようにしています。","id":"Aku <b>berusaha nggak</b> lihat HP sebelum tidur. <i>(kebiasaan)</i>"},{"jp":"あしたは<ruby>８時<rt>はちじ</rt></ruby>までに<ruby>来<rt>く</rt></ruby>るようにしてください。","speech":"あしたは８時までに来るようにしてください。","id":"Besok <b>tolong usahakan</b> datang sebelum jam 8. <i>(permintaan)</i>"}],"dialogs":[{"jp":"<ruby>絶対<rt>ぜったい</rt></ruby>に<b><ruby>落<rt>お</rt></ruby>ちないようにする</b>","speech":"絶対に落ちないようにする","id":"Aku <b>bakal berusaha</b> sungguh-sungguh <b>supaya nggak</b> jatuh. <i>(ようにする · niat)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP12 · 06:56"},{"jp":"<ruby>部屋<rt>へや</rt></ruby>は あんまり<b><ruby>見<rt>み</rt></ruby>ないようにはした</b>ぞ","speech":"部屋はあんまり見ないようにはしたぞ","id":"Aku udah <b>berusaha nggak</b> terlalu ngelihatin kamarnya kok. <i>(ようにした · usaha)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP11 · 09:24"},{"jp":"ねっ ヒッキー　 <ruby>逃<rt>に</rt></ruby>げ<ruby>出<rt>だ</rt></ruby>さ<b>ないようにする</b>だけの<ruby>日々<rt>ひび</rt></ruby>","speech":"ねっヒッキー逃げ出さないようにするだけの日々","id":"Ya kan, Hikki — hari-hari yang isinya cuma <b>berusaha nggak</b> kabur. <i>(usaha terus-menerus)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP06 · 00:21"},{"jp":"ならばそれが<ruby>覚<rt>さ</rt></ruby>めないように<ruby>手<rt>て</rt></ruby>は<b><ruby>叩<rt>たた</rt></ruby>かないようにしないと</b>な","speech":"ならばそれが覚めないように手は叩かないようにしないとな","id":"Kalau begitu, aku <b>harus berusaha nggak</b> tepuk tangan biar itu nggak buyar. <i>(ようにしないと)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP07 · 15:30"},{"jp":"そうならない<b>ようにはしている</b>つもり","speech":"そうならないようにはしているつもり","id":"Aku sih merasa udah <b>berusaha</b> biar nggak jadi begitu. <i>(ようにしている)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP09 · 10:04"}]},{"id":"n4_b37_01","level":"N4","bab":37,"lokasi":"第37課","titleMain":"受身形","titleSub":["Ｎ１は Ｎ２に 〜られる"],"meaning":"Di-… (oleh N2) — orang menerima tindakan dari orang lain (pasif langsung)","formula":"Grup 1: -u → -a + <b>れる</b>（書<b>かれる</b> ／ 言う → 言<b>われる</b>）<br>Grup 2: -る → <b>られる</b>（ほめ<b>られる</b>） · する → <b>される</b> ／ 来る → <b>こられる</b><br>Ｎ1(orang)<b>は</b> Ｎ2(pelaku)<b>に</b> + 受身形（私は 先生<b>に</b> ほめ<b>られました</b>）","nuance":"<ol><li>Sudut pandang <b>orang yang dikenai</b> tindakan; pelaku ditandai <b>に</b>.</li><li>Bisa positif (ほめられる, 誘われる) atau negatif (しかられる, 怒られる).</li></ol>⚠️ Grup 2 pasif = potensial (食べられる): bedakan lewat konteks & <b>に</b> pelaku. Pasif juga dipakai sebagai bahasa hormat (S49).","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>部長<rt>ぶちょう</rt></ruby>にほめられました。","speech":"私は部長にほめられました。","id":"Aku <b>dipuji</b> oleh manajer. <i>(positif)</i>"},{"jp":"<ruby>子<rt>こ</rt></ruby>どものとき、よく<ruby>母<rt>はは</rt></ruby>にしかられました。","speech":"子どものとき、よく母にしかられました。","id":"Waktu kecil, aku sering <b>dimarahi</b> ibu. <i>(negatif)</i>"},{"jp":"<ruby>友達<rt>ともだち</rt></ruby>に<ruby>結婚式<rt>けっこんしき</rt></ruby>に<ruby>招待<rt>しょうたい</rt></ruby>されました。","speech":"友達に結婚式に招待されました。","id":"Aku <b>diundang</b> teman ke pesta pernikahannya. <i>(する → される)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>に<ruby>名前<rt>なまえ</rt></ruby>を<ruby>呼<rt>よ</rt></ruby>ばれました。","speech":"先生に名前を呼ばれました。","id":"Namaku <b>dipanggil</b> guru. <i>(Grup 1)</i>"}],"dialogs":[{"jp":"この<ruby>前<rt>まえ</rt></ruby>なんて クラスの<ruby>子<rt>こ</rt></ruby>に<ruby>放課後<rt>ほうかご</rt></ruby><ruby>遊<rt>あそ</rt></ruby>ぼうって<b><ruby>誘<rt>さそ</rt></ruby>われた</b>とき...","speech":"この前なんてクラスの子に放課後遊ぼうって誘われたとき...","id":"Waktu itu, pas dia <b>diajak</b> anak sekelas main sepulang sekolah… <i>(Ｎに誘われる)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 01:21"},{"jp":"<ruby>保護者会<rt>ほごしゃかい</rt></ruby>に めっちゃ<b><ruby>怒<rt>おこ</rt></ruby>られた</b>らしいよ","speech":"保護者会にめっちゃ怒られたらしいよ","id":"Katanya dia <b>dimarahin</b> habis-habisan sama perkumpulan orang tua. <i>(Ｎに怒られる)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 21:07"},{"jp":"わっちはな<ruby>大昔<rt>おおむかし</rt></ruby>この<ruby>村<rt>むら</rt></ruby>の<ruby>青年<rt>せいねん</rt></ruby>に<b><ruby>頼<rt>たの</rt></ruby>まれた</b>んじゃ","speech":"わっちはな大昔この村の青年に頼まれたんじゃ","id":"Aku ini, dulu sekali, <b>dimintai</b> tolong oleh seorang pemuda desa ini. <i>(Ｎに頼まれる)</i>","source":"狼と香辛料 · EP01 · 19:08"},{"jp":"<ruby>次<rt>つぎ</rt></ruby>は お<ruby>母<rt>かあ</rt></ruby>さんに<b><ruby>頼<rt>たの</rt></ruby>まれた</b> <ruby>掛川<rt>かけがわ</rt></ruby>のお<ruby>茶屋<rt>ちゃや</rt></ruby>さんだな","speech":"次はお母さんに頼まれた掛川のお茶屋さんだな","id":"Berikutnya toko teh di Kakegawa yang <b>dititipkan</b> Ibu. <i>(Ｎに頼まれた + KB)</i>","source":"ゆるキャン△ SEASON２ · EP02 · 01:09"},{"jp":"<ruby>本当<rt>ほんとう</rt></ruby>に<b><ruby>褒<rt>ほ</rt></ruby>められたくて</b> いい<ruby>子<rt>こ</rt></ruby>にしてただけなので","speech":"本当に褒められたくていい子にしてただけなので","id":"Aku cuma jadi anak baik karena beneran pengin <b>dipuji</b>. <i>(受身形 + たい)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP11 · 15:57"}]},{"id":"n4_b37_02","level":"N4","bab":37,"lokasi":"第37課","titleMain":"受身形","titleSub":["Ｎ１は Ｎ２に Ｎ３を 〜られる","雨に降られる"],"meaning":"(Barang/bagian tubuh)-ku di-… oleh N2 — pasif \"kena\", nuansa apes/dirugikan","formula":"Ｎ1(orang)<b>は</b> Ｎ2(pelaku)<b>に</b> Ｎ3(milik N1)<b>を</b> + 受身形<br>（私は 泥棒<b>に</b> 時計<b>を</b> 盗<b>まれました</b>）<br>KK intransitif: 雨<b>に</b>降<b>られる</b> ／ 子どもに泣<b>かれる</b>","nuance":"<ol><li>Yang dikenai = <b>milik</b> N1 (barang, bagian tubuh), tapi subjeknya tetap <b>orangnya</b> karena dia yang merasakan akibat.</li><li>Hampir selalu <b>merugikan / menjengkelkan</b> (迷惑の受身).</li></ol>⚠️ ×私の足は誰かに踏まれました → ○私は誰かに<b>足を</b>踏まれました. Pelaku boleh dihilangkan (財布をとられた).","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>誰<rt>だれ</rt></ruby>かに<ruby>足<rt>あし</rt></ruby>を<ruby>踏<rt>ふ</rt></ruby>まれました。","speech":"私は誰かに足を踏まれました。","id":"Kakiku <b>diinjak</b> seseorang. <i>(bagian tubuh)</i>"},{"jp":"<ruby>泥棒<rt>どろぼう</rt></ruby>に<ruby>時計<rt>とけい</rt></ruby>を<ruby>盗<rt>ぬす</rt></ruby>まれました。","speech":"泥棒に時計を盗まれました。","id":"Jamku <b>dicuri</b> maling. <i>(barang · rugi)</i>"},{"jp":"<ruby>弟<rt>おとうと</rt></ruby>にパソコンを<ruby>壊<rt>こわ</rt></ruby>されました。","speech":"弟にパソコンを壊されました。","id":"Laptopku <b>dirusak</b> adikku. <i>(barang · rugi)</i>"},{"jp":"<ruby>電車<rt>でんしゃ</rt></ruby>の<ruby>中<rt>なか</rt></ruby>で<ruby>財布<rt>さいふ</rt></ruby>をとられました。","speech":"電車の中で財布をとられました。","id":"Dompetku <b>dicopet</b> di dalam kereta. <i>(pelaku dihilangkan)</i>"},{"jp":"<ruby>帰<rt>かえ</rt></ruby>りに<ruby>雨<rt>あめ</rt></ruby>に<ruby>降<rt>ふ</rt></ruby>られて、 <ruby>困<rt>こま</rt></ruby>りました。","speech":"帰りに雨に降られて、困りました。","id":"Pas pulang aku <b>kehujanan</b>, repot deh. <i>(intransitif · apes)</i>"}],"dialogs":[{"jp":"<ruby>粉<rt>こな</rt></ruby>を<b><ruby>盗<rt>ぬす</rt></ruby>まれない</b>ように<ruby>気<rt>き</rt></ruby>をつけな","speech":"粉を盗まれないように気をつけな","id":"Hati-hati biar tepungmu nggak <b>dicuri</b> orang. <i>(Ｎを盗まれる)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP21 · 12:12"},{"jp":"だまされた?　 <ruby>銀貨<rt>ぎんか</rt></ruby>10<ruby>枚<rt>まい</rt></ruby>を<b>だまし<ruby>取<rt>と</rt></ruby>られた</b> ということか?","speech":"だまされた?　銀貨10枚をだまし取られたということか?","id":"Ditipu? Maksudnya sepuluh keping perakku <b>ditipu dan diambil</b>? <i>(Ｎを〜られる · rugi)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP03 · 20:38"},{"jp":"<ruby>周<rt>あまね</rt></ruby>くんは かっこいいから⸺　 <ruby>他<rt>ほか</rt></ruby>の<ruby>人<rt>ひと</rt></ruby>に<b><ruby>取<rt>と</rt></ruby>られたら</b> どうしようって<ruby>思<rt>おも</rt></ruby>ってましたし","speech":"周くんはかっこいいから⸺　他の人に取られたらどうしようって思ってましたし","id":"Amane-kun kan keren, jadi aku takut gimana kalau <b>direbut</b> orang lain. <i>(Ｎに取られる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP12 · 20:37"},{"jp":"<ruby>途中<rt>とちゅう</rt></ruby><ruby>雨<rt>あめ</rt></ruby>に<b><ruby>降<rt>ふ</rt></ruby>られて</b>にもかかわらず　まったく<ruby>失<rt>うしな</rt></ruby>われていない<ruby>艶<rt>つや</rt></ruby>を<ruby>見<rt>み</rt></ruby>てもらいたい","speech":"途中雨に降られてにもかかわらずまったく失われていない艶を見てもらいたい","id":"Walau di jalan <b>kehujanan</b>, coba lihat kilaunya yang sama sekali nggak pudar. <i>(雨に降られる · intransitif)</i>","source":"狼と香辛料 · EP03 · 07:07"},{"jp":"サキュバスには<b><ruby>逃<rt>に</rt></ruby>げられました</b>ね","speech":"サキュバスには逃げられましたね","id":"Succubus-nya <b>kabur</b> ya (kita kecolongan). <i>(intransitif · apes)</i>","source":"この素晴らしい世界に祝福を！ · EP09 · 19:58"}]},{"id":"n4_b37_03","level":"N4","bab":37,"lokasi":"第37課","titleMain":"受身形","titleSub":["Ｎが 〜られる","Ｎによって","Ｎから・Ｎで"],"meaning":"Di-… (oleh orang banyak/umum) · によって = oleh (pencipta/penemu) · から/で = dibuat dari…","formula":"Ｎ(benda)<b>が／は</b> + 受身形（この本は世界中で読<b>まれています</b>）<br>Pencipta: Ｎ<b>によって</b> + 書かれる／発明される／建てられる<br>Bahan: Ｎ<b>から</b> 造られる (berubah) ／ Ｎ<b>で</b> 造られる (terlihat)","nuance":"<ol><li><b>Benda/acara</b> jadi subjek ketika pelaku tidak penting / orang banyak (使われている, 開かれる, 呼ばれている).</li><li><b>によって</b>: pelaku untuk menciptakan, menemukan, membangun, menulis.</li><li><b>から</b> = bahan berubah (ビールは麦から); <b>で</b> = bahan masih terlihat (木で造られた机).</li></ol>⚠️ Pelaku biasa pakai <b>に</b> (先生にほめられた); pencipta pakai <b>によって</b> (ベルによって発明された).","examples":[{"jp":"この<ruby>本<rt>ほん</rt></ruby>は<ruby>世界中<rt>せかいじゅう</rt></ruby>で<ruby>読<rt>よ</rt></ruby>まれています。","speech":"この本は世界中で読まれています。","id":"Buku ini <b>dibaca</b> di seluruh dunia. <i>(umum)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>でもビールが<ruby>造<rt>つく</rt></ruby>られています。","speech":"日本でもビールが造られています。","id":"Di Jepang juga bir <b>diproduksi</b>. <i>(umum)</i>"},{"jp":"「 <ruby>源氏物語<rt>げんじものがたり</rt></ruby>」は<ruby>紫式部<rt>むらさきしきぶ</rt></ruby>によって<ruby>書<rt>か</rt></ruby>かれました。","speech":"「源氏物語」は紫式部によって書かれました。","id":"\"Hikayat Genji\" <b>ditulis oleh</b> Murasaki Shikibu. <i>(によって)</i>"},{"jp":"ビールは<ruby>麦<rt>むぎ</rt></ruby>から<ruby>造<rt>つく</rt></ruby>られます。","speech":"ビールは麦から造られます。","id":"Bir <b>dibuat dari</b> gandum. <i>(から · bahan berubah)</i>"},{"jp":"このお<ruby>寺<rt>てら</rt></ruby>は<ruby>約<rt>やく</rt></ruby>６００<ruby>年前<rt>ねんまえ</rt></ruby>に<ruby>建<rt>た</rt></ruby>てられました。","speech":"このお寺は約６００年前に建てられました。","id":"Kuil ini <b>dibangun</b> sekitar 600 tahun lalu. <i>(umum)</i>"}],"dialogs":[{"jp":"<ruby>達磨<rt>だるま</rt></ruby><ruby>火山<rt>かざん</rt></ruby>の<ruby>噴火<rt>ふんか</rt></ruby><b>によって<ruby>作<rt>つく</rt></ruby>られた</b>-　なだらかな<ruby>高原<rt>こうげん</rt></ruby>","speech":"達磨火山の噴火によって作られた-　なだらかな高原","id":"Dataran tinggi landai yang <b>terbentuk oleh</b> letusan gunung Daruma. <i>(によって)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 10:16"},{"jp":"キャベンディッシュの<ruby>慈愛<rt>じあい</rt></ruby>の<ruby>精神<rt>せいしん</rt></ruby>は-　 <ruby>彼女<rt>かのじょ</rt></ruby><b>によって<ruby>作<rt>つく</rt></ruby>られた</b>","speech":"キャベンディッシュの慈愛の精神は-　彼女によって作られた","id":"Semangat kasih keluarga Cavendish <b>diciptakan oleh</b> dia. <i>(によって · pencipta)</i>","source":"リトルウィッチアカデミア (TV) · EP20 · 13:54"},{"jp":"<ruby>魔法<rt>まほう</rt></ruby><b>によって<ruby>作<rt>つく</rt></ruby>られた</b> <ruby>複製体<rt>ふくせいたい</rt></ruby>だな","speech":"魔法によって作られた複製体だな","id":"Ini replika yang <b>dibuat dengan</b> sihir ya. <i>(によって · sarana)</i>","source":"葬送のフリーレン · EP23 · 20:55"},{"jp":"<ruby>燃<rt>も</rt></ruby>える<ruby>葡萄酒<rt>ぶどうしゅ</rt></ruby>と<b><ruby>呼<rt>よ</rt></ruby>ばれている</b>やつだ","speech":"燃える葡萄酒と呼ばれているやつだ","id":"Itu yang <b>disebut</b> \"anggur yang menyala\". <i>(umum · 呼ばれている)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP01 · 11:37"},{"jp":"そう アレキサンマルコ<ruby>教会<rt>きょうかい</rt></ruby>っていう<ruby>丘<rt>おか</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>のもう<b><ruby>使<rt>つか</rt></ruby>われていない</b> <ruby>教会<rt>きょうかい</rt></ruby>","speech":"そうアレキサンマルコ教会っていう丘の上のもう使われていない教会","id":"Iya, Gereja Alexanmarco — gereja di atas bukit yang udah <b>nggak dipakai</b> lagi. <i>(benda · 使われている)</i>","source":"トニカクカワイイ · EP04 · 21:33"}]},{"id":"n4_b38_01","level":"N4","bab":38,"lokasi":"第38課","titleMain":"〜のは＋形容詞","titleSub":["〜するのはおもしろい"],"meaning":"(Kegiatan) …-nya itu (seru / susah / bahaya…)","formula":"Ｖ-biasa + <b>の</b> = kegiatan (kata benda)<br>Ｖ-biasa + <b>のは</b> + KS penilaian<br>（テニスをする<b>のは</b>おもしろいです）","nuance":"<ol><li>Kegiatan dijadikan <b>topik</b>, lalu dinilai: おもしろい, 難しい, 楽しい, 危ない, 大変, 恥ずかしい.</li><li>の bisa diganti <b>こと</b> (lebih kaku): 勉強すること<b>は</b>楽しい.</li></ol>⚠️ ×テニスをするはおもしろい — KK wajib diberi <b>の</b> dulu sebelum partikel.","examples":[{"jp":"テニスをするのはおもしろいです。","speech":"テニスをするのはおもしろいです。","id":"<b>Main tenis itu</b> seru. <i>(のは＋KS)</i>"},{"jp":"<ruby>毎朝<rt>まいあさ</rt></ruby><ruby>早<rt>はや</rt></ruby>く<ruby>起<rt>お</rt></ruby>きるのは <ruby>大変<rt>たいへん</rt></ruby>です。","speech":"毎朝早く起きるのは大変です。","id":"<b>Bangun pagi</b> tiap hari <b>itu</b> berat. <i>(のは＋KS-na)</i>"},{"jp":"<ruby>夜<rt>よる</rt></ruby><ruby>一人<rt>ひとり</rt></ruby>で<ruby>歩<rt>ある</rt></ruby>くのは <ruby>危<rt>あぶ</rt></ruby>ないですよ。","speech":"夜一人で歩くのは危ないですよ。","id":"<b>Jalan sendirian</b> malam-malam <b>itu</b> bahaya lho. <i>(のは＋KS)</i>"},{"jp":"<ruby>外国語<rt>がいこくご</rt></ruby>を<ruby>勉強<rt>べんきょう</rt></ruby>するのは <ruby>楽<rt>たの</rt></ruby>しいです。","speech":"外国語を勉強するのは楽しいです。","id":"<b>Belajar</b> bahasa asing <b>itu</b> menyenangkan. <i>(のは＋KS)</i>"}],"dialogs":[{"jp":"いや ギター<b><ruby>弾<rt>ひ</rt></ruby>くのは</b> <ruby>楽<rt>たの</rt></ruby>しいけど","speech":"いやギター弾くのは楽しいけど","id":"Bukan, <b>main gitar sih</b> seru, tapi… <i>(のは楽しい)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 00:45"},{"jp":"とっさに<b><ruby>名乗<rt>なの</rt></ruby>るのは</b> <ruby>難<rt>むずか</rt></ruby>しいね","speech":"とっさに名乗るのは難しいね","id":"<b>Memperkenalkan diri</b> secara spontan <b>itu</b> susah ya. <i>(のは難しい)</i>","source":"この素晴らしい世界に爆焔を！ · EP01 · 16:22"},{"jp":"でも カメラで<ruby>花火<rt>はなび</rt></ruby><b><ruby>撮<rt>と</rt></ruby>るのは</b> <ruby>難<rt>むずか</rt></ruby>しいわよ","speech":"でもカメラで花火撮るのは難しいわよ","id":"Tapi <b>motret</b> kembang api pakai kamera <b>itu</b> susah lho. <i>(のは難しい)</i>","source":"トニカクカワイイ · EP12 · 14:09"},{"jp":"うまく<b><ruby>説明<rt>せつめい</rt></ruby>するのは</b> <ruby>難<rt>むずか</rt></ruby>しいけれど　 <ruby>私<rt>わたし</rt></ruby>からちゃんと<ruby>話<rt>はな</rt></ruby>しておきたいの","speech":"うまく説明するのは難しいけれど私からちゃんと話しておきたいの","id":"<b>Menjelaskannya</b> dengan baik <b>itu</b> susah, tapi aku pengin cerita langsung dariku. <i>(のは難しい)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP12 · 01:01"},{"jp":"さすがに<ruby>二部屋<rt>ふたへや</rt></ruby><ruby>都合<rt>つごう</rt></ruby>を<b>するのは</b> <ruby>難<rt>むずか</rt></ruby>しいですから","speech":"さすがに二部屋都合をするのは難しいですから","id":"<b>Menyediakan</b> dua kamar <b>itu</b> jelas sulit, jadi… <i>(のは難しい · sopan)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP01 · 09:05"}]},{"id":"n4_b38_02","level":"N4","bab":38,"lokasi":"第38課","titleMain":"〜のが＋好き／上手","titleSub":["〜のが好きです","〜のが早いです"],"meaning":"Suka / jago / cepat (dalam) melakukan…","formula":"Ｖ-biasa + <b>のが</b> + 好き／嫌い／上手／下手／得意／苦手／早い／遅い<br>（花を育てる<b>のが</b>好きです ／ 食べる<b>のが</b>早いです）","nuance":"<ol><li>KS 好き・上手・早い dll. mengambil objek dengan <b>が</b> → kegiatan juga diberi <b>のが</b>.</li><li>Untuk diri sendiri lebih rendah hati: <b>得意 / 苦手</b>; 上手 biasanya memuji orang lain.</li></ol>⚠️ ×テニスをするが好き / ×テニスをするのを好き → ○テニスをする<b>のが</b>好き.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>花<rt>はな</rt></ruby>を<ruby>育<rt>そだ</rt></ruby>てるのが<ruby>好<rt>す</rt></ruby>きです。","speech":"私は花を育てるのが好きです。","id":"Aku <b>suka merawat</b> bunga. <i>(のが好き)</i>"},{"jp":"<ruby>田中<rt>たなか</rt></ruby>さんは<ruby>絵<rt>え</rt></ruby>をかくのが<ruby>上手<rt>じょうず</rt></ruby>です。","speech":"田中さんは絵をかくのが上手です。","id":"Tanaka-san <b>jago menggambar</b>. <i>(のが上手)</i>"},{"jp":"<ruby>兄<rt>あに</rt></ruby>は<ruby>食<rt>た</rt></ruby>べるのが<ruby>早<rt>はや</rt></ruby>いです。","speech":"兄は食べるのが早いです。","id":"Kakakku <b>makannya cepat</b>. <i>(のが早い)</i>"},{"jp":"<ruby>人<rt>ひと</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>で<ruby>話<rt>はな</rt></ruby>すのが<ruby>苦手<rt>にがて</rt></ruby>です。","speech":"人の前で話すのが苦手です。","id":"Aku <b>nggak jago bicara</b> di depan orang. <i>(のが苦手)</i>"}],"dialogs":[{"jp":"リョウさんは<ruby>\"一人<rt>ひとり</rt></ruby>で<b>いるのが<ruby>好<rt>す</rt></ruby>き</b>な<ruby>人<rt>ひと</rt></ruby>\"だ!","speech":"リョウさんは \"一人でいるのが好きな人\"だ!","id":"Ryo-san itu \"orang yang <b>suka sendirian</b>\"! <i>(のが好き)</i>","source":"ぼっち・ざ・ろっく！ · EP02 · 04:39"},{"jp":"いえ<ruby>私<rt>わたし</rt></ruby>は<ruby>一人<rt>ひとり</rt></ruby>で<b><ruby>食<rt>た</rt></ruby>べるのが<ruby>好<rt>す</rt></ruby>き</b>だから そういうのはちょっと","speech":"いえ私は一人で食べるのが好きだからそういうのはちょっと","id":"Nggak, aku <b>lebih suka makan</b> sendirian, jadi yang begitu agak… <i>(のが好き)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP01 · 21:19"},{"jp":"<ruby>真昼<rt>まひる</rt></ruby>がオシャレして<ruby>楽<rt>たの</rt></ruby>しんでるのを<b><ruby>見<rt>み</rt></ruby>るのが<ruby>好<rt>す</rt></ruby>き</b>だから","speech":"真昼がオシャレして楽しんでるのを見るのが好きだから","id":"Soalnya aku <b>suka lihat</b> Mahiru dandan dan menikmatinya. <i>(のが好き)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 11:07"},{"jp":"おいおい<ruby>何<rt>なん</rt></ruby>で<ruby>意識<rt>いしき</rt></ruby><ruby>高<rt>たか</rt></ruby>い<ruby>系<rt>けい</rt></ruby>ってこうも<ruby>人<rt>ひと</rt></ruby>と<ruby>一緒<rt>いっしょ</rt></ruby>に<b>やるのが<ruby>好<rt>す</rt></ruby>き</b>なの","speech":"おいおい何で意識高い系ってこうも人と一緒にやるのが好きなの","id":"Ya ampun, kenapa sih orang-orang \"sok ambisius\" itu <b>suka banget ngerjain</b> bareng orang lain? <i>(のが好き)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP06 · 19:15"},{"jp":"あっ あのっ... <ruby>私<rt>わたし</rt></ruby>は<ruby>大勢<rt>おおぜい</rt></ruby>の<ruby>輪<rt>わ</rt></ruby>に<ruby>入<rt>はい</rt></ruby>って<ruby>人<rt>ひと</rt></ruby>と<b><ruby>話<rt>はな</rt></ruby>すのが<ruby>苦手<rt>にがて</rt></ruby></b>でして!　 <ruby>話<rt>はな</rt></ruby>すのが<ruby>苦手<rt>にがて</rt></ruby>? いつも<ruby>元気<rt>げんき</rt></ruby>で<ruby>明<rt>あか</rt></ruby>るい<ruby>君<rt>きみ</rt></ruby>が?","speech":"あっあのっ... 私は大勢の輪に入って人と話すのが苦手でして!　話すのが苦手? いつも元気で明るい君が?","id":"A-anu… aku <b>nggak jago ngobrol</b> sama orang kalau masuk kelompok besar! — Nggak jago ngobrol? Kamu yang selalu ceria itu? <i>(のが苦手)</i>","source":"わたしが恋人になれるわけないじゃん、ムリムリ! (※ムリじゃなかった!?) · EP01 · 04:54"}]},{"id":"n4_b38_03","level":"N4","bab":38,"lokasi":"第38課","titleMain":"〜のを＋忘れる／知る","titleSub":["〜のを忘れました","〜のを知っていますか"],"meaning":"Lupa (melakukan)… · tahu (bahwa)…?","formula":"Ｖる + <b>のを忘れました</b>（牛乳を買う<b>のを忘れました</b>）<br>〜(biasa) + <b>のを知っていますか</b>（結婚する<b>のを知っていますか</b>）<br>Persepsi: Ｖ + <b>のを</b> 見る／聞く","nuance":"<ol><li><b>〜のを忘れる</b>: lupa <b>melakukan</b> (beda dengan 傘を忘れた = lupa barang).</li><li><b>〜のを知っていますか</b> → jawab \"tidak\": <b>いいえ、知りませんでした</b> (bukan ×知っていません).</li></ol>⚠️ 見る・聞く (persepsi) <b>wajib の</b> (×歌うことを聞いた); 〜ことができる / 趣味は〜ことです <b>wajib こと</b>.","examples":[{"jp":"<ruby>牛乳<rt>ぎゅうにゅう</rt></ruby>を<ruby>買<rt>か</rt></ruby>うのを<ruby>忘<rt>わす</rt></ruby>れました。","speech":"牛乳を買うのを忘れました。","id":"Aku <b>lupa beli</b> susu. <i>(のを忘れる)</i>"},{"jp":"かぎをかけるのを<ruby>忘<rt>わす</rt></ruby>れないでください。","speech":"かぎをかけるのを忘れないでください。","id":"Tolong <b>jangan lupa mengunci</b> pintu. <i>(のを忘れないで)</i>"},{"jp":"ミラーさんが<ruby>来週<rt>らいしゅう</rt></ruby><ruby>結婚<rt>けっこん</rt></ruby>するのを<ruby>知<rt>し</rt></ruby>っていますか。","speech":"ミラーさんが来週結婚するのを知っていますか。","id":"<b>Tahu nggak kalau</b> Pak Miller minggu depan menikah? <i>(のを知っている)</i>"},{"jp":"いいえ、<ruby>知<rt>し</rt></ruby>りませんでした。","speech":"いいえ、知りませんでした。","id":"Nggak, aku <b>nggak tahu</b> (baru tahu sekarang). <i>(jawaban)</i>"}],"dialogs":[{"jp":"<ruby>君<rt>きみ</rt></ruby>と<b><ruby>踊<rt>おど</rt></ruby>るのを</b> すっかり<b><ruby>忘<rt>わす</rt></ruby>れていた</b>","speech":"君と踊るのをすっかり忘れていた","id":"Aku benar-benar <b>lupa berdansa</b> denganmu. <i>(のを忘れる)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP12 · 15:48"},{"jp":"そうだ ギレーヌって ドルディア<ruby>族<rt>ぞく</rt></ruby>だったわよね?　あっ すっかり<b><ruby>聞<rt>き</rt></ruby>くのを<ruby>忘<rt>わす</rt></ruby>れていました</b>","speech":"そうだギレーヌってドルディア族だったわよね?　あっすっかり聞くのを忘れていました","id":"Oh iya, Ghislaine itu suku Doldia kan? — Ah, saya benar-benar <b>lupa menanyakannya</b>. <i>(のを忘れる · sopan)</i>","source":"無職転生 ～異世界行ったら本気だす～ 第2クール · EP04 · 03:57"},{"jp":"<ruby>昨夜<rt>さくや</rt></ruby><ruby>私<rt>わたし</rt></ruby>は<ruby>日課<rt>にっか</rt></ruby>である<ruby>爆裂<rt>ばくれつ</rt></ruby><ruby>魔法<rt>まほう</rt></ruby>を<b><ruby>唱<rt>とな</rt></ruby>えるのを<ruby>忘<rt>わす</rt></ruby>れ</b>　 <ruby>起<rt>お</rt></ruby>き<ruby>出<rt>だ</rt></ruby>そうとしていたところ","speech":"昨夜私は日課である爆裂魔法を唱えるのを忘れ起き出そうとしていたところ","id":"Semalam aku <b>lupa merapal</b> sihir ledakan yang jadi rutinitas harianku, jadi aku mau bangun… <i>(のを忘れ · tulis)</i>","source":"この素晴らしい世界に爆焔を！ · EP12 · 14:00"},{"jp":"<ruby>俺<rt>おれ</rt></ruby>は ズルいヤツだよ　 <ruby>受<rt>う</rt></ruby>け<ruby>入<rt>い</rt></ruby>れてくれる<b>のを<ruby>知<rt>し</rt></ruby>って</b> おまえに<ruby>寄<rt>よ</rt></ruby>りかかった","speech":"俺はズルいヤツだよ受け入れてくれるのを知っておまえに寄りかかった","id":"Aku ini licik — aku <b>tahu</b> kamu bakal menerimaku, makanya aku bersandar padamu. <i>(のを知る)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP10 · 08:24"}]},{"id":"n4_b38_04","level":"N4","bab":38,"lokasi":"第38課","titleMain":"〜のは Ｎです","titleSub":["生まれたのは北海道です"],"meaning":"Yang (melakukan/terjadi)… itu (adalah) N — kalimat penekanan","formula":"[info yang sudah diketahui] + <b>のは</b> + [info yang ditekankan] + <b>です</b><br>（娘が生まれた<b>のは</b> 10年前<b>です</b>）<br>KS-na: 好き<b>なのは</b>","nuance":"<ol><li>Menyorot informasi baru/penting (waktu, tempat, orang, benda) di akhir kalimat.</li><li>Subjek di dalam bagian の tetap <b>が</b> (娘<b>が</b>生まれたのは), bukan は.</li></ol>⚠️ KS-na + <b>な</b> + のは (好き<b>な</b>のは). Sering untuk membantah: 裏切ったのは俺じゃない.","examples":[{"jp":"<ruby>娘<rt>むすめ</rt></ruby>が<ruby>生<rt>う</rt></ruby>まれたのは、 <ruby>１０年前<rt>じゅうねんまえ</rt></ruby>です。","speech":"娘が生まれたのは、１０年前です。","id":"<b>Anakku lahir itu</b> sepuluh tahun lalu. <i>(penekanan · waktu)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>に<ruby>来<rt>き</rt></ruby>て、はじめて<ruby>行<rt>い</rt></ruby>ったのは <ruby>京都<rt>きょうと</rt></ruby>です。","speech":"日本に来て、はじめて行ったのは京都です。","id":"<b>Tempat yang pertama kali kudatangi</b> setelah ke Jepang <b>itu</b> Kyoto. <i>(penekanan · tempat)</i>"},{"jp":"この<ruby>写真<rt>しゃしん</rt></ruby>を<ruby>撮<rt>と</rt></ruby>ったのは、 <ruby>兄<rt>あに</rt></ruby>です。","speech":"この写真を撮ったのは、兄です。","id":"<b>Yang memotret</b> foto ini <b>adalah</b> kakakku. <i>(penekanan · orang)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>が<ruby>一番<rt>いちばん</rt></ruby><ruby>好<rt>す</rt></ruby>きなのは、 <ruby>夏<rt>なつ</rt></ruby>です。","speech":"私が一番好きなのは、夏です。","id":"<b>Yang paling kusuka itu</b> musim panas. <i>(KS-na + なのは)</i>"}],"dialogs":[{"jp":"<b><ruby>呼<rt>よ</rt></ruby>び<ruby>出<rt>だ</rt></ruby>したのは</b> そっち<b>でしょ</b>","speech":"呼び出したのはそっちでしょ","id":"<b>Yang manggil</b> aku keluar <b>kan</b> kamu. <i>(penekanan · orang)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 18:32"},{"jp":"<b><ruby>裏切<rt>うらぎ</rt></ruby>ったのは</b> <ruby>俺<rt>おれ</rt></ruby>じゃない レメリオ<b>だ</b>!","speech":"裏切ったのは俺じゃないレメリオだ!","id":"<b>Yang berkhianat</b> bukan aku — Remerio! <i>(penekanan · membantah)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP12 · 11:47"},{"jp":"まあ<ruby>船<rt>ふね</rt></ruby>で<ruby>一番<rt>いちばん</rt></ruby><b><ruby>驚<rt>おどろ</rt></ruby>いたのは</b> <ruby>食<rt>た</rt></ruby>べ<ruby>物<rt>もの</rt></ruby><b>だ</b>","speech":"まあ船で一番驚いたのは食べ物だ","id":"Yah, <b>yang paling bikin kaget</b> di kapal itu makanannya. <i>(penekanan · benda)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP22 · 14:42"},{"jp":"<b><ruby>助<rt>たす</rt></ruby>けてくれたのは</b> ナサ<ruby>君<rt>くん</rt></ruby>だけ<b>だった</b>から","speech":"助けてくれたのはナサ君だけだったから","id":"Soalnya <b>yang nolongin</b> kami cuma Nasa-kun. <i>(penekanan · orang)</i>","source":"トニカクカワイイ · EP03 · 20:16"},{"jp":"じゃあ リンちゃん バイク<b><ruby>好<rt>す</rt></ruby>きなのは</b> <ruby>遺伝<rt>いでん</rt></ruby><b>なんだ</b>ね","speech":"じゃあリンちゃんバイク好きなのは遺伝なんだね","id":"Jadi, Rin-chan <b>suka motor itu</b> turunan ya. <i>(KS-na + なのは)</i>","source":"ゆるキャン△ SEASON２ · EP12 · 19:03"}]},{"id":"n4_b39_01","level":"N4","bab":39,"lokasi":"第39課","titleMain":"〜て、","titleSub":["聞いて、びっくりしました","〜なくて","〜くて"],"meaning":"(Karena)…, jadi (merasa)… — sebab yang memunculkan perasaan/keadaan","formula":"Ｖ-<b>て</b>（ニュースを聞い<b>て</b>、びっくりしました）<br>Ｖ-ない → <b>なくて</b>（わから<b>なくて</b>、困っています）<br>KS-i → <b>くて</b> ／ KS-na・KB → <b>で</b>（難し<b>くて</b> ／ 複雑<b>で</b>）","nuance":"<ol><li>Belakang = <b>perasaan/keadaan</b> yang muncul sendiri: びっくりする, 安心する, 困る, 残念, 寂しい, うれしい, 〜できない.</li><li>Juga untuk minta maaf: 遅くなって<b>ごめん</b> / 報告してなくて<b>ごめん</b>.</li></ol>⚠️ Belakang <b>tidak boleh</b> kehendak/permintaan (×危なくて、触らないでください → ○危ない<b>から／ので</b>). Negatif = <b>なくて</b>, bukan ×ないで.","examples":[{"jp":"ニュースを<ruby>聞<rt>き</rt></ruby>いて、びっくりしました。","speech":"ニュースを聞いて、びっくりしました。","id":"Aku <b>kaget dengar</b> beritanya. <i>(Ｖて)</i>"},{"jp":"<ruby>漢字<rt>かんじ</rt></ruby>がわからなくて、 <ruby>困<rt>こま</rt></ruby>っています。","speech":"漢字がわからなくて、困っています。","id":"Aku <b>nggak ngerti</b> kanji, <b>jadi bingung</b>. <i>(なくて)</i>"},{"jp":"<ruby>家族<rt>かぞく</rt></ruby>に<ruby>会<rt>あ</rt></ruby>えなくて、 <ruby>寂<rt>さび</rt></ruby>しいです。","speech":"家族に会えなくて、寂しいです。","id":"<b>Nggak bisa ketemu</b> keluarga, <b>jadi kesepian</b>. <i>(なくて)</i>"},{"jp":"<ruby>土曜日<rt>どようび</rt></ruby>のパーティーに<ruby>行<rt>い</rt></ruby>けなくて、 <ruby>残念<rt>ざんねん</rt></ruby>です。","speech":"土曜日のパーティーに行けなくて、残念です。","id":"Sayang banget <b>nggak bisa datang</b> ke pesta hari Sabtu. <i>(なくて)</i>"},{"jp":"<ruby>話<rt>はなし</rt></ruby>が<ruby>複雑<rt>ふくざつ</rt></ruby>で、よくわかりませんでした。","speech":"話が複雑で、よくわかりませんでした。","id":"Ceritanya <b>rumit, jadi</b> aku kurang paham. <i>(KS-na + で)</i>"}],"dialogs":[{"jp":"それを<b><ruby>聞<rt>き</rt></ruby>いて<ruby>安心<rt>あんしん</rt></ruby>しました</b>","speech":"それを聞いて安心しました","id":"Aku <b>lega dengar</b> itu. <i>(Ｖて → perasaan)</i>","source":"謎解きはディナーのあとで · EP04 · 19:01"},{"jp":"まりんちゃん また<b><ruby>会<rt>あ</rt></ruby>えて うれしい</b>","speech":"まりんちゃんまた会えてうれしい","id":"Marin-chan, aku <b>senang bisa ketemu</b> lagi. <i>(Ｖて → perasaan)</i>","source":"その着せ替え人形は恋をする Season 2 · EP02 · 18:24"},{"jp":"<b><ruby>遅<rt>おそ</rt></ruby>くなって ごめん</b>ね","speech":"遅くなってごめんね","id":"<b>Maaf ya telat</b>. <i>(〜て + minta maaf)</i>","source":"瑠璃の宝石 · EP12 · 18:39"},{"jp":"ごめんな その... <b><ruby>報告<rt>ほうこく</rt></ruby>してなくて</b>","speech":"ごめんなその... 報告してなくて","id":"Maaf ya… soalnya <b>nggak ngabarin</b>. <i>(〜なくて · urutan dibalik)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP01 · 09:51"},{"jp":"<b><ruby>怖<rt>こわ</rt></ruby>くて</b> ここから<b><ruby>動<rt>うご</rt></ruby>けない</b>","speech":"怖くてここから動けない","id":"<b>Saking takutnya</b>, aku <b>nggak bisa bergerak</b> dari sini. <i>(〜くて → keadaan)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 03:27"}]},{"id":"n4_b39_02","level":"N4","bab":39,"lokasi":"第39課","titleMain":"Ｎで","titleSub":["事故で","病気で","地震で"],"meaning":"Karena (kejadian N)… — kecelakaan, bencana, penyakit","formula":"Ｎ(kejadian) + <b>で</b> + akibat<br>（地震<b>で</b>ビルが倒れました ／ 病気<b>で</b>会社を休みました）","nuance":"<ol><li>KB berupa <b>kejadian alam, kecelakaan, penyakit</b> + で = sebab.</li><li>Sama seperti 〜て: belakang bukan kehendak/permintaan.</li></ol>⚠️ Bukan で tempat/alat — lihat jenis KB-nya. Kosakata bab: <b>途中で</b> (di tengah jalan).","examples":[{"jp":"<ruby>地震<rt>じしん</rt></ruby>でビルが<ruby>倒<rt>たお</rt></ruby>れました。","speech":"地震でビルが倒れました。","id":"Gedung roboh <b>karena gempa</b>. <i>(bencana)</i>"},{"jp":"<ruby>病気<rt>びょうき</rt></ruby>で <ruby>会社<rt>かいしゃ</rt></ruby>を<ruby>休<rt>やす</rt></ruby>みました。","speech":"病気で会社を休みました。","id":"Aku nggak masuk kerja <b>karena sakit</b>. <i>(penyakit)</i>"},{"jp":"<ruby>事故<rt>じこ</rt></ruby>で <ruby>電車<rt>でんしゃ</rt></ruby>が<ruby>遅<rt>おく</rt></ruby>れました。","speech":"事故で電車が遅れました。","id":"Keretanya terlambat <b>karena kecelakaan</b>. <i>(kecelakaan)</i>"},{"jp":"<ruby>台風<rt>たいふう</rt></ruby>で <ruby>旅行<rt>りょこう</rt></ruby>に<ruby>行<rt>い</rt></ruby>けませんでした。","speech":"台風で旅行に行けませんでした。","id":"Aku nggak bisa pergi liburan <b>gara-gara topan</b>. <i>(bencana)</i>"}],"dialogs":[{"jp":"<ruby>前<rt>まえ</rt></ruby>は<b><ruby>台風<rt>たいふう</rt></ruby>で</b> ライブ<ruby>来<rt>こ</rt></ruby>られなかったので　 <ruby>張<rt>は</rt></ruby>り<ruby>切<rt>き</rt></ruby>ってます","speech":"前は台風でライブ来られなかったので張り切ってます","id":"Dulu dia nggak bisa datang ke live <b>gara-gara topan</b>, jadi sekarang semangat banget. <i>(Ｎで · bencana)</i>","source":"ぼっち・ざ・ろっく！ · EP11 · 15:16"},{"jp":"ルパも<ruby>家族<rt>かぞく</rt></ruby>が<b><ruby>事故<rt>じこ</rt></ruby>で</b> <ruby>亡<rt>な</rt></ruby>くなった<ruby>時<rt>とき</rt></ruby>...","speech":"ルパも家族が事故で亡くなった時...","id":"Rupa juga, waktu keluarganya meninggal <b>karena kecelakaan</b>… <i>(Ｎで · kecelakaan)</i>","source":"ガールズバンドクライ · EP07 · 12:05"},{"jp":"お<ruby>父<rt>とう</rt></ruby>さんが<b><ruby>事故<rt>じこ</rt></ruby>で</b> <ruby>記憶<rt>きおく</rt></ruby><ruby>喪失<rt>そうしつ</rt></ruby>になったとか","speech":"お父さんが事故で記憶喪失になったとか","id":"Kayak \"ayahku hilang ingatan <b>karena kecelakaan</b>\" gitu. <i>(Ｎで · kecelakaan)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 01:39"},{"jp":"ああ だから<ruby>私<rt>わたし</rt></ruby>の<ruby>弟<rt>おとうと</rt></ruby>が<b><ruby>病気<rt>びょうき</rt></ruby>で</b> その<ruby>薬代<rt>くすりだい</rt></ruby>が<ruby>必要<rt>ひつよう</rt></ruby>で...","speech":"ああだから私の弟が病気でその薬代が必要で...","id":"Ah, makanya… adikku <b>sakit</b>, jadi butuh biaya obat… <i>(Ｎで · penyakit)</i>","source":"この素晴らしい世界に爆焔を！ · EP04 · 10:32"}]},{"id":"n4_b39_03","level":"N4","bab":39,"lokasi":"第39課","titleMain":"〜ので","titleSub":["〜なので"],"meaning":"Karena… / soalnya… — alasan yang disampaikan dengan halus & objektif","formula":"Ｖ / KS-i (bentuk biasa) + <b>ので</b>（用事がある<b>ので</b>）<br>KS-na / KB + <b>なので</b>（暇<b>なので</b> ／ 雨<b>なので</b>）<br>Sangat sopan: 〜ます／です + <b>ので</b>","nuance":"<ol><li>Lebih <b>halus</b> dari 〜から; cocok untuk minta izin, minta maaf, pamit (用事があるので、お先に失礼します).</li><li>Belakang <b>boleh</b> permintaan/izin (頭が痛いので、帰ってもいいですか).</li></ol>⚠️ ×雨だので → ○雨<b>な</b>ので. <b>から</b> lebih subjektif/tegas (bisa untuk perintah: 危ないから触るな).","examples":[{"jp":"<ruby>用事<rt>ようじ</rt></ruby>があるので、お<ruby>先<rt>さき</rt></ruby>に<ruby>失礼<rt>しつれい</rt></ruby>します。","speech":"用事があるので、お先に失礼します。","id":"<b>Karena</b> ada urusan, saya pamit duluan. <i>(pamit)</i>"},{"jp":"バスが<ruby>来<rt>こ</rt></ruby>なかったので、 <ruby>遅<rt>おく</rt></ruby>れました。","speech":"バスが来なかったので、遅れました。","id":"<b>Soalnya</b> busnya nggak datang, jadi saya telat. <i>(alasan)</i>"},{"jp":"<ruby>頭<rt>あたま</rt></ruby>が<ruby>痛<rt>いた</rt></ruby>いので、 <ruby>早<rt>はや</rt></ruby>く<ruby>帰<rt>かえ</rt></ruby>ってもいいですか。","speech":"頭が痛いので、早く帰ってもいいですか。","id":"<b>Karena</b> kepala saya sakit, boleh pulang lebih awal? <i>(minta izin)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>休<rt>やす</rt></ruby>みなので、ゆっくり<ruby>寝<rt>ね</rt></ruby>ます。","speech":"明日は休みなので、ゆっくり寝ます。","id":"<b>Karena</b> besok libur, aku mau tidur puas. <i>(KB + なので)</i>"}],"dialogs":[{"jp":"<ruby>仕事<rt>しごと</rt></ruby>が<b>ありますので</b> これで　ん?","speech":"仕事がありますのでこれでん?","id":"<b>Karena</b> masih ada pekerjaan, saya pamit dulu. Hm? <i>(〜ますので · pamit sopan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP06 · 20:28"},{"jp":"あ<ruby>一人<rt>ひとり</rt></ruby>で<b>できるので</b> <ruby>大丈夫<rt>だいじょうぶ</rt></ruby>です","speech":"あ一人でできるので大丈夫です","id":"Ah, <b>soalnya</b> saya <b>bisa</b> sendiri, jadi nggak apa-apa. <i>(menolak halus)</i>","source":"トニカクカワイイ · EP07 · 13:26"},{"jp":"<ruby>家<rt>いえ</rt></ruby>が<b><ruby>酒店<rt>さかてん</rt></ruby>なので</b> それで へえー","speech":"家が酒店なのでそれでへえー","id":"<b>Soalnya</b> rumahku <b>toko sake</b>, jadi… — Ooh. <i>(KB + なので)</i>","source":"ゆるキャン△ SEASON２ · EP06 · 04:48"},{"jp":"オンタイムで<b><ruby>進行<rt>しんこう</rt></ruby>するので</b> そのつもりで","speech":"オンタイムで進行するのでそのつもりで","id":"<b>Karena</b> acaranya <b>berjalan</b> tepat waktu, harap bersiap. <i>(alasan → instruksi)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 07:00"},{"jp":"<b>せっかくなので</b> みんなで<ruby>回<rt>まわ</rt></ruby>りませんか?","speech":"せっかくなのでみんなで回りませんか?","id":"<b>Mumpung</b> udah di sini, gimana kalau keliling bareng? <i>(なので → ajakan)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP06 · 07:01"}]},{"id":"n4_b40_01","level":"N4","bab":40,"lokasi":"第40課","titleMain":"疑問詞〜か","titleSub":["どこへ行くか、決めましたか"],"meaning":"(Tahu / tidak tahu / putuskan) apa / di mana / kapan / siapa… — pertanyaan dengan kata tanya di dalam kalimat","formula":"Kata tanya + … + bentuk biasa + <b>か</b>、わかりません／知っていますか／教えてください<br>（<b>どこ</b>へ行く<b>か</b>、決めましたか）<br>KS-na / KB: <b>buang だ</b>（あの人が<b>だれか</b>）","nuance":"<ol><li>Untuk pertanyaan <b>dengan kata tanya</b>: 何・どこ・いつ・だれ・どう・いくら.</li><li>Diikuti わかる, 知る, 教える, 決める, 調べる, 考える, 覚える.</li></ol>⚠️ Tanpa kata tanya → <b>〜かどうか</b>. Standar: ×だれだか → ○<b>だれか</b>.","examples":[{"jp":"どこへ<ruby>行<rt>い</rt></ruby>くか、 <ruby>決<rt>き</rt></ruby>めましたか。","speech":"どこへ行くか、決めましたか。","id":"Sudah putuskan <b>mau ke mana</b>? <i>(どこ〜か)</i>"},{"jp":"<ruby>荷物<rt>にもつ</rt></ruby>がいつ<ruby>着<rt>つ</rt></ruby>くか、 <ruby>教<rt>おし</rt></ruby>えてください。","speech":"荷物がいつ着くか、教えてください。","id":"Tolong kasih tahu <b>kapan</b> barangnya <b>sampai</b>. <i>(いつ〜か)</i>"},{"jp":"あの<ruby>人<rt>ひと</rt></ruby>がだれか、 <ruby>知<rt>し</rt></ruby>っていますか。","speech":"あの人がだれか、知っていますか。","id":"Kamu tahu <b>siapa</b> orang itu? <i>(KB · buang だ)</i>"},{"jp":"<ruby>何<rt>なに</rt></ruby>を<ruby>買<rt>か</rt></ruby>ったか、 <ruby>忘<rt>わす</rt></ruby>れてしまいました。","speech":"何を買ったか、忘れてしまいました。","id":"Aku lupa <b>beli apa</b>. <i>(何〜か)</i>"}],"dialogs":[{"jp":"ところで クロエは<b>どこにいるか<ruby>分<rt>わ</rt></ruby>かりますか</b>","speech":"ところでクロエはどこにいるか分かりますか","id":"Ngomong-ngomong, kamu <b>tahu</b> Chloe <b>ada di mana</b>? <i>(どこ〜か)</i>","source":"狼と香辛料 · EP01 · 04:25"},{"jp":"さて<b>どうすれば<ruby>良<rt>よ</rt></ruby>くなるか</b> <ruby>考<rt>かんが</rt></ruby>えましょう","speech":"さてどうすれば良くなるか考えましょう","id":"Nah, mari kita pikirkan <b>bagaimana caranya</b> supaya jadi lebih baik. <i>(どう〜か)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP01 · 16:41"},{"jp":"それを<ruby>注意深<rt>ちゅういぶか</rt></ruby>く<ruby>聞<rt>き</rt></ruby>くと<ruby>相手<rt>あいて</rt></ruby>が<b><ruby>何<rt>なに</rt></ruby>を<ruby>考<rt>かんが</rt></ruby>えているか<ruby>分<rt>わ</rt></ruby>かった</b>","speech":"それを注意深く聞くと相手が何を考えているか分かった","id":"Kalau kudengarkan baik-baik, aku <b>tahu apa yang</b> dipikirkan lawan. <i>(何〜か)</i>","source":"鬼滅の刃 · EP13 · 18:05"},{"jp":"あの<b><ruby>何<rt>なに</rt></ruby>を<ruby>考<rt>かんが</rt></ruby>えているか<ruby>分<rt>わ</rt></ruby>からない</b> <ruby>生物<rt>せいぶつ</rt></ruby>が","speech":"あの何を考えているか分からない生物が","id":"Makhluk yang <b>nggak ketahuan apa yang</b> dipikirkannya itu… <i>(何〜かわからない)</i>","source":"斉木楠雄のΨ難 · EP04 · 15:25"},{"jp":"<b>どこに</b> まだ<ruby>毒<rt>どく</rt></ruby>が<b><ruby>紛<rt>まぎ</rt></ruby>れているか<ruby>分<rt>わ</rt></ruby>からない</b> <ruby>以上<rt>いじょう</rt></ruby>","speech":"どこにまだ毒が紛れているか分からない以上","id":"Selama <b>nggak tahu di mana</b> racunnya masih tercampur… <i>(どこ〜か)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP23 · 01:03"}]},{"id":"n4_b40_02","level":"N4","bab":40,"lokasi":"第40課","titleMain":"〜かどうか","titleSub":[],"meaning":"Apakah … atau tidak — pertanyaan ya/tidak di dalam kalimat","formula":"Bentuk biasa + <b>かどうか</b>、わかりません／調べてください<br>（間違いがない<b>かどうか</b>、調べてください）<br>KS-na / KB: <b>buang だ</b>（本当<b>かどうか</b>）","nuance":"<ol><li>Untuk pertanyaan <b>tanpa kata tanya</b> (jawaban ya/tidak).</li><li>Sering dengan は untuk kontras: 〜かどうか<b>は</b>別問題だ / わからない.</li></ol>⚠️ Ada kata tanya → <b>か</b> saja (×どこへ行くかどうか). ×本当だかどうか → ○本当<b>かどうか</b>.","examples":[{"jp":"<ruby>間違<rt>まちが</rt></ruby>いがないかどうか、 <ruby>調<rt>しら</rt></ruby>べてください。","speech":"間違いがないかどうか、調べてください。","id":"Tolong cek <b>ada kesalahan atau tidak</b>. <i>(KK)</i>"},{"jp":"その<ruby>話<rt>はなし</rt></ruby>が<ruby>本当<rt>ほんとう</rt></ruby>かどうか、わかりません。","speech":"その話が本当かどうか、わかりません。","id":"Aku nggak tahu cerita itu <b>benar atau tidak</b>. <i>(KB · buang だ)</i>"},{"jp":"<ruby>忘年会<rt>ぼうねんかい</rt></ruby>に<ruby>出席<rt>しゅっせき</rt></ruby>するかどうか、<ruby>２０日<rt>はつか</rt></ruby>までに<ruby>返事<rt>へんじ</rt></ruby>をください。","speech":"忘年会に出席するかどうか、２０日までに返事をください。","id":"Tolong kabari <b>ikut pesta akhir tahun atau tidak</b> paling lambat tanggal 20. <i>(KK)</i>"},{"jp":"このパソコンが<ruby>使<rt>つか</rt></ruby>えるかどうか、ちょっと<ruby>見<rt>み</rt></ruby>てみます。","speech":"このパソコンが使えるかどうか、ちょっと見てみます。","id":"Aku coba lihat dulu laptop ini <b>bisa dipakai atau tidak</b>. <i>(potensial)</i>"}],"dialogs":[{"jp":"ただ<b>あるかどうか<ruby>分<rt>わ</rt></ruby>からない</b>","speech":"ただあるかどうか分からない","id":"Cuma, aku <b>nggak tahu ada atau nggak</b>. <i>(KK)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP07 · 07:19"},{"jp":"それが<b>いいことかどうか</b>は<ruby>知<rt>し</rt></ruby>りませんけど","speech":"それがいいことかどうかは知りませんけど","id":"Aku sih nggak tahu itu <b>hal baik atau bukan</b>. <i>(KB · buang だ)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP05 · 03:56"},{"jp":"それを<b><ruby>余計<rt>よけい</rt></ruby>かどうか</b> <ruby>決<rt>き</rt></ruby>めるのは<ruby>私<rt>わたし</rt></ruby>です","speech":"それを余計かどうか決めるのは私です","id":"Yang menentukan itu <b>berlebihan atau nggak</b> adalah aku. <i>(KS-na · buang だ)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP07 · 08:34"},{"jp":"<b><ruby>見<rt>み</rt></ruby>つかるかどうか</b>なんて<ruby>分<rt>わ</rt></ruby>からない でもこれが<ruby>運命<rt>うんめい</rt></ruby>なら","speech":"見つかるかどうかなんて分からないでもこれが運命なら","id":"Aku nggak tahu <b>bakal ketemu atau nggak</b>, tapi kalau ini takdir… <i>(KK)</i>","source":"トニカクカワイイ · EP01 · 08:36"},{"jp":"<b><ruby>伝<rt>つた</rt></ruby>わるかどうか</b>はまた<ruby>別<rt>べつ</rt></ruby><ruby>問題<rt>もんだい</rt></ruby>だ","speech":"伝わるかどうかはまた別問題だ","id":"<b>Tersampaikan atau nggak</b>, itu soal lain. <i>(かどうかは)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP05 · 11:11"}]},{"id":"n4_b40_03","level":"N4","bab":40,"lokasi":"第40課","titleMain":"〜てみます","titleSub":["〜てみたい","〜てみてください"],"meaning":"Coba (melakukan)… — melakukan sesuatu untuk melihat hasilnya","formula":"Ｖ-<b>て</b> + <b>みます</b>（着<b>てみます</b>）<br>Ｖ-て + <b>みたいです</b> = pengin coba · Ｖ-て + <b>みてください</b> = silakan coba<br>Kasual: 〜<b>てみよう</b> ／ 〜<b>てみて</b>","nuance":"<ol><li>Mencoba untuk tahu rasanya/hasilnya: makan, pakai, tanya, pergi.</li><li><b>みる</b> ditulis hiragana (bukan 見る).</li></ol>⚠️ <b>見てみる</b> (coba lihat) ≠ <b>見てくる</b> (lihat sebentar lalu kembali, S43). やってみたい ≠ <b>みたい</b> (sepertinya).","examples":[{"jp":"この<ruby>服<rt>ふく</rt></ruby>を<ruby>着<rt>き</rt></ruby>てみてもいいですか。","speech":"この服を着てみてもいいですか。","id":"Boleh <b>coba pakai</b> baju ini? <i>(minta izin)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>の<ruby>温泉<rt>おんせん</rt></ruby>に<ruby>行<rt>い</rt></ruby>ってみたいです。","speech":"日本の温泉に行ってみたいです。","id":"Aku <b>pengin coba</b> ke onsen Jepang. <i>(てみたい)</i>"},{"jp":"おいしいですよ。<ruby>食<rt>た</rt></ruby>べてみてください。","speech":"おいしいですよ。食べてみてください。","id":"Enak lho. <b>Coba</b> dimakan. <i>(てみてください)</i>"},{"jp":"わからないので、 <ruby>先生<rt>せんせい</rt></ruby>に<ruby>聞<rt>き</rt></ruby>いてみます。","speech":"わからないので、先生に聞いてみます。","id":"Aku nggak tahu, jadi <b>coba</b> kutanyakan ke guru. <i>(てみます)</i>"}],"dialogs":[{"jp":"とりあえず<b>やってみよう</b>!","speech":"とりあえずやってみよう!","id":"Pokoknya, <b>coba</b> aja dulu! <i>(てみよう · ajakan)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 14:42"},{"jp":"ねえ これ<b><ruby>食<rt>た</rt></ruby>べてみて</b>","speech":"ねえこれ食べてみて","id":"Eh, <b>coba</b> makan ini deh. <i>(てみて · menawarkan)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 16:19"},{"jp":"へえ じゃあ そこに<b><ruby>行<rt>い</rt></ruby>ってみます</b>","speech":"へえじゃあそこに行ってみます","id":"Oh gitu, kalau begitu aku <b>coba ke</b> sana. <i>(てみます)</i>","source":"ゆるキャン△ SEASON２ · EP02 · 04:28"},{"jp":"あっ ゲームセンターにも<b><ruby>行<rt>い</rt></ruby>ってみたいです</b>","speech":"あっゲームセンターにも行ってみたいです","id":"Ah, aku juga <b>pengin coba</b> ke game center. <i>(てみたい)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP09 · 03:59"},{"jp":"ホント? <ruby>実<rt>じつ</rt></ruby>は<b><ruby>着<rt>き</rt></ruby>てみたかった</b>の それ","speech":"ホント? 実は着てみたかったのそれ","id":"Beneran? Sebenarnya aku <b>pengin coba pakai</b> itu. <i>(てみたかった)</i>","source":"ぼっち・ざ・ろっく！ · EP11 · 11:34"}]},{"id":"n4_b40_04","level":"N4","bab":40,"lokasi":"第40課","titleMain":"い形容詞→〜さ","titleSub":["長さ","重さ","高さ"],"meaning":"Tingkat / ukuran …-nya — KS-i dijadikan kata benda (panjang, berat, tinggi…)","formula":"KS-i: buang <b>い</b> + <b>さ</b><br>長い → 長<b>さ</b> ／ 重い → 重<b>さ</b> ／ 高い → 高<b>さ</b> ／ 大きい → 大き<b>さ</b><br>いい → <b>よさ</b> · KS-na juga bisa: 便利<b>さ</b>","nuance":"<ol><li>Ukuran/derajat yang bisa diukur: 長さ, 重さ, 高さ, 大きさ, 速さ.</li><li>Juga sifat abstrak: 楽しさ, 優しさ, 便利さ.</li></ol>⚠️ いい → <b>よさ</b> (bukan ×いさ). Tanya ukuran: 重さは<b>どのくらい</b>ですか.","examples":[{"jp":"<ruby>山<rt>やま</rt></ruby>の<ruby>高<rt>たか</rt></ruby>さはどうやって<ruby>測<rt>はか</rt></ruby>るか、 <ruby>知<rt>し</rt></ruby>っていますか。","speech":"山の高さはどうやって測るか、知っていますか。","id":"Kamu tahu bagaimana cara mengukur <b>tinggi</b> gunung? <i>(高さ)</i>"},{"jp":"この<ruby>荷物<rt>にもつ</rt></ruby>の<ruby>重<rt>おも</rt></ruby>さを<ruby>量<rt>はか</rt></ruby>ってください。","speech":"この荷物の重さを量ってください。","id":"Tolong timbang <b>berat</b> barang ini. <i>(重さ)</i>"},{"jp":"<ruby>橋<rt>はし</rt></ruby>の<ruby>長<rt>なが</rt></ruby>さは<ruby>５００<rt>ごひゃく</rt></ruby>メートルです。","speech":"橋の長さは５００メートルです。","id":"<b>Panjang</b> jembatannya 500 meter. <i>(長さ)</i>"},{"jp":"<ruby>新<rt>あたら</rt></ruby>しい<ruby>家<rt>いえ</rt></ruby>の<ruby>大<rt>おお</rt></ruby>きさはどのくらいですか。","speech":"新しい家の大きさはどのくらいですか。","id":"<b>Ukuran</b> rumah barunya kira-kira seberapa? <i>(大きさ)</i>"}],"dialogs":[{"jp":"これ<b><ruby>長<rt>なが</rt></ruby>さ</b> <ruby>合<rt>あ</rt></ruby>ってんのか","speech":"これ長さ合ってんのか","id":"<b>Panjang</b>-nya ini udah pas belum ya? <i>(長さ)</i>","source":"ゆるキャン△ · EP02 · 09:18"},{"jp":"<ruby>北<rt>きた</rt></ruby>の<ruby>町<rt>まち</rt></ruby>でも<ruby>困<rt>こま</rt></ruby>らない<ruby>格好<rt>かっこう</rt></ruby>で <b><ruby>大<rt>おお</rt></ruby>きさ</b>はこいつに<ruby>合<rt>あ</rt></ruby>わせて","speech":"北の町でも困らない格好で大きさはこいつに合わせて","id":"Pakaian yang nggak bikin repot di kota utara, dan <b>ukuran</b>-nya disesuaikan sama dia. <i>(大きさ)</i>","source":"狼と香辛料 · EP07 · 15:43"},{"jp":"あの バーの<b><ruby>重<rt>おも</rt></ruby>さ</b>って...","speech":"あのバーの重さって...","id":"Anu, <b>berat</b> barbelnya itu… <i>(重さ)</i>","source":"ダンベル何キロ持てる？ · EP01 · 10:50"},{"jp":"<b><ruby>高<rt>たか</rt></ruby>さ</b>634メートル! おー","speech":"高さ634メートル! おー","id":"<b>Tinggi</b>-nya 634 meter! Wooh! <i>(高さ)</i>","source":"SHIROBAKO · EP08 · 03:39"},{"jp":"みんなでやるキャンプは-　 <ruby>違<rt>ちが</rt></ruby>うジャンルの<b><ruby>楽<rt>たの</rt></ruby>しさ</b>が あると<ruby>思<rt>おも</rt></ruby>うよ","speech":"みんなでやるキャンプは-　違うジャンルの楽しさがあると思うよ","id":"Kemah rame-rame itu punya <b>keseruan</b> dari jenis yang beda, menurutku. <i>(楽しさ · abstrak)</i>","source":"ゆるキャン△ · EP11 · 21:37"}]},{"id":"n4_b41_01","level":"N4","bab":41,"lokasi":"第41課","titleMain":"さしあげる・いただく・くださる・やる","titleSub":["Ｎをさしあげます","Ｎをくださいます"],"meaning":"Memberi / menerima barang versi keigo — ke atasan (さしあげる), dari atasan (いただく), atasan memberi saya (くださる), ke bawahan / hewan / tanaman (やる)","formula":"Saya は Atasan に N を <b>さしあげます</b> ← あげる<br>Saya は Atasan に／から N を <b>いただきます</b> ← もらう<br>Atasan は 私 に N を <b>くださいます</b> ← くれる<br>Saya は Bawahan / hewan / tanaman に N を <b>やります</b> ← あげる","nuance":"<ol><li><b>さしあげる・いただく</b> = 謙譲語 (merendahkan aksi saya). <b>くださる</b> = 尊敬語 (meninggikan pemberi).</li><li><b>やる</b>: ke anak, adik, hewan, tanaman (花に水をやる = menyiram). Sekarang banyak orang pakai あげる saja.</li><li>Konjugasi khusus: くださる → <b>くださいます</b> (×くださります).</li></ol>⚠️ Arah pemberian sama persis dengan あげる・もらう・くれる. Keluarga sendiri tidak ditinggikan ke orang luar (×母がくださいました → ○母がくれました).","examples":[{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>にプレゼントをくださいました。","speech":"部長は私にプレゼントをくださいました。","id":"Pak manajer <b>memberi saya</b> hadiah. <i>(くださる · atasan → saya)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>部長<rt>ぶちょう</rt></ruby>にお<ruby>土産<rt>みやげ</rt></ruby>をさしあげました。","speech":"私は部長にお土産をさしあげました。","id":"Saya <b>memberikan</b> oleh-oleh kepada Pak manajer. <i>(さしあげる · saya → atasan)</i>"},{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>社長<rt>しゃちょう</rt></ruby>に<ruby>珍<rt>めずら</rt></ruby>しい<ruby>切手<rt>きって</rt></ruby>をいただきました。","speech":"私は社長に珍しい切手をいただきました。","id":"Saya <b>menerima</b> perangko langka dari Pak direktur. <i>(いただく)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>が<ruby>結婚<rt>けっこん</rt></ruby>のお<ruby>祝<rt>いわ</rt></ruby>いに<ruby>時計<rt>とけい</rt></ruby>をくださいました。","speech":"先生が結婚のお祝いに時計をくださいました。","id":"Pak guru <b>memberi saya</b> jam tangan sebagai hadiah pernikahan. <i>(くださる)</i>"},{"jp":"<ruby>毎朝<rt>まいあさ</rt></ruby>、 <ruby>花<rt>はな</rt></ruby>に<ruby>水<rt>みず</rt></ruby>をやります。","speech":"毎朝、花に水をやります。","id":"Tiap pagi saya <b>menyiram</b> bunga. <i>(やる · tanaman)</i>"}],"dialogs":[{"jp":"えっ? <ruby>1本<rt>いっぽん</rt></ruby> <b><ruby>差<rt>さ</rt></ruby>し<ruby>上<rt>あ</rt></ruby>げます</b>から","speech":"えっ? 1本差し上げますから","id":"Eh? Saya <b>kasih</b> satu kok. <i>(さしあげる · sopan)</i>","source":"ぼっち・ざ・ろっく！ · EP09 · 14:52"},{"jp":"お<ruby>礼<rt>れい</rt></ruby>に<ruby>何<rt>なに</rt></ruby>を<b><ruby>差<rt>さ</rt></ruby>し<ruby>上<rt>あ</rt></ruby>げれば</b>いいですか","speech":"お礼に何を差し上げればいいですか","id":"Sebagai balasan, saya <b>sebaiknya memberi</b> apa? <i>(さしあげる · ke yang dihormati)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP09 · 08:40"},{"jp":"もしも<ruby>事態<rt>じたい</rt></ruby>を<ruby>挽回<rt>ばんかい</rt></ruby>できた<ruby>暁<rt>あかつき</rt></ruby>には それなりの<ruby>報酬<rt>ほうしゅう</rt></ruby>を<b><ruby>頂<rt>いただ</rt></ruby>きます</b>","speech":"もしも事態を挽回できた暁にはそれなりの報酬を頂きます","id":"Kalau saya berhasil membalikkan keadaan, saya akan <b>menerima</b> imbalan yang pantas. <i>(いただく · menerima)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP23 · 07:55"},{"jp":"おい ミケ<ruby>今<rt>いま</rt></ruby><ruby>餌<rt>えさ</rt></ruby>を<b>やる</b>から...","speech":"おいミケ今餌をやるから...","id":"Hei Mike, sekarang <b>kukasih</b> makan nih… <i>(やる · ke hewan)</i>","source":"斉木楠雄のΨ難 2 · EP09 · 15:51"},{"jp":"<ruby>餌<rt>えさ</rt></ruby>を<b>やらない</b>なんて<ruby>許<rt>ゆる</rt></ruby>せない","speech":"餌をやらないなんて許せない","id":"<b>Nggak ngasih</b> makan?! Nggak bisa dimaafkan! <i>(やる · ke hewan)</i>","source":"白い砂のアクアトープ · EP15 · 19:36"}]},{"id":"n4_b41_02","level":"N4","bab":41,"lokasi":"第41課","titleMain":"〜ていただく・〜てくださる","titleSub":["〜ていただきました","〜てくださいました"],"meaning":"Mendapat kebaikan (atasan) melakukan… / (atasan) berbaik hati melakukan… untuk saya — versi sopan 〜てもらう・〜てくれる","formula":"Saya は Atasan <b>に</b> Ｖ-て + <b>いただきます</b> ← てもらう<br>Atasan <b>が</b> (私に) Ｖ-て + <b>くださいます</b> ← てくれる<br>Ｖ-て + <b>いただいて</b>、ありがとうございます","nuance":"<ol><li><b>〜ていただく</b>: subjek = saya (penerima jasa); orang yang berjasa ditandai <b>に</b>.</li><li><b>〜てくださる</b>: subjek = atasan (pemberi jasa), ditandai <b>が／は</b>.</li><li>Selalu membawa rasa <b>terima kasih</b>; penutup favorit: 〜ていただき、ありがとうございます.</li></ol>⚠️ ×課長<b>が</b>直していただきました → ○課長<b>に</b>. Kalau merugikan, pakai 受身 (叱られました), bukan ていただく.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>課長<rt>かちょう</rt></ruby>に<ruby>手紙<rt>てがみ</rt></ruby>の<ruby>間違<rt>まちが</rt></ruby>いを<ruby>直<rt>なお</rt></ruby>していただきました。","speech":"私は課長に手紙の間違いを直していただきました。","id":"Kesalahan di surat saya <b>dikoreksi</b> oleh Pak kepala bagian. <i>(ていただく · Atasan に)</i>"},{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>の<ruby>奥様<rt>おくさま</rt></ruby>にお<ruby>茶<rt>ちゃ</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えていただきました。","speech":"部長の奥様にお茶を教えていただきました。","id":"Saya <b>diajari</b> upacara minum teh oleh istri Pak manajer. <i>(ていただく)</i>"},{"jp":"<ruby>社長<rt>しゃちょう</rt></ruby>が<ruby>駅<rt>えき</rt></ruby>まで<ruby>送<rt>おく</rt></ruby>ってくださいました。","speech":"社長が駅まで送ってくださいました。","id":"Pak direktur <b>berbaik hati mengantar</b> saya sampai stasiun. <i>(てくださる · Atasan が)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>が<ruby>推薦状<rt>すいせんじょう</rt></ruby>を<ruby>書<rt>か</rt></ruby>いてくださいました。","speech":"先生が推薦状を書いてくださいました。","id":"Pak guru <b>berbaik hati menuliskan</b> surat rekomendasi untuk saya. <i>(てくださる)</i>"},{"jp":"わざわざ<ruby>来<rt>き</rt></ruby>ていただいて、ありがとうございます。","speech":"わざわざ来ていただいて、ありがとうございます。","id":"Terima kasih <b>sudah repot-repot datang</b>. <i>(ていただいて、ありがとう)</i>"}],"dialogs":[{"jp":"<ruby>紹介<rt>しょうかい</rt></ruby>し<b>ていただいた</b>キャンプ<ruby>場<rt>じょう</rt></ruby>も すごくよかったです","speech":"紹介していただいたキャンプ場もすごくよかったです","id":"Bumi perkemahan yang <b>Anda kenalkan</b> ke kami juga bagus banget. <i>(ていただく · terima kasih)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 03:33"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は わざわざ ごちそうを<ruby>用意<rt>ようい</rt></ruby>し<b>ていただいて</b>　ありがとうございました","speech":"今日はわざわざごちそうを用意していただいてありがとうございました","id":"Terima kasih banyak sudah <b>repot-repot menyiapkan</b> jamuan hari ini. <i>(ていただいて、ありがとう)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP22 · 15:15"},{"jp":"あっ あの<ruby>本当<rt>ほんとう</rt></ruby>にいいんですか? かか... <ruby>買<rt>か</rt></ruby>っ<b>ていただいて</b>","speech":"あっあの本当にいいんですか? かか... 買っていただいて","id":"Eh, anu… beneran nggak apa-apa nih… saya <b>dibeliin</b>? <i>(ていただく · sungkan)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 18:53"},{"jp":"<ruby>小雪<rt>こゆき</rt></ruby>さんのこと<ruby>覚<rt>おぼ</rt></ruby>え<b>てくださっていた</b>のですね","speech":"小雪さんのこと覚えてくださっていたのですね","id":"Ternyata Anda <b>masih ingat</b> soal Koyuki-san ya. <i>(てくださる · subjek = lawan bicara)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP07 · 15:36"},{"jp":"このお<ruby>方<rt>かた</rt></ruby>を<ruby>保護<rt>ほご</rt></ruby>し<b>てくださった</b>ことには　 <ruby>感謝<rt>かんしゃ</rt></ruby>いたします","speech":"このお方を保護してくださったことには感謝いたします","id":"Saya berterima kasih karena Anda <b>sudi melindungi</b> beliau. <i>(てくださる)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 11:21"}]},{"id":"n4_b41_03","level":"N4","bab":41,"lokasi":"第41課","titleMain":"〜てやる・〜てさしあげる","titleSub":["〜てやります","〜てさしあげます"],"meaning":"Melakukan… untuk (bawahan / anak / hewan) · melakukan… untuk (atasan) — versi khusus 〜てあげる","formula":"Bawahan <b>に</b> N を Ｖ-て + <b>やる</b>（娘に本を読んでやる）<br>Bawahan <b>を</b> Ｖ-て + <b>やる</b>（子どもを公園に連れて行ってやる）<br>Atasan に Ｖ-て + <b>さしあげる</b>","nuance":"<ol><li><b>〜てやる</b>: untuk anak sendiri, adik, hewan. Ke teman sebaya terdengar kasar / sombong.</li><li><b>〜てさしあげる</b>: untuk atasan / orang yang dihormati — tapi tetap menonjolkan \"aku berjasa\".</li><li>Di anime, <b>〜てやる</b> juga dipakai untuk tekad / ancaman (ぶっ飛ばしてやる).</li></ol>⚠️ Menawarkan bantuan ke atasan: ×持ってさしあげましょうか → ○<b>お持ちしましょうか</b> (S50).","examples":[{"jp":"<ruby>娘<rt>むすめ</rt></ruby>に<ruby>本<rt>ほん</rt></ruby>を<ruby>読<rt>よ</rt></ruby>んでやりました。","speech":"娘に本を読んでやりました。","id":"Saya <b>membacakan</b> buku untuk putri saya. <i>(てやる · anak)</i>"},{"jp":"<ruby>息子<rt>むすこ</rt></ruby>に<ruby>自転車<rt>じてんしゃ</rt></ruby>を<ruby>買<rt>か</rt></ruby>ってやりました。","speech":"息子に自転車を買ってやりました。","id":"Saya <b>membelikan</b> sepeda untuk putra saya. <i>(てやる · anak)</i>"},{"jp":"<ruby>毎日<rt>まいにち</rt></ruby>、 <ruby>犬<rt>いぬ</rt></ruby>を<ruby>散歩<rt>さんぽ</rt></ruby>に<ruby>連<rt>つ</rt></ruby>れて<ruby>行<rt>い</rt></ruby>ってやります。","speech":"毎日、犬を散歩に連れて行ってやります。","id":"Tiap hari saya <b>mengajak</b> anjing jalan-jalan. <i>(てやる · hewan)</i>"},{"jp":"<ruby>困<rt>こま</rt></ruby>っているお<ruby>年寄<rt>としよ</rt></ruby>りに<ruby>道<rt>みち</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えてさしあげました。","speech":"困っているお年寄りに道を教えてさしあげました。","id":"Saya <b>menunjukkan</b> jalan kepada orang tua yang sedang kebingungan. <i>(てさしあげる)</i>"}],"dialogs":[{"jp":"<ruby>花子<rt>はなこ</rt></ruby>も<ruby>帰<rt>かえ</rt></ruby>ったら<ruby>本<rt>ほん</rt></ruby><ruby>読<rt>よ</rt></ruby><b>んでやる</b>からな","speech":"花子も帰ったら本読んでやるからな","id":"Hanako juga, nanti pas aku pulang <b>kubacakan</b> buku ya. <i>(てやる · ke adik)</i>","source":"鬼滅の刃 · EP01 · 02:17"},{"jp":"<ruby>櫛<rt>くし</rt></ruby>とか<ruby>帽子<rt>ぼうし</rt></ruby>とか<ruby>買<rt>か</rt></ruby><b>ってやる</b>よ","speech":"櫛とか帽子とか買ってやるよ","id":"Nanti <b>kubelikan</b> sisir atau topi deh. <i>(てやる · orang dekat)</i>","source":"狼と香辛料 · EP04 · 13:50"},{"jp":"そうか　じゃあ<ruby>教会<rt>きょうかい</rt></ruby>が<ruby>言<rt>い</rt></ruby>うところの<ruby>奇跡<rt>きせき</rt></ruby>について<ruby>教<rt>おし</rt></ruby>え<b>てやろう</b>","speech":"そうかじゃあ教会が言うところの奇跡について教えてやろう","id":"Oh gitu. Kalau begitu <b>biar kuajari</b> soal \"mukjizat\" versi Gereja. <i>(てやる · nada dari atas)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP21 · 09:58"},{"jp":"<ruby>寛大<rt>かんだい</rt></ruby>な<ruby>私<rt>わたし</rt></ruby>は こんなもんで<ruby>許<rt>ゆる</rt></ruby>し<b>て<ruby>差<rt>さ</rt></ruby>し<ruby>上<rt>あ</rt></ruby>げます</b>よ","speech":"寛大な私はこんなもんで許して差し上げますよ","id":"Karena saya murah hati, cukup segini saja saya <b>maafkan</b>. <i>(てさしあげる · sok berjasa)</i>","source":"この素晴らしい世界に爆焔を！ · EP08 · 08:20"},{"jp":"さすれば<ruby>神々<rt>かみがみ</rt></ruby>からの<ruby>贈<rt>おく</rt></ruby>り<ruby>物<rt>もの</rt></ruby>として-　どんな<ruby>願<rt>ねが</rt></ruby>いでも かなえ<b>てさしあげましょう</b>","speech":"さすれば神々からの贈り物として-　どんな願いでもかなえてさしあげましょう","id":"Kalau begitu, sebagai hadiah dari para dewa, akan <b>saya kabulkan</b> permohonan apa pun. <i>(てさしあげる · gaya sopan)</i>","source":"この素晴らしい世界に祝福を！ · EP01 · 09:52"}]},{"id":"n4_b41_04","level":"N4","bab":41,"lokasi":"第41課","titleMain":"〜てくださいませんか","titleSub":[],"meaning":"Maukah Anda (berkenan)…? — permintaan sangat sopan","formula":"Ｖ-て + <b>くださいませんか</b>（教えてくださいませんか）<br>Keigo: お Ｖ-ます + <b>くださいませんか</b>（お任せくださいませんか）<br>≈ Ｖ-て + <b>いただけませんか</b>","nuance":"<ol><li>Kesopanan: 〜て &lt; 〜てください &lt; 〜てくれませんか &lt; <b>〜てくださいませんか</b> ≈ 〜ていただけませんか.</li><li>Pertanyaan negatif → lawan bicara diberi ruang menolak; cocok ke guru, atasan, orang asing, atau permintaan yang merepotkan.</li></ol>⚠️ くださる = \"Anda memberi\"; いただける = \"bisakah saya menerima\". Keduanya sama sopan.","examples":[{"jp":"すみませんが、この<ruby>漢字<rt>かんじ</rt></ruby>の<ruby>読<rt>よ</rt></ruby>み<ruby>方<rt>かた</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えてくださいませんか。","speech":"すみませんが、この漢字の読み方を教えてくださいませんか。","id":"Permisi, <b>maukah Anda memberi tahu</b> cara baca kanji ini? <i>(permintaan sopan)</i>"},{"jp":"いい<ruby>先生<rt>せんせい</rt></ruby>を<ruby>紹介<rt>しょうかい</rt></ruby>してくださいませんか。","speech":"いい先生を紹介してくださいませんか。","id":"<b>Maukah Anda mengenalkan</b> guru yang bagus kepada saya? <i>(permintaan)</i>"},{"jp":"もう<ruby>少<rt>すこ</rt></ruby>しゆっくり<ruby>話<rt>はな</rt></ruby>してくださいませんか。","speech":"もう少しゆっくり話してくださいませんか。","id":"<b>Bisakah Anda</b> bicara sedikit lebih pelan? <i>(permintaan)</i>"},{"jp":"<ruby>結婚式<rt>けっこんしき</rt></ruby>でスピーチをしてくださいませんか。","speech":"結婚式でスピーチをしてくださいませんか。","id":"<b>Maukah Anda</b> memberi sambutan di pernikahan saya? <i>(permintaan berat)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby>と<ruby>踊<rt>おど</rt></ruby>っ<b>てくださいませんか</b>?","speech":"私と踊ってくださいませんか?","id":"<b>Maukah Anda</b> berdansa dengan saya? <i>(ajakan sopan)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP10 · 08:40"},{"jp":"もしも そうならば　 <ruby>知恵<rt>ちえ</rt></ruby>とお<ruby>金<rt>かね</rt></ruby>を<ruby>貸<rt>か</rt></ruby>し<b>てくださいませんか</b>?","speech":"もしもそうならば知恵とお金を貸してくださいませんか?","id":"Kalau memang begitu, <b>maukah Anda meminjamkan</b> akal dan uang kepada kami? <i>(permintaan berat)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP23 · 07:28"},{"jp":"<ruby>壬氏<rt>じんし</rt></ruby><ruby>様<rt>さま</rt></ruby>を<ruby>許<rt>ゆる</rt></ruby>し<b>てくださいませんか</b>","speech":"壬氏様を許してくださいませんか","id":"<b>Maukah Anda</b> memaafkan Tuan Jinshi? <i>(memohon)</i>","source":"薬屋のひとりごと · EP10 · 16:08"},{"jp":"よろしければ あしたのお<ruby>昼<rt>ひる</rt></ruby>の<ruby>校内<rt>こうない</rt></ruby><ruby>放送<rt>ほうそう</rt></ruby>に　ゲストとして<ruby>出<rt>で</rt></ruby><b>てくださいませんか</b>?","speech":"よろしければあしたのお昼の校内放送にゲストとして出てくださいませんか?","id":"Kalau berkenan, <b>maukah kamu</b> tampil sebagai bintang tamu di siaran sekolah siang besok? <i>(よろしければ + permintaan)</i>","source":"時々ボソッとロシア語でデレる隣のアーリャさん · EP11 · 11:58"},{"jp":"よかったら<ruby>見<rt>み</rt></ruby>に<ruby>来<rt>き</rt></ruby><b>て くださいませんか</b>?","speech":"よかったら見に来てくださいませんか?","id":"Kalau sempat, <b>maukah kamu</b> datang menonton? <i>(undangan)</i>","source":"斉木楠雄のΨ難 2 · EP24 · 14:40"}]},{"id":"n4_b42_01","level":"N4","bab":42,"lokasi":"第42課","titleMain":"〜ために","titleSub":["Ｖるために","Ｎのために"],"meaning":"Untuk / supaya bisa… (tujuan yang disengaja) · demi… (Ｎのために)","formula":"Ｖ-る (kehendak) + <b>ために</b>（店を持つために）<br>Ｎ + <b>の</b> + <b>ために</b>（家族のために ／ 健康のために）","nuance":"<ol><li><b>Tujuan</b>: KK kehendak (買う, 持つ, 勉強する) dan <b>subjek kedua klausa sama</b>.</li><li><b>Ｎのために</b> = demi / untuk kepentingan seseorang atau sesuatu.</li></ol>⚠️ KK non-kehendak / potensial / 〜ない → <b>ように</b> (忘れないようにメモする). ために juga bisa berarti \"karena\" (N3: 事故のために遅れた).","examples":[{"jp":"<ruby>将来<rt>しょうらい</rt></ruby>、 <ruby>自分<rt>じぶん</rt></ruby>の<ruby>店<rt>みせ</rt></ruby>を<ruby>持<rt>も</rt></ruby>つために、 <ruby>貯金<rt>ちょきん</rt></ruby>しています。","speech":"将来、自分の店を持つために、貯金しています。","id":"Aku menabung <b>supaya</b> nanti bisa punya toko sendiri. <i>(tujuan)</i>"},{"jp":"<ruby>家族<rt>かぞく</rt></ruby>のために、 <ruby>一生懸命<rt>いっしょうけんめい</rt></ruby><ruby>働<rt>はたら</rt></ruby>きます。","speech":"家族のために、一生懸命働きます。","id":"Aku bekerja keras <b>demi</b> keluarga. <i>(Ｎのために)</i>"},{"jp":"<ruby>弁護士<rt>べんごし</rt></ruby>になるために、 <ruby>法律<rt>ほうりつ</rt></ruby>を<ruby>勉強<rt>べんきょう</rt></ruby>しています。","speech":"弁護士になるために、法律を勉強しています。","id":"Aku belajar hukum <b>untuk</b> menjadi pengacara. <i>(tujuan)</i>"},{"jp":"<ruby>健康<rt>けんこう</rt></ruby>のために、 <ruby>毎朝<rt>まいあさ</rt></ruby><ruby>走<rt>はし</rt></ruby>っています。","speech":"健康のために、毎朝走っています。","id":"<b>Demi</b> kesehatan, aku lari tiap pagi. <i>(Ｎのために)</i>"},{"jp":"<ruby>子<rt>こ</rt></ruby>どもの<ruby>教育<rt>きょういく</rt></ruby>のために、お<ruby>金<rt>かね</rt></ruby>をためています。","speech":"子どもの教育のために、お金をためています。","id":"Aku menabung <b>untuk</b> pendidikan anak. <i>(Ｎのために)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby>も<ruby>結束<rt>けっそく</rt></ruby>バンドに<ruby>貢献<rt>こうけん</rt></ruby>する<b>ために</b> ギターボーカル<ruby>探<rt>さが</rt></ruby>しを!","speech":"私も結束バンドに貢献するためにギターボーカル探しを!","id":"Aku juga mau cari gitaris-vokalis <b>demi</b> berkontribusi buat Kessoku Band! <i>(Ｖるために · tujuan)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 02:57"},{"jp":"チクショー!　 <ruby>俺<rt>おれ</rt></ruby>は こんな<ruby>暮<rt>く</rt></ruby>らしをする<b>ために</b> ここに<ruby>来<rt>き</rt></ruby>たんじゃねえ!","speech":"チクショー!　俺はこんな暮らしをするためにここに来たんじゃねえ!","id":"Sialan! Aku datang ke sini bukan <b>untuk</b> hidup kayak gini! <i>(Ｖるために · tujuan)</i>","source":"この素晴らしい世界に爆焔を！ · EP10 · 00:13"},{"jp":"<ruby>生<rt>い</rt></ruby>き<ruby>残<rt>のこ</rt></ruby>る<b>ために</b>　 <ruby>売<rt>う</rt></ruby>れる<b>ために</b>　これを<ruby>選<rt>えら</rt></ruby>んだんだ","speech":"生き残るために売れるためにこれを選んだんだ","id":"<b>Demi</b> bertahan hidup, <b>demi</b> laku, mereka memilih ini. <i>(Ｖるために)</i>","source":"ガールズバンドクライ · EP08 · 14:37"},{"jp":"<ruby>虹夏<rt>にじか</rt></ruby>ちゃん リョウさん<ruby>結束<rt>けっそく</rt></ruby>バンド<b>のために</b>!","speech":"虹夏ちゃんリョウさん結束バンドのために!","id":"<b>Demi</b> Nijika-chan, Ryo-san, dan Kessoku Band! <i>(Ｎのために · demi)</i>","source":"ぼっち・ざ・ろっく！ · EP01 · 21:56"},{"jp":"お<ruby>兄<rt>にい</rt></ruby>ちゃんが<ruby>小町<rt>こまち</rt></ruby><b>のために</b> <ruby>頑張<rt>がんば</rt></ruby>るなら","speech":"お兄ちゃんが小町のために頑張るなら","id":"Kalau Kakak berjuang <b>demi</b> Komachi… <i>(Ｎのために · demi)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP05 · 07:39"}]},{"id":"n4_b42_02","level":"N4","bab":42,"lokasi":"第42課","titleMain":"〜のに","titleSub":["〜のに使う","〜のに必要だ","〜のにかかる"],"meaning":"Untuk (keperluan)… — fungsi barang, atau biaya / waktu / hal yang dibutuhkan","formula":"Ｖ-る + <b>のに</b> + 使う ／ 便利だ ／ いい ／ 役に立つ ／ 必要だ ／ (時間・お金が) かかる<br>Kata benda: Ｎ + <b>に</b>（引っ越しに使う）","nuance":"<ol><li>Predikat di belakangnya <b>terbatas</b>: 使う, 便利だ, 役に立つ, 必要だ, かかる.</li><li>Menjelaskan <b>fungsi / kegunaan</b> barang, atau <b>ongkos & waktu</b> untuk suatu kegiatan.</li></ol>⚠️ Bukan tujuan tindakan umum: ×勉強するのに日本へ来た → ○勉強する<b>ために</b>. Jangan tertukar dengan のに \"padahal\" (S45).","examples":[{"jp":"このはさみは<ruby>花<rt>はな</rt></ruby>を<ruby>切<rt>き</rt></ruby>るのに<ruby>使<rt>つか</rt></ruby>います。","speech":"このはさみは花を切るのに使います。","id":"Gunting ini <b>dipakai untuk</b> memotong bunga. <i>(のに使う)</i>"},{"jp":"<ruby>日本<rt>にほん</rt></ruby>で<ruby>生活<rt>せいかつ</rt></ruby>するのに、 <ruby>一<rt>いっ</rt></ruby>か<ruby>月<rt>げつ</rt></ruby>いくらぐらいかかりますか。","speech":"日本で生活するのに、一か月いくらぐらいかかりますか。","id":"<b>Untuk</b> hidup di Jepang, kira-kira <b>butuh</b> berapa per bulan? <i>(のにかかる · biaya)</i>"},{"jp":"この<ruby>辞書<rt>じしょ</rt></ruby>は<ruby>漢字<rt>かんじ</rt></ruby>を<ruby>調<rt>しら</rt></ruby>べるのに<ruby>便利<rt>べんり</rt></ruby>です。","speech":"この辞書は漢字を調べるのに便利です。","id":"Kamus ini <b>praktis untuk</b> mencari kanji. <i>(のに便利)</i>"},{"jp":"この<ruby>本<rt>ほん</rt></ruby>を<ruby>全部<rt>ぜんぶ</rt></ruby><ruby>読<rt>よ</rt></ruby>むのに、 <ruby>一週間<rt>いっしゅうかん</rt></ruby>かかりました。","speech":"この本を全部読むのに、一週間かかりました。","id":"<b>Butuh</b> seminggu <b>untuk</b> membaca habis buku ini. <i>(のにかかる · waktu)</i>"},{"jp":"この<ruby>箱<rt>はこ</rt></ruby>は<ruby>引<rt>ひ</rt></ruby>っ<ruby>越<rt>こ</rt></ruby>しに<ruby>使<rt>つか</rt></ruby>います。","speech":"この箱は引っ越しに使います。","id":"Kotak ini <b>dipakai untuk</b> pindahan. <i>(Ｎに使う)</i>"}],"dialogs":[{"jp":"そう<ruby>衛星<rt>えいせい</rt></ruby><ruby>写真<rt>しゃしん</rt></ruby>とかで<ruby>位置<rt>いち</rt></ruby>を<ruby>特定<rt>とくてい</rt></ruby>する<b>のに<ruby>使<rt>つか</rt></ruby>う</b>の","speech":"そう衛星写真とかで位置を特定するのに使うの","id":"Iya, ini <b>dipakai untuk</b> menentukan posisi lewat foto satelit dan semacamnya. <i>(のに使う · fungsi)</i>","source":"宇宙よりも遠い場所 · EP11 · 16:02"},{"jp":"はい<ruby>絵本<rt>えほん</rt></ruby>を<ruby>作<rt>つく</rt></ruby>る<b>のに<ruby>必要<rt>ひつよう</rt></ruby></b>なんです","speech":"はい絵本を作るのに必要なんです","id":"Iya, ini <b>perlu untuk</b> bikin buku bergambar. <i>(のに必要)</i>","source":"本好きの下剋上 司書になるためには手段を選んでいられません 第2期 · EP08 · 06:18"},{"jp":"もう<ruby>半分<rt>はんぶん</rt></ruby>は<ruby>毛皮<rt>けがわ</rt></ruby>を<ruby>加工<rt>かこう</rt></ruby>する<b>のに<ruby>必要<rt>ひつよう</rt></ruby></b>な<ruby>物<rt>もの</rt></ruby>を<ruby>商<rt>あきな</rt></ruby>っている<ruby>人<rt>ひと</rt></ruby>たち","speech":"もう半分は毛皮を加工するのに必要な物を商っている人たち","id":"Separuh lagi adalah orang-orang yang menjual barang yang <b>diperlukan untuk</b> mengolah bulu. <i>(のに必要な N)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP08 · 06:16"},{"jp":"<ruby>1本<rt>いっぽん</rt></ruby>の<ruby>映画<rt>えいが</rt></ruby>を<ruby>作<rt>つく</rt></ruby>る<b>のに<ruby>必要<rt>ひつよう</rt></ruby></b>な<ruby>金<rt>かね</rt></ruby>は<ruby>大体<rt>だいたい</rt></ruby><ruby>2億<rt>におく</rt></ruby>から<ruby>3億<rt>さんおく</rt></ruby>","speech":"1本の映画を作るのに必要な金は大体2億から3億","id":"Duit yang <b>dibutuhkan untuk</b> bikin satu film kira-kira 200 sampai 300 juta yen. <i>(のに必要 · biaya)</i>","source":"【推しの子】第3期 · EP09 · 01:55"},{"jp":"<ruby>私<rt>わたし</rt></ruby><ruby>計算<rt>けいさん</rt></ruby>したんです　 <ruby>縄<rt>なわ</rt></ruby>が ちぎれる<b>のにかかる</b> <ruby>時間<rt>じかん</rt></ruby>を...","speech":"私計算したんです縄がちぎれるのにかかる時間を...","id":"Saya sudah menghitung waktu yang <b>dibutuhkan sampai</b> talinya putus… <i>(のにかかる · waktu)</i>","source":"サイレント・ウィッチ 沈黙の魔女の隠しごと · EP08 · 09:16"}]},{"id":"n4_b43_01","level":"N4","bab":43,"lokasi":"第43課","titleMain":"Ｖ-ます＋そうです","titleSub":["今にも降りそうです","〜そうになる"],"meaning":"Kelihatannya (sebentar lagi) akan… / hampir… — perkiraan dari tanda-tanda yang terlihat sekarang (様態)","formula":"Ｖ-<s>ます</s> + <b>そうです</b>（降りそうです ／ 落ちそうです）<br><b>〜そうになる</b> = hampir saja…（転びそうになった）<br>Negatif: Ｖ-ます + <b>そうもない ／ そうにない</b>","nuance":"<ol><li><b>Tanda-tanda</b> kejadian sebentar lagi, sering dengan <b>今にも</b> (今にも雨が降りそうです).</li><li><b>Prediksi</b> dari situasi (この調子なら5時に終わりそうです).</li><li><b>〜そうになる</b>: hampir terjadi, tapi tidak jadi (泣きそうになった).</li></ol>⚠️ Sambung ke <b>Ｖ-ます</b>. Bentuk biasa + そう (降る<b>そうです</b>) = 伝聞 \"katanya\" (Bab 47)!","examples":[{"jp":"<ruby>今<rt>いま</rt></ruby>にも<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>りそうです。","speech":"今にも雨が降りそうです。","id":"<b>Kelihatannya sebentar lagi</b> hujan. <i>(tanda-tanda)</i>"},{"jp":"シャツのボタンが<ruby>取<rt>と</rt></ruby>れそうですよ。","speech":"シャツのボタンが取れそうですよ。","id":"Kancing kemejamu <b>hampir copot</b>, lho. <i>(tanda-tanda)</i>"},{"jp":"この<ruby>調子<rt>ちょうし</rt></ruby>なら、 <ruby>仕事<rt>しごと</rt></ruby>は<ruby>5時<rt>ごじ</rt></ruby>までに<ruby>終<rt>お</rt></ruby>わりそうです。","speech":"この調子なら、仕事は5時までに終わりそうです。","id":"Kalau begini terus, pekerjaannya <b>sepertinya bakal</b> selesai sebelum jam 5. <i>(prediksi)</i>"},{"jp":"<ruby>寒<rt>さむ</rt></ruby>くて、 <ruby>死<rt>し</rt></ruby>にそうです。","speech":"寒くて、死にそうです。","id":"Dingin banget, <b>rasanya mau</b> mati. <i>(hiperbola)</i>"},{"jp":"<ruby>階段<rt>かいだん</rt></ruby>で<ruby>転<rt>ころ</rt></ruby>びそうになりました。","speech":"階段で転びそうになりました。","id":"Aku <b>hampir</b> jatuh di tangga. <i>(〜そうになる)</i>"}],"dialogs":[{"jp":"<ruby>今<rt>いま</rt></ruby>にも<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>り<b>そう</b>なんだからね","speech":"今にも雨が降りそうなんだからね","id":"Soalnya <b>sebentar lagi kayaknya</b> hujan, tahu! <i>(今にも〜そう · tanda-tanda)</i>","source":"らんま1/2 · EP69 · 03:14"},{"jp":"<ruby>危<rt>あぶ</rt></ruby>ねえな　 <ruby>今<rt>いま</rt></ruby>にも<ruby>倒<rt>たお</rt></ruby>れ<b>そうだ</b>","speech":"危ねえな今にも倒れそうだ","id":"Bahaya nih, dia <b>kelihatannya</b> sebentar lagi <b>tumbang</b>. <i>(tanda-tanda)</i>","source":"はじめの一歩 THE FIGHTING! · EP34 · 10:18"},{"jp":"あぁ ヤバい<ruby>泣<rt>な</rt></ruby>き<b>そう</b>...","speech":"あぁヤバい泣きそう...","id":"Aduh, gawat… <b>rasanya mau</b> nangis… <i>(perasaan sendiri · hampir)</i>","source":"声優ラジオのウラオモテ · EP03 · 19:20"},{"jp":"<ruby>馬小屋<rt>うまごや</rt></ruby>で<ruby>寝泊<rt>ねと</rt></ruby>まりしたら-　 <ruby>体力<rt>たいりょく</rt></ruby><ruby>回復<rt>かいふく</rt></ruby>どころか<ruby>凍<rt>こご</rt></ruby>え<ruby>死<rt>し</rt></ruby>に<b>そうになる</b>わ","speech":"馬小屋で寝泊まりしたら-　体力回復どころか凍え死にそうになるわ","id":"Tidur di kandang kuda, boro-boro pulih tenaga, malah <b>hampir</b> mati kedinginan! <i>(〜そうになる · hampir)</i>","source":"この素晴らしい世界に祝福を！ · EP07 · 14:22"},{"jp":"<ruby>今<rt>いま</rt></ruby><ruby>私<rt>わたし</rt></ruby>は<ruby>荷台<rt>にだい</rt></ruby>から<ruby>転<rt>ころ</rt></ruby>げ<ruby>落<rt>お</rt></ruby>ち<b>そうに なっている</b> <ruby>積<rt>つ</rt></ruby>み<ruby>荷<rt>に</rt></ruby>を　 <ruby>戻<rt>もど</rt></ruby>そうとしています","speech":"今私は荷台から転げ落ちそうになっている積み荷を戻そうとしています","id":"Sekarang saya sedang berusaha mengembalikan muatan yang <b>hampir</b> terguling jatuh dari gerobak. <i>(〜そうになる)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP18 · 07:19"}]},{"id":"n4_b43_02","level":"N4","bab":43,"lokasi":"第43課","titleMain":"形容詞＋そうです","titleSub":["おいしそう","元気そう","よさそう"],"meaning":"Kelihatannya / tampaknya (enak, senang, bagus…) — kesan dari penampilan, belum dipastikan","formula":"KS-i: buang <s>い</s> + <b>そう</b>（おいしそう）· KS-na + <b>そう</b>（元気そう）<br>Pengecualian: いい → <b>よさそう</b> · ない → <b>なさそう</b><br><b>そうな</b> + N（おいしそうなケーキ）· <b>そうに</b> + V（楽しそうに遊ぶ）","nuance":"<ol><li>Kesan <b>sebelum tahu pasti</b>: おいしそう = kelihatannya enak (belum dicicip).</li><li>Menebak <b>perasaan orang lain</b> dari raut wajah: うれしそう, 楽しそう, 寂しそう.</li><li>Tidak untuk hal yang sudah jelas terlihat (×このりんごは赤そうです).</li></ol>⚠️ <b>かわいそう</b> = kasihan (bukan \"kelihatan imut\"). Negatif: おいしく<b>なさそう</b> / おいしそうじゃない.","examples":[{"jp":"この<ruby>料理<rt>りょうり</rt></ruby>はおいしそうです。","speech":"この料理はおいしそうです。","id":"Masakan ini <b>kelihatannya enak</b>. <i>(KS-i)</i>"},{"jp":"ミラーさんはうれしそうですね。","speech":"ミラーさんはうれしそうですね。","id":"Miller-san <b>kelihatan senang</b>, ya. <i>(perasaan orang lain)</i>"},{"jp":"この<ruby>辞書<rt>じしょ</rt></ruby>はよさそうですね。","speech":"この辞書はよさそうですね。","id":"Kamus ini <b>kelihatannya bagus</b>, ya. <i>(いい → よさそう)</i>"},{"jp":"<ruby>丈夫<rt>じょうぶ</rt></ruby>そうなかばんを<ruby>買<rt>か</rt></ruby>いました。","speech":"丈夫そうなかばんを買いました。","id":"Aku membeli tas yang <b>kelihatannya kuat</b>. <i>(そうな + N)</i>"},{"jp":"<ruby>子<rt>こ</rt></ruby>どもたちが<ruby>楽<rt>たの</rt></ruby>しそうに <ruby>遊<rt>あそ</rt></ruby>んでいます。","speech":"子どもたちが楽しそうに遊んでいます。","id":"Anak-anak bermain <b>dengan riang</b>. <i>(そうに + V)</i>"}],"dialogs":[{"jp":"スモア? おいし<b>そう</b>","speech":"スモア? おいしそう","id":"S'mores? <b>Kelihatannya enak!</b> <i>(KS-i · kesan)</i>","source":"ゆるキャン△ · EP11 · 05:32"},{"jp":"ぼっちちゃん<ruby>楽<rt>たの</rt></ruby>し<b>そうだね</b>","speech":"ぼっちちゃん楽しそうだね","id":"Bocchi-chan <b>kelihatan senang</b> ya. <i>(perasaan orang lain)</i>","source":"ぼっち・ざ・ろっく！ · EP07 · 04:27"},{"jp":"ゆず<ruby>風呂<rt>ぶろ</rt></ruby><ruby>気持<rt>きも</rt></ruby>ちよ<b>さそうだね</b>","speech":"ゆず風呂気持ちよさそうだね","id":"Mandi yuzu <b>kelihatannya enak</b> ya. <i>(いい → よさそう)</i>","source":"ゆるキャン△ SEASON２ · EP09 · 06:09"},{"jp":"<ruby>元気<rt>げんき</rt></ruby><b>そう</b>でよかったよ","speech":"元気そうでよかったよ","id":"Syukurlah kamu <b>kelihatan sehat</b>. <i>(KS-na + そう)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP05 · 03:56"},{"jp":"ホント なでしこって おいし<b>そうに</b> <ruby>食<rt>た</rt></ruby>べるよね","speech":"ホントなでしこっておいしそうに食べるよね","id":"Nadeshiko tuh beneran makannya <b>kelihatan lahap</b> banget ya. <i>(そうに + V)</i>","source":"ゆるキャン△ SEASON２ · EP03 · 13:29"}]},{"id":"n4_b43_03","level":"N4","bab":43,"lokasi":"第43課","titleMain":"〜てきます","titleSub":["ちょっと〜てきます","行ってきます"],"meaning":"(Pergi) …dulu, nanti kembali — pergi melakukan sesuatu lalu balik ke tempat semula","formula":"Ｖ-て + <b>きます</b>（借りてきます ／ 買ってきます）<br>Sering dengan <b>ちょっと</b> · tempat kegiatan + <b>で</b>（コンビニで買ってきます）<br>Salam: <b>行ってきます</b> → 行ってらっしゃい","nuance":"<ol><li><b>Pergi – lakukan – kembali</b>: ちょっと辞書を借りてきます.</li><li><b>行ってきます</b> = pergi dan akan pulang (salam keluar rumah).</li></ol>⚠️ 〜てくる juga berarti <b>arah ke pembicara</b> (電話がかかってきた) dan <b>perubahan mulai terjadi</b> (寒くなってきました).","examples":[{"jp":"ちょっと<ruby>辞書<rt>じしょ</rt></ruby>を<ruby>借<rt>か</rt></ruby>りてきます。","speech":"ちょっと辞書を借りてきます。","id":"Aku <b>pinjam</b> kamus <b>sebentar</b> (lalu balik). <i>(pergi–lakukan–kembali)</i>"},{"jp":"<ruby>郵便局<rt>ゆうびんきょく</rt></ruby>へ<ruby>行<rt>い</rt></ruby>ってきます。","speech":"郵便局へ行ってきます。","id":"Aku <b>ke</b> kantor pos <b>dulu</b>. <i>(nanti kembali)</i>"},{"jp":"コンビニでジュースを<ruby>買<rt>か</rt></ruby>ってきます。","speech":"コンビニでジュースを買ってきます。","id":"Aku <b>beli</b> jus di minimarket <b>dulu</b>. <i>(tempat + で)</i>"},{"jp":"ちょっと<ruby>出<rt>で</rt></ruby>かけてきます。","speech":"ちょっと出かけてきます。","id":"Aku <b>keluar sebentar</b> ya. <i>(ちょっと)</i>"}],"dialogs":[{"jp":"あっ は... はい! <ruby>今<rt>いま</rt></ruby> そこで<ruby>買<rt>か</rt></ruby>っ<b>てきます</b>","speech":"あっは... はい! 今そこで買ってきます","id":"Ah, i… iya! Aku <b>beli dulu</b> di situ sekarang! <i>(pergi–beli–kembali)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 04:45"},{"jp":"<ruby>家<rt>いえ</rt></ruby><ruby>行<rt>い</rt></ruby>って ギター<ruby>取<rt>と</rt></ruby>っ<b>てくる</b>から","speech":"家行ってギター取ってくるから","id":"Aku pulang <b>ambil</b> gitar <b>dulu</b> ya! <i>(kasual 〜てくる)</i>","source":"ガールズバンドクライ · EP09 · 09:43"},{"jp":"よし コンビニ<ruby>行<rt>い</rt></ruby>って<ruby>買<rt>か</rt></ruby>っ<b>てくる</b>","speech":"よしコンビニ行って買ってくる","id":"Oke, aku ke minimarket <b>beli dulu</b>. <i>(pergi–beli–kembali)</i>","source":"ゆるキャン△ SEASON２ · EP06 · 11:17"},{"jp":"<ruby>分<rt>わ</rt></ruby>かりました<ruby>見<rt>み</rt></ruby><b>てきます</b>","speech":"分かりました見てきます","id":"Baik, aku <b>lihat dulu</b> (lalu kembali). <i>(sopan)</i>","source":"ゆるキャン△ SEASON２ · EP13 · 09:23"},{"jp":"なにか<ruby>飲<rt>の</rt></ruby>み<ruby>物<rt>もの</rt></ruby>をとっ<b>てきます</b>ね","speech":"なにか飲み物をとってきますね","id":"Saya <b>ambilkan</b> minuman <b>dulu</b> ya. <i>(sopan)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP11 · 18:41"}]},{"id":"n4_b44_01","level":"N4","bab":44,"lokasi":"第44課","titleMain":"〜すぎます","titleSub":["飲みすぎる","高すぎる"],"meaning":"Terlalu… / ke-…-an — melewati batas wajar, biasanya berakibat buruk","formula":"Ｖ-<s>ます</s> + <b>すぎる</b>（飲みすぎる）<br>KS-<s>い</s> + <b>すぎる</b>（高すぎる）· KS-na + <b>すぎる</b>（複雑すぎる）<br>いい → <b>よすぎる</b> · ない → <b>なさすぎる</b> · KB: <b>〜すぎ</b>（食べすぎだよ）","nuance":"<ol><li>すぎる = KK golongan 2 → すぎます / すぎた / すぎて / すぎない.</li><li><b>〜すぎて、〜</b> = alasan (食べすぎて、おなかが痛い).</li><li>Default-nya <b>negatif</b>; かわいすぎる！ = hiperbola kasual.</li></ol>⚠️ いい → <b>よすぎる</b> (×いすぎる). Bentuk KB <b>〜すぎ</b>: 考えすぎ = overthinking.","examples":[{"jp":"<ruby>昨日<rt>きのう</rt></ruby>はお<ruby>酒<rt>さけ</rt></ruby>を<ruby>飲<rt>の</rt></ruby>みすぎました。","speech":"昨日はお酒を飲みすぎました。","id":"Kemarin aku <b>minum terlalu banyak</b>. <i>(Ｖ + すぎる)</i>"},{"jp":"このセーターは<ruby>大<rt>おお</rt></ruby>きすぎます。","speech":"このセーターは大きすぎます。","id":"Sweter ini <b>terlalu besar</b>. <i>(KS-i)</i>"},{"jp":"このパソコンの<ruby>使<rt>つか</rt></ruby>い<ruby>方<rt>かた</rt></ruby>は<ruby>複雑<rt>ふくざつ</rt></ruby>すぎて、よく<ruby>分<rt>わ</rt></ruby>かりません。","speech":"このパソコンの使い方は複雑すぎて、よく分かりません。","id":"Cara pakai komputer ini <b>terlalu rumit</b>, jadi nggak begitu paham. <i>(KS-na · すぎて = alasan)</i>"},{"jp":"<ruby>食<rt>た</rt></ruby>べすぎると、おなかを<ruby>壊<rt>こわ</rt></ruby>しますよ。","speech":"食べすぎると、おなかを壊しますよ。","id":"Kalau <b>makan kebanyakan</b>, nanti sakit perut lho. <i>(peringatan)</i>"},{"jp":"<ruby>最近<rt>さいきん</rt></ruby>、 <ruby>仕事<rt>しごと</rt></ruby>が<ruby>忙<rt>いそが</rt></ruby>しすぎて、 <ruby>全然<rt>ぜんぜん</rt></ruby><ruby>寝<rt>ね</rt></ruby>ていません。","speech":"最近、仕事が忙しすぎて、全然寝ていません。","id":"Akhir-akhir ini kerjaan <b>terlalu sibuk</b>, aku sama sekali nggak tidur. <i>(alasan)</i>"}],"dialogs":[{"jp":"スープ<ruby>飲<rt>の</rt></ruby>み<b>すぎた</b>","speech":"スープ飲みすぎた","id":"Kebanyakan <b>minum</b> sup nih. <i>(Ｖ + すぎる)</i>","source":"ゆるキャン△ · EP01 · 12:24"},{"jp":"いいのいいの ちょっと<ruby>多<rt>おお</rt></ruby>く<ruby>作<rt>つく</rt></ruby>り<b>すぎた</b>しさ","speech":"いいのいいのちょっと多く作りすぎたしさ","id":"Nggak apa-apa, aku agak <b>kebanyakan bikin</b> kok. <i>(Ｖ + すぎる)</i>","source":"ゆるキャン△ · EP07 · 13:55"},{"jp":"<ruby>下北<rt>しもきた</rt></ruby>の<ruby>街<rt>まち</rt></ruby>なかで<ruby>写真<rt>しゃしん</rt></ruby><ruby>撮<rt>と</rt></ruby>るなんて　 <ruby>陰<rt>いん</rt></ruby>キャにはハードル<ruby>高<rt>たか</rt></ruby><b>すぎる</b>!","speech":"下北の街なかで写真撮るなんて陰キャにはハードル高すぎる!","id":"Foto-foto di tengah kota Shimokita? Buat introvert kayak aku itu <b>terlalu berat</b>! <i>(KS-i + すぎる)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 09:20"},{"jp":"<ruby>関税<rt>かんぜい</rt></ruby>が<ruby>高<rt>たか</rt></ruby><b>すぎる</b>んだよ","speech":"関税が高すぎるんだよ","id":"Bea cukainya <b>terlalu tinggi</b>! <i>(KS-i + すぎる)</i>","source":"狼と香辛料 · EP08 · 16:59"},{"jp":"<ruby>五月<rt>いつき</rt></ruby><ruby>食<rt>た</rt></ruby>べ<b>すぎ</b>じゃない?","speech":"五月食べすぎじゃない?","id":"Itsuki, kamu <b>kebanyakan makan</b> nggak sih? <i>(KB 〜すぎ)</i>","source":"五等分の花嫁 · EP01 · 09:34"}]},{"id":"n4_b44_02","level":"N4","bab":44,"lokasi":"第44課","titleMain":"〜やすい・〜にくい","titleSub":["使いやすい","読みにくい"],"meaning":"Mudah (di-)… / susah (di-)… — sifat benda, tingkat kesulitan, atau kecenderungan","formula":"Ｖ-<s>ます</s> + <b>やすい</b>（使いやすい ／ 汚れやすい）<br>Ｖ-<s>ます</s> + <b>にくい</b>（読みにくい ／ 割れにくい）<br>Konjugasi seperti KS-i: やす<b>く</b>なる ／ にく<b>かった</b>","nuance":"<ol><li><b>Sifat / kesulitan</b>: 使いやすい, 読みにくい, 言いにくい (sungkan bilang).</li><li><b>Kecenderungan</b> (KK non-kehendak): 白いシャツは汚れやすい, このコップは割れにくい.</li></ol>⚠️ やすい (易い) ≠ 安い (murah). <b>〜づらい</b> (N3) = susah karena beban fisik / perasaan.","examples":[{"jp":"このパソコンは<ruby>使<rt>つか</rt></ruby>いやすいです。","speech":"このパソコンは使いやすいです。","id":"Komputer ini <b>mudah dipakai</b>. <i>(sifat benda)</i>"},{"jp":"この<ruby>字<rt>じ</rt></ruby>は<ruby>小<rt>ちい</rt></ruby>さくて、 <ruby>読<rt>よ</rt></ruby>みにくいです。","speech":"この字は小さくて、読みにくいです。","id":"Huruf ini kecil, jadi <b>susah dibaca</b>. <i>(sifat benda)</i>"},{"jp":"<ruby>白<rt>しろ</rt></ruby>いシャツは<ruby>汚<rt>よご</rt></ruby>れやすいです。","speech":"白いシャツは汚れやすいです。","id":"Kemeja putih <b>gampang kotor</b>. <i>(kecenderungan)</i>"},{"jp":"このコップは<ruby>割<rt>わ</rt></ruby>れにくいです。","speech":"このコップは割れにくいです。","id":"Gelas ini <b>nggak gampang pecah</b>. <i>(kecenderungan)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>の<ruby>説明<rt>せつめい</rt></ruby>は<ruby>分<rt>わ</rt></ruby>かりやすいです。","speech":"先生の説明は分かりやすいです。","id":"Penjelasan guru <b>mudah dipahami</b>. <i>(sifat)</i>"}],"dialogs":[{"jp":"そうね これが<ruby>一番<rt>いちばん</rt></ruby> わかり<b>やすい</b>かも","speech":"そうねこれが一番わかりやすいかも","id":"Iya ya, yang ini mungkin paling <b>gampang dipahami</b>. <i>(やすい)</i>","source":"ガールズバンドクライ · EP12 · 20:17"},{"jp":"はい カイジン<ruby>様<rt>さま</rt></ruby>が<ruby>作<rt>つく</rt></ruby>ってくださった<ruby>織機<rt>しょっき</rt></ruby>は　とても<ruby>使<rt>つか</rt></ruby>い<b>やすい</b>です","speech":"はいカイジン様が作ってくださった織機はとても使いやすいです","id":"Iya, alat tenun yang dibuatkan Tuan Kaijin sangat <b>mudah dipakai</b>. <i>(やすい · sifat benda)</i>","source":"転生したらスライムだった件 · EP11 · 02:10"},{"jp":"そうだな<ruby>字<rt>じ</rt></ruby>も ちょっと<ruby>読<rt>よ</rt></ruby>み<b>にくい</b>しな","speech":"そうだな字もちょっと読みにくいしな","id":"Iya juga, tulisannya juga agak <b>susah dibaca</b>. <i>(にくい · sifat benda)</i>","source":"本好きの下剋上 司書になるためには手段を選んでいられません 第2期 · EP08 · 10:58"},{"jp":"その... <ruby>言<rt>い</rt></ruby>い<b>にくい</b>というか　 <ruby>言<rt>い</rt></ruby>うのが<ruby>恥<rt>は</rt></ruby>ずかしいのですけど","speech":"その... 言いにくいというか言うのが恥ずかしいのですけど","id":"Anu… gimana ya, <b>susah ngomongnya</b>, atau lebih tepatnya malu buat bilang… <i>(言いにくい · sungkan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP01 · 03:29"},{"jp":"なんというか<ruby>入<rt>はい</rt></ruby>り<b>にくい</b> <ruby>雰囲気<rt>ふんいき</rt></ruby>というか...","speech":"なんというか入りにくい雰囲気というか...","id":"Gimana ya, suasananya bikin <b>susah masuk</b>, gitu… <i>(にくい + N)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP08 · 18:34"}]},{"id":"n4_b44_03","level":"N4","bab":44,"lokasi":"第44課","titleMain":"Ｎにします","titleSub":["何にしますか","コーヒーにします"],"meaning":"Saya pilih… / (kita) putuskan… — memilih satu dari beberapa pilihan","formula":"Ｎ + <b>にします</b>（コーヒーにします）<br>Tanya: 何 + <b>にしますか</b><br>Ajakan: Ｎ + <b>にしよう ／ にしましょう</b>","nuance":"<ol><li><b>Memesan / memilih</b> (menu, kamar, warna): オレンジジュースにします.</li><li><b>Menetapkan</b> jadwal / tempat: 会議は明日にします.</li></ol>⚠️ <b>Ｖことにします</b> = memutuskan <i>melakukan</i>. <b>Ｎになります</b> = jadi / diputuskan (bukan kehendak saya).","examples":[{"jp":"<ruby>部屋<rt>へや</rt></ruby>はシングルにしますか、ツインにしますか。","speech":"部屋はシングルにしますか、ツインにしますか。","id":"Kamarnya <b>mau pilih</b> single atau twin? <i>(memilih)</i>"},{"jp":"<ruby>会議<rt>かいぎ</rt></ruby>は<ruby>明日<rt>あした</rt></ruby>にします。","speech":"会議は明日にします。","id":"Rapatnya <b>kita tetapkan</b> besok. <i>(menetapkan jadwal)</i>"},{"jp":"<ruby>今夜<rt>こんや</rt></ruby>はカレーにします。","speech":"今夜はカレーにします。","id":"Malam ini <b>aku pilih</b> kari. <i>(memilih menu)</i>"},{"jp":"<ruby>飲<rt>の</rt></ruby>み<ruby>物<rt>もの</rt></ruby>は<ruby>何<rt>なに</rt></ruby>にしますか。……オレンジジュースにします。","speech":"飲み物は何にしますか。……オレンジジュースにします。","id":"Minumnya <b>mau apa</b>? — <b>Saya pesan</b> jus jeruk. <i>(memesan)</i>"}],"dialogs":[{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby> キャンプごはんは<ruby>何<rt>なに</rt></ruby><b>にしますか</b>?","speech":"部長キャンプごはんは何にしますか?","id":"Ketua, menu makan kemahnya <b>mau apa</b>? <i>(何にしますか)</i>","source":"ゆるキャン△ · EP04 · 00:28"},{"jp":"これ<b>にする</b>わサンキュ","speech":"これにするわサンキュ","id":"<b>Aku pilih</b> yang ini deh, makasih. <i>(memilih)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP07 · 14:28"},{"jp":"ほんまや<ruby>私<rt>わたし</rt></ruby> それ<b>にする</b>わ","speech":"ほんまや私それにするわ","id":"Eh iya bener, aku <b>pesan</b> itu aja deh. <i>(memesan · logat Kansai)</i>","source":"ゆるキャン△ SEASON２ · EP05 · 12:11"},{"jp":"<ruby>応援<rt>おうえん</rt></ruby>ソング<b>にしよう</b>","speech":"応援ソングにしよう","id":"<b>Kita bikin</b> lagu penyemangat <b>aja</b>! <i>(にしよう · memutuskan)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 07:41"},{"jp":"そろそろ<ruby>夕飯<rt>ゆうはん</rt></ruby><b>にしよう</b>か はーい","speech":"そろそろ夕飯にしようかはーい","id":"Udah waktunya, <b>kita makan malam</b> yuk? — Iyaa. <i>(にしよう · ajakan)</i>","source":"ゆるキャン△ SEASON２ · EP08 · 11:13"}]},{"id":"n4_b44_04","level":"N4","bab":44,"lokasi":"第44課","titleMain":"〜くします・〜にします","titleSub":["大きくする","きれいにする"],"meaning":"Membuat (sesuatu) jadi… — mengubah keadaan dengan sengaja","formula":"Ｎ を + KS-<s>い</s> <b>く</b> + <b>する</b>（音を大きくする）<br>Ｎ を + KS-na / Ｎ + <b>に</b> + <b>する</b>（部屋をきれいにする）<br>いい → <b>よくする</b>","nuance":"<ol><li><b>〜くする / 〜にする</b> = ada pelaku yang <b>sengaja</b> mengubah.</li><li><b>〜くなる / 〜になる</b> = berubah dengan sendirinya.</li><li>KS sebagai keterangan: 野菜を細かく切る (memotong halus-halus).</li></ol>⚠️ 部屋を暖かく<b>する</b> (aku menghangatkan) ↔ 部屋が暖かく<b>なる</b> (jadi hangat). Ungkapan tetap: 大事にする, 幸せにする.","examples":[{"jp":"<ruby>音<rt>おと</rt></ruby>を<ruby>大<rt>おお</rt></ruby>きくします。","speech":"音を大きくします。","id":"Aku <b>besarkan</b> suaranya. <i>(KS-i)</i>"},{"jp":"<ruby>部屋<rt>へや</rt></ruby>をきれいにします。","speech":"部屋をきれいにします。","id":"Aku <b>bersihkan</b> kamar. <i>(KS-na)</i>"},{"jp":"ズボンを<ruby>短<rt>みじか</rt></ruby>くしてください。","speech":"ズボンを短くしてください。","id":"Tolong <b>pendekkan</b> celananya. <i>(KS-i)</i>"},{"jp":"<ruby>図書館<rt>としょかん</rt></ruby>の<ruby>中<rt>なか</rt></ruby>では<ruby>静<rt>しず</rt></ruby>かにしてください。","speech":"図書館の中では静かにしてください。","id":"Di dalam perpustakaan tolong <b>tenang</b>. <i>(KS-na)</i>"},{"jp":"<ruby>野菜<rt>やさい</rt></ruby>を<ruby>細<rt>こま</rt></ruby>かく <ruby>切<rt>き</rt></ruby>ります。","speech":"野菜を細かく切ります。","id":"Sayurnya dipotong <b>halus-halus</b>. <i>(〜く + Ｖ)</i>"}],"dialogs":[{"jp":"そこうるさいです<ruby>考<rt>かんが</rt></ruby>えてるから<ruby>静<rt>しず</rt></ruby>か<b>にして</b>ください","speech":"そこうるさいです考えてるから静かにしてください","id":"Situ berisik. Aku lagi mikir, jadi tolong <b>diam</b>. <i>(KS-na + にする)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP11 · 10:21"},{"jp":"<ruby>一度<rt>いちど</rt></ruby><ruby>網<rt>あみ</rt></ruby>をきれい<b>にして</b>...","speech":"一度網をきれいにして...","id":"<b>Bersihkan</b> dulu panggangannya sekali… <i>(KS-na + にする)</i>","source":"ゆるキャン△ · EP06 · 05:22"},{"jp":"<ruby>少<rt>すこ</rt></ruby>し<ruby>短<rt>みじか</rt></ruby><b>くして</b>みるか","speech":"少し短くしてみるか","id":"Coba <b>kupendekkan</b> sedikit, ah. <i>(KS-i + くする)</i>","source":"乙女ゲー世界はモブに厳しい世界です · EP05 · 15:52"},{"jp":"<ruby>規模<rt>きぼ</rt></ruby>を<ruby>大<rt>おお</rt></ruby>き<b>くする</b>には<ruby>時間<rt>じかん</rt></ruby>と<ruby>人手<rt>ひとで</rt></ruby>が<ruby>足<rt>た</rt></ruby>りないぞ","speech":"規模を大きくするには時間と人手が足りないぞ","id":"Buat <b>memperbesar</b> skalanya, waktu dan tenaga kita nggak cukup. <i>(KS-i + くする)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP06 · 18:42"},{"jp":"<ruby>幸<rt>しあわ</rt></ruby>せ<b>にする</b> <ruby>自信<rt>じしん</rt></ruby>もありますし　 <ruby>幸<rt>しあわ</rt></ruby>せ<b>にして</b>みせます","speech":"幸せにする自信もありますし幸せにしてみせます","id":"Saya yakin bisa <b>membahagiakannya</b>, dan pasti akan saya <b>bahagiakan</b>. <i>(幸せにする)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP06 · 16:22"}]},{"id":"n4_b45_01","level":"N4","bab":45,"lokasi":"第45課","titleMain":"〜場合は","titleSub":["Ｖる・Ｖた場合は","Ｎの場合は"],"meaning":"Dalam hal… / jika (terjadi)…, maka… — situasi hipotetis / darurat dan cara menanganinya","formula":"Ｖ-る / Ｖ-ない / Ｖ-た + <b>場合は</b>（遅れる場合は ／ なくした場合は）<br>KS-i + <b>場合は</b> · KS-na + <b>な場合は</b>（必要な場合は）<br>Ｎ + <b>の場合は</b>（火事の場合は）","nuance":"<ol><li>Khas <b>pengumuman, aturan, manual</b>; klausa B = instruksi (〜てください / 〜ないでください).</li><li><b>Ｎの場合は</b> juga = \"kalau soal N…\" (私の場合は…).</li><li>Ｖる場合 = sebelum terjadi; Ｖた場合 = setelah terjadi.</li></ol>⚠️ Untuk kejadian pasti / sudah terjadi pakai <b>とき</b> (×昨日駅に着いた場合 → ○着いたとき).","examples":[{"jp":"<ruby>火事<rt>かじ</rt></ruby>や<ruby>地震<rt>じしん</rt></ruby>の<ruby>場合<rt>ばあい</rt></ruby>は、エレベーターを<ruby>使<rt>つか</rt></ruby>わないでください。","speech":"火事や地震の場合は、エレベーターを使わないでください。","id":"<b>Dalam hal</b> kebakaran atau gempa, jangan gunakan lift. <i>(Ｎの場合は)</i>"},{"jp":"<ruby>約束<rt>やくそく</rt></ruby>の<ruby>時間<rt>じかん</rt></ruby>に<ruby>遅<rt>おく</rt></ruby>れる<ruby>場合<rt>ばあい</rt></ruby>は、 <ruby>連絡<rt>れんらく</rt></ruby>してください。","speech":"約束の時間に遅れる場合は、連絡してください。","id":"<b>Jika</b> akan terlambat dari waktu janjian, tolong hubungi kami. <i>(Ｖる場合は)</i>"},{"jp":"<ruby>領収書<rt>りょうしゅうしょ</rt></ruby>が<ruby>必要<rt>ひつよう</rt></ruby>な<ruby>場合<rt>ばあい</rt></ruby>は、 <ruby>言<rt>い</rt></ruby>ってください。","speech":"領収書が必要な場合は、言ってください。","id":"<b>Jika</b> perlu kuitansi, silakan bilang. <i>(KS-na な場合は)</i>"},{"jp":"カードをなくした<ruby>場合<rt>ばあい</rt></ruby>は、すぐに<ruby>銀行<rt>ぎんこう</rt></ruby>に<ruby>連絡<rt>れんらく</rt></ruby>してください。","speech":"カードをなくした場合は、すぐに銀行に連絡してください。","id":"<b>Jika</b> kartunya hilang, segera hubungi bank. <i>(Ｖた場合は)</i>"},{"jp":"<ruby>機械<rt>きかい</rt></ruby>が<ruby>故障<rt>こしょう</rt></ruby>した<ruby>場合<rt>ばあい</rt></ruby>は、このボタンを<ruby>押<rt>お</rt></ruby>してください。","speech":"機械が故障した場合は、このボタンを押してください。","id":"<b>Jika</b> mesinnya rusak, tekan tombol ini. <i>(Ｖた場合は)</i>"}],"dialogs":[{"jp":"<ruby>買<rt>か</rt></ruby>う<b><ruby>場合<rt>ばあい</rt></ruby>は</b> <ruby>薪屋<rt>まきや</rt></ruby>さんのものがオススメで-","speech":"買う場合は薪屋さんのものがオススメで-","id":"<b>Kalau</b> mau beli, aku saranin yang dari toko kayu bakar… <i>(Ｖる場合は · saran)</i>","source":"ゆるキャン△ · EP01 · 08:37"},{"jp":"<ruby>用事<rt>ようじ</rt></ruby>があり<ruby>食事<rt>しょくじ</rt></ruby>を<ruby>共<rt>とも</rt></ruby>に<ruby>取<rt>と</rt></ruby>らない<b><ruby>場合<rt>ばあい</rt></ruby>は</b>","speech":"用事があり食事を共に取らない場合は","id":"<b>Dalam hal</b> ada urusan dan kita tidak makan bersama… <i>(Ｖない場合は · aturan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP02 · 08:53"},{"jp":"そういう<b><ruby>場合<rt>ばあい</rt></ruby>は</b> <ruby>結婚<rt>けっこん</rt></ruby>が<ruby>前提<rt>ぜんてい</rt></ruby>だ","speech":"そういう場合は結婚が前提だ","id":"<b>Kalau</b> begitu <b>kasusnya</b>, ya harus menikah dulu. <i>(そういう場合は)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP08 · 20:04"},{"jp":"<ruby>最悪<rt>さいあく</rt></ruby><b>の<ruby>場合<rt>ばあい</rt></ruby>は</b>ね","speech":"最悪の場合はね","id":"Ya, <b>kalau</b> keadaannya paling buruk. <i>(Ｎの場合は)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP12 · 04:34"},{"jp":"わっち<b>の<ruby>場合<rt>ばあい</rt></ruby>は</b> <ruby>生<rt>い</rt></ruby>き<ruby>血<rt>ち</rt></ruby>か　それが<ruby>僅<rt>わず</rt></ruby>かな<ruby>麦<rt>むぎ</rt></ruby>か","speech":"わっちの場合は生き血かそれが僅かな麦か","id":"<b>Kalau</b> aku sih, butuh darah segar… atau sedikit gandum. <i>(Ｎの場合は · kalau soal N)</i>","source":"狼と香辛料 · EP01 · 13:18"}]},{"id":"n4_b45_02","level":"N4","bab":45,"lokasi":"第45課","titleMain":"〜のに","titleSub":["〜したのに","〜なのに"],"meaning":"Padahal… / meskipun… (kok malah)… — hasil berbeda dari harapan, dengan rasa kecewa / heran / kesal","formula":"Ｖ / KS-i (bentuk biasa) + <b>のに</b>（頑張ったのに ／ 高いのに）<br>KS-na / Ｎ + <b>な</b> + <b>のに</b>（好きなのに ／ 日曜日なのに）<br>Akhir kalimat: 〜<b>のに</b>！（言ったのに！）","nuance":"<ol><li>Emosi <b>kuat</b> (kecewa, tidak puas, heran) — bedanya dengan ても / けど yang netral.</li><li>A biasanya <b>fakta</b> yang sudah terjadi / sedang berlangsung.</li><li>Di akhir kalimat = keluhan / penyesalan: だから言ったのに！</li></ol>⚠️ Klausa B <b>tidak boleh</b> permintaan / perintah / niat / ajakan (×雨なのに出かけましょう → けど). Bedakan dengan のに tujuan (S42).","examples":[{"jp":"ダイエットしているのに、 <ruby>太<rt>ふと</rt></ruby>ってしまいました。","speech":"ダイエットしているのに、太ってしまいました。","id":"<b>Padahal</b> lagi diet, eh malah gemuk. <i>(kecewa)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>は<ruby>日曜日<rt>にちようび</rt></ruby>なのに、 <ruby>働<rt>はたら</rt></ruby>かなければなりません。","speech":"今日は日曜日なのに、働かなければなりません。","id":"<b>Padahal</b> hari Minggu, aku harus kerja. <i>(Ｎ + なのに · tidak puas)</i>"},{"jp":"<ruby>一生懸命<rt>いっしょうけんめい</rt></ruby><ruby>勉強<rt>べんきょう</rt></ruby>したのに、 <ruby>試験<rt>しけん</rt></ruby>に<ruby>落<rt>お</rt></ruby>ちました。","speech":"一生懸命勉強したのに、試験に落ちました。","id":"<b>Padahal</b> sudah belajar mati-matian, aku gagal ujian. <i>(kecewa)</i>"},{"jp":"<ruby>約束<rt>やくそく</rt></ruby>したのに、 <ruby>彼女<rt>かのじょ</rt></ruby>は<ruby>来<rt>き</rt></ruby>ませんでした。","speech":"約束したのに、彼女は来ませんでした。","id":"<b>Padahal</b> sudah janji, dia nggak datang. <i>(kesal)</i>"},{"jp":"このパソコンは<ruby>高<rt>たか</rt></ruby>いのに、すぐ<ruby>壊<rt>こわ</rt></ruby>れました。","speech":"このパソコンは高いのに、すぐ壊れました。","id":"<b>Padahal</b> komputer ini mahal, cepat sekali rusak. <i>(KS-i + のに)</i>"}],"dialogs":[{"jp":"<ruby>練習<rt>れんしゅう</rt></ruby><ruby>頑張<rt>がんば</rt></ruby>った<b>のに</b> かわいそうですね","speech":"練習頑張ったのにかわいそうですね","id":"<b>Padahal</b> mereka udah latihan keras, kasihan ya. <i>(Ｖた + のに · simpati)</i>","source":"ぼっち・ざ・ろっく！ · EP08 · 00:37"},{"jp":"ライブまで あと<ruby>10日<rt>とおか</rt></ruby><b>なのに</b>...","speech":"ライブまであと10日なのに...","id":"<b>Padahal</b> live tinggal 10 hari lagi… <i>(Ｎ + なのに · cemas)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 01:10"},{"jp":"コンパクト<b>なのに</b> しっかりしてるよね","speech":"コンパクトなのにしっかりしてるよね","id":"<b>Padahal</b> kecil, tapi kokoh ya. <i>(KS-na + なのに · heran)</i>","source":"ゆるキャン△ SEASON２ · EP06 · 02:39"},{"jp":"じゃから<ruby>釣<rt>つ</rt></ruby>り<ruby>合<rt>あ</rt></ruby>わぬと<ruby>言<rt>い</rt></ruby>った<b>のに</b>","speech":"じゃから釣り合わぬと言ったのに","id":"Makanya kan sudah kubilang nggak sepadan! <i>(言ったのに · akhir kalimat, kesal)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP08 · 11:11"},{"jp":"それは<ruby>分<rt>わ</rt></ruby>かってますよ　でも せっかく<ruby>約束<rt>やくそく</rt></ruby>した<b>のに</b>なあと...","speech":"それは分かってますよでもせっかく約束したのになあと...","id":"Saya ngerti kok. Cuma… <b>padahal</b> kita udah susah-susah janjian… <i>(せっかく〜のに · kecewa)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP04 · 13:43"}]},{"id":"n4_b46_01","level":"N4","bab":46,"lokasi":"第46課","titleMain":"〜ところです","titleSub":["Ｖるところ","Ｖているところ","Ｖたところ"],"meaning":"Baru mau… (る) / sedang… (ている) / baru saja… (た) — titik waktu yang tepat dalam suatu tindakan","formula":"これから Ｖ-る + <b>ところです</b> → baru mau<br>今 Ｖ-ている + <b>ところです</b> → sedang<br>たった今 Ｖ-た + <b>ところです</b> → baru saja<br>Ｖ-る + <b>ところでした</b> → tadi baru mau","nuance":"<ol><li><b>る</b> = tepat sebelum, <b>ている</b> = di tengah proses, <b>た</b> = tepat sesudah.</li><li>Sering jadi <b>jawaban</b> \"sudah…?\" / \"lagi apa?\" (いいえ、これから食べるところです).</li><li>Pasangan keterangan: これから・今から / 今 / たった今・ちょうど.</li></ol>⚠️ たところ = titik waktu (detik/menit); <b>たばかり</b> = perasaan \"belum lama\" (先月来たばかり, ×先月来たところ). (危うく)〜るところだった = hampir saja (N3).","examples":[{"jp":"これから<ruby>昼<rt>ひる</rt></ruby>ご<ruby>飯<rt>はん</rt></ruby>を<ruby>食<rt>た</rt></ruby>べるところです。","speech":"これから昼ご飯を食べるところです。","id":"Aku <b>baru mau</b> makan siang sekarang. <i>(Ｖるところ)</i>"},{"jp":"<ruby>今<rt>いま</rt></ruby><ruby>会議<rt>かいぎ</rt></ruby>をしているところです。","speech":"今会議をしているところです。","id":"Kami <b>sedang</b> rapat sekarang. <i>(Ｖているところ)</i>"},{"jp":"たった<ruby>今<rt>いま</rt></ruby>バスが<ruby>出<rt>で</rt></ruby>たところです。","speech":"たった今バスが出たところです。","id":"Busnya <b>baru saja</b> berangkat. <i>(Ｖたところ)</i>"},{"jp":"<ruby>故障<rt>こしょう</rt></ruby>の<ruby>原因<rt>げんいん</rt></ruby>は<ruby>今<rt>いま</rt></ruby><ruby>調<rt>しら</rt></ruby>べているところです。","speech":"故障の原因は今調べているところです。","id":"Penyebab kerusakannya <b>sedang</b> kami periksa. <i>(Ｖているところ)</i>"},{"jp":"ちょうど<ruby>今<rt>いま</rt></ruby>、 <ruby>出<rt>で</rt></ruby>かけるところでした。","speech":"ちょうど今、出かけるところでした。","id":"Aku <b>tadi pas mau</b> berangkat. <i>(Ｖるところでした)</i>"}],"dialogs":[{"jp":"<ruby>私<rt>わたし</rt></ruby>たち これから<ruby>依頼<rt>いらい</rt></ruby>を<ruby>受<rt>う</rt></ruby>ける<b>ところ</b>だけど　 <ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>行<rt>い</rt></ruby>く?","speech":"私たちこれから依頼を受けるところだけど一緒に行く?","id":"Kami <b>baru mau</b> ambil permintaan nih, mau ikut bareng? <i>(Ｖるところ · baru mau)</i>","source":"無職転生Ⅱ ～異世界行ったら本気だす～ · EP02 · 04:04"},{"jp":"いッ<ruby>今<rt>いま</rt></ruby>から<ruby>練習<rt>れんしゅう</rt></ruby>する<b>ところだった</b>んだよ　ホントだよ","speech":"いッ今から練習するところだったんだよホントだよ","id":"K-kami <b>baru mau</b> mulai latihan kok! Beneran! <i>(Ｖるところだった · tadi baru mau)</i>","source":"けいおん! · EP09 · 07:19"},{"jp":"<ruby>俺<rt>おれ</rt></ruby>は<ruby>今<rt>いま</rt></ruby><ruby>別<rt>べつ</rt></ruby>の<ruby>海賊<rt>かいぞく</rt></ruby>を<ruby>捜<rt>さが</rt></ruby>している<b>ところだ</b>","speech":"俺は今別の海賊を捜しているところだ","id":"Aku <b>lagi</b> nyari bajak laut lain sekarang. <i>(Ｖているところ · sedang)</i>","source":"ONE PIECE · EP94 · 12:49"},{"jp":"アッシュは? あ?　 <ruby>今<rt>いま</rt></ruby><ruby>出<rt>で</rt></ruby>ていった<b>ところ</b>だが","speech":"アッシュは? あ?　今出ていったところだが","id":"Ash mana? — Hah? Dia <b>baru aja</b> keluar. <i>(Ｖたところ · baru saja)</i>","source":"BANANA FISH · EP05 · 03:46"},{"jp":"<ruby>代<rt>か</rt></ruby>わりにテンの<ruby>毛皮<rt>けがわ</rt></ruby>を<ruby>買<rt>か</rt></ruby>い<ruby>付<rt>つ</rt></ruby>けてきた<b>ところです</b>","speech":"代わりにテンの毛皮を買い付けてきたところです","id":"Sebagai gantinya, saya <b>baru saja</b> memborong bulu marten. <i>(Ｖたところ · sopan)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP02 · 06:28"}]},{"id":"n4_b46_02","level":"N4","bab":46,"lokasi":"第46課","titleMain":"〜たばかりです","titleSub":["来たばかり","買ったばかりの〜"],"meaning":"Baru saja… / belum lama… — menurut perasaan pembicara (bisa menit sampai bulan)","formula":"Ｖ-た + <b>ばかりです</b>（先月来たばかりです）<br>Ｖ-た + <b>ばかりの</b> + Ｎ（買ったばかりの靴）<br>Ｖ-た + <b>ばかりなのに ／ ばかりで</b> · kasual: <b>ばっかり</b>","nuance":"<ol><li>Ukuran \"baru\" = <b>perasaan pembicara</b>, bukan jam: 先月来たばかり tetap wajar.</li><li>Sering jadi <b>alasan / pembelaan</b>: まだ習ったばかりなので… / 買ったばかりなのに壊れた.</li></ol>⚠️ Ｎばかり / Ｖてばかり = \"melulu\" (makna lain). <b>たところ</b> = titik waktu tepat; 先月・去年 hanya cocok dengan たばかり.","examples":[{"jp":"<ruby>先月<rt>せんげつ</rt></ruby><ruby>日本<rt>にほん</rt></ruby>に<ruby>来<rt>き</rt></ruby>たばかりです。","speech":"先月日本に来たばかりです。","id":"Aku <b>baru</b> datang ke Jepang bulan lalu. <i>(perasaan baru)</i>"},{"jp":"さっき<ruby>昼<rt>ひる</rt></ruby>ご<ruby>飯<rt>はん</rt></ruby>を<ruby>食<rt>た</rt></ruby>べたばかりです。","speech":"さっき昼ご飯を食べたばかりです。","id":"Aku <b>baru saja</b> makan siang tadi. <i>(baru saja)</i>"},{"jp":"このパソコンは<ruby>先週<rt>せんしゅう</rt></ruby><ruby>買<rt>か</rt></ruby>ったばかりなのに、もう<ruby>壊<rt>こわ</rt></ruby>れてしまいました。","speech":"このパソコンは先週買ったばかりなのに、もう壊れてしまいました。","id":"Komputer ini padahal <b>baru</b> dibeli minggu lalu, sudah rusak. <i>(ばかりなのに)</i>"},{"jp":"まだ<ruby>習<rt>なら</rt></ruby>ったばかりなので、 <ruby>上手<rt>じょうず</rt></ruby>に<ruby>話<rt>はな</rt></ruby>せません。","speech":"まだ習ったばかりなので、上手に話せません。","id":"Karena <b>baru</b> belajar, aku belum bisa bicara dengan lancar. <i>(alasan)</i>"}],"dialogs":[{"jp":"いや<ruby>実<rt>じつ</rt></ruby>は<ruby>遠<rt>とお</rt></ruby>くから<ruby>来<rt>き</rt></ruby>た<b>ばかり</b>で<ruby>今<rt>いま</rt></ruby> この<ruby>街<rt>まち</rt></ruby>に<ruby>着<rt>つ</rt></ruby>いたところなんだ","speech":"いや実は遠くから来たばかりで今この街に着いたところなんだ","id":"Oh, sebenarnya kami <b>baru</b> datang dari jauh, dan baru saja sampai di kota ini. <i>(たばかりで + たところ)</i>","source":"この素晴らしい世界に祝福を！ · EP01 · 13:01"},{"jp":"<ruby>来<rt>き</rt></ruby>てよ　 <ruby>仁菜<rt>にな</rt></ruby><ruby>東京<rt>とうきょう</rt></ruby><ruby>出<rt>で</rt></ruby>てきた<b>ばっかり</b>だからさ","speech":"来てよ仁菜東京出てきたばっかりだからさ","id":"Datang aja. Nina kan <b>baru</b> ke Tokyo. <i>(ばっかり · kasual, alasan)</i>","source":"ガールズバンドクライ · EP02 · 16:07"},{"jp":"つまり<ruby>今日<rt>きょう</rt></ruby><ruby>山梨<rt>やまなし</rt></ruby>に<ruby>引<rt>ひ</rt></ruby>っ<ruby>越<rt>こ</rt></ruby>してきた<b>ばかり</b>で","speech":"つまり今日山梨に引っ越してきたばかりで","id":"Jadi kamu <b>baru</b> pindah ke Yamanashi hari ini ya. <i>(たばかりで)</i>","source":"ゆるキャン△ · EP01 · 13:16"},{"jp":"<ruby>募集<rt>ぼしゅう</rt></ruby><ruby>始<rt>はじ</rt></ruby>めた<b>ばかり</b>で まだ<ruby>求人誌<rt>きゅうじんし</rt></ruby>にも<ruby>載<rt>の</rt></ruby>せてないって","speech":"募集始めたばかりでまだ求人誌にも載せてないって","id":"Katanya mereka <b>baru</b> buka lowongan, jadi belum dipasang di majalah loker. <i>(たばかりで · alasan)</i>","source":"ゆるキャン△ SEASON２ · EP04 · 18:30"},{"jp":"<ruby>確<rt>たし</rt></ruby>かに<ruby>買<rt>か</rt></ruby>った<b>ばかりの</b> <ruby>布団<rt>ふとん</rt></ruby>も<ruby>燃<rt>も</rt></ruby>えちゃっただろうね","speech":"確かに買ったばかりの布団も燃えちゃっただろうね","id":"Iya juga, futon yang <b>baru dibeli</b> juga pasti ikut kebakar ya. <i>(たばかりの + N)</i>","source":"トニカクカワイイ · EP09 · 01:15"}]},{"id":"n4_b46_03","level":"N4","bab":46,"lokasi":"第46課","titleMain":"〜はずです","titleSub":["来るはずです","休みのはずです"],"meaning":"Seharusnya… / mestinya… / pasti… — keyakinan berdasarkan alasan atau informasi yang jelas","formula":"Ｖ / KS-i (bentuk biasa) + <b>はずです</b>（来るはず ／ 寒いはず）<br>KS-na + <b>な</b>はず · Ｎ + <b>の</b>はず（休みのはず）<br><b>〜はずだった</b> = seharusnya (tapi tidak) · <b>〜はずがない</b> = tidak mungkin","nuance":"<ol><li>Dasar logis: jadwal, info, perhitungan (昨日送ったから、明日着くはずです).</li><li><b>〜はずなのに</b>: kenyataan bertentangan dengan keyakinan (入れたはずなのに、ない).</li></ol>⚠️ Bukan untuk <b>niat</b> sendiri (×私は行くはずです → 行くつもりです). はず = perkiraan fakta; <b>べき</b> = kewajiban; でしょう = dugaan biasa.","examples":[{"jp":"ミラーさんは<ruby>今日<rt>きょう</rt></ruby><ruby>来<rt>く</rt></ruby>るはずです。","speech":"ミラーさんは今日来るはずです。","id":"Miller-san <b>seharusnya</b> datang hari ini. <i>(jadwal)</i>"},{"jp":"<ruby>会議<rt>かいぎ</rt></ruby>は<ruby>3時<rt>さんじ</rt></ruby>からのはずです。","speech":"会議は3時からのはずです。","id":"Rapatnya <b>mestinya</b> mulai jam 3. <i>(Ｎのはず)</i>"},{"jp":"<ruby>荷物<rt>にもつ</rt></ruby>は<ruby>昨日<rt>きのう</rt></ruby><ruby>送<rt>おく</rt></ruby>りましたから、 <ruby>明日<rt>あした</rt></ruby><ruby>着<rt>つ</rt></ruby>くはずです。","speech":"荷物は昨日送りましたから、明日着くはずです。","id":"Paketnya sudah dikirim kemarin, jadi <b>seharusnya</b> sampai besok. <i>(perhitungan)</i>"},{"jp":"<ruby>彼<rt>かれ</rt></ruby>は<ruby>日本<rt>にほん</rt></ruby>に<ruby>10年<rt>じゅうねん</rt></ruby><ruby>住<rt>す</rt></ruby>んでいたから、 <ruby>日本語<rt>にほんご</rt></ruby>が<ruby>上手<rt>じょうず</rt></ruby>なはずです。","speech":"彼は日本に10年住んでいたから、日本語が上手なはずです。","id":"Dia tinggal di Jepang 10 tahun, jadi bahasa Jepangnya <b>pasti</b> bagus. <i>(KS-na なはず)</i>"},{"jp":"<ruby>鍵<rt>かぎ</rt></ruby>はかばんに<ruby>入<rt>い</rt></ruby>れたはずなのに、ありません。","speech":"鍵はかばんに入れたはずなのに、ありません。","id":"<b>Seharusnya</b> kuncinya sudah kumasukkan ke tas, tapi nggak ada. <i>(はずなのに)</i>"}],"dialogs":[{"jp":"<ruby>近<rt>ちか</rt></ruby>くに コンビニあった<b>はず</b>だから-","speech":"近くにコンビニあったはずだから-","id":"<b>Seharusnya</b> ada minimarket di dekat sini, jadi… <i>(ingatan · はず)</i>","source":"ゆるキャン△ · EP11 · 20:38"},{"jp":"そろそろ<ruby>来<rt>く</rt></ruby>る<b>はず</b>だけど...","speech":"そろそろ来るはずだけど...","id":"<b>Mestinya</b> dia udah mau datang sih… <i>(来るはず · jadwal)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 19:05"},{"jp":"<ruby>平塚<rt>ひらつか</rt></ruby><ruby>先生<rt>せんせい</rt></ruby><ruby>入<rt>はい</rt></ruby>るときはノックをお<ruby>願<rt>ねが</rt></ruby>いした<b>はずです</b>が","speech":"平塚先生入るときはノックをお願いしたはずですが","id":"Hiratsuka-sensei, <b>seharusnya</b> saya sudah minta Anda mengetuk pintu sebelum masuk. <i>(はずですが · menegur)</i>","source":"やはり俺の青春ラブコメはまちがっている。 · EP01 · 03:55"},{"jp":"<ruby>一人<rt>ひとり</rt></ruby><ruby>相手<rt>あいて</rt></ruby>は<ruby>二人<rt>ふたり</rt></ruby><b>のはずだ</b>","speech":"一人相手は二人のはずだ","id":"Cuma satu! Lawannya <b>mestinya</b> dua orang! <i>(Ｎのはず)</i>","source":"狼と香辛料 · EP04 · 15:50"},{"jp":"<ruby>明日<rt>あした</rt></ruby>からは<ruby>落<rt>お</rt></ruby>ち<ruby>着<rt>つ</rt></ruby>く<b>はずだ</b>","speech":"明日からは落ち着くはずだ","id":"Mulai besok <b>seharusnya</b> sudah tenang. <i>(prediksi berdasar)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP15 · 05:27"}]},{"id":"n4_b47_01","level":"N4","bab":47,"lokasi":"第47課","titleMain":"〜そうです","titleSub":["降るそうです","休みだそうです"],"meaning":"Katanya… / kabarnya… / saya dengar… — meneruskan informasi dari orang / sumber lain","formula":"Bentuk biasa + <b>そうです</b>（降るそうです ／ 寒いそうです）<br>KS-na / Ｎ + <b>だ</b> + <b>そうです</b>（便利だそうです ／ 休みだそうです）<br>Sumber: <b>〜によると ／ 〜の話では</b> · kasual: <b>〜って ／ 〜んだって</b>","nuance":"<ol><li>Meneruskan info <b>tanpa penilaian sendiri</b>; sumber sering disebut dengan によると.</li><li>そう-nya <b>tidak berubah</b> (×そうでした) dan tidak punya bentuk そうな + N.</li></ol>⚠️ Beda dengan 様態 (Bab 43): 降る<b>そう</b> = katanya hujan ↔ 降り<b>そう</b> = kelihatannya mau hujan; おいしい<b>そう</b> ↔ おいし<b>そう</b>.","examples":[{"jp":"<ruby>天気<rt>てんき</rt></ruby><ruby>予報<rt>よほう</rt></ruby>によると、 <ruby>明日<rt>あした</rt></ruby>は<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>るそうです。","speech":"天気予報によると、明日は雨が降るそうです。","id":"Menurut prakiraan cuaca, <b>katanya</b> besok hujan. <i>(によると)</i>"},{"jp":"ニュースによると、タイで<ruby>地震<rt>じしん</rt></ruby>があったそうです。","speech":"ニュースによると、タイで地震があったそうです。","id":"Menurut berita, <b>katanya</b> ada gempa di Thailand. <i>(Ｖた)</i>"},{"jp":"ミラーさんの<ruby>話<rt>はなし</rt></ruby>では、あのレストランはとてもおいしいそうです。","speech":"ミラーさんの話では、あのレストランはとてもおいしいそうです。","id":"Kata Miller-san, restoran itu <b>katanya</b> enak banget. <i>(KS-i)</i>"},{"jp":"<ruby>木村<rt>きむら</rt></ruby>さんは<ruby>来月<rt>らいげつ</rt></ruby><ruby>結婚<rt>けっこん</rt></ruby>するそうです。","speech":"木村さんは来月結婚するそうです。","id":"<b>Kabarnya</b> Kimura-san akan menikah bulan depan. <i>(kabar)</i>"},{"jp":"あの<ruby>店<rt>みせ</rt></ruby>は<ruby>日曜日<rt>にちようび</rt></ruby>は<ruby>休<rt>やす</rt></ruby>みだそうです。","speech":"あの店は日曜日は休みだそうです。","id":"<b>Katanya</b> toko itu tutup hari Minggu. <i>(Ｎ + だそうです)</i>"}],"dialogs":[{"jp":"ほうじ<ruby>茶<rt>ちゃ</rt></ruby>は<ruby>体<rt>からだ</rt></ruby>を<ruby>温<rt>あたた</rt></ruby>める<ruby>効果<rt>こうか</rt></ruby>がある<b>そうです</b>","speech":"ほうじ茶は体を温める効果があるそうです","id":"<b>Katanya</b> teh houji punya khasiat menghangatkan badan. <i>(Ｖ + そうです · info)</i>","source":"ゆるキャン△ · EP09 · 07:08"},{"jp":"<ruby>西伊豆町<rt>にしいずちょう</rt></ruby>の<ruby>海辺<rt>うみべ</rt></ruby>にある<b>そうです</b>","speech":"西伊豆町の海辺にあるそうです","id":"<b>Katanya</b> ada di tepi pantai kota Nishiizu. <i>(Ｖ + そうです)</i>","source":"ゆるキャン△ SEASON２ · EP10 · 17:11"},{"jp":"<ruby>交渉<rt>こうしょう</rt></ruby>は<ruby>失敗<rt>しっぱい</rt></ruby>した<b>そうです</b>","speech":"交渉は失敗したそうです","id":"<b>Kabarnya</b> negosiasinya gagal. <i>(Ｖた + そうです)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP06 · 10:07"},{"jp":"<ruby>勝<rt>か</rt></ruby>ったほうが ドラマの<ruby>主題歌<rt>しゅだいか</rt></ruby>に<ruby>決定<rt>けってい</rt></ruby><b>だそうです</b>","speech":"勝ったほうがドラマの主題歌に決定だそうです","id":"<b>Katanya</b> yang menang bakal jadi lagu tema drama. <i>(Ｎ + だそうです)</i>","source":"ガールズバンドクライ · EP12 · 12:37"},{"jp":"「あと チケット<ruby>全部<rt>ぜんぶ</rt></ruby><ruby>売<rt>う</rt></ruby>れました」<b>だそうです</b>","speech":"「あとチケット全部売れました」だそうです","id":"\"Terus, tiketnya udah kejual semua\" — <b>katanya</b> begitu! <i>(kutipan + だそうです)</i>","source":"ぼっち・ざ・ろっく！ · EP06 · 21:38"}]},{"id":"n4_b47_02","level":"N4","bab":47,"lokasi":"第47課","titleMain":"〜ようです","titleSub":["いるようです","事故のようです"],"meaning":"Sepertinya… / tampaknya… — dugaan dari pengamatan / indra pembicara sendiri","formula":"Bentuk biasa + <b>ようです</b>（誰かいるようです ／ 風邪をひいたようです）<br>KS-na + <b>な</b>ようです（好きなようです）<br>Ｎ + <b>の</b>ようです（事故のようです）· sering dengan <b>どうも ／ どうやら</b>","nuance":"<ol><li>Kesimpulan dari yang <b>dilihat, didengar, dirasakan</b>: 咳が出ます。風邪をひいたようです.</li><li>Lebih sopan dari <b>みたい</b> (kasual); lebih berbasis pengamatan langsung daripada <b>らしい</b>.</li></ol>⚠️ ようです = kesimpulanku ↔ そうです(伝聞) = kata orang. Ｎのようだ juga bisa perumpamaan (夢のようだ = seperti mimpi).","examples":[{"jp":"<ruby>隣<rt>となり</rt></ruby>の<ruby>部屋<rt>へや</rt></ruby>に<ruby>誰<rt>だれ</rt></ruby>かいるようです。","speech":"隣の部屋に誰かいるようです。","id":"<b>Sepertinya</b> ada orang di kamar sebelah. <i>(terdengar suara)</i>"},{"jp":"<ruby>咳<rt>せき</rt></ruby>が<ruby>出<rt>で</rt></ruby>ます。 <ruby>風邪<rt>かぜ</rt></ruby>をひいたようです。","speech":"咳が出ます。風邪をひいたようです。","id":"Saya batuk. <b>Sepertinya</b> saya masuk angin. <i>(rasa sendiri)</i>"},{"jp":"<ruby>外<rt>そと</rt></ruby>は<ruby>寒<rt>さむ</rt></ruby>いようです。みんなコートを<ruby>着<rt>き</rt></ruby>ています。","speech":"外は寒いようです。みんなコートを着ています。","id":"<b>Sepertinya</b> di luar dingin. Semua orang pakai mantel. <i>(pengamatan)</i>"},{"jp":"<ruby>人<rt>ひと</rt></ruby>がたくさん<ruby>集<rt>あつ</rt></ruby>まっていますね。 <ruby>事故<rt>じこ</rt></ruby>のようですね。","speech":"人がたくさん集まっていますね。事故のようですね。","id":"Banyak orang berkumpul ya. <b>Sepertinya</b> ada kecelakaan. <i>(Ｎのようです)</i>"},{"jp":"<ruby>電気<rt>でんき</rt></ruby>が<ruby>消<rt>き</rt></ruby>えていますね。 <ruby>田中<rt>たなか</rt></ruby>さんはもう<ruby>帰<rt>かえ</rt></ruby>ったようです。","speech":"電気が消えていますね。田中さんはもう帰ったようです。","id":"Lampunya mati ya. <b>Sepertinya</b> Tanaka-san sudah pulang. <i>(Ｖた)</i>"}],"dialogs":[{"jp":"<ruby>鳥<rt>とり</rt></ruby>が<ruby>多<rt>おお</rt></ruby>い<b>ようですね</b>","speech":"鳥が多いようですね","id":"<b>Sepertinya</b> burungnya banyak ya. <i>(KS-i · pengamatan)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP02 · 09:50"},{"jp":"クラスにも<ruby>打<rt>う</rt></ruby>ち<ruby>解<rt>と</rt></ruby>けている<b>ようだ</b>し","speech":"クラスにも打ち解けているようだし","id":"<b>Kayaknya</b> kamu juga udah mulai akrab di kelas. <i>(Ｖている · pengamatan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP09 · 13:57"},{"jp":"<ruby>商人<rt>しょうにん</rt></ruby>の<ruby>方<rt>かた</rt></ruby>は そのセリフが お<ruby>好<rt>す</rt></ruby>き<b>なようですね</b>","speech":"商人の方はそのセリフがお好きなようですね","id":"Para pedagang <b>tampaknya</b> suka sekali kalimat itu ya. <i>(KS-na + なようです)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP23 · 12:46"},{"jp":"あの<ruby>魔剣<rt>まけん</rt></ruby><ruby>使<rt>つか</rt></ruby>いの<ruby>冒険者<rt>ぼうけんしゃ</rt></ruby>は かなりの<ruby>重傷<rt>じゅうしょう</rt></ruby><b>のようです</b>","speech":"あの魔剣使いの冒険者はかなりの重傷のようです","id":"Petualang pengguna pedang sihir itu <b>tampaknya</b> terluka cukup parah. <i>(Ｎ + のようです)</i>","source":"この素晴らしい世界に爆焔を！ · EP11 · 08:13"},{"jp":"どうやら<ruby>自分<rt>じぶん</rt></ruby>が<ruby>間違<rt>まちが</rt></ruby>っていた<b>ようですね</b>","speech":"どうやら自分が間違っていたようですね","id":"<b>Rupanya</b> saya yang salah ya. <i>(どうやら〜ようです)</i>","source":"この素晴らしい世界に祝福を！2 · EP01 · 11:45"}]},{"id":"n4_b47_03","level":"N4","bab":47,"lokasi":"第47課","titleMain":"音・におい・味がします","titleSub":["音がします","においがします","味がします"],"meaning":"Terdengar suara… / tercium bau… / terasa rasa… — sensasi yang ditangkap indra","formula":"(keterangan) + <b>音 ／ 声 ／ におい ／ 味 + が + します</b><br>変な音がします · いいにおいがします · レモンの味がします<br>Firasat: 〜<b>気がします</b>","nuance":"<ol><li>Bukan perbuatan seseorang; kita <b>mengalami</b> sensasinya (tidak disengaja).</li><li>Keterangan: KS + 音 / Ｎの味 / 〜ような音.</li></ol>⚠️ 音<b>がする</b> (terdengar) ≠ 音<b>を出す</b> (sengaja bikin suara). 聞こえる fokus ke kemampuan mendengar.","examples":[{"jp":"この<ruby>車<rt>くるま</rt></ruby>は<ruby>変<rt>へん</rt></ruby>な<ruby>音<rt>おと</rt></ruby>がします。","speech":"この車は変な音がします。","id":"Mobil ini <b>ada suara</b> aneh. <i>(音)</i>"},{"jp":"<ruby>台所<rt>だいどころ</rt></ruby>からいいにおいがしますね。","speech":"台所からいいにおいがしますね。","id":"Dari dapur <b>tercium bau</b> harum ya. <i>(におい)</i>"},{"jp":"このお<ruby>菓子<rt>かし</rt></ruby>は<ruby>不思議<rt>ふしぎ</rt></ruby>な<ruby>味<rt>あじ</rt></ruby>がします。","speech":"このお菓子は不思議な味がします。","id":"Kue ini <b>rasanya</b> unik. <i>(味)</i>"},{"jp":"<ruby>隣<rt>となり</rt></ruby>の<ruby>部屋<rt>へや</rt></ruby>で<ruby>声<rt>こえ</rt></ruby>がします。 <ruby>誰<rt>だれ</rt></ruby>かいるようです。","speech":"隣の部屋で声がします。誰かいるようです。","id":"<b>Terdengar suara</b> di kamar sebelah. Sepertinya ada orang. <i>(声)</i>"}],"dialogs":[{"jp":"<ruby>今<rt>いま</rt></ruby> すごい<ruby>音<rt>おと</rt></ruby><b>がした</b>ような...","speech":"今すごい音がしたような...","id":"Barusan kayaknya <b>ada suara</b> keras… <i>(音がする)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP01 · 17:18"},{"jp":"おお ようやく<ruby>人<rt>ひと</rt></ruby>の<ruby>声<rt>こえ</rt></ruby><b>がした</b>と<ruby>思<rt>おも</rt></ruby>ったら　めぐみんじゃないか","speech":"おおようやく人の声がしたと思ったらめぐみんじゃないか","id":"Oh, kukira akhirnya <b>terdengar suara</b> orang — ternyata Megumin! <i>(声がする)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 14:19"},{"jp":"<ruby>姉<rt>ねえ</rt></ruby>ちゃんから いい<ruby>匂<rt>にお</rt></ruby>い<b>がする</b>","speech":"姉ちゃんからいい匂いがする","id":"Dari Kakak <b>tercium bau</b> wangi. <i>(においがする)</i>","source":"この素晴らしい世界に爆焔を！ · EP02 · 03:54"},{"jp":"ちょっと かんきつ<ruby>系<rt>けい</rt></ruby>っぽい<ruby>味<rt>あじ</rt></ruby><b>がする</b>","speech":"ちょっとかんきつ系っぽい味がする","id":"<b>Terasa</b> agak <b>rasa</b> jeruk-jerukan. <i>(味がする)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 12:19"},{"jp":"あの<ruby>人<rt>ひと</rt></ruby>の<ruby>料理<rt>りょうり</rt></ruby>は<ruby>幸<rt>しあわ</rt></ruby>せの<ruby>味<rt>あじ</rt></ruby><b>がする</b>んですよ","speech":"あの人の料理は幸せの味がするんですよ","id":"Masakan orang itu <b>rasanya</b> seperti kebahagiaan, lho. <i>(Ｎの味がする)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP04 · 08:56"}]},{"id":"n4_b48_01","level":"N4","bab":48,"lokasi":"第48課","titleMain":"使役形〜せる・〜させる","titleSub":["Ｎを行かせる","Ｎに食べさせる"],"meaning":"Menyuruh / membuat (seseorang) melakukan… (paksaan) · membiarkan / mengizinkan… (izin) · membuat (seseorang) merasa… (emosi)","formula":"Gol.1: -u → <b>-a + せる</b>（書かせる ／ 言わせる）· Gol.2: <b>〜させる</b>（食べさせる）<br>する → <b>させる</b> · 来る → <b>来(こ)させる</b><br>Intransitif: 人<b>を</b> Ｖ-させる（ミラーさんを出張させる）<br>Transitif: 人<b>に</b> 物<b>を</b> Ｖ-させる（子どもに野菜を食べさせる）","nuance":"<ol><li><b>強制</b> (menyuruh): 母は子どもに野菜を食べさせる.</li><li><b>許可</b> (membiarkan): 先生は私に自由に意見を言わせた.</li><li><b>感情</b> (menyebabkan perasaan): 友達を待たせる, 親を心配させる.</li></ol>⚠️ Tidak dipakai ke atasan (→ 〜ていただく). Dua を dalam satu kalimat dihindari → orangnya pakai <b>に</b>. 使役受身: 待た<b>された</b> = dibuat menunggu.","examples":[{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>はミラーさんをアメリカへ<ruby>出張<rt>しゅっちょう</rt></ruby>させます。","speech":"部長はミラーさんをアメリカへ出張させます。","id":"Manajer <b>menyuruh</b> Miller-san dinas ke Amerika. <i>(人を · 強制)</i>"},{"jp":"<ruby>母<rt>はは</rt></ruby>は<ruby>子<rt>こ</rt></ruby>どもに<ruby>野菜<rt>やさい</rt></ruby>を<ruby>食<rt>た</rt></ruby>べさせます。","speech":"母は子どもに野菜を食べさせます。","id":"Ibu <b>menyuruh</b> anaknya makan sayur. <i>(人に + 物を · 強制)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>に<ruby>自由<rt>じゆう</rt></ruby>に<ruby>意見<rt>いけん</rt></ruby>を<ruby>言<rt>い</rt></ruby>わせました。","speech":"先生は私に自由に意見を言わせました。","id":"Guru <b>membiarkan</b> saya bebas menyampaikan pendapat. <i>(許可)</i>"},{"jp":"<ruby>息子<rt>むすこ</rt></ruby>が<ruby>行<rt>い</rt></ruby>きたいと<ruby>言<rt>い</rt></ruby>ったので、 <ruby>塾<rt>じゅく</rt></ruby>に<ruby>行<rt>い</rt></ruby>かせました。","speech":"息子が行きたいと言ったので、塾に行かせました。","id":"Karena putraku bilang ingin pergi, aku <b>mengizinkannya</b> ke bimbel. <i>(許可)</i>"},{"jp":"<ruby>遅<rt>おそ</rt></ruby>くなって、 <ruby>友達<rt>ともだち</rt></ruby>を<ruby>30分<rt>さんじゅっぷん</rt></ruby>も<ruby>待<rt>ま</rt></ruby>たせてしまいました。","speech":"遅くなって、友達を30分も待たせてしまいました。","id":"Aku telat, jadi <b>membuat</b> temanku menunggu sampai 30 menit. <i>(感情 · menyebabkan)</i>"}],"dialogs":[{"jp":"<ruby>好<rt>す</rt></ruby>きな<ruby>人<rt>ひと</rt></ruby>には おいしいものを<ruby>食<rt>た</rt></ruby>べ<b>させたい</b> <ruby>心<rt>こころ</rt></ruby>なのです","speech":"好きな人にはおいしいものを食べさせたい心なのです","id":"Ke orang yang kusukai, rasanya pengin <b>bikin dia makan</b> yang enak-enak. <i>(人に + 物を + させる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP05 · 15:30"},{"jp":"ぬしよ<ruby>小娘<rt>こむすめ</rt></ruby>と<ruby>小僧<rt>こぞう</rt></ruby>を<ruby>先<rt>さき</rt></ruby>に<ruby>行<rt>い</rt></ruby><b>かせる</b>んじゃ","speech":"ぬしよ小娘と小僧を先に行かせるんじゃ","id":"Hei kamu, <b>suruh</b> si gadis dan bocah itu <b>pergi</b> duluan. <i>(人を + 行かせる · intransitif)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP11 · 14:07"},{"jp":"お<ruby>前<rt>まえ</rt></ruby>は<ruby>小僧<rt>こぞう</rt></ruby>を<ruby>走<rt>はし</rt></ruby><b>らせて</b> こう<ruby>言<rt>い</rt></ruby><b>わせた</b>んだ","speech":"お前は小僧を走らせてこう言わせたんだ","id":"Kau <b>menyuruh</b> bocah itu <b>berlari</b> ke sana-sini dan <b>membuatnya bilang</b> begini. <i>(強制)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP18 · 12:05"},{"jp":"そうやって<ruby>誰<rt>だれ</rt></ruby>かに やら<b>せたり</b> <ruby>押<rt>お</rt></ruby>しつけるの　お<ruby>母<rt>かあ</rt></ruby>さんそっくり","speech":"そうやって誰かにやらせたり押しつけるのお母さんそっくり","id":"Kamu <b>nyuruh</b> orang lain ngerjain dan melimpahkannya begitu — persis ibumu. <i>(人に + やらせる · 強制)</i>","source":"やはり俺の青春ラブコメはまちがっている。続 · EP04 · 12:12"},{"jp":"<ruby>悪<rt>わる</rt></ruby>い<ruby>待<rt>ま</rt></ruby><b>たせた</b>　ちょっと<ruby>平塚<rt>ひらつか</rt></ruby><ruby>先生<rt>せんせい</rt></ruby>んとこ<ruby>行<rt>い</rt></ruby>ってくるわ","speech":"悪い待たせたちょっと平塚先生んとこ行ってくるわ","id":"Sori, <b>bikin kamu nunggu</b>. Aku ke tempat Bu Hiratsuka bentar. <i>(待たせる · menyebabkan)</i>","source":"やはり俺の青春ラブコメはまちがっている。完 · EP04 · 19:52"}]},{"id":"n4_b48_02","level":"N4","bab":48,"lokasi":"第48課","titleMain":"〜させてください","titleSub":["〜させていただけませんか","〜させていただきます"],"meaning":"Izinkan saya… / bolehkah saya (diizinkan)…? — minta izin melakukan sesuatu sendiri","formula":"Ｖ-使役 (〜せる／させる) → 〜<b>せて／させて</b> + <b>ください</b>（待たせてください）<br>+ <b>いただけませんか</b>（早く帰らせていただけませんか）<br>+ <b>いただきます</b>（説明させていただきます）","nuance":"<ol><li>Kesopanan: 〜させて &lt; 〜させてください &lt; 〜させてもらえませんか &lt; <b>〜させていただけませんか</b>.</li><li><b>〜させていただきます</b> = \"saya akan (dengan izin Anda)…\" — khas kerja / pengumuman.</li></ol>⚠️ 待っ<b>てください</b> = Anda yang menunggu ↔ 待た<b>せてください</b> = izinkan <b>saya</b> menunggu.","examples":[{"jp":"すみません、ここで<ruby>待<rt>ま</rt></ruby>たせてください。","speech":"すみません、ここで待たせてください。","id":"Maaf, <b>izinkan saya</b> menunggu di sini. <i>(させてください)</i>"},{"jp":"<ruby>塾<rt>じゅく</rt></ruby>へ<ruby>行<rt>い</rt></ruby>かせていただけませんか。","speech":"塾へ行かせていただけませんか。","id":"<b>Bolehkah saya diizinkan</b> pergi ke bimbel? <i>(させていただけませんか)</i>"},{"jp":"<ruby>熱<rt>ねつ</rt></ruby>があるので、 <ruby>今日<rt>きょう</rt></ruby>は<ruby>早<rt>はや</rt></ruby>く<ruby>帰<rt>かえ</rt></ruby>らせていただけませんか。","speech":"熱があるので、今日は早く帰らせていただけませんか。","id":"Saya demam, jadi <b>bolehkah saya</b> pulang lebih awal hari ini? <i>(minta izin ke atasan)</i>"},{"jp":"その<ruby>仕事<rt>しごと</rt></ruby>、ぜひ<ruby>私<rt>わたし</rt></ruby>にやらせてください。","speech":"その仕事、ぜひ私にやらせてください。","id":"Pekerjaan itu, <b>tolong biarkan saya</b> yang mengerjakan. <i>(させてください)</i>"},{"jp":"では、 <ruby>計画<rt>けいかく</rt></ruby>について<ruby>説明<rt>せつめい</rt></ruby>させていただきます。","speech":"では、計画について説明させていただきます。","id":"Baiklah, <b>izinkan saya</b> menjelaskan rencananya. <i>(させていただきます)</i>"}],"dialogs":[{"jp":"<ruby>部屋<rt>へや</rt></ruby><ruby>掃除<rt>そうじ</rt></ruby><b>させてください</b>","speech":"部屋掃除させてください","id":"Kamarnya — <b>izinkan aku</b> membersihkannya. <i>(させてください)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP01 · 17:31"},{"jp":"これだけ<ruby>言<rt>い</rt></ruby><b>わせてください</b>!","speech":"これだけ言わせてください!","id":"<b>Izinkan aku</b> bilang satu hal ini saja! <i>(言わせてください)</i>","source":"ぼっち・ざ・ろっく！ · EP12 · 07:24"},{"jp":"ぜひ やら<b>せてください</b>","speech":"ぜひやらせてください","id":"<b>Tolong biarkan saya</b> yang mengerjakannya! <i>(ぜひ + させてください)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP10 · 20:13"},{"jp":"お<ruby>願<rt>ねが</rt></ruby>いします ここで<ruby>働<rt>はたら</rt></ruby><b>かせてください</b>!","speech":"お願いしますここで働かせてください!","id":"Saya mohon, <b>izinkan saya</b> bekerja di sini! <i>(働かせてください)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 00:27"},{"jp":"あなたの<ruby>言葉<rt>ことば</rt></ruby>を<ruby>訂正<rt>ていせい</rt></ruby><b>させていただきます</b>けど","speech":"あなたの言葉を訂正させていただきますけど","id":"<b>Izinkan saya</b> meralat ucapan Anda. <i>(させていただきます · sopan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP12 · 15:22"}]},{"id":"n4_b49_01","level":"N4","bab":49,"lokasi":"第49課","titleMain":"尊敬の〜れる・〜られる","titleSub":["行かれる","来られる","される"],"meaning":"(Beliau) … — meninggikan tindakan orang lain dengan bentuk pasif; tingkat hormat paling ringan","formula":"Bentuk sama dengan 受身形:<br>Gol.1: -a + <b>れる</b>（行かれる ／ 帰られる）· Gol.2: + <b>られる</b>（始められる）<br>する → <b>される</b>（出席される）· 来る → <b>来(こ)られる</b>","nuance":"<ol><li>Subjek = <b>orang lain</b> yang dihormati (atasan, tamu, guru).</li><li>Paling <b>ringan</b>: お〜になる / kata kerja khusus lebih hormat.</li></ol>⚠️ Ambigu dengan pasif & potensial (来られる = datang (hormat) / bisa datang) — konteks yang menentukan.","examples":[{"jp":"<ruby>先生<rt>せんせい</rt></ruby>は<ruby>明日<rt>あした</rt></ruby>の<ruby>会議<rt>かいぎ</rt></ruby>に<ruby>出席<rt>しゅっせき</rt></ruby>されますか。","speech":"先生は明日の会議に出席されますか。","id":"Apakah Bapak <b>akan menghadiri</b> rapat besok? <i>(される)</i>"},{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>はもう<ruby>帰<rt>かえ</rt></ruby>られました。","speech":"部長はもう帰られました。","id":"Pak manajer <b>sudah pulang</b>. <i>(帰られる)</i>"},{"jp":"<ruby>社長<rt>しゃちょう</rt></ruby>は<ruby>毎朝<rt>まいあさ</rt></ruby><ruby>何時<rt>なんじ</rt></ruby>に<ruby>会社<rt>かいしゃ</rt></ruby>へ<ruby>来<rt>こ</rt></ruby>られますか。","speech":"社長は毎朝何時に会社へ来られますか。","id":"Pak direktur tiap pagi <b>datang</b> ke kantor jam berapa? <i>(来られる)</i>"},{"jp":"このパソコンはいつ<ruby>買<rt>か</rt></ruby>われましたか。","speech":"このパソコンはいつ買われましたか。","id":"Komputer ini <b>Anda beli</b> kapan? <i>(買われる)</i>"}],"dialogs":[{"jp":"<ruby>今日<rt>きょう</rt></ruby>は どのバンドを<ruby>見<rt>み</rt></ruby>に<ruby>来<rt>こ</rt></ruby><b>られました</b>か?","speech":"今日はどのバンドを見に来られましたか?","id":"Hari ini Anda <b>datang</b> untuk menonton band yang mana? <i>(来られる · resepsionis)</i>","source":"ぼっち・ざ・ろっく！ · EP03 · 12:24"},{"jp":"キャンプに<ruby>来<rt>こ</rt></ruby><b>られた</b> <ruby>方<rt>かた</rt></ruby>ですか?","speech":"キャンプに来られた方ですか?","id":"Anda yang <b>datang</b> untuk berkemah? <i>(来られる)</i>","source":"ゆるキャン△ · EP06 · 18:34"},{"jp":"あの...　リュビンハイゲンに<ruby>行<rt>い</rt></ruby>か<b>れる</b>のですか?","speech":"あの...　リュビンハイゲンに行かれるのですか?","id":"Anu… apakah Anda <b>akan pergi</b> ke Ruvinheigen? <i>(行かれる)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP08 · 02:45"},{"jp":"<ruby>桜<rt>さくら</rt></ruby>さんも<ruby>1人<rt>ひとり</rt></ruby>でドライブ よく<ruby>行<rt>い</rt></ruby>か<b>れる</b>んですか","speech":"桜さんも1人でドライブよく行かれるんですか","id":"Sakura-san juga sering <b>pergi</b> nyetir sendirian? <i>(行かれる · ke yang lebih tua)</i>","source":"ゆるキャン△ SEASON２ · EP07 · 19:48"},{"jp":"<ruby>村長<rt>そんちょう</rt></ruby>は<ruby>一応<rt>いちおう</rt></ruby><ruby>帰<rt>かえ</rt></ruby>ら<b>れました</b>が　その<ruby>先<rt>さき</rt></ruby>ほどの...","speech":"村長は一応帰られましたがその先ほどの...","id":"Kepala desa sudah <b>pulang</b>, tapi… soal yang tadi… <i>(帰られる)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP22 · 12:31"}]},{"id":"n4_b49_02","level":"N4","bab":49,"lokasi":"第49課","titleMain":"お〜になります","titleSub":["お帰りになる","ご出席になる"],"meaning":"(Beliau) … — bentuk hormat standar untuk tindakan orang lain","formula":"<b>お</b> + Ｖ-<s>ます</s> + <b>になる</b>（お帰りになる ／ お読みになる）<br><b>ご</b> + KB (する) + <b>になる</b>（ご出席になる ／ ご利用になる）","nuance":"<ol><li>Lebih hormat dari 〜れる・られる; cocok ke tamu, pelanggan, atasan tinggi.</li><li>KK ber-ます 1 suku kata (見ます, 寝ます, います, 来ます) → pakai KK khusus.</li></ol>⚠️ ×お食べになる → <b>召し上がる</b>. Hindari keigo ganda: ×お帰りに<b>なられる</b>.","examples":[{"jp":"<ruby>社長<rt>しゃちょう</rt></ruby>はもうお<ruby>帰<rt>かえ</rt></ruby>りになりました。","speech":"社長はもうお帰りになりました。","id":"Pak direktur <b>sudah pulang</b>. <i>(お帰りになる)</i>"},{"jp":"この<ruby>本<rt>ほん</rt></ruby>をお<ruby>読<rt>よ</rt></ruby>みになりましたか。","speech":"この本をお読みになりましたか。","id":"Apakah Anda <b>sudah membaca</b> buku ini? <i>(お読みになる)</i>"},{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>は<ruby>何時<rt>なんじ</rt></ruby>にお<ruby>戻<rt>もど</rt></ruby>りになりますか。","speech":"部長は何時にお戻りになりますか。","id":"Pak manajer <b>kembali</b> jam berapa? <i>(お戻りになる)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>は<ruby>明日<rt>あした</rt></ruby>の<ruby>会議<rt>かいぎ</rt></ruby>にご<ruby>出席<rt>しゅっせき</rt></ruby>になります。","speech":"先生は明日の会議にご出席になります。","id":"Bapak guru <b>akan menghadiri</b> rapat besok. <i>(ご〜になる)</i>"}],"dialogs":[{"jp":"<ruby>今<rt>いま</rt></ruby> <b>お<ruby>帰<rt>かえ</rt></ruby>りになった</b>よ。","speech":"今お帰りになったよ。","id":"Beliau <b>baru saja pulang</b>. <i>(お帰りになる)</i>","source":"無職転生Ⅱ ～異世界行ったら本気だす～ 第2クール · EP02 · 19:11"},{"jp":"<b>お<ruby>帰<rt>かえ</rt></ruby>りになった</b>ら<ruby>一度<rt>いちど</rt></ruby> お<ruby>電話<rt>でんわ</rt></ruby>いただけますか?","speech":"お帰りになったら一度お電話いただけますか?","id":"Kalau beliau <b>sudah pulang</b>, bisakah menelepon saya sekali? <i>(お帰りになる · bisnis)</i>","source":"SHIROBAKO · EP24 · 04:20"},{"jp":"とても<ruby>面白<rt>おもしろ</rt></ruby>いんですよ　さくらちゃんも <b>お<ruby>読<rt>よ</rt></ruby>みになります</b>か?","speech":"とても面白いんですよさくらちゃんもお読みになりますか?","id":"Seru banget lho. Sakura-chan juga mau <b>membacanya</b>? <i>(お読みになる)</i>","source":"カードキャプターさくら · EP55 · 05:54"},{"jp":"<ruby>本部<rt>ほんぶ</rt></ruby>から ボスが <b>お<ruby>越<rt>こ</rt></ruby>しになりました</b>","speech":"本部からボスがお越しになりました","id":"Bos dari markas pusat sudah <b>datang</b>. <i>(お越しになる = 来る)</i>","source":"モブサイコ100 · EP11 · 07:19"},{"jp":"お<ruby>母様<rt>かあさま</rt></ruby>は<ruby>少<rt>すこ</rt></ruby>し<b>お<ruby>休<rt>やす</rt></ruby>みになる</b>んですって","speech":"お母様は少しお休みになるんですって","id":"Katanya Ibu mau <b>beristirahat</b> sebentar. <i>(お休みになる)</i>","source":"ヴァイオレット・エヴァーガーデン · EP10 · 06:07"}]},{"id":"n4_b49_03","level":"N4","bab":49,"lokasi":"第49課","titleMain":"特別な尊敬語","titleSub":["いらっしゃる","召し上がる","おっしゃる","ご覧になる"],"meaning":"Kata kerja hormat khusus untuk tindakan orang lain — wajib dihafal","formula":"行く・来る・いる → <b>いらっしゃる</b> · 食べる・飲む → <b>召し上がる</b><br>言う → <b>おっしゃる</b> · 見る → <b>ご覧になる</b> · する → <b>なさる</b><br>知っている → <b>ご存じだ</b> · くれる → <b>くださる</b> · 寝る → <b>お休みになる</b>","nuance":"<ol><li>Bentuk ます: いらっしゃ<b>い</b>ます, おっしゃ<b>い</b>ます, なさ<b>い</b>ます, くださ<b>い</b>ます (bukan 〜ります).</li><li><b>ご存じ</b> seperti KS-na: ご存じです / ご存じの方 / ご存じありません.</li></ol>⚠️ Jangan untuk diri sendiri / kelompok sendiri ke orang luar (×うちの社長がいらっしゃいます → 社長の田中はおります).","examples":[{"jp":"ミラーさんはどこにいらっしゃいますか。","speech":"ミラーさんはどこにいらっしゃいますか。","id":"Miller-san <b>ada</b> di mana? <i>(いる → いらっしゃる)</i>"},{"jp":"<ruby>部長<rt>ぶちょう</rt></ruby>は<ruby>何<rt>なに</rt></ruby>を<ruby>召<rt>め</rt></ruby>し<ruby>上<rt>あ</rt></ruby>がりますか。","speech":"部長は何を召し上がりますか。","id":"Pak manajer <b>mau makan</b> apa? <i>(食べる → 召し上がる)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>がそうおっしゃいました。","speech":"先生がそうおっしゃいました。","id":"Pak guru <b>berkata</b> begitu. <i>(言う → おっしゃる)</i>"},{"jp":"<ruby>週末<rt>しゅうまつ</rt></ruby>は<ruby>何<rt>なに</rt></ruby>をなさいますか。","speech":"週末は何をなさいますか。","id":"Akhir pekan Anda <b>akan melakukan</b> apa? <i>(する → なさる)</i>"},{"jp":"<ruby>田中<rt>たなか</rt></ruby>さんの<ruby>電話<rt>でんわ</rt></ruby><ruby>番号<rt>ばんごう</rt></ruby>をご<ruby>存<rt>ぞん</rt></ruby>じですか。","speech":"田中さんの電話番号をご存じですか。","id":"Apakah Anda <b>tahu</b> nomor telepon Tanaka-san? <i>(知っている → ご存じ)</i>"}],"dialogs":[{"jp":"ウィズさんは <b>いらっしゃいます</b>か?","speech":"ウィズさんはいらっしゃいますか?","id":"Apakah Wiz-san <b>ada</b>? <i>(いる → いらっしゃる)</i>","source":"この素晴らしい世界に祝福を！ · EP08 · 11:02"},{"jp":"どうぞ <b><ruby>召<rt>め</rt></ruby>し<ruby>上<rt>あ</rt></ruby>がって</b>ください","speech":"どうぞ召し上がってください","id":"Silakan <b>dimakan</b>. <i>(食べる → 召し上がる)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP02 · 10:12"},{"jp":"...と ロレンス<ruby>氏<rt>し</rt></ruby>は <b>おっしゃって</b>おりますが","speech":"...とロレンス氏はおっしゃっておりますが","id":"…begitulah yang <b>dikatakan</b> Tuan Lawrence. <i>(言う → おっしゃる)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP16 · 07:52"},{"jp":"<ruby>総裁<rt>そうさい</rt></ruby>は <b>ご<ruby>覧<rt>らん</rt></ruby>になりました</b>か?","speech":"総裁はご覧になりましたか?","id":"Apakah Bapak Ketua sudah <b>melihatnya</b>? <i>(見る → ご覧になる)</i>","source":"SPY×FAMILY 第2クール · EP13 · 18:15"},{"jp":"ああ ついでと<ruby>言<rt>い</rt></ruby>っては なんですが　テレオまでの<ruby>道<rt>みち</rt></ruby>を <b>ご<ruby>存<rt>ぞん</rt></ruby>じありません</b>か?","speech":"ああついでと言ってはなんですがテレオまでの道をご存じありませんか?","id":"Oh, sekalian saja — apakah Anda <b>tahu</b> jalan ke Tereo? <i>(知っている → ご存じ)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 05:55"}]},{"id":"n4_b49_04","level":"N4","bab":49,"lokasi":"第49課","titleMain":"お〜ください","titleSub":["お待ちください","ご利用ください"],"meaning":"Silakan… / mohon… — permintaan / persilaan hormat (versi keigo 〜てください)","formula":"<b>お</b> + Ｖ-<s>ます</s> + <b>ください</b>（お座りください ／ お待ちください）<br><b>ご</b> + KB (する) + <b>ください</b>（ご利用ください ／ ご注意ください）<br>Khusus: 見る → <b>ご覧ください</b> · 来る → <b>お越しください</b>","nuance":"<ol><li>Khas <b>pelayanan, toko, resepsionis, pengumuman</b>.</li><li>Lebih hormat & lembut dari 〜てください (yang bisa terdengar menyuruh).</li></ol>⚠️ KK 1 suku kata tidak bisa: ×お見ください → ○<b>ご覧ください</b>.","examples":[{"jp":"どうぞお<ruby>座<rt>すわ</rt></ruby>りください。","speech":"どうぞお座りください。","id":"<b>Silakan duduk</b>. <i>(お座りください)</i>"},{"jp":"<ruby>少々<rt>しょうしょう</rt></ruby>お<ruby>待<rt>ま</rt></ruby>ちください。","speech":"少々お待ちください。","id":"<b>Mohon tunggu</b> sebentar. <i>(お待ちください)</i>"},{"jp":"こちらにお<ruby>名前<rt>なまえ</rt></ruby>をお<ruby>書<rt>か</rt></ruby>きください。","speech":"こちらにお名前をお書きください。","id":"<b>Silakan tulis</b> nama Anda di sini. <i>(お書きください)</i>"},{"jp":"エレベーターをご<ruby>利用<rt>りよう</rt></ruby>ください。","speech":"エレベーターをご利用ください。","id":"<b>Silakan gunakan</b> lift. <i>(ご〜ください)</i>"},{"jp":"こちらの<ruby>資料<rt>しりょう</rt></ruby>をご<ruby>覧<rt>らん</rt></ruby>ください。","speech":"こちらの資料をご覧ください。","id":"<b>Silakan lihat</b> dokumen ini. <i>(ご覧ください · khusus)</i>"}],"dialogs":[{"jp":"どう どうぞ<b>お<ruby>座<rt>すわ</rt></ruby>りください</b>","speech":"どうどうぞお座りください","id":"S-silakan <b>duduk</b>. <i>(お座りください)</i>","source":"白い砂のアクアトープ · EP05 · 02:02"},{"jp":"どうぞ <b>お<ruby>入<rt>はい</rt></ruby>りください</b>","speech":"どうぞお入りください","id":"Silakan <b>masuk</b>. <i>(お入りください)</i>","source":"ヴァイオレット・エヴァーガーデン · EP10 · 09:06"},{"jp":"まあ どうぞ<b>お<ruby>掛<rt>か</rt></ruby>けください</b>　 <ruby>渚<rt>なぎさ</rt></ruby><ruby>君<rt>くん</rt></ruby>も","speech":"まあどうぞお掛けください渚君も","id":"Nah, silakan <b>duduk</b>. Nagisa-kun juga. <i>(お掛けください)</i>","source":"暗殺教室 第２期 · EP09 · 12:41"},{"jp":"はいはい<ruby>婚姻届<rt>こんいんとどけ</rt></ruby>ですね<ruby>少々<rt>しょうしょう</rt></ruby><b>お<ruby>待<rt>ま</rt></ruby>ち<ruby>下<rt>くだ</rt></ruby>さい</b>","speech":"はいはい婚姻届ですね少々お待ち下さい","id":"Baik, akta nikah ya. <b>Mohon tunggu</b> sebentar. <i>(お待ちください · loket)</i>","source":"トニカクカワイイ · EP01 · 20:19"},{"jp":"こちらに <b>お<ruby>掛<rt>か</rt></ruby>けになって</b> <b>お<ruby>待<rt>ま</rt></ruby>ちください</b>","speech":"こちらにお掛けになってお待ちください","id":"Silakan <b>duduk</b> di sini dan <b>mohon tunggu</b>. <i>(お〜になって + お〜ください)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP08 · 10:06"}]},{"id":"n4_b50_01","level":"N4","bab":50,"lokasi":"第50課","titleMain":"お〜します・ご〜します","titleSub":["お持ちします","ご説明いたします"],"meaning":"Saya (akan) … untuk Anda — merendahkan tindakan saya yang ditujukan ke orang yang dihormati","formula":"<b>お</b> + Ｖ-<s>ます</s> + <b>します ／ いたします</b>（お持ちします ／ お送りします）<br><b>ご</b> + KB (する) + <b>します ／ いたします</b>（ご説明いたします ／ ご案内します）<br>Menawarkan: <b>お〜しましょうか</b>","nuance":"<ol><li>Subjek = <b>saya / pihak saya</b>; harus ada orang yang dituju (×お歩きします).</li><li><b>〜いたします</b> lebih sopan dari 〜します.</li><li><b>お待ちしております</b> = kami menantikan Anda (pelayanan).</li></ol>⚠️ お持ち<b>になる</b> (尊敬: beliau membawa) ↔ お持ち<b>する</b> (謙譲: saya membawakan). KK 1 suku kata → KK khusus (拝見する).","examples":[{"jp":"<ruby>重<rt>おも</rt></ruby>そうですね。お<ruby>持<rt>も</rt></ruby>ちしましょうか。","speech":"重そうですね。お持ちしましょうか。","id":"Kelihatannya berat ya. <b>Boleh saya bawakan?</b> <i>(menawarkan)</i>"},{"jp":"<ruby>今日<rt>きょう</rt></ruby>の<ruby>予定<rt>よてい</rt></ruby>をご<ruby>説明<rt>せつめい</rt></ruby>いたします。","speech":"今日の予定をご説明いたします。","id":"<b>Saya akan menjelaskan</b> jadwal hari ini. <i>(ご〜いたします)</i>"},{"jp":"タクシーをお<ruby>呼<rt>よ</rt></ruby>びしましょうか。","speech":"タクシーをお呼びしましょうか。","id":"<b>Perlu saya panggilkan</b> taksi? <i>(menawarkan)</i>"},{"jp":"<ruby>会議室<rt>かいぎしつ</rt></ruby>へご<ruby>案内<rt>あんない</rt></ruby>します。","speech":"会議室へご案内します。","id":"<b>Saya antar</b> Anda ke ruang rapat. <i>(ご案内する)</i>"},{"jp":"<ruby>皆様<rt>みなさま</rt></ruby>のお<ruby>越<rt>こ</rt></ruby>しをお<ruby>待<rt>ま</rt></ruby>ちしております。","speech":"皆様のお越しをお待ちしております。","id":"<b>Kami menantikan</b> kedatangan Bapak/Ibu sekalian. <i>(お待ちしております)</i>"}],"dialogs":[{"jp":"お<ruby>茶<rt>ちゃ</rt></ruby>なら すぐ <b>お<ruby>持<rt>も</rt></ruby>ちします</b>ので","speech":"お茶ならすぐお持ちしますので","id":"Kalau teh, <b>saya bawakan</b> segera kok. <i>(お持ちする)</i>","source":"この素晴らしい世界に祝福を！2 · EP01 · 12:40"},{"jp":"よろしければ　 <ruby>女性<rt>じょせい</rt></ruby>に<ruby>人気<rt>にんき</rt></ruby>の<ruby>品<rt>しな</rt></ruby>を いくつか <b>ご<ruby>案内<rt>あんない</rt></ruby>しましょう</b>か?","speech":"よろしければ女性に人気の品をいくつかご案内しましょうか?","id":"Kalau berkenan, <b>boleh saya tunjukkan</b> beberapa barang yang populer di kalangan perempuan? <i>(ご〜しましょうか · menawarkan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP06 · 15:26"},{"jp":"よろしければ<b>お<ruby>送<rt>おく</rt></ruby>りします</b>よ","speech":"よろしければお送りしますよ","id":"Kalau mau, <b>saya antar</b>. <i>(お送りする)</i>","source":"白い砂のアクアトープ · EP01 · 13:46"},{"jp":"では ルールを<b>ご<ruby>説明<rt>せつめい</rt></ruby>します</b>","speech":"ではルールをご説明します","id":"Baiklah, <b>saya jelaskan</b> peraturannya. <i>(ご説明する)</i>","source":"カードキャプターさくら · EP34 · 07:17"},{"jp":"それでは<ruby>今日<rt>きょう</rt></ruby>のゲストを<b>ご<ruby>紹介<rt>しょうかい</rt></ruby>します</b>!","speech":"それでは今日のゲストをご紹介します!","id":"Baiklah, <b>saya perkenalkan</b> bintang tamu hari ini! <i>(ご紹介する)</i>","source":"声優ラジオのウラオモテ · EP01 · 01:06"}]},{"id":"n4_b50_02","level":"N4","bab":50,"lokasi":"第50課","titleMain":"参ります・おります・申します・いたします","titleSub":[],"meaning":"Pergi/datang · ada · bernama/berkata · melakukan — versi merendah (丁重語) untuk sopan kepada lawan bicara","formula":"行く・来る → <b>参ります</b> · いる → <b>おります</b>（〜ている → <b>〜ております</b>）<br>言う → <b>申します</b> · する → <b>いたします</b><br>ある・です → <b>ございます ／ でございます</b>","nuance":"<ol><li>Tidak perlu ada orang yang dituju; sopan ke <b>pendengar</b> (アメリカから参りました).</li><li>Khas perkenalan diri, telepon kantor, pengumuman (電車が参ります).</li><li>Ke orang luar, kelompok sendiri direndahkan: 社長の田中は出かけております.</li></ol>⚠️ 申します = bernama / berkata (umum); <b>申し上げます</b> = berkata <b>kepada</b> yang dihormati.","examples":[{"jp":"<ruby>私<rt>わたし</rt></ruby>はアメリカから<ruby>参<rt>まい</rt></ruby>りました。","speech":"私はアメリカから参りました。","id":"Saya <b>datang</b> dari Amerika. <i>(参ります)</i>"},{"jp":"ミラーと<ruby>申<rt>もう</rt></ruby>します。よろしくお<ruby>願<rt>ねが</rt></ruby>いいたします。","speech":"ミラーと申します。よろしくお願いいたします。","id":"<b>Nama saya</b> Miller. <b>Mohon bantuannya</b>. <i>(申します · いたします)</i>"},{"jp":"<ruby>明日<rt>あした</rt></ruby>は<ruby>一日<rt>いちにち</rt></ruby>うちにおります。","speech":"明日は一日うちにおります。","id":"Besok seharian saya <b>ada</b> di rumah. <i>(おります)</i>"},{"jp":"<ruby>電車<rt>でんしゃ</rt></ruby>が<ruby>参<rt>まい</rt></ruby>ります。 <ruby>白線<rt>はくせん</rt></ruby>の<ruby>内側<rt>うちがわ</rt></ruby>までお<ruby>下<rt>さ</rt></ruby>がりください。","speech":"電車が参ります。白線の内側までお下がりください。","id":"Kereta <b>akan datang</b>. Mohon mundur ke belakang garis putih. <i>(pengumuman)</i>"},{"jp":"<ruby>社長<rt>しゃちょう</rt></ruby>の<ruby>田中<rt>たなか</rt></ruby>は<ruby>今<rt>いま</rt></ruby><ruby>出<rt>で</rt></ruby>かけております。","speech":"社長の田中は今出かけております。","id":"Pak Tanaka (direktur kami) sedang <b>keluar</b>. <i>(kelompok sendiri ke orang luar)</i>"}],"dialogs":[{"jp":"はじめまして<ruby>椎名<rt>しいな</rt></ruby><ruby>真昼<rt>まひる</rt></ruby>と<b><ruby>申<rt>もう</rt></ruby>します</b>","speech":"はじめまして椎名真昼と申します","id":"Salam kenal, <b>nama saya</b> Shiina Mahiru. <i>(言う → 申します)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 · EP05 · 08:15"},{"jp":"はい クメルスンから<b><ruby>参<rt>まい</rt></ruby>りました</b>","speech":"はいクメルスンから参りました","id":"Ya, saya <b>datang</b> dari Kumerson. <i>(来る → 参ります)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 13:07"},{"jp":"テレオの<ruby>村<rt>むら</rt></ruby>を<ruby>預<rt>あず</rt></ruby>かって<b>おります</b> セムと<b><ruby>申<rt>もう</rt></ruby>します</b>","speech":"テレオの村を預かっておりますセムと申します","id":"Saya yang <b>mengurus</b> Desa Tereo, <b>nama saya</b> Sem. <i>(〜ております + 申します)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP20 · 16:51"},{"jp":"<ruby>夜分<rt>やぶん</rt></ruby><ruby>失礼<rt>しつれい</rt></ruby><b>いたします</b>　どなたか いらっしゃいませんか?","speech":"夜分失礼いたしますどなたかいらっしゃいませんか?","id":"<b>Maaf mengganggu</b> malam-malam. Apakah ada orang di dalam? <i>(する → いたします)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 08:19"},{"jp":"<ruby>約束<rt>やくそく</rt></ruby>どおり<ruby>我<rt>わ</rt></ruby>が<ruby>主<rt>あるじ</rt></ruby>をお<ruby>迎<rt>むか</rt></ruby>えに<b><ruby>参<rt>まい</rt></ruby>りました</b>","speech":"約束どおり我が主をお迎えに参りました","id":"Sesuai janji, saya <b>datang</b> menjemput tuan saya. <i>(参りました)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 11:11"}]},{"id":"n4_b50_03","level":"N4","bab":50,"lokasi":"第50課","titleMain":"伺う・拝見する・お目にかかる","titleSub":["存じております","いただきます"],"meaning":"Berkunjung / bertanya · melihat · bertemu · tahu · menerima — 謙譲語 khusus untuk tindakan saya terhadap orang yang dihormati","formula":"訪ねる・聞く → <b>伺う</b>（お伺いします）· 見る → <b>拝見する</b><br>会う → <b>お目にかかる</b> · 知っている → <b>存じております</b>（知らない → <b>存じません</b>）<br>食べる・飲む・もらう → <b>いただく</b>","nuance":"<ol><li><b>伺う</b> = 2 arti: berkunjung (明日お宅に伺います) & bertanya / mendengar (お名前を伺っても…).</li><li><b>お伺いします</b> = keigo ganda tapi sudah diterima umum di kerja.</li></ol>⚠️ <b>ご存じ</b> (尊敬: Anda tahu) ↔ <b>存じる</b> (謙譲: saya tahu). Jangan pakai untuk tindakan orang lain.","examples":[{"jp":"<ruby>明日<rt>あした</rt></ruby><ruby>3時<rt>さんじ</rt></ruby>にお<ruby>伺<rt>うかが</rt></ruby>いします。","speech":"明日3時にお伺いします。","id":"Besok jam 3 saya <b>akan berkunjung</b>. <i>(訪ねる → 伺う)</i>"},{"jp":"ちょっと<ruby>伺<rt>うかが</rt></ruby>いたいことがあるんですが。","speech":"ちょっと伺いたいことがあるんですが。","id":"Ada yang <b>ingin saya tanyakan</b> sedikit. <i>(聞く → 伺う)</i>"},{"jp":"<ruby>先生<rt>せんせい</rt></ruby>の<ruby>作品<rt>さくひん</rt></ruby>を<ruby>拝見<rt>はいけん</rt></ruby>しました。","speech":"先生の作品を拝見しました。","id":"Saya <b>sudah melihat</b> karya Bapak. <i>(見る → 拝見する)</i>"},{"jp":"<ruby>社長<rt>しゃちょう</rt></ruby>の<ruby>奥様<rt>おくさま</rt></ruby>にお<ruby>目<rt>め</rt></ruby>にかかりました。","speech":"社長の奥様にお目にかかりました。","id":"Saya <b>bertemu</b> istri Pak direktur. <i>(会う → お目にかかる)</i>"},{"jp":"そのことは<ruby>存<rt>ぞん</rt></ruby>じております。","speech":"そのことは存じております。","id":"Saya <b>sudah tahu</b> hal itu. <i>(知っている → 存じております)</i>"}],"dialogs":[{"jp":"ご<ruby>注文<rt>ちゅうもん</rt></ruby>がお<ruby>決<rt>き</rt></ruby>まりでしたら <b>お<ruby>伺<rt>うかが</rt></ruby>いします</b>","speech":"ご注文がお決まりでしたらお伺いします","id":"Kalau pesanannya sudah ditentukan, <b>akan saya catat</b>. <i>(聞く → 伺う · pelayan)</i>","source":"お隣の天使様にいつの間にか駄目人間にされていた件 第2期 · EP08 · 13:43"},{"jp":"また<ruby>明日<rt>あした</rt></ruby> <b><ruby>伺<rt>うかが</rt></ruby>います</b>","speech":"また明日伺います","id":"Besok <b>saya datang</b> lagi. <i>(訪ねる → 伺う)</i>","source":"この素晴らしい世界に爆焔を！ · EP06 · 10:37"},{"jp":"どれどれ ぼっちちゃんの<ruby>力作<rt>りきさく</rt></ruby> <b><ruby>拝見<rt>はいけん</rt></ruby>しましょー</b>","speech":"どれどれぼっちちゃんの力作拝見しましょー","id":"Mana-mana, <b>coba kulihat</b> karya andalan Bocchi-chan! <i>(見る → 拝見する · bercanda)</i>","source":"ぼっち・ざ・ろっく！ · EP04 · 21:01"},{"jp":"お<ruby>初<rt>はつ</rt></ruby>に<b>お<ruby>目<rt>め</rt></ruby>にかかります</b> お<ruby>名前<rt>なまえ</rt></ruby>は?","speech":"お初にお目にかかりますお名前は?","id":"Senang <b>bertemu</b> dengan Anda untuk pertama kali. Siapa nama Anda? <i>(会う → お目にかかる)</i>","source":"狼と香辛料 MERCHANT MEETS THE WISE WOLF · EP03 · 17:36"},{"jp":"お<ruby>名前<rt>なまえ</rt></ruby>だけは <b><ruby>存<rt>ぞん</rt></ruby>じ<ruby>上<rt>あ</rt></ruby>げています</b>","speech":"お名前だけは存じ上げています","id":"Saya hanya <b>tahu</b> nama beliau saja. <i>(知る → 存じ上げる)</i>","source":"狼と香辛料II 狼と琥珀色の憂鬱 · EP11 · 02:05"}]}];
